  CollectionHall_100310_Title = {
    Text = "불멸의 백야"
  },
  CollectionHall_100442_Desc = {
    Text = "<Title:개요>\n인류 부유한 상인 가정에서 태어났으나, 몸에는 구울의 피가 흐르고 있습니다. 반인반구울의 혈통은 그에게 독특한 특성을 부여하여 다른 사람들이 볼 수 없는 세상을 보게 했습니다. 그 세상은 광란하며, 엉뚱하고, 화려한 색채에 그는 헤어나지 못했습니다.\n거의 망설임 없이, 픽맨은 그가 본 모든 것을 붓으로 기록하기로 했습니다. 그는 그 속에 빠져들어 날마다 묘사하는 과정에서 숙달된 그림 기법을 가지게 되었습니다.\n주류 미학은 픽맨을 완전히 버렸고, 그의 광란한 이론을 아무도 받아들일 수 없었습니다. 픽맨은 이에 대해 자주 슬퍼했지만, 절대 포기하지 않았습니다.\n마침내, 픽맨은 융식의 포옹을 받아들여 구울의 피를 완전히 깨우쳤습니다. 그는 인간 세계를 떠나 구울의 왕성으로 갔습니다. 언젠가 그는 현실타래 세계에서 그 환상적이고 광란한 광경을 사람들이 한 명 한 명 앞에 보여줄 것입니다."
  },
  CollectionHall_100442_LockTip = {
    Text = "「피크먼」을 깨어남한 후 잠금 해제"
  },
  CollectionHall_100442_Title = {Text = "픽맨"},
  CollectionHall_100458_Desc = {
    Text = "걱정을 잠시 내려놓고, 피로를 빨리 멀리 하세요.\n따뜻한 모닥불 옆에서 잠깐 쉬어봅시다."
  },
  CollectionHall_100458_LockTip = {
    Text = "의식 잠수 '불멸의 극지' 완수"
  },
  CollectionHall_100458_Title = {
    Text = "모닥불 온기 휴식"
  },
  CollectionHall_100459_Desc = {
    Text = "타오르라, 타오르라, 너에게 속한 모든 것을 다 태워라.\n그리고 그 끝없는 불길 속에서, 너와 세상의 장례를 시작하라!"
  },
  CollectionHall_100459_LockTip = {
    Text = "의식 잠수 '불멸의 극지' 완수"
  },
  CollectionHall_100459_Title = {
    Text = "열화 속의 장례식"
  },
  CollectionHall_100460_Desc = {
    Text = "나는 말했다, 어떤 방식으로든 모두를 집으로 데려가겠다고.\n\"나는 내 모든 것을 태울 것이고, 그 다음에…\n별들에서 온 이 업화로, 이 허위하고 더럽고 혼돈의 세상을 태워버릴 것이다!\"\n\"나는 케이티구라의 이름으로 선언한다!\"\n\"하늘이 새벽을 맞이할 것이다!\""
  },
  CollectionHall_100460_LockTip = {
    Text = "의식 잠수 '불멸의 극지' 완수"
  },
  CollectionHall_100460_Title = {
    Text = "모든 것을 태우는 여명"
  },
  CollectionHall_100461_Desc = {
    Text = "광기의 죽음은 만화경처럼 회전하며, 질병과 시체의 비린내는 가장 좋은 향기가 된다. 너희는 수많은 죽음을 향해 멀리서 잔을 높이 들어올린다—만약 죽음이 운명이라면, 우리 함께 기쁘게 이 무도회로 달려가자, 춤의 마지막 박자에 함께 지옥의 문으로 떨어지자."
  },
  CollectionHall_100461_LockTip = {
    Text = "의식 잠수 “타오르는 군연” 어려움 완료"
  },
  CollectionHall_100461_Title = {
    Text = "적포도주, 꽃과 화려한 죽음"
  },
  CollectionHall_100462_Desc = {
    Text = "아주 오래 전, 그녀는 우주에서 독재하는 제왕이었고, 그녀가 보는 모든 것은 그녀의 지배 아래에 있었다. \n 아주 오래 후, 그녀의 눈에는 끝없이 펼쳐진 먼지밖에 보이지 않았고, 그녀가 지배하는 것은 황폐함과 고독뿐이었다."
  },
  CollectionHall_100462_LockTip = {
    Text = "의식 잠수 완료 “타오르는 군연”"
  },
  CollectionHall_100462_Title = {
    Text = "황폐를 다스리는 여왕"
  },
  CollectionHall_100463_Desc = {
    Text = "그녀는 난폭하고 폭력적이며 기분이 변덕스럽지만, 동시에 그녀는 관대하고 박식하며 지혜로 가득 차 있습니다. \n 그녀는 방탕한 폭군이자 어린 양의 보호자이며, 그녀는 당신에게 사랑을 주고, 또한 죽음을 선사합니다. 이 땅의 모든 생명체는 그녀의 발 아래 엎드려 경외심을 가지고 그녀의 이름을 부릅니다. \n 여왕의 무도회에서 마음껏 빠져들고, 그녀와 함께 영원한 검은 불꽃 속으로 잠기세요."
  },
  CollectionHall_100463_LockTip = {
    Text = "의식 잠수 완료 “타오르는 군연”"
  },
  CollectionHall_100463_Title = {
    Text = "죽음을 향한 광연"
  },
  CollectionHall_100464_Desc = {
    Text = "만약 죽기 전에 마지막으로 할 수 있는 일이 있다면, 춤추는 것이다.\n달콤한 좋은 술을 마시고, 향기로운 고기를 삼키며, 환희의 음악 속에서 마음껏 회전하라.\n이 세상의 마지막 반영이 여전히 황홀한 금빛으로 반짝이기를."
  },
  CollectionHall_100464_LockTip = {
    Text = "의식 잠수 “타오르는 군연” 어려움 완료"
  },
  CollectionHall_100464_Title = {
    Text = "역병의 가면"
  },
  CollectionHall_100465_Desc = {
    Text = "그녀는 항상 호수에서 화려했던 옛날을 본다. \n 풍화된 기억은 허상 같은 꿈처럼, 꿈속에서 그녀는 끝없는 폐허 속에 앉아 자신에게 속한 모든 것이 환영처럼 흐릿하게 사라지는 것을 목격한다. \n 그 꿈마저 잊혀질 때, 피리를 부는 사자가 안개를 뚫고 와서 그녀를 잃어버린 이들의 귀향으로 인도한다."
  },
  CollectionHall_100465_LockTip = {
    Text = "의식 잠수 완료 “타오르는 군연”"
  },
  CollectionHall_100465_Title = {
    Text = "호수 속의 반영"
  },
  CollectionHall_100466_Desc = {
    Text = "별들 사이에서 결코 사라지지 않는 존재가 다시 두 눈을 뜨고, 이 흐리고 더럽지만 무척 푸른 행성에 불사의 힘을 투사한다, \n 그것은 40억 년 전, 하늘을 가리고 태양이 내렸을 때와 똑같다."
  },
  CollectionHall_100466_LockTip = {
    Text = "의식 잠수 '불멸의 극지' 완수"
  },
  CollectionHall_100466_Title = {
    Text = "40억 년의 재회"
  },
  CollectionHall_116205_Title = {
    Text = "안녕, 네버랜드"
  },
  CollectionHall_116601_LockTip = {
    Text = "한정 이벤트 「극지의 끝밤: 융합의 괴로움」의 어떤 스테이지를 통과해야 한다"
  },
  CollectionHall_116601_Title = {
    Text = "극주기의 끝밤: 섞인 쓰라린 피"
  },
  CollectionHall_116868_Title = {
    Text = "안녕, 영원한 고향"
  },
  CollectionHall_117619_Title = {
    Text = "하늘의 저편·하"
  },
  CollectionHall_117621_LockTip = {
    Text = "의식 잠수 클리어 “하늘 너머·하”의 임의의 관문 해금"
  },
  CollectionHall_117621_Title = {Text = "정화"},
  CollectionHall_117957_LockTip = {
    Text = "한정 시간 복장 행사 「사탕을 주지 않으면 장난칠 거야」에서 무료 추출 완료로 잠금을 해제합니다"
  },
  CollectionHall_117957_Title = {
    Text = "유령 이야기회"
  },
  CollectionHall_117958_Desc = {
    Text = "그녀는 기억과 과거를 넘어 떠도는 존재로, 죽음과 삶의 진흙 속을 지나 조용히 너와 재회한다."
  },
  CollectionHall_117958_LockTip = {
    Text = "조사 작전 7-19 완료 시 해제"
  },
  CollectionHall_117958_Title = {
    Text = "관 속에서 재회"
  },
  CollectionHall_117959_Desc = {
    Text = "시, 감정, 기억, 도덕…… 모든 것이 부담입니다. 이 이치를 시인들은 결코 이해하지 못합니다."
  },
  CollectionHall_117959_LockTip = {
    Text = "특파대 기록 “장미의 거처” 어려움 완료"
  },
  CollectionHall_117959_Title = {
    Text = "시대 축제"
  },
  CollectionHall_117960_Desc = {
    Text = "그녀는 반드시 혼자서 출연하기를 원했고, 그렇지 않으면 너에게 총을 쏠 것이라 했다.\n하지만 결국 그녀는 좋은 제자를 얻었고, 한 마리의 늑대를 얻었다."
  },
  CollectionHall_117960_LockTip = {
    Text = "완료 이몽 시야「안녕 영원의 고향」"
  },
  CollectionHall_117960_Title = {Text = "독각극"},
  CollectionHall_117961_Desc = {
    Text = "먹어라, 에프! 봐라, 에프!\n광란과 현실타래 사이, 색채와 예술이 쌓아올린 다리!\n오직 우리 둘만 여기 있어, 오직 우리가 진실타래을 볼 수 있어!"
  },
  CollectionHall_117961_LockTip = {
    Text = "의식 잠수 「기괴의 회화」 완료"
  },
  CollectionHall_117961_Title = {
    Text = "환영합니다! 에버!"
  },
  CollectionHall_117962_Desc = {
    Text = "그녀는 매 시구를 쓸 때마다 꽃잎이 돋아날 것이라고 생각했다.\n그녀는 자신의 삶을 시구에 물주기 하며, 마지막 시편이 완성되면 그녀들은 이전의 정원으로 돌아갈 수 있을 것이다."
  },
  CollectionHall_117962_LockTip = {
    Text = "특파대 기록 “장미의 거처” 어려움 완료"
  },
  CollectionHall_117962_Title = {
    Text = "마지막 시편"
  },
  CollectionHall_117963_Desc = {
    Text = "그는 이쪽을 버리고 저쪽으로 가기로 결심했다.\n그와 이별하라, 하지만 그를 잊지는 마라.\n그는 너를 일깨울 것이고, 너를 지켜볼 것이며, 그 미친 천재 화가와 밤하늘에 걸린 달이 함께 할 것이다."
  },
  CollectionHall_117963_LockTip = {
    Text = "의식 잠수 「기괴의 회화」 완료"
  },
  CollectionHall_117963_Title = {
    Text = "그곳으로 가라"
  },
  CollectionHall_117964_Desc = {
    Text = "소리쳐라, 춤춰라, 꿀과 우유가 불꽃 옆에서 뒤섞일 때.\n그 종말은 점점 더 가까워지고 있다. 발로 기어오르고, 팔로 엉켜서, 목에 키스를 하라—— 번식하라! 번식하라! 어머니 나무의 그늘 아래에서, 결국에는 자손들이 은혜를 받을 것이다!"
  },
  CollectionHall_117964_LockTip = {
    Text = "조사 작전 7-19 완료 시 해제"
  },
  CollectionHall_117964_Title = {
    Text = "번식, 번식!"
  },
  CollectionHall_117965_Desc = {
    Text = "우리에게 승리하고, 우리를 죽여라. 그리고 나서, 우리를 구해줘."
  },
  CollectionHall_117965_LockTip = {
    Text = "조사 작전·어려움 8-10 완료 시 해제"
  },
  CollectionHall_117965_Title = {
    Text = "운명이 다가온다"
  },
  CollectionHall_117966_Desc = {
    Text = "한 아가씨의 팔이 신축 로프에 매달려 있고, 한 아가씨가 두 번 죽은 다른 아가씨와 함께 거짓 영혼을 만들어냈다."
  },
  CollectionHall_117966_LockTip = {
    Text = "특파대 기록 “사냥 즐겁게!”"
  },
  CollectionHall_117966_Title = {
    Text = "너를 붙잡았다"
  },
  CollectionHall_117967_Desc = {
    Text = "여왕의 육체는 융식에 침범당하고, 아란의 백성은 모래 속에서 유랑합니다.\n시간은 틈새를 통해 목격되었으며, 고인이 되어 아란의 수백 년 운명을 목격하지 못하였습니다."
  },
  CollectionHall_117967_LockTip = {
    Text = "조사 작전·어려움 7-12 완료 시 해제"
  },
  CollectionHall_117967_Title = {
    Text = "백 년의 증인"
  },
  CollectionHall_117969_Desc = {
    Text = "그 알 수 없는 존재, 반항할 수 없고, 무지하고 맹목적인 존재.\n그것은 떠오르기 시작했고, 반쯤 깨어났으며, 공포스럽고 거대한 압력을 드러냈습니다."
  },
  CollectionHall_117969_LockTip = {
    Text = "조사 작전·어려움 8-10 완료 시 해제"
  },
  CollectionHall_117969_Title = {
    Text = "신의 권위에 저항하다"
  },
  CollectionHall_117970_Desc = {
    Text = "조용히, 계속 가자. 서곡은 이미 울려 퍼졌다.\n나는 너를 운명적이고, 최고의, 아름다운 종장으로 안내할 것이다."
  },
  CollectionHall_117970_LockTip = {
    Text = "조사 작전 8-14 완료 시 해제"
  },
  CollectionHall_117970_Title = {
    Text = "웅장한 율령"
  },
  CollectionHall_117971_Desc = {
    Text = "특별한 주석이 필요할 수도 있습니다, 이 말은 시합에서 두 가지 주의 사항이라는 의미입니다.\n절대 상대방에게 양보하지 말고, 동료에게도 양보하지 마세요."
  },
  CollectionHall_117971_LockTip = {
    Text = "완료 이몽 시야「안녕 영원의 고향」어려움 난이도"
  },
  CollectionHall_117971_Title = {
    Text = "겸손을 금지한다"
  },
  CollectionHall_117972_Desc = {
    Text = "서대의 꽃들이 당신에게 초대를 보내며, 함께 꿈속으로 들어오세요."
  },
  CollectionHall_117972_LockTip = {
    Text = "“장미의 거처” 특파대 기록 완료"
  },
  CollectionHall_117972_Title = {
    Text = "시중세계"
  },
  CollectionHall_117973_Desc = {
    Text = "“‘기사 정신’ 팀, 1/4의 기사 정신과 3/4의 전투 광마가 있습니다.”"
  },
  CollectionHall_117973_LockTip = {
    Text = "완료 이몽 시야「안녕 영원의 고향」"
  },
  CollectionHall_117973_Title = {
    Text = "미덕의 기사와 거인"
  },
  CollectionHall_117974_Desc = {
    Text = "옛날의 여왕, 잊혀진 여왕, 그녀는 여전히 끝없는 고독 속에서 기다리고 있다.\n그녀의 피와 씨가 소멸 이후의 새로운 세계로 옮겨지기를 기다리고 있다."
  },
  CollectionHall_117974_LockTip = {
    Text = "조사 작전 7-19 완료 시 해제"
  },
  CollectionHall_117974_Title = {
    Text = "뒤틀린 풍요의 씨앗"
  },
  CollectionHall_117975_Desc = {
    Text = "정원은 퍼즐이고, 장미는 그녀가 내린 답이다."
  },
  CollectionHall_117975_LockTip = {
    Text = "“장미의 거처” 특파대 기록 완료"
  },
  CollectionHall_117975_Title = {
    Text = "봄날에게 꽃을"
  },
  CollectionHall_117976_Desc = {
    Text = "햇살이 꽃집의 유리창을 지나 오를라의 얼굴에 비추었다. 그녀는 햇살을 뚫고 잠이 쏟아지는 오를라 앞에 섰다.\n그녀를 매번 깨울 때마다 장미를 몸 뒤에 숨겨 놓는다."
  },
  CollectionHall_117976_LockTip = {
    Text = "“장미의 거처” 특파대 기록 완료"
  },
  CollectionHall_117976_Title = {
    Text = "온실타래의 아침빛"
  },
  CollectionHall_117977_Desc = {
    Text = "그녀는 정원의 이야기를 시 페이지에 적었다.\n그녀는 정원의 이야기를 불길에 던졌다."
  },
  CollectionHall_117977_LockTip = {
    Text = "“장미의 거처” 특파대 기록 완료"
  },
  CollectionHall_117977_Title = {
    Text = "시 페이지의 잔재"
  },
  CollectionHall_117978_Desc = {
    Text = "빈곤, 허기, 질병, 배신이 없는 곳. 꽃과 시들만 있는 시대, 그녀들만의 낙원입니다."
  },
  CollectionHall_117978_LockTip = {
    Text = "“장미의 거처” 특파대 기록 완료"
  },
  CollectionHall_117978_Title = {
    Text = "환상의 낙원"
  },
  CollectionHall_117979_Desc = {
    Text = "첫 막에 총이 등장하면, 마지막에 반드시 발사될 것이다.\n너는 재회할 때 그녀에게 이야기할 이야기를 이미 구상해 두었다.\n그것은 꿈이었고, 꿈의 시작에 밝은 태양이 떨어졌고, 꿈의 결말에 검은 태양이 떨어졌다."
  },
  CollectionHall_117979_LockTip = {
    Text = "완료 이몽 시야「안녕 영원의 고향」어려움 난이도"
  },
  CollectionHall_117979_Title = {
    Text = "떨어지는 태양"
  },
  CollectionHall_117980_Desc = {
    Text = "꿀술이 이미 가득 붓고, 귀한 손님이 도착했습니다. 레무와시에게 새로운 씨앗을 가져와 주시고, 욕망에 젖은 열정을 마음껏 누리세요!"
  },
  CollectionHall_117980_LockTip = {
    Text = "조사 작전 7-19 완료 시 해제"
  },
  CollectionHall_117980_Title = {
    Text = "열정적인 시간"
  },
  CollectionHall_117981_Desc = {
    Text = "시간, 생명, 공허, 운명.\n모든 난해한 꿈, 어렴풋한 현실타래이 평등하게 흐름 속으로 모여서, 없어지듯이 흔적 없이, 한길로 나아가서 바다로 간다."
  },
  CollectionHall_117981_LockTip = {
    Text = "조사 작전·어려움 7-12 완료 시 해제"
  },
  CollectionHall_117981_Title = {
    Text = "바다로 돌아가다"
  },
  CollectionHall_117982_Desc = {
    Text = "그녀는 모래 위에 검은 물결을 그리며, 너를 끌어당기고, 붙잡아 모든 것들을 황폐함 속에서 너에게 전달한다.\n오늘밤의 달은 아름답고 난해한 비밀을 가리고 있으며, 그녀는 춤을 추며 너의 의문을 풀어주고, 또 하나의 춤을 남겨 너에게 더 많은 퍼즐을 남긴다."
  },
  CollectionHall_117982_LockTip = {
    Text = "조사 작전 7-19 완료 시 해제"
  },
  CollectionHall_117982_Title = {
    Text = "은빛 모래 바다의 춤"
  },
  CollectionHall_117983_Desc = {
    Text = "반역자에게는 애정을 주고, 그의 악취미의 희생품이 되며, 그의 나쁜 습관을 나눈다."
  },
  CollectionHall_117983_LockTip = {
    Text = "특파대 기록 “사냥 즐겁게!”"
  },
  CollectionHall_117983_Title = {
    Text = "악습 복사"
  },
  CollectionHall_117984_Desc = {
    Text = "불길한 징조와 즐거운 음이 얽혀 나타난다, 그는 적이자 친구, 그는 애매모호하다."
  },
  CollectionHall_117984_LockTip = {
    Text = "조사 작전 8-14 완료 시 해제"
  },
  CollectionHall_117984_Title = {
    Text = "운명의 서곡"
  },
  CollectionHall_117985_Desc = {
    Text = "모든 음표를 포착하고, 올바른 리듬에 맞춰 떨어지세요.\n조심하세요, 주의하세요, 까다로운 지휘자를 대면할 때 실타래수하면 돌이킬 수 없는 구렁텅이에 빠질 수 있습니다."
  },
  CollectionHall_117985_LockTip = {
    Text = "조사 작전 8-14 완료 시 해제"
  },
  CollectionHall_117985_Title = {
    Text = "박자를 맞춰서"
  },
  CollectionHall_117986_Desc = {
    Text = "장미 한 송이로 시 한 편을 바꾸어봐요.\n사람들의 황량한 심장 속에 장미가 붉게 자리잡고 있습니다."
  },
  CollectionHall_117986_LockTip = {
    Text = "특파대 기록 “장미의 거처” 어려움 완료"
  },
  CollectionHall_117986_Title = {
    Text = "장미여, 장미"
  },
  CollectionHall_117987_Desc = {
    Text = "우리는 당신을 위해 완벽한 휴가를 준비했습니다. 해변, 햇살, 배구 경기, 옛 친구와 새로운 친구들.\n무조건 자외선 차단제를 잘 발라주세요, 하늘에서 태양이 떨어져도 놀라지 마세요, 이는 정상적인 현상입니다."
  },
  CollectionHall_117987_LockTip = {
    Text = "완료 이몽 시야「안녕 영원의 고향」"
  },
  CollectionHall_117987_Title = {
    Text = "룬티니언의 여름"
  },
  CollectionHall_117988_Desc = {
    Text = "너는 음악을 잘 하지도, 퍼즐을 좋아하지도 않는다.\n하지만 그는 차분하고 우아하게 너를 교향곡에 엮고, 신비롭고 무례하게 그의 수수께끼를 던졌다."
  },
  CollectionHall_117988_LockTip = {
    Text = "조사 작전 8-14 완료 시 해제"
  },
  CollectionHall_117988_Title = {
    Text = "지휘자의 수수께끼"
  },
  CollectionHall_117989_Desc = {
    Text = "불쌍한, 오만한, 세상 물정도 모르는 늑대.\n그는 다른 손님들과 함께 휴게실타래에 버려졌고, 짧은 평화로운 도박판에서.\n익숙했던 행운을 잃고, 그는 만 레오방 이상 잃어버렸다."
  },
  CollectionHall_117989_LockTip = {
    Text = "특파대 기록 “사냥 즐겁게!”"
  },
  CollectionHall_117989_Title = {
    Text = "나쁜 카드"
  },
  CollectionHall_117990_Desc = {
    Text = "같은 모자, 같은 장미, 같은 웃음.\n막이 오르고 관객들이 자리잡고 있습니다, 자 이제, 누가 검은 안개 속에서 튕겨 나왔는지 찾아봅시다?"
  },
  CollectionHall_117990_LockTip = {
    Text = "특파대 기록 “사냥 즐겁게!”"
  },
  CollectionHall_117990_Title = {Text = "작은 N"},
  CollectionHall_117991_Desc = {
    Text = "좋은 일상은 항상 악몽에서 시작해, 묘지에서 끝난다.\n오, 이게 바로 삶이다, 달콤한 삶."
  },
  CollectionHall_117991_LockTip = {
    Text = "특파대 기록 “사냥 즐겁게!” 어려움 난이도 완료"
  },
  CollectionHall_117991_Title = {
    Text = "아, 인생"
  },
  CollectionHall_117992_Desc = {
    Text = "내 손을 잡아 주세요.\n손가락이 닿을 때, 당신에게 봄을 선물하겠습니다."
  },
  CollectionHall_117992_LockTip = {
    Text = "“장미의 거처” 특파대 기록 완료"
  },
  CollectionHall_117992_Title = {
    Text = "두 사람의 봄날"
  },
  CollectionHall_117993_Desc = {
    Text = "갑작스러운 방문, 배려 깊은 방문, 행복한 방문입니다.\n비슷한 친구들, 다르지 않은 친구들.\n아, 친구여, 모든 사람은 친구가 필요합니다. 나는 무엇으로 너를 대접할까, 나의 친구여?"
  },
  CollectionHall_117993_LockTip = {
    Text = "의식 잠수 「기괴의 회화」 완료"
  },
  CollectionHall_117993_Title = {
    Text = "서로 닮지 않은 친구"
  },
  CollectionHall_117994_Desc = {
    Text = "관 속에서 기어 나오는 룰렛, 눈 속의 끊임없는 과거.\n한 게임, 또 하나의 게임, 늑대의 털과 행운이 밝은 다음 주 월요일을 가져온다."
  },
  CollectionHall_117994_LockTip = {
    Text = "특파대 기록 “사냥 즐겁게!”"
  },
  CollectionHall_117994_Title = {
    Text = "늑대의 다음 주 월요일"
  },
  CollectionHall_117995_Desc = {
    Text = "아란의 백성은 대막을 지나고, 그들은 이곳에서 태어나고 성장하며, 반드시 이곳에서 번창하고, 필연적으로 이곳에서 사라질 운명이다."
  },
  CollectionHall_117995_LockTip = {
    Text = "조사 작전 7-19 완료 시 해제"
  },
  CollectionHall_117995_Title = {
    Text = "풍요의 종말"
  },
  CollectionHall_117996_Desc = {
    Text = "착한 아이야, 착한 아가야, 성스러운 강은 너의 요절한 통곡을 달래줄 것이며, 성스러운 강은 너의 흐르는 혼을 품어줄 것이다."
  },
  CollectionHall_117996_LockTip = {
    Text = "조사 작전 7-19 완료 시 해제"
  },
  CollectionHall_117996_Title = {
    Text = "아직 성스러운 강에"
  },
  CollectionHall_117997_Desc = {
    Text = "정원의 잔해와 과거의 재가 이 작은 땅 위에 떨어졌다. 그들은 슬픈 기억 속에서 하늘을 떠돌고, 열망에 불타서 사라진다."
  },
  CollectionHall_117997_LockTip = {
    Text = "특파대 기록 “장미의 거처” 어려움 완료"
  },
  CollectionHall_117997_Title = {
    Text = "정원의 추억"
  },
  CollectionHall_117998_Desc = {
    Text = "괴괴한 것은 예술가의 영감을 기르고 성장시키며, 화가는 색깔로 현실타래을 해체하고, 광기와 미치광이가 엉킨 선들 속에 자생하고 있습니다."
  },
  CollectionHall_117998_LockTip = {
    Text = "의식 잠수 「기괴의 회화」 완료"
  },
  CollectionHall_117998_Title = {
    Text = "전위 예술"
  },
  CollectionHall_117999_Desc = {
    Text = "여름밤의 꿈속에서만 도달할 수 있는 곳이 있다. 그것은 우리가 재회할 수 있는 영원한 고향이다."
  },
  CollectionHall_117999_LockTip = {
    Text = "완료 이몽 시야「안녕 영원의 고향」"
  },
  CollectionHall_117999_Title = {
    Text = "영원히 휴가 없는 날"
  },
  CollectionHall_118000_Desc = {
    Text = "화가는 그 무서운 예술을 찾았고, 그는 캔버스를 들어올려 친구들을 초대하였다. 색채 폭발의 광란 기행으로."
  },
  CollectionHall_118000_LockTip = {
    Text = "의식 잠수 「기괴의 회화」 완료"
  },
  CollectionHall_118000_Title = {
    Text = "미친 그림의 기행"
  },
  CollectionHall_118001_Desc = {
    Text = "그들은 혈맥, 형제, 연인, 가까운 친구를 포옹하며, 자신을 바치고 흑달콤한 부활 속으로 녹아들었다.\n그들의 뼈는 모수로 돌아가고, 그들의 육체는 성스러운 강으로 흘러간다."
  },
  CollectionHall_118001_LockTip = {
    Text = "조사 작전·어려움 7-12 완료 시 해제"
  },
  CollectionHall_118001_Title = {Text = "어머니"},
  CollectionHall_118002_Desc = {
    Text = "뜨거운 태양이 곧 죽어갑니다, 바람이 모래를 몰아가며 그것을 꺼버립니다.\n떨어지는 태양이 내려가며, 하늘과 모래의 경계로 추락합니다."
  },
  CollectionHall_118002_LockTip = {
    Text = "조사 작전 7-19 완료 시 해제"
  },
  CollectionHall_118002_Title = {
    Text = "모래에 빠지다"
  },
  CollectionHall_118003_Desc = {
    Text = "어째서 한 불길이 모든 서약을 태울 수 있을까?\n어째서 시가의 세계에도 고통이 가득할까?"
  },
  CollectionHall_118003_LockTip = {
    Text = "“장미의 거처” 특파대 기록 완료"
  },
  CollectionHall_118003_Title = {
    Text = "상반되는 수사학"
  },
  CollectionHall_118004_Desc = {
    Text = "근원의 길로, 생명으로 쌓아올리며 그 힘에 맞서 외칩니다. 혈통을 아란으로 돌려보내고 풍요를 아란으로 돌려보냅니다!"
  },
  CollectionHall_118004_LockTip = {
    Text = "조사 작전 7-19 완료 시 해제"
  },
  CollectionHall_118004_Title = {
    Text = "폭풍의 벽"
  },
  CollectionHall_118005_Desc = {
    Text = "이것은 현실타래이고, 이것은 광기이며, 이것은 어두운 면이고, 이것은 꿈이다.\n광신자와 천재가 번갈아 중얼거리고 있다, 더 미세하게, 더욱 미세하게——눈을 떼지 마라."
  },
  CollectionHall_118005_LockTip = {
    Text = "의식 잠수 「기괴의 회화」 완료"
  },
  CollectionHall_118005_Title = {
    Text = "혼란 속으로 들어간다"
  },
  CollectionHall_118006_Desc = {
    Text = "극한의 추위, 계략, 폭설, 모두 야수의 후각을 방해할 수 없다."
  },
  CollectionHall_118006_LockTip = {
    Text = "특파대 기록 “사냥 즐겁게!”"
  },
  CollectionHall_118006_Title = {Text = "후각"},
  CollectionHall_118007_Desc = {
    Text = "경계를 게을리하지 마세요. 오래된 친구만이 당신을 발로 차면서…… 배구를 할 수 있는 건 아닙니다."
  },
  CollectionHall_118007_LockTip = {
    Text = "완료 이몽 시야「안녕 영원의 고향」"
  },
  CollectionHall_118007_Title = {
    Text = "새로운 동료"
  },
  CollectionHall_118008_Desc = {
    Text = "아니 아니 아니 아니 아니 아니, 올인을 하는 것은 이기기 위한 것이 아니야.\n올인의 요점은 올인하는 것이고, 올인은 올인하기 위해서야."
  },
  CollectionHall_118008_LockTip = {
    Text = "특파대 기록 “사냥 즐겁게!” 어려움 난이도 완료"
  },
  CollectionHall_118008_Title = {
    Text = "명탐정의 포커"
  },
  CollectionHall_118009_Desc = {
    Text = "가까워졌습니다, 죽은 신, 마지막 숨결, 전설적이지만 알려지지 않은 과거, 응결되고 담담하게 이별이 되어갑니다."
  },
  CollectionHall_118009_LockTip = {
    Text = "조사 작전·어려움 7-12 완료 시 해제"
  },
  CollectionHall_118009_Title = {
    Text = "선행자의 종소리"
  },
  CollectionHall_118010_Desc = {
    Text = "그녀의 입에서 내려오는 것은 신탁인지 왕의 명령인지, 하늘의 은총인지 사심인지.\n나무 영혼과 인형이 공명하며 그녀에게 영원한 고독의 허무를 약속한다."
  },
  CollectionHall_118010_LockTip = {
    Text = "조사 작전·어려움 7-12 완료 시 해제"
  },
  CollectionHall_118010_Title = {
    Text = "무음의 신탁"
  },
  CollectionHall_118011_Desc = {
    Text = "나는 그 분의 모습과 이름을 잊었다.\n하지만 나는 사심을 버리고, 은개미가 되어 그 분이 돌아오기를 기다리며, 그 분이 다시 오실타래 때까지 내 품에 안기기를 바란다, 그 분이 그 탄식을 부정하기를."
  },
  CollectionHall_118011_LockTip = {
    Text = "조사 작전·어려움 7-12 완료 시 해제"
  },
  CollectionHall_118011_Title = {
    Text = "고인의 명복을 빌며"
  },
  CollectionHall_118012_Desc = {
    Text = "정원의 잔디 위에서, 그들은 구름이 바람에 따라 변하는 것을 바라본다.\n코레트, 저 두 개의 쫓고 있는 구름은 나비 부인과 애벌레 선생님이 춤추고 있는 거야."
  },
  CollectionHall_118012_LockTip = {
    Text = "“장미의 거처” 특파대 기록 완료"
  },
  CollectionHall_118012_Title = {
    Text = "구름처럼 쫓아가다"
  },
  CollectionHall_118013_Desc = {
