  },
  CollectionHall_120464_LockTip = {
    Text = "기대해주세요"
  },
  CollectionHall_120464_Title = {
    Text = "욕심쟁이 지갑"
  },
  CollectionHall_120465_LockTip = {
    Text = "조사 작전 4-5에서 해제 가능"
  },
  CollectionHall_120465_Title = {
    Text = "각지락거림"
  },
  CollectionHall_120466_LockTip = {
    Text = "조사 작전 3-10에서 해제 가능"
  },
  CollectionHall_120466_Title = {
    Text = "무성 전보"
  },
  CollectionHall_121154_Title = {Text = "낙원"},
  CollectionHall_121341_Desc = {
    Text = "<Title:소개>\n임신의 「성아」 책임을 맡은 「공주」는 지금은 바다를 건너는 자 교단 내에서 중요한 「신모」가 되었습니다.\n그녀는 또한 자유를 향해 달려가는 숙녀였으며, 미사그가 기록한 머피처럼 소나니르호의 탈출 여정을 함께 했습니다.\n하지만 비밀 지키는 사람이 존재하지 않는 세계에서, 운명은 어린 백조의 고귀한 목을 꺾었습니다.\n왜곡된 혈맥은 저항의 여지도 없이 그녀를 엮어버립니다. 육체적 죽음을 방치해도 피할 수 없습니다. 그녀는 그저 겉모습을 유지하며「나는 존귀한 신모」라는 말을 되풀이할 뿐, 이는 오직 자신의 암시와 설득일 뿐입니다.\n그녀는 오직 순종해야만 했고, 허깨비의 신탁에, 터무니없는 운명에 순종하며 끝없는 쓴맛 속에서 간신히 환상의 달콤함을 느끼게 됩니다."
  },
  CollectionHall_121341_LockTip = {
    Text = "「탄망·머피」를 깨어남한 후 잠금 해제"
  },
  CollectionHall_121341_Title = {
    Text = "탄망·머피"
  },
  CollectionHall_121381_Desc = {
    Text = "당신은 천 개의 도토리로 이 세계에서 온 이야기를 교환했습니다.\n영웅과 마신에 대한 이야기, 감시와 인내의 이야기.\n어쩔 수 없이, 이별과 친구들, 그리고 새로운 친구들에 대한 이야기.\n한때 다녀갔던 이야기."
  },
  CollectionHall_121381_LockTip = {
    Text = "「역전의 턴」의 다차원 연결 완료"
  },
  CollectionHall_121381_Title = {
    Text = "만상 여관의 회상"
  },
  CollectionHall_121382_Desc = {
    Text = "오래오래 후, 그와 그가 마침내 전해지는 민속시 하나를 갖게 되었습니다.\n죽고 다시 부활하는 구원, 하나로 묶인 쌍둥이 영혼에 대한 이야기입니다."
  },
  CollectionHall_121382_LockTip = {
    Text = "완료 이몽 시야「천변 저편·하」"
  },
  CollectionHall_121382_Title = {
    Text = "날개 없는 새의 시가"
  },
  CollectionHall_121383_Desc = {
    Text = "소년은 순간적인 모든 것에 대해 갚을 수밖에 없는 대가를 치렀습니다.\n이제는 그에게 침묵의 권력만이 동반됩니다.\n왕은 잠들었고, 그는 꿈속에서 세계의 종말을 맞이합니다."
  },
  CollectionHall_121383_LockTip = {
    Text = "의식 잠수 완료 “가관의 날”"
  },
  CollectionHall_121383_Title = {
    Text = "끝없는 고독의 왕토"
  },
  CollectionHall_121384_Desc = {
    Text = "그녀들은 당신을 에워싸고, 당신을 숭배하며, 당신과 함께 있습니다.\n그들은 창조신에게 돛을 펼칩니다."
  },
  CollectionHall_121384_LockTip = {
    Text = "조사 작전 9-11 완료 시 해제"
  },
  CollectionHall_121384_Title = {
    Text = "창조신에게 항해를"
  },
  CollectionHall_121385_Desc = {
    Text = "그것은 부러짐 속에서 다시 태어난 날개였다. 그것은 희생으로 자유를 얻은 날개였다.\n운명의 예언이 이미 실타래현되었고, 그는 후회와 고통 속에서 맹세했다, 피로 갚아야 한다고."
  },
  CollectionHall_121385_LockTip = {
    Text = "완료 이몽 시야「천변 저편·하」"
  },
  CollectionHall_121385_Title = {
    Text = "폭풍이 일어날 때"
  },
  CollectionHall_121386_Desc = {
    Text = "부조리와 혼돈의 꿈의 시작에서, 그는 운명을 정면으로 맞이할 운명이었다.\n그러나 그는 너무 많은 것을 겪었고, 너무 많은 것을 정의했다.\n그는 인간이 유지할 수 있는 최대의 이성을 가지고, 자신의 기원을 바라보는 결심을 했다, 그 최고신을."
  },
  CollectionHall_121386_LockTip = {
    Text = "조사 작전 9-11 완료 시 해제"
  },
  CollectionHall_121386_Title = {
    Text = "원초적 숙명 전투"
  },
  CollectionHall_121387_Desc = {
    Text = "얻고, 잃고, 끊어내고, 희생합니다.\n영웅은 모든 대가를 치르고, 보물을 보호하는 권력은 그의 보상입니다."
  },
  CollectionHall_121387_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_121387_Title = {
    Text = "무목의 눈"
  },
  CollectionHall_121388_Desc = {
    Text = "그는 왕관을 자신에게 올리고, 족쇄를 자신에게, \n그것은 짧고 허망한 따뜻함이며, 반드시 멸망할 과거의 영광이다."
  },
  CollectionHall_121388_LockTip = {
    Text = "의식 잠수 완료 “가관의 날”"
  },
  CollectionHall_121388_Title = {
    Text = "유왕의 고독한 길"
  },
  CollectionHall_121389_Desc = {
    Text = "비록 상황이 당신에게 불리한 것으로 보이지만, 당신의 입가가 살짝 올라갔습니다.\n“제 차례입니다, 카드를 뽑겠습니다!”\n만상 여관이나 미사그에서든,\n보조의 능력을 무시하는 것은 큰 실타래수를 초래하리란 걸... 이그나티스!"
  },
  CollectionHall_121389_LockTip = {
    Text = "「역전의 턴」의 다차원 연결 완료"
  },
  CollectionHall_121389_Title = {
    Text = "저의 역전의 순간입니다!"
  },
  CollectionHall_121390_Desc = {
    Text = "완전한 전설은 적을 친구로 만드는 것을 놓칠 수 없다."
  },
  CollectionHall_121390_LockTip = {
    Text = "조사 작전·어려움 9-10 완료 시 해제"
  },
  CollectionHall_121390_Title = {
    Text = "적, 친구"
  },
  CollectionHall_121391_Desc = {
    Text = "이 순간부터, 너는 비밀 수호자라는 특별한 책무를 짊어지고, 많은 미사그의 교사 및 학생들과 함께하게 될 거야."
  },
  CollectionHall_121391_LockTip = {
    Text = "조사 작전·어려움 9-11 완료 시 해제"
  },
  CollectionHall_121392_Desc = {
    Text = "우리는 아마도 영원 속의 한 순식간, 맹렬한 물줄기 속의 모래알입니다.\n하지만 상서는 우리에게 소중한 영원입니다. 세상이 아무리 미쳐 혼란스러워도——\n인간의 존엄은 이성을 밝히는 빛 위에 세워질 것입니다."
  },
  CollectionHall_121392_LockTip = {
    Text = "조사 작전 9-11 완료 시 해제"
  },
  CollectionHall_121392_Title = {
    Text = "상세 송축"
  },
  CollectionHall_121393_Desc = {
    Text = "영웅들은 동화 속으로 뛰어들었습니다. 모든 동화는 똑같습니다. 동물, 악마, 요정, 그리고 알 수 없는 곳.\n짧은 자유와 허상의 바람을 넘어서, 동화의 끝에는 그에게 부여된 가짜 심장이 숨겨져 있습니다."
  },
  CollectionHall_121393_LockTip = {
    Text = "완료 이몽 시야「천변 저편·하」"
  },
  CollectionHall_121393_Title = {
    Text = "은하로 날아오르다"
  },
  CollectionHall_121394_Desc = {
    Text = "여기는 이세계 시공의 틈에 위치한 만상 여관입니다.\n서로 다른 우주를 연결하는 전송문, 광활한 별빛이 반짝이며, 당신의 오심을 환영합니다.\n잠깐… 이건 우리 비밀 지키는 사람을 위해 뭘 하러 온 거죠?"
  },
  CollectionHall_121394_LockTip = {
    Text = "「역전의 턴」의 다차원 연결 완료"
  },
  CollectionHall_121394_Title = {
    Text = "만상의 여관에 오신 것을 환영합니다!"
  },
  CollectionHall_121395_Desc = {
    Text = "미사그의 날카로운 칼날이 당신에게 이 대결의 승리를 가져다줄 것입니다.\n당신과 파트너 간의 유대는 견고합니다.\n비록 언젠가 당신들이 서로 다른 우주에 있더라도, 이 점은 변하지 않을 것입니다."
  },
  CollectionHall_121395_LockTip = {
    Text = "「역전의 턴」의 다차원 연결 완료"
  },
  CollectionHall_121395_Title = {
    Text = "미사그의 검！"
  },
  CollectionHall_121396_Desc = {
    Text = "“매일 시험을 하지 않았어? 그럼 먼저 만상 카드를 하나 하자!”\n“융합 재해 구역을 하지 않았어? 그럼 먼저 만상 카드를 하나 하자!”\n“이건 상위 대국이 아니야, 만상 카드야! 천 개의 도토리를 내가 보관해줄게!”"
  },
  CollectionHall_121396_LockTip = {
    Text = "「역전의 턴」의 다차원 연결 완료"
  },
  CollectionHall_121396_Title = {
    Text = "함께 만상 카드를 즐겨보자!"
  },
  CollectionHall_121397_Desc = {
    Text = "내 이름을 호출해, 잊혀진 새벽 이전에."
  },
  CollectionHall_121397_LockTip = {
    Text = "조사 작전·어려움 9-11 완료 시 해제"
  },
  CollectionHall_121397_Title = {
    Text = "잊혀진 것에서 @2"
  },
  CollectionHall_121398_Desc = {
    Text = "“내게 계약을 하자, 카드 마스터가 되어라!”\n이 세계에서 온 드래곤족 미소녀가 너에게 열정적이면서도 이상한 초대를 했다.\n이 차원 공간의 작은 사고가 빨리 정상으로 돌아오도록 너에게는 다른 선택지가 없다."
  },
  CollectionHall_121398_LockTip = {
    Text = "「역전의 턴」의 다차원 연결 완료"
  },
  CollectionHall_121398_Title = {
    Text = "사장님, 이그나티스!"
  },
  CollectionHall_121399_Desc = {
    Text = "후발자는 무거운 선물 속에서 이렇게 한 줄 주석을 찾게 될 것이다.\n영웅이 되기를 피한 유일한 이는 영웅이 되었고, 친구를 소중히 여기는 아이는 오직 한 친구만 남았다."
  },
  CollectionHall_121399_LockTip = {
    Text = "의식 잠수 완료 “가관의 날”"
  },
  CollectionHall_121399_Title = {
    Text = "여유는 독행"
  },
  CollectionHall_121400_Desc = {
    Text = "주님으로부터 벗어나고, 주님을 직면하며, 주님을 반역하라.\n너의 이야기는 아무도 모르고, 너의 기억은 영원히 남는다."
  },
  CollectionHall_121400_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_121400_Title = {
    Text = "창세의 어리석은 주"
  },
  CollectionHall_121401_Desc = {
    Text = "모든 것이 더 이상 의미가 없기에 네가 여기 서 있다.\n그동안의 모든 과거는 네가 정의한 전부의 의미이기에, 네가 여기 서게 되었다."
  },
  CollectionHall_121401_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_121401_Title = {Text = "존재론"},
  CollectionHall_121402_Desc = {
    Text = "그들을 향한 길, 그들을 멀리하는 길.\n모든 것이 곧 나뉘고, 모든 것이 곧 끝나고, 모든 것이 곧 시작될 것이다.\n문 앞의 모습은 이렇게 긴 대기를 시작했으며, 은열쇠가 너의 귀환을 이끌어주기를 기다리고 있다."
  },
  CollectionHall_121402_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_121402_Title = {
    Text = "그들을 향한 길"
  },
  CollectionHall_121403_Desc = {
    Text = "그들의 가능성 경계, 분리, 수렴, 붕괴.\n유일한 구세주를 맞이할 때까지, 마침내 유일한 종말로 나아갈 때까지."
  },
  CollectionHall_121403_LockTip = {
    Text = "조사 작전·어려움 9-10 완료 시 해제"
  },
  CollectionHall_121403_Title = {
    Text = "유일한 종말"
  },
  CollectionHall_121404_Desc = {
    Text = "유왕은 이 거래를 받아들였다.\n그는 말했다, 내 나라는 아무 문제도 없을 것이다."
  },
  CollectionHall_121404_LockTip = {
    Text = "의식 잠수 완료 “가관의 날”"
  },
  CollectionHall_121404_Title = {Text = "가관"},
  CollectionHall_121405_Desc = {
    Text = "이 부서진 시공의 틈 사이에는 전설적인 만상 여관이 위치해 있었습니다.\n한때 서로 다른 우주를 연결하던 전송문이며, 한때 광활한 별빛이 반짝였고, 한때 모든 카드 전문가를 환영했던 곳입니다.\n그리고 당신은 그 모든 존재했던 것의 증명입니다."
  },
  CollectionHall_121405_LockTip = {
    Text = "「역전의 턴」의 다차원 연결 완료"
  },
  CollectionHall_121405_Title = {
    Text = "안녕, 카드 마스터!"
  },
  CollectionHall_121406_Desc = {
    Text = "주가 너를 바라보고, 너는 주의 눈을 찔렀다."
  },
  CollectionHall_121406_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_121406_Title = {
    Text = "종말 집중"
  },
  CollectionHall_121407_Desc = {
    Text = "전사, 복수자, 노예, 주인, 상인.\n같은 입장일까? 다른 입장일까? 같은 입장."
  },
  CollectionHall_121407_LockTip = {
    Text = "조사 작전 9-11 완료 시 해제"
  },
  CollectionHall_121407_Title = {
    Text = "다중성 전투가"
  },
  CollectionHall_121408_Desc = {
    Text = "당신은 알고 있죠, 당신은 아무런 위대한 일을 위해 싸우고 있는 것이 아닙니다.\n수업을 뺄 때, 과제를 위해, 디저트를 위해, 친구를 위해, 난로를 위해, 시간을 낭비하기 위해.\n당신은 그저 평범한, 일상적으로 죽음에 나아가는 사람입니다."
  },
  CollectionHall_121408_LockTip = {
    Text = "조사 작전·어려움 9-11 완료 시 해제"
  },
  CollectionHall_121408_Title = {
    Text = "평소 죽음을 맞이하는 자들을 위해"
  },
  CollectionHall_121409_Desc = {
    Text = "동물, 모든 고등 동물들은 어려운 사회 행동에 의해 제어될 수밖에 없습니다.\n그러나 그녀는 직접 죽음으로 달려가, 원하던 진실타래을 해체합니다.\n미친, 뛰어난 천재로서 그녀는 차라리 파멸을 몰고 오기를 선택하며, 생명들에게 희망이라는 비극을 삼키지 않도록 은혜를 베풀었습니다."
  },
  CollectionHall_121409_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_121409_Title = {
    Text = "커뮤니티 행동 해체"
  },
  CollectionHall_121410_Desc = {
    Text = "그는 높은 하늘에서 계속해서 쏟아지는 고통의 물을 보내주고, 모아지며 모아진다.\n궁극적으로 우리 혈육이 융합되기 전에 반드시 되돌아가야만 하는 그 강 흐름이 생기게 될 것이다."
  },
  CollectionHall_121410_LockTip = {
    Text = "완료 이몽 시야「천변 저편·하」"
  },
  CollectionHall_121410_Title = {
    Text = "고통의 강"
  },
  CollectionHall_121411_Desc = {
    Text = "그들은 재회를 기대하며 작별 인사를 했다.\n왜냐하면 이것은 한 분의 소중한 존재이기 때문이며, 이것은 운명이 아닌 소중한 존재의 죽음이기 때문이다."
  },
  CollectionHall_121411_LockTip = {
    Text = "조사 작전 9-11 완료 시 해제"
  },
  CollectionHall_121411_Title = {
    Text = "한 명의 지극히 소중한 자의 죽음"
  },
  CollectionHall_121412_Desc = {
    Text = "잠깐 쉬며 숨을 고르세요.\n설령 맞닥뜨린 주제가 세계 종말이라 해도, 모든 사람이 이렇게 세 명의 중대한 멘토와 동시에 대면할 기회를 갖는 것은 아닙니다."
  },
  CollectionHall_121412_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_121412_Title = {Text = "극 중간"},
  CollectionHall_121413_Desc = {
    Text = "천 개의 도토리 이야기는 첫 번째 도토리에서 시작해야 한다.\n상위 대국에서 카드 한 장을 사용 할 때마다,\n이그나티우스의 눈 속에는 이상하게 스쳐 지나가는 황금빛 회상 조명이 있다."
  },
  CollectionHall_121413_LockTip = {
    Text = "「역전의 턴」의 다차원 연결 완료"
  },
  CollectionHall_121413_Title = {
    Text = "무한 리필!"
  },
  CollectionHall_121414_Desc = {
    Text = "광란, 파멸의 전주곡, 이는 질서 있는 세계의 기초 논리입니다.\n그가 파멸할까요, 세상이 파멸할까요?\n아무도 모른다.\n하지만 창조신 앞에서, 광란이 그와 세계의 새로운 탄생을 양육하고 있습니다."
  },
  CollectionHall_121414_LockTip = {
    Text = "조사 작전 9-11 완료 시 해제"
  },
  CollectionHall_121414_Title = {
    Text = "광란 푸가"
  },
  CollectionHall_121415_Desc = {
    Text = "세상에서 가장 비이성적인 것은 무엇인가?\n그는 목표가 없고, 원한과 관계가 없으며, 선악을 가리지 않는다.\n그는 깨어날 때 꿈 속에서 태어난 모든 것을 가루로 만들어 버리기를 바란다."
  },
  CollectionHall_121415_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_121415_Title = {Text = "분말"},
  CollectionHall_121416_Desc = {
    Text = "독일한 그 조각으로서, 신이 되는 것은 아주 간단합니다.\n자, 그 대가는 무엇일까요?"
  },
  CollectionHall_121416_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_121416_Title = {
    Text = "신이 되기"
  },
  CollectionHall_121417_Desc = {
    Text = "긴 인류 문명 속에서 우리는 많은 것들을 세웠습니다.\n 물질에 대한 것, 정신에 대한 것, 존재, 사랑, 연기와 분쟁에 대한 것.\n 그러나 그것은 단지 창조자의 꿈속에서 무시할 만한 잡음과, 이해하지 못한 허구의 집합이었습니다."
  },
  CollectionHall_121417_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_121417_Title = {
    Text = "허구 집합"
  },
  CollectionHall_121418_Desc = {
    Text = "미사그 역사상 가장 소심한 비밀 지키는 사람이 거대한 행복 속에서 죽었습니다."
  },
  CollectionHall_121418_LockTip = {
    Text = "조사 작전·어려움 9-11 완료 시 해제"
  },
  CollectionHall_121418_Title = {
    Text = "도망칠 결심을 한 영웅"
  },
  CollectionHall_121898_LockTip = {
    Text = "조사 작전 성신편 4-0 완료 시 해제"
  },
  CollectionHall_121898_Title = {
    Text = "영원한 허망 순례"
  },
  CollectionHall_121901_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_121901_Title = {
    Text = "신의 탄생 7일"
  },
  CollectionHall_122565_LockTip = {
    Text = "제한 시간 이벤트 “안개 속의 제물: 잃어버린 자아”의 임의의 스테이지를 클리어해야 합니다"
  },
  CollectionHall_122565_Title = {
    Text = "안개 속의 제물 의식:잃어버린 자아"
  },
  CollectionHall_123756_Title = {
    Text = "은과 피의 세례"
  },
  CollectionHall_124124_Desc = {
    Text = "당신은 많은 존재들과 두 번째 면을 볼 가능성이 있습니다. 비록 그것이 존재해서는 안 되는 아기이거나, 잘못된 신으로부터 태어난 것일지라도 말입니다."
  },
  CollectionHall_124124_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124124_Title = {
    Text = "두 번째 면"
  },
  CollectionHall_124125_Desc = {
    Text = "아… 원래 더 나쁜 결말이 있었군요."
  },
  CollectionHall_124125_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124125_Title = {
    Text = "그녀와 그와 그분의 죽음"
  },
  CollectionHall_124126_Desc = {
    Text = "눈부신 순간에 떠나는 동행자를 어떻게 묘사할 건가요? \n 그의 눈부심을 묘사하지 말고, 그의 팔을 묘사하고, 그에게서 느껴지는 시더 향기를 묘사하세요."
  },
  CollectionHall_124126_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124126_Title = {
    Text = "스노우송목"
  },
  CollectionHall_124127_Desc = {
    Text = "여행의 끝에서, 누가 당신을 기다리고 있는지 알고 있습니다.\n하지만 당신은 아직 탈출하지 못했고, 다시 높은 곳에서 떨어졌습니다."
  },
  CollectionHall_124127_LockTip = {
    Text = "조사 작전·어려움 성신편 4-10 완료 시 해제"
  },
  CollectionHall_124127_Title = {
    Text = "떨어지다"
  },
  CollectionHall_124128_Desc = {
    Text = "아이들은 어머니에게 속하지 않으며, 그분은 모든 사람들이 여기 남아야 한다고 결심했습니다.\n그분의 영원히 지속되는 달콤한 낙원에 남아있어야 합니다."
  },
  CollectionHall_124128_LockTip = {
    Text = "조사 작전·어려움 성신편 4-10 완료 시 해제"
  },
  CollectionHall_124128_Title = {
    Text = "달콤한 놀이공원"
  },
  CollectionHall_124129_Desc = {
    Text = "당신은 그녀를 구할 시간이 없었고, 그녀는 탈출하지 못했습니다.\n그녀는 분식당했고, 그녀는 고립되어 있었으며, 가짜 제무줄에 묶여 있었습니다."
  },
  CollectionHall_124129_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124129_Title = {
    Text = "가짜 탯줄"
  },
  CollectionHall_124130_Desc = {
    Text = "3.14159@2, 3.141592@3, 3.14159265@4……\n눈밭에 끝이 없는 원, 잔인하고 영원히 끝나지 않는 원주율."
  },
  CollectionHall_124130_LockTip = {
    Text = "조사 작전·어려움 성신편 4-10 완료 시 해제"
  },
  CollectionHall_124131_Desc = {
    Text = "너 또 늦게 왔어, 머무르지 말고, 더 빨리, 더 빨리!\n다음 결말로 서둘러 가."
  },
  CollectionHall_124131_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124131_Title = {
    Text = "어떤 결말"
  },
  CollectionHall_124132_Desc = {
    Text = "나를 안아줘, 내 아가, 내…… 아버지, 내 운명."
  },
  CollectionHall_124132_LockTip = {
    Text = "조사 작전·어려움 성신편 4-10 완료 시 해제"
  },
  CollectionHall_124132_Title = {
    Text = "그의 딸의 어두운 유터스 안에서"
  },
  CollectionHall_124133_Desc = {
    Text = "하늘이 밝아질 준비를 하고 있다. 어제와 작별하자. \n 어제의 고통, 부조리, 혼란과 작별하고, \n 더 밝고 각기 다른 내일을 맞이하자."
  },
  CollectionHall_124133_LockTip = {
    Text = "조사 작전·어려움 성신편 4-10 완료 시 해제"
  },
  CollectionHall_124133_Title = {
    Text = "새벽에 작별하다"
  },
  CollectionHall_124134_Desc = {
    Text = "그녀는 현실타래과, 허망함 사이에 작은 방패를 세웠다. \n 밀가루, 계란, 레몬, 꿀, 설탕, 베이킹 파우더, 버터로 구워진 방패."
  },
  CollectionHall_124134_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124134_Title = {
    Text = "반죽 방패"
  },
  CollectionHall_124135_Desc = {
    Text = "이 세상은 여전히 그렇고, 아이는 어머니에게 의존하며, 아이는 어머니에게 거짓말을 한다."
  },
  CollectionHall_124135_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124135_Title = {
    Text = "거짓말쟁이와 화음"
  },
  CollectionHall_124136_Desc = {
    Text = "신의 탄생의 일곱째 날. \n오, 신이여, 신이여…… \n단지 황당한 오류와 거짓말일 뿐이다."
  },
  CollectionHall_124136_LockTip = {
    Text = "조사 작전·어려움 성신편 4-10 완료 시 해제"
  },
  CollectionHall_124136_Title = {
    Text = "부패 신명"
  },
  CollectionHall_124137_Desc = {
    Text = "자세요, 자세요, 바다의 아기여, 칠흑 같은 달빛이 당신의 어두운 포대기에 비추게 하여, 수천 년, 수억 년의 잠든 꿈이 영원한 허망으로 빠져들게 하소서."
  },
  CollectionHall_124137_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124137_Title = {
    Text = "검은 월광"
  },
  CollectionHall_124138_Desc = {
    Text = "도망쳐! 두 마리 물고기가 수면으로 뛰어올랐다. \n 그들은 잠시 모든 것을 던져버리고 세상과 서로를 속이며 유랑하려고 했다."
  },
  CollectionHall_124138_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124138_Title = {
    Text = "비밀 망명"
  },
  CollectionHall_124139_Desc = {
    Text = "아버지가 딸을 낳고, 딸이 아버지를 임신한다. \n 망상, 왜곡, 그녀가 빠져든 순환하는 운명."
  },
  CollectionHall_124139_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124139_Title = {
    Text = "망상의 왜곡의 잉태"
  },
  CollectionHall_124140_Desc = {
    Text = "죽음과 고통보다 더 무서운 것이 무엇인가요? \n 당신에게는 이것이 해결하기 어려운 문제가 아닙니다."
  },
  CollectionHall_124140_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124140_Title = {
    Text = "출발점으로 돌아가기"
  },
  CollectionHall_124141_Desc = {
    Text = "그녀와 그녀는 그녀와 그녀의 성실타래이 있고, 그는 그와 그의 반항과 충성이 있습니다.\n그녀는 엄청난 거짓말을 엮고, 그는 그와 그녀가 그녀와 함께 연기를 합니다.\n집, 모두가 달콤하고 분리할 수 없는 집을 이루고 있습니다."
  },
  CollectionHall_124141_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124141_Title = {Text = "집"},
  CollectionHall_124142_Desc = {
    Text = "바다에서 떠오르는 신국의 이름을 부르자——리모리아, 리모리아."
  },
  CollectionHall_124142_LockTip = {
    Text = "조사 작전 성신편 4-16 완료 시 해제"
  },
  CollectionHall_124142_Title = {Text = "해국"},
  CollectionHall_124224_LockTip = {
    Text = "다차원 연결 “은과 피의 세례”의임의의 단계를 클리어 해금합니다"
  },
  CollectionHall_124224_Title = {
    Text = "모샤의 이세계 조사 기록"
  },
  CollectionHall_124395_Desc = {
    Text = "로탄의 생애에서 가장 고통스럽고도 충만했던 그날, 그녀의 손에 쥔 칼날은 폭풍처럼 눈앞의 신명을 향해 내리쳤다. 거대한 검과 리바이어던의 행성처럼 웅장한 몸체가 함께, 이 폭풍 속에서 산산이 부서졌다.\n선혈의 왕관을 그분 기사단의 노예에게 건넨 후, 그 대가로 로탄은 단 하나의 요구만을 했다: 새로운 무기가 필요하다고.\n로탄에 대한 두려움과 경외심을 품은 새 국왕은 사람을 시켜 리바이어던의 뼈를 가져오게 하여, 그녀를 위해 비할 데 없는 한 쌍의 거대한 검을 주조하게 했다. 여섯 나라 최고의 대장장이들이 밤낮없이 주조하고 담금질하는 가운데, 죽은 신명의 유골은 신을 죽인 자의 손 안에서 신생을 얻었다.\n기억될 만한 가치가 있는 상대방 한 명이 일찍이 이 불멸의 검날을 증언한 적이 있었다. 그의 거대한 망치는 로탄의 갑옷과 거대한 검을 산산조각 냈고, 균열은 거미줄처럼 검신을 따라 확산되었으며, 유백색의 파편이 핏빛 공기 속에 튀어 올랐다, 마치 그녀가 리바이어던을 찌르던 그날처럼. 그는 자신이 약점을 찾았다고 생각했다. 그러나, 그는 로탄이 자신의 앞에 다시 일어서는 것을 보았고, 부서졌어야 할 그 거대한 검이 그의 가슴을 꿰뚫으며 그의 혈육을 흡입했다. 새로운 뼈가 부서진 곳에서 솟아올라, 이전보다 더욱 날카롭고 더욱 치밀해졌다. 단면은 마디마디 자라나, 마치 황야에서 미친 듯이 자라는 첨예한 가시덤불처럼. 그는 선명하게 느꼈다, 자신의 HP가 저 백골로 주조된 칼날에 씹히고 삼켜지고 있음을.\n알고 보니, 일찍이 별과 하늘을 포식했던 그 거대한 짐승은 결코 죽지 않았던 것이다. 계약이 맺어진 그 순간부터, 그것은 그녀와 하나로 합쳐졌다. 로탄이 거대한 검을 들어 올릴 때마다, 검신의 뼈 첨예한 가시가 피어나기 시작하여, 날카로운 첨예한 가시로 상대방을 향해 잔인한 환호를 보냈다.\n그것은 그녀의 무기였다. 그녀는 그것의 두 발이었다. 그녀와 그것은, 처음부터 끝까지 같은 갈망에 빠져 있었다. 그녀들은 죽지도 않고 멸하지도 않으며, 영원히 만족을 모른다.\n멈추지 않는 전장, 그것이 그녀들의 유일한 귀착지였다."
  },
  CollectionHall_124395_Title = {
    Text = "불멸의 곯은 뼈"
  },
  CollectionHall_124397_Desc = {
    Text = "수년 후, 엎드려 기도를 올리는 바다를 건너는 자를 보며, 탄망·머피는 어머니가 그녀에게 푸른 고리 문어 이야기를 해 준 그 먼 오후를 회상할 것입니다。\n병 속의 유물은 유연하고 눈부시며, 기묘한 유령이 물속에서 떠다니며 어린 그녀를 자극하여 자연스레 가까이 다가가게 했습니다。\n그러나 미리암은 그녀의 머리를 쓰다듬으며 거부할 수 없는 힘으로 어두운 선실타래 구석을 보게 했습니다 - 해양을 건넌 자의 시신이 맥없이 쓰러져 있고, 독소에 완전하게 흡입된 뒤의 무력한 상태를 나타내고 있었습니다。\n「기억해라, 바다에서 가장 고요하고 치명적인 것은 대부분 가장 아름다운 것이다。」\n유리병의 차가운 광휘가 그녀의 자비로운 측면을 비추었고, 탄망·머피는 아름다움으로 포장된 공포만을 느꼈습니다。\n\n세월은 별들의 규칙에 따라 조용히 흐르고, 탄망·머피는 여전히 오만하지만 조용함과 관찰을 배우게 되었습니다。\n「리모리아, 리모리아……」\n제단 위에서 평온하고 온화한 얼굴이 점차 광란에 물들며, 그녀는 마침내 깨달았습니다 - 그녀는 미리암을 결코 진정으로 알지 못한 것입니다。자비롭게 그녀의 머리를 쓰다듬었던 어머니의 손은 신국의 적에게 가장 엄격한 징벌을 가할 수 있습니다。\n그 순간, 기억 깊이 봉인된 공포가 갑자기 부활하여 차가운 인식으로 굳어졌습니다 - 그녀의 자비로운 모습은 결국 허장의 촉수일 뿐이며, 온화한 외면이 변하여 나타난 아름다운 푸른 고리가 바로 피를 봉합하는 독소 그 자체입니다。\n\n오늘날, 공허의 신이 마침내 탄망·머피에게 왕관을 씌웠습니다。 그녀는 해양을 건넌 자를 내려다보며 미리암의 시선 속에서 사라지지 않은 거의 황당한 평안을 맞이합니다, 마치 유리병 앞에서 아름다운 생물을 응시하던 그 작은 자신을 다시 보는 듯했습니다。"
  },
  CollectionHall_124397_Title = {
    Text = "푸른 고리 독소"
  },
  CollectionHall_124400_Desc = {
    Text = "이름 모를 역병이 도시와 마을을 집어삼키고, 전쟁을 탐하는 자들이 혼란 속에서 마음껏 살육을 벌이며, 철과 피의 교향곡이 끓어오르며 광란했다.\n공포에서 비롯되거나, 혹은 공포를 이용하거나.\n공포는 보이지 않는 적, 오래된 적, 치명적인 적이다.\n그는 자격 미달의 기사였고, 공포에 패배했다.\n하지만 일찍이 엄숙하게 내뱉었던 맹세는 여전히 귓가에 울려 퍼졌다. 해가 바뀌고 날이 지나도, 이미 허무로 변해버린 고향을 가로질러.\n「나는 약자를 자비롭게 대할 것이다, 나는 강적에게 용감하게 맞설 것이다.」\n밤이 범행자의 발자국을 숨기고, 비명과 울음의 홍수가 거리를 뒤덮으며, 군중은 겁에 질린 양 떼처럼 우왕좌왕했다.\n「나는 악인에게 조금도 물러섬 없이 맞설 것이다, 나는 싸울 수 없는 자들을 위해 싸울 것이다.」\n창끝에 피가 물들고, 은빛 방패는 녹슬었으며, 그림자는 만족스럽게 미소 짓고, 까마귀 떼가 하늘 위를 선회하며, 눈동자 속에는 악마의 섬광이 번뜩였다.\n「나는 나의 도움을 필요로 하는 자들을 도울 것이다.」\n「저자다, 그가 왔다.」 사람들이 낮은 목소리로 중얼거렸다. 공포가 그들의 얼굴을 일그러뜨렸다. 「속이 텅 빈 괴물, 복수의 망령, 죽음의 깊은 연못에서 돌아와 자신의 적들을 원한의 검은 늪으로 끌어들이려 한다.」\n그가 맞다. 그는 잊지 않았다, 결코 잊은 적이 없었다.\n왜 계속해야 하는가? 영광과 신앙조차도, 만물이 결국 소멸할 것이라면.\n왜 물러서야 하는가? 운명이 어떻게 조롱하든, 인간은 오직 무릎을 꿇고 순종할 수밖에 없다면.\n설마 오직 충성에 충성하고, 헌신에 헌신하기 위해서인가?\n공국 최후의 기사는 헛되이 물음을 던졌다. 영혼은 잔해가 된 육신처럼 황폐했고, 공포의 잔재가 제멋대로 흘러넘쳐 파멸의 바다를 이루었다.\n하지만 텅 빈 가슴속은 여전히 침묵을 지킬 뿐, 잃어버린 답은 아직 행방을 알 수 없었다."
  },
  CollectionHall_124400_Title = {
    Text = "지난 날은 그림자처럼 따라온다"
  },
  CollectionHall_124404_Desc = {
    Text = "그것은 내가 아버지와 함께 해성으로 이주한 두 번째 해였다. 이블린이 편지에서 울부짖는 소리에 나는 마음이 어지러워졌고, 그녀와의 이별을 결심했다. 이것은 비단과 흑단으로 장식된 부유한 땅으로, 모든 썩어가는 자들이 그것이 잠든 동안의 혼란을 감지했다. 지폐의 액면가는 같은 무게의 금으로 바꿀 수 있으며, 그 항로를 장악하면 극히 적은 비용으로 수천 배의 부를 이끌어낼 수 있다. \n 그러나 이블린은 아마도 그녀의 애매하고 추적하기 힘든 기괴한 혈통이 초래한 신경질 때문에, 이 여자는 선조의 메시지를 확신하고 있었다. 동방에는 그들이 믿는 이교의 신들이 있으며, 마치 심해의 어떤 물고기처럼 유혹적인 미끼를 흔들며, 먹이를 서서히 잡아들이는 것이다. \n 그녀는 틀렸다. 해성에는 바다의 짠맛이 전혀 없다. \n 오직 층층이 쌓여, 향기롭고도 두렵게 만드는 백목련만이 존재할 뿐이다. \n 나와 아버지를 동시에 빠뜨린 백목련. \n 내가 그녀를 보았을 때, '서'라는 이름의 여자의 모습이 내 시선에 들어온 첫 순간, 나는 영원히 이 고대의 땅에서 빠져나갈 수 없게 되었다. \n 그녀는 가까이 다가가고 싶게 만들고, 소유하고 싶게 만들고, @3\n 그녀는 끊임없이 끊임없이 끊임없이 끊임없이 끊임없이 원하게 만든다……@2@3@2!!\n 아, 내가 왜 여기에 왔는가? 나는 무엇을 가져가려 하는가? 나는…… 누구인가? \n 더 이상 중요하지 않다. 그녀가 나를 초대했고, 나는 그 대저택의 테이블에 앉아 있었다. \n 이미 나와 같은 미친 아버지는 순종적인 미소를 지으며, 화려한 반찬들이 식탁을 가득 메우고, 금속 뚜껑이 있는 접시가 어색하게 놓여 있었다. \n 서는 빛을 거슬러 저녁 해 속에 앉아 있었고, 그 빛은 그녀에게 부드러운 금 테두리를 만들어 주었다. 천천히, 그 검은 부채가 내려갔다. \n 이블린처럼, 어릴 적의 친구처럼, 흐릿한 만남처럼…… 내 어머니처럼. \n 그것은 마치 사원에 있는 금빛 신상처럼 단정하고 아름다운 얼굴이었다. \n 나는 흡입하는 소리를 듣지 못했고, 아버지에게서 나는 비린내도 맡지 못했으며, 그저 그 얼굴과 그 얼굴의 주인이 내게 하얀 손을 내밀어 접시를 열고, 적당한 고기를 집어 들며, 두 개의 가는 나무젓가락으로 그것을 집어 올리는 것을 매료되어 바라보았다. \n 그녀는 나를 부르며, 구워진 동물의 기름이 내 입가에 떨어졌다. \n \"작은 선생님, 당신은 뭔가 먹어야 합니다.\" \n 나는 순종적이고 둔하게 입을 벌렸다. \n\n 백목련이 이미 피어 있었다. 그것은 나에게 조용히 매달려 있었다. \n —— \"무명자의 손기록\" \n"
  },
  CollectionHall_124404_Title = {
    Text = "백합의 미끼"
  },
  CollectionHall_124405_Desc = {
    Text = "「이성을 등불로 삼으면, 인생의 안개를 걷어낼 수 있다.」\n언젠가, 모샤는 이런 말을 들은 적이 있었다.\n어쩌면 소로 컴퍼니의 기술자가 구무등을 조정하면서 무심코 내뱉은 감상이었을까? 아니면 필린겐 레스토랑에 갔을 때 어떤 행인이 던진 농담이었을까?\n모샤는 이미 잊어버렸다. 그녀가 선명하게 기억할 수 있는 것은, 그 말을 들었을 때 자신의 얼굴에 떠올랐던 습관적인 사교적 미소와, 그 미소 뒤에 감춰진 조소뿐이었다.\n「등불? 하, 무슨 구닥다리 골동품이야, 요즘 사람들은 손전등을 쓴다고.」\n그녀는 그것이 비유에 불과하다는 걸 모르는 게 아니었다. 다만 이해할 가치가 없다고 여겼을 뿐.\n어차피 언젠가 그녀는 죽을 것이다. 그리고 죽음 이후에는, 무슨 이성이니 안개니 하는 것들은 더 이상 존재하지 않는다——그녀는 이 세계에서 완전히 해방될 것이다.\n이것은 합리적이고 필연적인 추론이었다. 그녀가 해야 할 일은, 그 「필연」이 도래하기 전의 과정을 즐기는 것뿐.\n하지만 아무도 그녀에게 말해 준 적이 없었다. 「필연」도 「우연」과 마주칠 수 있다는 것을.\n비슷한 안개, 비슷한 곤경, 하지만 여기에는 구무등도, 조사단도, 그녀에게 익숙한 그 어떤 것도 없었다. 그녀의 도끼는 세상의 괴물을 베어낼 수 있었지만, 자신의 고독과 혼란이 피어낸 안개는 베어낼 수 없었다.\n돌아갈 수 있을까? 돌아가게 될까? 도대체 언제 돌아갈 수 있는 걸까……\n하나 또 하나의 질문이 마음속에서 떠올랐고, 보이지 않는 깊은 물처럼 천천히 그녀의 마음을 삼켜 갔다. 이 순간, 그녀의 마음속 유일한, 전부인 생각은——\n이성을 유지해라.\n미치지 마! 미치지 마! 미치지 마!\n저 세계의 안개든, 이 세계의 안개든, 자기 내면의 안개든.\n다시, 돌아가기 위해."
  },
  CollectionHall_124405_Title = {
    Text = "이성의 등불"
  },
  CollectionHall_124407_Desc = {
    Text = "일곱 번째 생일날, 아버지는 「모이라이」라는 이름의 물레를 그녀의 무릎 위에 올려놓았다. 그 이름은 이미 아무도 제사 지내지 않는 세 운명의 여신에게 속한 것이었으나, 물레 자체는 매끄럽고 새것이었으며, 구리 축은 금속 광택을 띠며 차갑고 묵직했다.\n그때부터, 아라크네는 운명의 물레를 들었다. 선택이 아니라, 무심코 내뱉은 말들이 훗날 어김없이 실타래현되었기에, 그녀는 이 운명적인 책임을 외면할 수 없었다.\n그때부터, 그녀는 쉬지 않고 짜 나갔다. 하루 또 하루, 운명의 실타래이 정밀한 물레 위에서 소리 없이 돌아가는 것을 바라보며, 세상 사람들을 위해 첫 입맞춤의 떨림, 전마의 울음, 갓난아이의 첫울음, 그리고 묘비 위의 거친 각인을 짜냈다.\n그때부터, 그녀는 수만 갈래로 엇갈리는 실타래 속에서 「더 나은」 방향을 골라, 칠흑의 역병을 일찍 물러나게 하고, 역사가 전화를 피하게 하고, 문명이 폐허 속에서 재건되도록 했다……그와 동시에, 광기와 배신, 혹은 영원한 어둠으로 향하는 실타래도 짜냈으니, 오직 시공을 가로지르는 운명의 그물을 유지하기 위해서였다.\n「무엇이 더 나은 것일까?」\n침묵하는 물레는 대답하지 않고, 다만 계속 돌아갈 뿐이었다. 좋은 것, 나쁜 것, 탄생과 부고가 같은 한 올의 실타래 위에서 번갈아 나타났다. 그때 젊었던 그녀는 자신의 숙명이 무엇인지 아직 알지 못했으나, 이미 수없이 많은 실타래 끝에서 세계의 종말을 내다보고 있었다.\n「만약 세계가 멸망의 숙명을 피할 수 없다면……」\n「아니, 나는 이 세계를 사랑해.」\n아라크네는 물레를 응시하며, 입 밖에 내지 못한 생각을 버렸다.\n「그렇다면……나의 숙명은?」\n그녀는 중얼거렸고, 텅 빈 메아리만이 사방 벽 사이를 떠돌았다.\n……\n셀 수 없이 많은 문명이 운명의 그물 위에서 일어나고 무너졌다. 피라미드는 모래 속에서 잠들고, 우주선은 별의 바다를 스쳐 지나가고, 언어는 계절의 순환처럼 바뀌고, 신들의 이름은 먼지 쌓인 사전 속에 적혀 갔다……그리고 그녀는 시종 그 자리에 앉아, 손안의 물레를 돌리며, 인류가 희망과 멸망의 순환을 되풀이하는 것을 지켜보았다.\n어느 날, 한 줄기 부름이 영원의 감옥과 만고의 적막을 초월했다.\n「언니……」\n그녀는 마침내 종말을 향하던 시선을 거두고, 눈을 감아 네프레아를 바라보았다. 자신의 몸속에 있는 또 다른 자신——갓 태어난 아이처럼 순수한 그 눈에는 심판도, 공포도 없었고, 오직 온전한 신뢰만이 있었다. 마치 아직 한 글자도 적히지 않은 백지처럼.\n그 순간, 아라크네는 마침내 깨달았다. 사랑과 책임, 증오와 멸망, 모든 것이 운명 앞에서는 다를 바 없다는 것을. 그리하여 그녀는 자신의 손으로 잘라 내고 버렸던 기억들, 일어났어야 하나 결코 찾아오지 않았던 고통과 후회와 상실타래을, 한 올의 실타래로 엮어 가장 무겁고도 가장 부드러운 선물로 삼아, 네프레아의 손목에 묶어 주었다.\n「이곳을 떠나렴, 네프레아.」 아라크네는 미소 지었다. 「너는 자유야.」\n아라크네는 더 이상 자신의 숙명을 알 필요가 없었다. 일곱 살 그해 물레를 들어 올린 순간, 그녀는 이미 미래의 방향을 선택했기 때문이다. 그리고 숙명의 물레는 조용히 돌아가며, 그녀가 곧 몸을 던질, 결코 막이 내리지 않을 전투를 지켜볼 것이다."
  },
  CollectionHall_124407_Title = {
    Text = "숙명의 물레"
  },
  CollectionHall_124410_Desc = {
    Text = "먹어치워! 먹어치워! 먹어치워! 먹어치워!……\n환혹의 악몽.\n부숴! 부숴! 부숴! 부숴!……\n대해의 꿈결의 속삭임.\n파괴하라! 파괴하라!! 파괴하라!!! 파괴하라!!!!\n억제할 수 없는 광란.\n「모스크가 배고파요.」\n소녀는 흐르는 피의 고기를 삼켰지만, 아무리 먹어도 배 속의 공허함은 해소되지 않았다.\n「모스크가 목말라요.」\n소녀는 비린내 나는 바닷물을 삼켰지만, 아무리 마셔도 목의 건조함은 해소되지 않았다.\n「모스크가 졸려요.」\n소녀는 마비된 자신을 때렸지만, 아무리 자도 생각의 피로는 억제되지 않았다.\n오직 순수한 파괴만이 내면의 그를 만족시킬 수 있기 때문이다.\n「하지만, 모스크, 안 돼!」\n그러나 소녀는 숙명의 호출을 거부했고, 특수 제작된 강철은 그녀가 벗어날 수 없는 감옥이 되었다.\n그녀는 자신을 견고한 감옥으로 만들어, 자신의 억제를 통해 심해에서 온 광란을 가두었다.\n「모스크, 가두었어, 나쁜 놈!」\n이로써, AF 1■■가 나타난 이후, 수많은 생명체를 포식한 거대한 소용돌이 모르스크스는 AF 31■에서 완전히 침묵에 빠졌다.\n\n\n\n\n"
  },
  CollectionHall_124410_Title = {
    Text = "갇힌 광란"
  },
  CollectionHall_124413_Desc = {
    Text = "책장에는 지루한 연구 문헌 외에도 꽤 재미있어 보이는 아동 도서 몇 권이 꽂혀 있었다.\n《신데렐라》, 《백설공주》, 《인어공주》, 《라푼젤》…… 이 책들의 주인이 왜 이것들을 책장에 꽂아 두었는지—지금은 알 길이 없다.\n그 이야기들은 현실타래과는 전혀 다른 줄거리를 엮어내고 있었다. 「왕자」, 「공주」, 「사랑」…… 이 단어들이 소녀의 마음을 두근거리게 했다.\n밤하늘에서 반짝이는 수많은 빛이 대지 위로 쏟아져 내려, 마치 흐르는 빛의 강을 이룰 것만 같았다.\n쏟아지는 달빛 속에서 소녀는 살며시 발끝을 세우고, 투명한 유리 구두를 신은 척했다. 마치 줄곧 기다려 온 것처럼—이 깊고 고독한 기나긴 밤이 마침내 밝아 오기를……"
  },
  CollectionHall_124413_Title = {
    Text = "진흙 속의 동화"
  },
  CollectionHall_124414_Desc = {
    Text = "상선과 상선 사이를 떠돌며, 항상 낡은 삼베 옷의 그늘 속에 몸을 숨기던 늙은 마녀는 나침반이 사람들을 그가 가야 할 곳으로 인도할 것이라고 말했다. 수레주인들은 장난치며 약초 냄새 나는 그녀의 헛소리를 비웃고, 다섯 플로린을 던져주고 이 정교한 황동 장식품을 가져갔다.\n그리고 그들은 나중에 이름을 잃은 작은 마을 항구에 정박했고, 폰토스는 이 이야기를 좋아했으며, 나침반의 주인은 폰토스를 좋아했다.\n물론, 유머러스하고, 명랑하며, 바람처럼 자유롭게 오가는 폰토스를 좋아하지 않는 사람은 없었다.\n그것은 원래 좋은 기념품이 되어야 했고, 폰토스가 사랑하는 조카에게 전해준 후 먼 저편에 대한 상상을 열어주는 키가 되어야 했다—하지만 그것은 폰토스가 그를 찾지 못하게 했고, 폰토스는 허락하지 않았으며, 절대로 그의 삶에 다른 가능성이 생기는 것을 용납하지 않을 것이었다.\n많은 세월이 흐르고, 폰토스가 달빛 속에서 수많은 밤을 헤치며 에포양스로 돌아와야 할 그 모습을 찾아 헤맬 때, 그는 이렇게 생각했다.\n오, 그 헛된, 보호의 마법이 그에게서 떠났으니, 폰토스는 이제 그를 데려올 수 있다.\n단지 폰토스는 아직 몰랐다, \"나침반은 사람들을 그가 가야 할 곳으로 인도할 것\"이라는 것을, 마치 모든 배에 자신의 항로가 있듯, 서로 다른 사람은 항상 서로 다른 방향을 선택한다는 것을."
  },
  CollectionHall_124414_Title = {
    Text = "갈림길을 가리키는 나침반"
  },
  CollectionHall_124415_Desc = {
    Text = "「성냥 사세요… 성냥 사세요…」 겨울밤, 손발이 새빨갛게 얼어붙은 소녀가 중얼거렸다. 「한 냥만요, 한 냥만 사주세요.」\n\n「미안하지만, 네 성냥은 안 살 거야.」 순백의 그림자가 살짝 몸을 숙이며 겨울의 달을 가렸다. 「반대로, 나는 너한테 뭔가를 팔려고 왔다구.」\n\n「하지만, 저는 돈이 없는걸요……」\n\n「괜찮아. 요정의 축복을 믿어봐, 곧 성냥이 다 팔릴 테니까.」\n\n하얀 옷의 요정이 소녀의 손에 사탕 하나를 쥐여 주고선, 소녀의 귀에 입을 댔다.\n\n「저기 길 건너편에 털 외투를 입은 중년 아주머니 보이지? 그 아주머니 치맛자락을 붙잡고서, 악착같이 울어. 『아주머니, 날씨가 너무 추워요… 제 할머니가 위독한 병에 걸리셔서, 한 끼라도 배부르게 먹지 못하시면 곧 돌아가시고 말 거예요… 제발 한 푼만 주세요.』 라고 말해.」\n\n「하지만 할머니는 오래전에 이미……」\n\n「그럼 더 좋네! 그때 그 느낌을 생각하면서 더 구슬프게 우는 거지……」\n\n「그래도 인색해하며 돈을 꺼내지 않는다면, 내게 또 다른 방법이 있어. 이런 연말 저녁에 밖을 배회하는 사람은, 분명 가정이 평안하지 않은 법이지. 뒤에 이렇게 덧붙여 봐. 『할머니는 제 유일한 가족이에요. 연말에는 누구도 혼자가 되고 싶지 않은 법이잖아요. 부탁이에요, 아름다우신 부인. 동전 세 닢만 주세요, 빨리 성냥을 팔아서 할머니와 함께할 수 있게요.』」\n\n「성냥은 한 닢인데……」\n\n「남은 두 닢 중 한 닢은 내 몫이고, 나머지 한 닢은 그분께 바치는 거야.」 카라부가 마법봉을 흔들자, 잠든 하얀 유충이 물결처럼 흘러내렸다.\n\n「깊게 생각하지 마. 요정의 축복을 믿으면 돼, 이 방법은 백발백중이니까. 기억해, 그녀가 돈을 꺼내기 전까지 절대 손을 놓지 마. 실타래패하면, 다른 외로운 부잣집 부인을 찾으면 되는 법이니까. 걱정 말라구, 이 세상에 여유 있게 돈을 가진 여자라면 우리 둘을 먹여살려도 돈이 남을게 분명해.」\n\n백발백중이라는 방법이 왜 실타래패하는지, 더 이상 추궁하려는 사람은 없었다. 어쨌든, 182가지 대본을 갱신한 끝에, 소녀의 성냥은 성공적으로 모두 팔렸다.\n\n진짜 「요정님」이 등장하지 않은 이 이야기에서, 가짜 요정은 얼어 죽기 직전의 가난하고 불쌍한 소녀를 구했다.\n\n해피엔딩이면 된 거지. 그럼, 그럼."
  },
  CollectionHall_124415_Title = {
    Text = "평온한 진실타래"
  },
  CollectionHall_124844_Desc = {
    Text = "<Title:소개>\n타무란에서 온 신비한 소녀. 그녀의 설명에 따르면, 원래는 현지 대학의 준 대학생이었으나, 한 차례 “운명적인 로맨틱한 만남”으로 인해 안개 경계 조사단의 전방이 되었다.\n별빛 새벽회의 “안개 재해 사건”에서 모카는 우연히 이 세계로 소환되었고, 이후 은과 피의 의식에서 그녀는 세례를 받으며 인간에서 깨어남체로 변모하고 “안개 재해 사건”을 끝냈다.\n자신의 세계가 아닌 곳에 있는 그녀는 여전히 돌아갈 방법을 찾고 있지만, 동시에 이 세계의 미래에 대한 흥미를 느끼며 “세계의 결말”을 증언하고 싶어한다."
  },
  CollectionHall_124844_LockTip = {
    Text = "깨어남「모샤」후 잠금 해제"
  },
  CollectionHall_124844_Title = {Text = "무셰트"},
  CollectionHall_125443_LockTip = {
    Text = "제한 시간 이벤트 “해성 구소식: 현녀무상”의 임의 단계 클리어해야 합니다"
  },
  CollectionHall_125443_Title = {
    Text = "해성 구소식: 현녀무상"
  },
  CollectionHall_126315_LockTip = {
    Text = "기간 한정 이벤트 「직조자의 자박: 인형의 무대」의 스테이지 중 하나를 클리어해야 합니다"
  },
  CollectionHall_126315_Title = {
    Text = "직조자의 자박: 인형의 무대"
  },
  CollectionHall_126425_LockTip = {
    Text = "조사 작전 성신편 4-1에서 해제 가능"
  },
  CollectionHall_126425_Title = {
    Text = "머피의 환영"
  },
  CollectionHall_126471_Desc = {
    Text = "모카는 이미 안개의 존재에 익숙해졌다.\n아무리 다루기 힘든 안개이든, 아무리 위험한 안개이든, 그녀는 항상 그 안개 속에서 안전하게 걸어나올 수 있었다.\n이번에도 마찬가지다.\n그녀는 결국 새로운 세계의 안개를 뚫고 자신의 차원으로 돌아갈 것이다.\n어떤 대가를 치르더라도."
  },
  CollectionHall_126471_LockTip = {
    Text = "다차원 연결 “은과 피의 세례” 완료"
  },
  CollectionHall_126471_Title = {
    Text = "새로운 세계의 안개를 벗겨내다"
  },
  CollectionHall_126472_Desc = {
    Text = "안개는 언젠가 사라질 것이다.\n 그때 안개 속에서 울려 퍼지던 비명이 사라지고, 제단 위에 흐르던 피자국이 닦여질 것이다.\n 방황하는 영혼은 해방을 얻고 올바른 길을 찾게 될 것이다 —\n 빛나는 별들로 나아가거나 진실타래한 대지에 남아 있을 것이다."
  },
  CollectionHall_126472_LockTip = {
    Text = "다차원 연결 “은과 피의 세례” 완료"
  },
  CollectionHall_126472_Title = {
    Text = "안개가 사라지는 순간"
  },
  CollectionHall_126473_Desc = {
    Text = "우주는 세계를 잉태하였고, 세계는 생명을 잉태하였습니다. 그리고 서로 다른 세계의 생명은 또 다른 규칙과 이념을 잉태하였습니다.\n그들이 교차할 때, 싸움은 결코 두 개의 육체, 두 개의 의지, 두 개의 생명만이 아닙니다.\n그것은 영원히 평행하다가 갑자기 교차하는 두 개의 우주의 충돌입니다."
  },
  CollectionHall_126473_LockTip = {
    Text = "다차원 연결 “은과 피의 세례” 완료"
  },
  CollectionHall_126473_Title = {
    Text = "신념의 대결"
  },
  CollectionHall_126474_Desc = {
    Text = "작업이 끝난 후, 나는 과거의 나와 작별할 것입니다.\n다시 돌아갈 수 없는 익숙한 과거와 타무란, 그리고 인간이었던 나와 작별할 것입니다.\n나는 안개로 가득 찬 그 세계를 그리워할 것입니다.\n이후, 나는 새로운 신분으로, 안개가 사라진 이 세계에서, 흥미로운 공포의 세계에서 살아갈 것입니다."
  },
  CollectionHall_126474_LockTip = {
    Text = "다차원 연결 “은과 피의 세례” 어려움 완료"
  },
  CollectionHall_126474_Title = {
    Text = "안개 말하는 자의 신생"
  },
  CollectionHall_126475_Desc = {
    Text = "잔혹한 세계에서, 한 사람의 영혼은 쉽게 타버릴 수 있다.\n그래서 우리는 타인과 세계를 탐구하며, 가족애, 사랑, 우정, 향수……\n그 닿을 수 없는 감정은 이로써 보이지 않는 힘으로 변하여, 지속되는 생명으로 사람들을 이 세계에서 좀 더 오래, 더 오래 타게 한다……"
  },
  CollectionHall_126475_LockTip = {
    Text = "다차원 연결 “은과 피의 세례” 완료"
  },
  CollectionHall_126475_Title = {
    Text = "잔인한 생존 지혜"
  },
  CollectionHall_126476_Desc = {
    Text = "고대의 별들은 세계의 탄생, 성장 및 번영을 증언했으며, 또한 세계의 끝을 증언할 것이다. \n 생존을 갈망하는 사람들아, 살아남는 유일한 방법은 우리의 발 아래, 우리를 배반하는 대지에 있지 않고, 우리의 머리 위, 그 영원한 별들이 빛나는 곳에 있다."
  },
  CollectionHall_126476_LockTip = {
    Text = "다차원 연결 “은과 피의 세례” 완료"
  },
  CollectionHall_126476_Title = {
    Text = "별들이 빛나는 곳"
  },
  CollectionHall_126477_Desc = {
    Text = "세상을 구원하는 것은 그녀의 스타일이 아니며, 여기도 그녀의 세계가 아니다.\n하지만 그녀는 수호자의 목소리를 들었고, 세상을 구하기 위해 수호자가 기울인 엄청난 희생을 보았다.\n사람이 목숨을 걸고 지킨 세계는 파멸되어서는 안 된다.\n적어도 이 순간, 그녀가 직접 파괴해서는 안 된다."
  },
  CollectionHall_126477_LockTip = {
    Text = "다차원 연결 “은과 피의 세례” 어려움 완료"
  },
  CollectionHall_126477_Title = {
    Text = "이해할 수 없는 선택"
  },
  CollectionHall_126906_LockTip = {
    Text = "의식 잠수 “부채 아래 밤담화”의 임의의 단계 해금"
  },
  CollectionHall_126906_Title = {
    Text = "야울다집"
  },
  CollectionHall_126989_Desc = {
    Text = "<Title:개요>\n그녀의 진정한 출처는 더 이상 고증할 수 없으며, 이 고대 “신명”에 대한 가장 오래된 기록은 수천 년 전으로 거슬러 올라갑니다.\n모든 사람이 그녀를 바라볼 때마다 서로 다른 얼굴을 보게 되며, 실타래제로는 상대방의 기억을 무의식적으로 오염시킬 수 있는 능력을 가지고 있어, 자신의 형상을 자연스럽게 상대방의 기억 속에 녹여내어 최종적으로 상대방이 자신을 유일하게 중요한 사람으로 인식하게 만듭니다.\n다른 대부분의 깨어남체와 달리, 그녀는 거의 인간의 감정과 시각을 가지고 있지 않습니다.\n그녀는 하나의 생각, 하나의 광상, 하나의 안개——그녀는 서로 다른 사람으로 인식되며, 리우, 리, 취안, 장으로 인식됩니다. 그녀는 환희 속에서 태어났고, 끊임없는 혼란에서 오는 환희를 추구합니다.\n하지만 그녀는 완전히 이해할 수 없는 존재는 아니며, 그녀가 선택한 개체, 그녀에게 극한의 즐거움을 주는 그 개체는 진정으로 그를 정의할 수 있는 이름을 엿볼 기회를 가질 것입니다. 그 이름은 다른 명칭들과 같이 변하지 않습니다.\n“천선현녀”."
  },
  CollectionHall_126989_LockTip = {
    Text = "웨이크업 “서” 후 해금"
  },
  CollectionHall_126989_Title = {Text = "서"},
  CollectionHall_127110_Desc = {
    Text = "양손 대검은 길고 무거워 충분한 힘으로 사람을 두 조각으로 자를 수 있다. \n\n다거는 가볍고 민첩해 숨기기 쉽고, 뜻밖의 공격에 매우 적합하다. \n\n커브가 아름다운 날도는 칼날이 날카로워 찔러 넣을 때 쉽게 살갗에 박혀 깊은 상처를 남긴다. \n\n총은 빠르고 강력하며, 석궁은 소리 없이 빠르게 날아간다. 다양한 금속 부품들이 조명 아래 차가운 빛을 발산한다. 열 살의 라몬나는 벽 가득 채워진 무기 앞에 서서, 그녀의 나이와 어울리지 않는 성숙함과 진중함을 표정에 담고 있었다. \n\n“어떤 걸 고르겠니?” 양부——아니, 자신을 키워준 아버지——의 목소리가 뒤에서 들려왔다. “결정되면 내가 너에게 선생님을 찾아줄 거야.” \n\n어떤 걸까? 대검의 무게는 장점이자 단점이다; 다거는 긴 무기에 대응하기 어렵다; 커브 날도는 길지만, 절단은 항상 불필요한 손상을 가져온다; 총은 소음이 크고, 석궁은 탄약이 쉽게 고갈된다. \n\n미사그 훈련장에서 며칠 동안 관전하면서, 그녀는 전투 양측의 약점을 한눈에 알아볼 수 있었고, 공격 경로를 거의 직관적으로 계획할 수 있었다. 그런 많은 경험을 쌓아야 알 수 있는 것들이 그녀에게는 단 한 초면 충분히 추론할 수 있었다. 아니, 그녀가 원하는 것은 그것이 아니다. 그녀는 더 정확하고, 가장 적은 힘으로 최대의 데미지를 입힐 수 있는 무기가 필요했다. \n\n여자아이는 잠시 고민한 끝에, 옆에서 의자를 가져와 올라가 높은 곳에 걸린 래피어를 손으로 잡았다. \n\n세밀하고 우아하며, 민첩하고 가벼워 정확하게 피해를 입힐 수 있다——맞아, 바로 이거다. 이건 그녀의 모든 요구사항을 충족시킨다."
  },
  CollectionHall_127110_Title = {
    Text = "거꾸로 가는 시계"
  },
  CollectionHall_127111_Desc = {
    Text = "「세상이 종말로 향할 때, 어떤 재미난 것이 일어날까?」\n무셰트는 그것에 대해 알지는 못했지만, 기대에 가득찼다.\n이런 기대는 이전의 것과는 사뭇 다르다. 이번에는 고대 유물 몇 개를 파는 조그마한 재미가 아니라, 하나의 세계를 기준으로 한 연구와 조사이기 때문이다. 그리고 이 연구와 조사에서 가장 중요하고 핵심적인 것은 단 한 사람——\n바로 미사그의 수호자이다.\n「난 이 세계를 구원할 거야……」\n「이 세계를 결코 붕괴할 운명으로 향하게 만들지 않을 테니까……」\n하나의 세계의 흥망성쇠를 짊어진 사람이 이렇게 이상에 가득찬 마음으로 약속하는 것에 대해 무셰트는 감동한 표정을 지어야 한다는 걸 알고 있었다. 이건 인류 사회의 관습적인 사회적 예의이니까.\n하지만, 그녀는 더 이상 위장하고 싶지 않았다. 아니, 수호자가 @4를 정면으로 대면하고, 자신의 대가로 하나의 세계가 구원되는 것을 보며 우주적인 공포를 겪은 사람에게는 결코 위장할 필요가 없다고 느꼈기 때문이다.\n「위장」은 인류 사회의 게임 규칙으로, 격식은 있나 지루하다. 반면 우주는…… 우주는 진실타래하고 직설적이다——\n살거나, 파괴되거나. 둘 중에 하나.\n그래서 그녀는 수호자에게 한 대답도 진실타래하고 직설적으로 전했다.\n「나는 이 세계가 구원받을지, 아니면 파괴될지 솔직히 상관없어…… 그보다 나는 네가 더 궁금해.」\n나는 네가 이상을 실타래현할 수 있을지, 아니면 이상을 추구하는 길에서 무너질 것인지 궁금하다.\n또한 이 세계가 당신의 소원에 응답할지, 아니면 피할 수 없는 파괴로 향할지도 궁금하다.\n어느 쪽이든, 그건 성대하고 흔치 않은 재미가 될 것이기 때문이다.\n나는 그때를 항상 고대하고 있다……\n내 눈으로, 내 도끼로, 기다리고 있을 것이니."
  },
  CollectionHall_127111_Title = {
    Text = "광란의 세계 끝에서"
  },
  CollectionHall_127112_Desc = {
    Text = "“기억이 무엇인가요?”\n“당신이 잊은 것이라네.”\n\n리리는 기억력이 나쁜 엄마를 가지고 있었다.\n그녀는 리리를 밥을 먹으러 부르는 것을 잊고, 리리에게 약을 먹이는 것도 잊었으며, 심지어 리리의 이름까지 잊어버렸다.\n“어떻게 해야 하나요?”\n리리는 병상에 앉아 깊은 한숨을 내쉬었다.\n이런 엄마는 정말 걱정이 많았다.\n\n그 후, 리리는 자신의 이름을 나무 패찰에 써서 매일 가슴에 걸었다.\n이제는 기억해줄 거야?\n처음에는 엄마가 웃으면서 그녀가 불필요하다고 말했고, 그것은 오랜 피로로 인한 합병증이라고 했다.\n\n차츰, 그녀는 혼란스럽고 짜증이 났다:\n“리리…… 리리는 누구야?”\n호박색 눈는 리리를 바라보며 약간의 경계심을 담고 있었다.\n원래, 단어의 의미도 잊혀질 때, 언어에 의존하여 일시적으로 유지된 화목함은 결국 사라지고 말았다.\n\n리리는 엄마를 껴안았다.\n모녀의 심장 소리는 겨우 몇 인치를 사이에 두고 있었지만, 그녀는 매우 외롭다고 느꼈다.\n\n그날 이후, 리리는 나무 패찰을 거두고, 엄마에게 애교를 부리지 않았으며, 자신이 며칠 동안 굶었다는 것을 상기시키지도 않았다.\n그녀는 죽음을 기다리는 환자로, 무감각하게 사망 선고를 기다렸다.\n그녀는 멀리서 자신이 주사받고 마취되고 엄마가 원하는 모습으로 조작되는 것을 지켜보는 관객이었다.\n모녀 간의 즐거운 대화와 부드러운 포옹……\n그 모든 환상적인 거품이 반짝이는 즐거운 추억들은 리리가 조심스럽게 마음에 잠그고 있었다.\n오직 어떤 피곤한 밤들에만, 그녀는 그것들을 꺼내어 살짝 핥았다."
  },
  CollectionHall_127112_Title = {
    Text = "고통을 넘어"
  },
  CollectionHall_127113_Desc = {
    Text = "고대의 탑이 굉음과 함께 무너지며, 서로 다른 시공간과 종족에 속한 학자들이 저술한 책들이 사방에 산재했다. 단 한순간, 크고 작은 검은 삼각형들이 모든 책과 벽돌을 덮었고 순식간에 연결되어 주변으로 빠르게 확산되었다. \n검은 점액은 용암처럼 정돈된 거리 위를 흘러가며 사람들을 공포에 몰아넣었다. 사람들은 비명을 지르고 울부짖으며 이 끔찍한 재앙에서 벗어나려 했다. 일부는 교통수단을 이용해 도망치려 했지만, 황란 속에서 건물이나 사고 난 우주선 및 차량과 충돌했다. 많은 이들이 반응할 틈도 없이 도보로 점액에서 멀어지려 달렸지만, 같은 공포에 질린 사람들에게 밀려 넘어져 결국 점액에 동화되었다. 어린아이가 길가에서 크게 울었고, 몇몇 젊은이는 남아 있는 방에 숨어 이렇게 하면 죽음을 피할 수 있을 것이라 망상했다. \n“분명히 아무런 예고도 없었는데, 왜, 왜!” \n“왜 아무도 우리에게 경고하지 않았나요!” \n“@1, 융식이다! 도와줘!” \n“의식 이동을 빨리 해! 그것만이——아!” \n“@2, 장비를 사용해!” 어떤 목소리가 말했다, “우리가 시간을 벌어줄게!” \n“안 돼! 나——” \n“우린 이미 @1에 당했지만, 너는 희망이 있어.” 부드러운 목소리가 답했다, “살아남아, @2, 살아남아. 그리고——” \n\n벤코르가 눈을 번쩍 뜨자, 그녀 주변에는 높이 쌓인 책들과 커피 얼룩이 가득한 여러 개의 머그잔이 있었다. 멀지 않은 곳의 칠판에는 크고 작은 메모와 노트가 붙어 있었고, 중간에 연산이 절반 진행된 공식이 적혀 있었다. 어질러진 방 구석, 중앙, 그리고 그녀가 앉아 있는 거대한 기계 옆에는 조명이 설치되어 있어 사무실타래 전체를 매우 밝게 비추고 있었다. \n그녀는 잠시 침묵하더니 몸을 위치 측정기에 더 깊이 감싸며 중단했던 연산을 계속했다."
  },
  CollectionHall_127113_Title = {
    Text = "끝나지 않는 계산"
  },
  CollectionHall_127114_Desc = {
    Text = "통증, 극심한 통증이 그녀의 모든 감각을 채웠다. \n\n금속으로 만든 잠수복은 수압 아래에서 아무런 가치도 없었고, 외피는 안쪽으로 웅크려들었으며 나사가 터져 나갔다. 무언가가 그녀의 복강을 누르고 있었고, 무언가가 그녀의 팔을 관통했다. 차가운 해수가 잠수복의 파손된 부분으로 들어왔고, 두꺼운 금속으로 만들어진 헬멧만이 겨우 원래의 모습을 유지하며 그녀에게 약간의 산소를 제공했다. \n\n헬멧의 유일한 탐색창을 통해 그녀는 바깥의 바닷물이 청록색에서 검은색으로, 다시 검은색에서 깜깜해지는 것을 보았다. 숨을 쉬면서 생긴 수증기가 유리에 응결되었고, 소용돌이의 끊임없는 소리가 점점 멀어져 귀 속에서 남아있는 환영이 되었다. 그녀는 사지를 느낄 수 없었고, 숨 쉬기도 점점 힘들어졌다. \n\n그녀는 자신이 실타래신했을 것이라고 추측했다. 추위, 출혈, 산소 부족, 어느 하나라도 그녀의 의식을 흐리게 할 만큼 충분했다. 동시에 그녀는 확신할 수 없었다. 왜냐하면 그녀가 어떻게 눈을 깜빡여도 마주하는 것은 항상 같은 어둠이었기 때문이다. \n\n여기는 빛이 도달하지 못하는 곳, 아직 인간이 탐지하지 못한 바다의 깊은 곳이다. \n\n미지의 영역, 마지막 모험. 그녀는 이렇게 하여 꿈을 이룬 것일까? 지금은 아무것도 볼 수 없지만. \n\n발목에서 이상한 감각이 전해졌다. 그녀는 본능적으로 고개를 숙여 보았는데, 어둠 속에서 무언가가 종아리를 타고 올라오는 듯했다. 특이한 심해 생물일까? 어떻게 해수보다 더 차가울 수 있을까? 어떻게…… 이런 어둠 속에서 그녀는 그 물체의 윤곽을 볼 수 있는 것 같았다. \n\n검은색의, 기어가는, 진흙처럼…… \n이것은 무엇인가? 그녀는 어디에 있는가? 그녀는…… 누구인가?"
  },
  CollectionHall_127114_Title = {
    Text = "기억의 나선"
  },
  CollectionHall_127115_Desc = {
    Text = "(이하 답변은 클레멘틴의 진료 수첩에서 발췌한 것으로 참고용입니다)\n\n1. 케이크스.\n2. 16, 17……? 하늘만 알죠.\n사람이 죽은 후에 이런 쓸데없는 걸 신경 쓰겠어요?\n3. 망해버린 작은 어촌 마을이야. 지도 어디에서도 그 이름을 찾을 수 없어.\n4. 말하고 싶지 않아.\n5. 괴물. 못생긴 놈. 멍청이. 바보@1……이런 게 좀 더 흔하지.\n6. 반짝이는 황금 메기 얼굴, 줄여서 메기 얼굴.\n7. 비 오는 날.\n8. 모릅니다. 비가 내릴 때면 해변을 왔다 갔다 하곤 했어요……\n몇 년간 멀리만 바라보고 다른 건 하지 않았어요.\n9. 내가 말했잖아! 나@1%모르겠다@1꺼져!!\n-------\n14. 음……혹시 오언 삼촌이 비 오는 날 큰 돛단배를 타고 와서 나를 “집”으로 데려가겠다고 말했던 것 같아……\n15. 그래요, 그는 약속을 지켰어요……\n나는 바닷속에서 며칠 동안 떠다녔어요. 목도 말랐고 배도 고팠고 온몸이 아팠어요……\n그때 오언 삼촌과 그의 하얀 돛단배를 봤어요.\n그분의 모습이…… 아니 정확히 말하면 그의 뼈가 돛대에 걸려 있었어요——그도 변이에 실타래패했죠.\n그리고 나는 마지막 힘을 짜내 그쪽으로 떠갔고, 돛대에 앉아 그와 함께 있었어요.\n16. 우리는 함께 집으로 돌아가기로 했어요."
  },
  CollectionHall_127115_Title = {
    Text = "상처받은 지느러미"
  },
  CollectionHall_127116_Desc = {
    Text = "“사람들은 조류가 밀려올 때 태어나고, 조류가 빠져나갈 때 죽는다.”\n이는 닝피아의 고향에서 항상 전해져 내려오는 전설이다.\n\n세바다의 주민들은 죽음을 두려워하지 않았다. 그들에게 있어 생명의 싹트기와 시들어가는 것은 마치 조수의 밀물과 썰물처럼 자연의 일부였다.\n그들은 푸른 하늘, 바다, 무리 지어 날아다니는 갈매기, 그리고 아침 햇살을 맞이하며 피어나는 수련을 사랑했다.\n그들은 증기, 철길, 그리고 모든 인위적인 개입 흔적이 짙은 사물을 혐오했다—생명에 대한 개입도 포함된다.\n자신의 생명을 인위적으로 끊는 것은 세바다 사람들에게 받아들일 수 없는 일이었다.\n\n닝피아는 전형적인 세바다 사람이 아니었다.\n예를 들어, 그녀는 침몰한 배의 분위기에 항상 끌렸다.\n죽은 침몰선은 수많은 생명체들의 집이었다: 물고기, 수초, 다양한 조개류……\n여기서 생명과 죽음은 신비롭고 거룩한 방식으로 얽혀 있었다.\n닝피아는 침몰선에 다가가며 평온함을 느꼈고, 마치 매우 엄숙한 대성당에 들어서는 것 같았다.\n\n아버지가 그녀를 외출하여 마음을 풀게 해주던 시절에, 닝피아는 다섯 막으로 이루어진 연극을 본 적이 있었다.\n그 연극의 내용은 닝피아에게 이미 희미해졌지만, 고대의 한 황제의 일생을 다루었던 것 같다.\n그는 생전에 남북을 정벌하며 전쟁을 벌였지만, 부끄러운 음모로 죽었다.\n그녀는 연극 속 한 줄을 기억했다:\n<Italic:겁쟁이는 죽기 전에 이미 여러 번 죽었지만, 용사는 한 번만 죽는다.>\n\n수년 후, 닝피아가 차가운 바닷물에 발을 들여놓으며 삶에 대한 애정으로 고통받을 때, 그녀의 머릿속에 그 문장이 떠올랐다:\n“용사는 한 번만 죽는다……”\n그래서 그녀는 눈물을 닦고, 마지막으로 부모님께 안녕히 계세요 하고, 침몰선으로 계속 걸어갔다.\n그녀는 자신의 용사가 될 것이다."
  },
  CollectionHall_127116_Title = {
    Text = "부패의 선물"
  },
  CollectionHall_127117_Desc = {
    Text = "@1년 6월 5일\n알비노가 융식 균열에서 몇 개의 희귀한 은심을 가져왔다. 정말 그답다.\n제련 방법을 개선했다.\n이번에는 충분한 양의 이산화탄소와 염소 가스를 통입하여 저온에서 증발시키고 결정화시켰다…\n기계적인 절차라서 기록할 것이 없다.\n\n@1년 6월 6일\n실타래험체 024의 내장과 지간을 절단했다.\n알비노가 진료소에서 가져온 소재로, 13개의 융식구멍이 형성되었고 최대 직경은 8mm이다.\nOS-106번 융식 괴물의 부속물을 절단했다.\n각종 테스트 데이터를 비교한 결과, 024와의 공명 상성이 가장 높았다.\n유일한 문제는… 그 터치 월들이 너무 “활발”하다는 것이다.\n상당히 오랜 시간 동안 낙지 먹는 걸 원하지 않을 것 같다.\n결과가 실타래망스럽지 않기를 바란다.\n\n@1년 6월 6일\n접합 실타래험이 성공했지만, 실타래험체의 모든 생명 징후가 사라졌다.\n이는 흔한 상황으로, 접합 부위에 감염이 확산되지 않았다면 문제가 없다.\n1주 동안 관찰실타래에 보내 관찰하도록 하겠다. 그 다음부터는 내 일이 아니다.\n오늘 「내부 저널」에서 활인 깨어남체 실타래험을 비난하는 두 편의 글을 읽었다.\n말할 것도 없이, 서명을 보면 내가 미사그에서의 옛 친구들임을 알 수 있다.\n참 웃기지 않나, 이들 중 어느 누구도 그들의 비만한 엉덩이를 조금이라도 움직여 실타래험실타래을 돌아보면, 나의 결론이 흔들리지 않는다는 것을 알게 될 것이다.\n024의 실타래험은 훌륭한 반격이 될 것이다.\n\n@1년 6월 22일\n2주가 지났는데도 024의 모든 체증은 여전히 불안정하다—혹은 이렇게 말하자면, 그녀 체내의 인격이 세포 유사 분열의 속도로 광적으로 증식하고 있다.\n실타래험은 상상도 할 수 없는 방식으로 실타래패를 선언했다.\n024를 왁스상관에 보내버릴까, 매일 나를 지키며 내 어리석음과 경솔함을 상기시키는 것은 원하지 않는다."
  },
  CollectionHall_127117_Title = {
    Text = "이형체의 포식"
  },
  CollectionHall_127118_Desc = {
    Text = "그것은 은백색이고 맑으며 먼지 하나 없는 마음이다. \n 그것은 순은으로 만들어져 있으며, 기계 구조의 심장에서 규칙적으로 박동하고 있다. \n 또한 혈육에 잠식당했고, 진흙으로 오염되기도 했다. \n 하지만 죽음의 그늘 아래 있을 때, 결국 그것은 본래의 모습으로 회귀했다."
  },
  CollectionHall_127118_Title = {
    Text = "순수한 은빛의 초심"
  },
  CollectionHall_127119_Desc = {
    Text = "시간이 흐르면서, 로탄은 행성의 초생 시기의 기억을 거의 잊어버렸다. \n그녀는 단지 자신이 선택받은 존재라는 것만 기억할 뿐이다. \n\n그것은 모든 개념이 탄생하기 이전의 이야기이다. \n“생명”은 아직 뿌리를 내리지 않았고, “신성”은 천외에 있었다. \n이 혼돈의 성운 속에서, 카오스와 카오스가 충돌하고 물질은 충격과 교란 속에서 점차 형체를 갖추어 갔다. \n별들이 먼지를 흡수하고 암석이 산맥으로 솟아올랐으며 대기가 강대한 수역으로 가라앉았다. \n그리고 마침내 이곳은 한 “행성”으로 선포되었다. \n\n카오스의 영혼은 시간의 감옥에 갇혀 신생의 대지를 들이받았다. \n폭렬적인 본성을 제어하지 못하고 파괴 욕구에 사로잡힌 그는, 수많은 산맥을 무너뜨렸다. 또 수많은 강과 늪을 메웠다. \n그리고——“신성”이 먼 별을 건너 황무지의 행성에 강림했다. \n\n“신성”은 문명의 씨앗을 가져왔고 카오스의 영혼을 “질서”의 육체에 가두었다. \n“나와……이런 약속을 해주겠니?” \n포효하는 카오스 정령 앞에서 흰 베일을 두른 “신성”이 조용히 말했다. \n“위대한 문명이 여기서 탄생할 것이다.” \n“당신은 무위의 지혜로운 자와 만나고 방황하는 날카로운 칼날과 맞서 싸울 것이다……미래에는 더 이상 파괴와 멸망에 지배되지 않을 것이다.” \n“그날이 오기 전까지……우리가 재회하기 전까지, 나를 대신해 이곳을 지켜주길 바란다.”"
  },
  CollectionHall_127119_Title = {
    Text = "별하늘의 짐승"
  },
  CollectionHall_127120_Desc = {
    Text = "그는 세상에서 일곱 번의 사계절을 목격했을 때 대공에게 기사로 지명되었다. \n\n대공이 장난으로 한 말이었지만, 모두가 진지하게 받아들였다. \n기사들은 그의 승마와 무술을 가르쳤고, 여관은 그에게 예의를 교육했으며, 공주 또한 이 어린 기사를 신뢰하며 의지했다. \n\n아퀴탄과 협곡의 들판을 걷던 젊은 기사는 공주의 말을 이끌었다. 공주는 힘없이 말 위에 엎드려 있었고, 보이지 않는 어둠이 그녀의 몸을 잠식하고 있었다. \n\n“공주님, 더 이상 앞으로 갈 수 없습니다.” \n이 협곡을 건너고 강을 넘어가면, 그들을 길러준 땅을 떠나게 될 것입니다. \n외부에서는 전쟁이 확산되고, 적군은 비옥한 땅을 탐내며 호시탐탐 노리고 있었다. \n천혜의 요새 덕분에 작은 영토는 간신히 생존해 ‘국가’로서의 존엄성을 유지할 수 있었다. \n협곡의 이쪽에서 그들은 맞은편의 멸망과 고통을 목격했다. \n무고한 자들의 기도와 울음소리는 강물에 떨어져, 승리자의 시편이 되었다. \n\n위대한 나라라 할지라도 역사를 막을 수는 없다. \n\n적군은 그의 연약한 손을 잘라냈고, 그는 더 이상 창과 방패를 들 수 없었다. \n적군은 그의 약한 무릎을 부수어, 철기병들이 궁전 문을 부수고 들어오는 것을 막지 못하게 했다. \n기사는 적군의 말 다리를 물어뜯었지만, 적의 폭력을 저지하지는 못했다. \n\n그리고 그는 처음으로 공주가 말했던 ‘검은 역병’을 목격했다. \n\n홍수처럼 쏟아져 나온 검은 액체가 궁전 문을 넘어 철기병들의 다리를 덮쳤지만, 아무도 멈추지 않았다. \n‘검은 역병’이 그의 입과 코로 침투해 폐 깊숙이 스며들었지만, 그는 여기서 쓰러지고 싶지 않았다. \n그때, 너무나 익숙한 목소리가 머릿속에서 직접 울려왔다. \n“네가 해야 할 일은 이미 충분해…… 나의 가장 충실타래한 기사여.” \n\n끝내, 눈앞에는 텅 빈 하얀 공간만 남았다."
  },
  CollectionHall_127120_Title = {
    Text = "기사의 맹세"
  },
  CollectionHall_127121_Desc = {
    Text = "그들은 인간의 미지에 대한 상상에서 탄생했지만, 상상만큼 히스테리컬하거나 사나운 모습은 보이지 않았다. \n\n그들은 이성적이며, 차분하다. \n\n그들은 미래를 위해, 존속을 위해 왔다. \n\n그들은 가장 비정상적이고 믿기 어려운 기적이다. \n\n처음에는 그들의 소리가 벌레의 울음소리 같았다. 하지만 그들의 생각을 완전히 이해한 후, 그 소리는 침묵했다. \n\n그러나 이후로, 소리의 주인들은 그녀가 내리는 모든 결정에 영향을 주려고 했다. \n\n깨어남체로서 깨어난 첫 해, 그녀는 머릿속의 소리와 함께 살아가는 법을 배웠다. \n\n그녀는 의식 속으로 잠입해 형식탑의 일부가 되었으며, 필요한 정보와 지식을 취한 뒤 안전하게 현실타래로 돌아왔다. \n\n“검은 역병”이 이 몸을 찾아왔을 때도, 그녀는 똑같이 행동했다. \n\n그녀는 몸과 지식, 기억, 영혼을 분리하여 뇌를 불멸의 개체로 만들려 했다. \n\n수술이 끝난 후, 그녀는 생생하고 신비로운 수면에 빠질 뻔했으나, 단 몇 초 만에 그녀의 사고는 다시 시작되었다. \n\n그녀는 분명히 알고 있었다. 자신이 형태와 힘, 대칭성의 카오스를 넘어선 절대적인 파괴에 접근하고 있다는 것을."
  },
  CollectionHall_127121_Title = {
    Text = "죽음을 넘어"
  },
  CollectionHall_127122_Desc = {
    Text = "사람들은 항상 자신의 척도로 경계를 그리고, 기호를 정하려고 한다. \n 인간의 육신 안에 세상이 제한되어 있다는 것은 얼마나 협소하고 어리석으며 가여운가. \n 그녀는 일찍이 육신을 버렸지만, 여전히 진정한 경계를 만질 수 없었다. \n 지식의 강은 혼란스럽고 끝이 없으며, 검은 공허가 다시 그녀를 따라잡았다. \n 그녀는 조용히 그것과 마주했다. 어떤 유형의 면도 세상의 전모를 볼 수 없다면, 공허의 뒤에 진정한 답이 있을까? \n 그녀는 자신의 생명으로 이생에서 가장 미친 도박을 했다. \n 그녀는 마침내 종말을 보았다. \n 진실타래의 문이 활짝 열리며, 세상의 모습이 순식간에 뒤집혔다. \n 원래 그런 것이었구나, 원래 그런 것이었구나. \n 그녀는 모든 사람이 이 공허의 진실타래을 보고, 무익한 투쟁에서 벗어나기를 간절히 바랐다. \n 과거 그녀는 파도의 정상에 서서 세상을 이끌었다. \n 이제 그녀는 여전히 양치기의 가죽 채찍을 휘두르며, 가볍게 걸어가며 세상을 심연으로 인도한다. \n 사람들은 공포에 떨며 그녀를 몰아냈다. 그녀를 악마 같은 미치광이로 여겼다. \n 참 이상하다, 그녀는 생각했다. \n 하지만 나의 눈에는 너희들도 그렇게 보인다. \n"
  },
  CollectionHall_127122_Title = {
    Text = "허무로 추락하는 인형"
  },
  CollectionHall_127123_Desc = {
    Text = "죽음을 두려워할 필요는 없다. 그것은 단지 육체가 혼을 어둠에게 돌려주는 과정, 밀물처럼 퇴수되어 깊은 평온으로 돌아가는 것이다. 완전히 녹아 없어져 아무도 모르는, 의미 없는 존재가 되는 것이 진정한 공포이다.\n그녀는 평화롭게 죽지 않았다.\n고사한 몸은 이미 얼어붙었고, 혈액과 부식액이 혼합되어 어두운 빨간 유리처럼 응고되었다. 그러나 그녀의 젊은 혼은 여전히 목 깊은 곳에서 떨리고 있었고, 사라지지 않은 그 의식은 연기처럼 골절 사이에 걸쳐 있었다. 마치 약하고 날개가 꺾인 아름다운 나비와 같았다.\n두레세인은 조용히 방에 들어가 발소리 하나 없이 먼지를 동요시키지 않았다. 그는 그녀 옆에 무릎을 꿇고 부드러운 시선으로 그녀의 감겨진 눈과 펼쳐지지 않은 손가락, 불안하게 흔들리는 혼을 지나쳤다.\n「나는 아직 살아 있습니까?」\n「이 어둠이 나를 삼킬까요?」\n그는 아무 말 없이 손을 뻗어 그녀의 갈라진 손가락을 하나씩 펴주었다. 마치 떨고 있는 꽃잎의 주름을 펴주는 것처럼. 연민도 없고 비판도 없으며, 오직 평화롭고 고요한 인내심이, 마치 세상의 가장 공정하고 위엄 있는 신이 그녀에게 평화의 권리를 부여하듯이. 순간 그녀는 영원의 고요에 도달한 듯 했다.\n그래서 순수한 향기가 그들의 맞잡은 손에서 퍼져 나갔고, 그는 몸을 숙여 만족스럽고 엄숙하게 그녀의 손가락 위에 입맞춤을 했다. 그 입맞춤이 떨어진 순간, 죽음의 마지막 메아리가 점점 길어져 공중에 떠 있는 한 줄기 바람으로 녹아들어, 폭풍 이후의 호수처럼 완전히 고요해졌다. 의심도 원망도 두려움도 없었다. 그녀는 마침내 죽음 그 자체에 속하게 되었다.\n「나는 너를 기억할 것이다.」\n그는 몸을 세우고 이제 완전히 고요한 모습의 그녀를 바라보았다. 멍한 사이에, 날카로운 송곳니가 피부를 찔렀고, 그는 세리네의 목소리를 들었다.\n「나는 당신을 믿습니다, 형님。」\n그녀는 운이 좋았다. 두레세인의 기억 속에서 그녀는 영원한 안식을 얻게 될 것이다."
  },
  CollectionHall_127123_Title = {
    Text = "안식의 입맞춤"
  },
  CollectionHall_127124_Desc = {
    Text = "처음으로 살아있는 골렘을 본 것은 여학자의 집에서였다. \n“지금까지 그녀는 나를 놀라게 한다. 나에게 그녀는 우주 자체다.” \n골렘이 기계적인 미소를 지으며 혼란스러운 중얼거림을 내뱉었다. \n그녀의 회색 눈를 바라보며, 마치 거친 회색 바다에 빠진 것 같았다. 반짝이는 파도가 하나의 지평선에서 다른 지평선으로 기어올랐다. \n\n여행을 떠나기 전, 여학자는 너에게 낡은 소책자를 건넸다. 그 안에는 골렘을 만드는 비결이 적혀 있었다. \n그날 밤, 너는 그것을 펼쳐 서투른 공식과 주문을 연구했지만, 머릿속은 골렘의 알 수 없는 미소로 가득 차 있었다. \n너는 그녀를 잊을 수 없었다. \n\n몇 일 후, 너는 핑계를 대고 다시 방문했다. \n산더미처럼 쌓인 책, 도구, 해골을 넘어서, 두꺼운 커튼과 얽힌 거미줄을 헤치고, 마지막으로 골렘 앞에 앉았다. \n여학자는 구석에 웅크리고 있었다. 불과 며칠 사이에 그녀는 피폐해졌고, 눈에서 빛이 사라져 있었다. \n“너도 왔구나…… 그들처럼.” \n여학자가 힘없이 기침을 했다. \n“응…… 내가 왔어.” \n너는 골렘의 손을 들어 입으로 가져가 끊임없이 키스했다. \n차가운 손가락이 네 목덜미를 가볍게 쓸어내며, 미세한 통증과 함께 네가 눈을 감았다. \n\n눈을 뜰 때, 따뜻한 하얀 햇빛 아래에서 너는 몸이 부드러운 파도에 따라 흔들리고 있었다. \n너는 전에 없이 가벼웠다. 마치 영혼이 육체를 버린 것 같았다. \n너는 고개를 돌려, 회색과 검은색 머리를 보았다. \n그들은 울부짖고, 비틀거리며, 검은색 야화처럼 회색 원질의 바다 위에 별처럼 흩어져 있었다. \n“아니——” \n목에서 검은 점액이 토해져 나오며, 너는 더 이상 움직일 수 없었다. \n너도 결국 그 머리들 중 하나가 되어버렸다. \n\n“@2년 6월, 유명한 연금술사 로마린 루트비히가 자신의 서재에서 의문의 죽음을 맞이한 것이 발견되었다. 머리는 사라지고, 함께 실타래종된 것은 그 신비한 연금술 매뉴얼이었다……” \n\n(위 내용은 미사그 도서관 《연금술 잡설》 제2권에 기록되어 있음)"
  },
  CollectionHall_127124_Title = {
    Text = "가장 소중한 수집품"
  },
  CollectionHall_127125_Desc = {
    Text = "지금까지도 카스톨은 자유의 진정한 의미를 말할 수 없습니다.\n그는 항상 자신이 쌍둥이 중 더 바보 같은 것처럼 느끼며, 소년 시절부터 폴뤼크스의 뒤를 무감각하게 따라가며, 동생이 기발한 아이디어를 말하는 것을 들었습니다.\n지루하고 무기력한 수련 생활 속에서 그는 그 한 가지 가벼운 빛을 갖는 것이 가장 행복하다고 생각했지만, 유리엣이 폴뤼크스에게 정기적인 개조 의식을 명령할 때까지는 몰랐습니다.\n끝없는 고통이 전적으로 폴뤼크스 한 사람에게 쏟아지고, 카스톨은 당황해하며 동생의 곁에 함께 있고, 그 풀어낸 얼굴에서 웃음이 점점 사라져가는 것을 바라보며 자신이 할 수 있는 일은 아무것도 생각하지 못했습니다.\n「너는 자유가 무엇인지 알고 있니？」 한밤중, 폴뤼크스는 그들이 낡아버린 손으로 복사한 책을 들고 조용히 카스톨에게 물었습니다.\n카스톨은 고개를 저었습니다.\n「그렇다면, 너는 외부 세계를 보러 가고 싶니? 형이여.」\n카스톨은 소름이 돋으며 멈칫했습니다. 그는 폴뤼크스가 추구하는 것을 이해한 것 같은데, 그것은 그가 한 번도 본 적이 없는 것들, 마른 글자 속에만 존재하고 자신의 상상 너머에 존재하는 것들이었습니다.\n그는 이런 대역죄 같은, 경악할 만한 생각에 깊이 충격을 받았고, 아무 말 없이 머뭇거리며 아마도 오랜 시간이 지났거나, 아니면 몇 호흡이 지났을 뿐일지도 모르지만, 그는 두려움 없이 고개를 끄덕였습니다.\n어쨌든 그건 교회를 상대해야 하고, 자기 생명을 내어놓아야 하는 일이었으며.\n결국, 두 마리 새가 한 번도 나가지 않은 감옥에서 날아 나왔지만, 안타깝게도 그들은 자유의 대가가 이렇게 감당하기 힘든 것이라는 걸 전혀 생각하지 못했습니다.\n사냥꾼의 총 소리가 울리고, 새들은 공중에서 떨어졌습니다.\n카스톨은 겨우 자유의 맛을 맛보고 있었을 때, 동생의 자유를 향한 날개가 억지로 뽑히는 것을 바라보았습니다.\n유리엣의 무서운 분노를 마주한 채, 창백하고 떨리는 동생은 군중을 등지고 자신에게 굴복하지 않는 미소를 보였습니다.\n「끝까지 버텨라, 자유를 위해서.」\n카스톨은 폴뤼크스의 그 무언의 입모양을 자꾸 생각했습니다. 그가 그 두 단어를 신앙처럼 음미하게 되었을 때, 그제야 그는 다시 폴뤼크스와 마주하게 되었고, 그때는 그가 언제나 자신을 앞서 이끌어 오던 사람이 그렇게 무정하게 그 두 단어를 버렸다는 것을 깨닫고 놀랐습니다."
  },
  CollectionHall_127125_Title = {
    Text = "견딜 수 없는 자유"
  },
  CollectionHall_127126_Desc = {
    Text = "바람과 비가 얽힌 밤, 신의 딸은 외롭게 창문 아래에 앉아 있다. \n 차가운 달빛이 아기 띠에 비추고, 검은 끈적한 액체가 흐르는 성스러운 아기가 그 안에서 편안히 잠들고 있다. \n 신의 딸은 자장가를 부르기 시작한다. \n “자라, 자라, 바다의 작은 보물아.” \n “너의 요람은 검은 달이야.” \n “별들을 꿈속에 삼켜버려.” \n 노래는 기도이기도 하며, 심해의 물고기들이 이에 따라 모여든다. \n 온 배는 마치 거대한 제단처럼, 그녀가 성스러운 아기를 낳은 날과 같다. \n 자신의 가슴을 가르고, 핏줄이 흐르는 살과 뼈를 제거하며, 생명으로 양육의 은혜와 종족의 운명에 보답한다. \n 그녀의 희생은 갈망하던 자유를 가져오지 않았고, 죽음은 영원한 편안함이 아니라 비극의 시작일 뿐이다. \n 그 이후로, 그녀의 평화는 오직 밤에서만 온다. \n “자라, 자라, 바다의 작은 보물아.” \n 이 자장가가 끝날 무렵, 위대한 신국이 바다를 찢고, 거친 파도 속에서 솟아오를 것이다. \n 이러한 허망한 환상을 품고, 뫼르피는 조용히 눈을 감았다."
  },
  CollectionHall_127126_Title = {
    Text = "어둠 속의 안식"
  },
  CollectionHall_127127_Desc = {
    Text = "그는 항상 자신을 혹독하게 비난했으며, 혹독함으로 모든 동료들을 쫓아냈습니다. 그는 자신이 영원히 혼자서 걸어가며 음악의 극치를 추구할 것이라고 생각했습니다. \n높은 곳은 추운 법, 그는 이 운명을 받아들였습니다. \n그러다 그는 그 사람의 연주를 들었습니다. \n그 사람의 연주는 완벽과는 전혀 상관이 없었습니다. 너무 자유로운 음악은 그 사람 자체처럼, 가끔은 악보와 다른 실타래수를 하기도 하고, 갑자기 어떤 부분을 잊어버리기도 했습니다. 그런 때마다 그의 손은 즉흥적으로 재미있고 생동감 넘치는 피아노 소리를 연주해내며, 청중에게 놀라움과 찬사를 받았습니다. \n그는 그 사람을 바라보며, 마치 음표 사이에서 자유롭게 놀고 있는 음악의 요정을 바라보는 것 같았습니다. \n이것이 아버지가 천부라고 부르는 것이겠죠. 사실타래 그도 모든 사람들과 마찬가지로 깊이 끌렸지만, 그의 발걸음을 바꿀 수는 없었습니다. \n그는 그렇게 평범하고 어리석은 사람이어서, 이렇게 고생스럽게 길을 걷는 수밖에 없었습니다. \n모든 사람들이 그 사람을 따라갔고, 그는 점점 멀어져갔습니다. \n그는 그와 가까워지고 싶었지만, 그는 연주 말고는 아무것도 할 줄 몰랐습니다. \n어떻게 그와 대화를 나누어야 할지, 어떤 악보를 사용해야 그의 마음을 얻을 수 있을지 고민했습니다. \n그는 악보를 작성하며, 마치 첫인사를 신중하게 고려하듯이. 결국 그는 다시 말할 기회를 잃었습니다. \n깊은 후회가 그를 덮쳤고, 모든 것이 갑자기 의미를 잃었습니다. \n눈에는 완성되지 않은 그 편지만 남아 있었습니다. 이미 떠나간 영혼에게 보내려고 했던 편지였습니다. \n그는 심혈을 기울여 결국 그 악보 앞에 쓰러졌습니다. 꿈속에서도 그는 그 길 끝의 빛을 만질 수 없었습니다. \n만약 내가 그 길 끝까지 갈 수 없다면, 내 평생의 집착은 무엇을 위한 것일까요? \n먼 곳에서 그 빛에서 유연한 피리 소리가 전해져 왔습니다. 그는 그 질문 가득한 영혼을 달랬습니다. \n혼란 속에서 그는 그 피리를 집어 들고, 자신의 진정한 사명을 알게 되었습니다. \n그의 영원히 끝없는 연주로, 영원한 평화를 가져오기 위해. \n"
  },
  CollectionHall_127127_Title = {
    Text = "영원한 진혼곡"
  },
  CollectionHall_127128_Desc = {
    Text = "아무리 앞부분의 인생 기억이 없더라도, 당신의 발달되지 않은 근육에서 알 수 있듯이, 당신은 이전에 운동이나 폭력을 좋아하는 부류의 사람이 아니었음이 분명하다.\n당신은 미사그가 조사원에게 정한 전투 기준이 왜 이렇게 높고 포괄적인지 도무지 이해할 수 없다.\n도대체 조사원의 중점은 조사라는 두 글자에 있지 않은가, 지혜로운 머리, 치밀한 논리와 적당한 행운에 있지 않은가?\n매번 라몬나에게 기숙사의 이불 속에서 제시간에 끌려 나와, 텅 빈 운동장에서 연속적인 공격에 맞서게 될 때, 당신은 도르 교수의 풍자로 가득한 논리학 수업이 그리워진다. 산더미 같은 과제와 가장 탈모를 유발하는 시험지조차 전투 훈련 중 계속해서 맞고 넘어지는 고통보다 훨씬 부드럽다.\n19번째, 당신은 모든 행동 경로를 차단한 찌르는 검에 의해 균형을 잃고 뒤로 넘어져 땅에 주저앉으며 온몸의 뼈가 부서질 듯한 느낌을 받는다.\n헐떡이며 당신은 지쳐서 이마의 땀을 닦아내며 어떤 이유로도 다시 일어나지 않겠다고 결심한다.\n라몬나는 전혀 놀라운 표정을 짓지 않고, 멋진 검꽃을 그리며 검을 수납하며, 굽 높은 신발이 경쾌하게 발소리를 내며 당신에게 다가온다. 당신은 두 눈을 감고 모든 비난과 비판을 감수하기로 결심한다.\n의외로, 어떤 타격이나 욕설도 오지 않았고, 3초 후 당신은 눈을 뜨니, 한 장의 부드러운 미소가 당신의 앞에 다가와 있었다.\n라몬나는 살짝 허리를 굽혀, 깨끗한 장갑으로 감싼 손바닥을 당신에게 내민다.\n「사실타래 당신은 이미 많이 노력했어요, 알고 있어요. 하지만 우리가 마주해야 할 것은 항상 미지의 두려움과 위험이며, 나조차도 배려하지 못하는 예기치 않은 순간이 있을 거예요.」\n「그냥 내가 조금 안심할 수 있도록, 다시 한 번 해보자, 파트너.」"
  },
  CollectionHall_127128_Title = {
    Text = "파트너 특훈"
  },
  CollectionHall_127129_Desc = {
    Text = "사람은 노래를 즐기는 생명체이며, 황성인들에게도 마찬가지다. \n멜로디는 목에서 자유롭게 흘러나오며, 어떠한 의도나 목적 없이. \n그들은 바람에 의해 흩어진 음표로 변해, 감정과 함께 시들어간다. \n사막에서는 모든 유랑 부족들이 자신만의 노래를 가지고 있다고 한다. \n하지만 황성인들은 자신의 노래를 잃어버렸다. \n\n노래와 함께 잃어버린 것은 이름이었다. \n누구도 황성의 원래 이름을 모른다. \n저주받은 행성이다. 가뭄, 폭풍, 기근…… \n다양한 재앙들이 서로 경쟁하듯 나타나, 결국 황성을 완전히 무너뜨렸다. \n화려한 옷을 입은 큰 인물들은 방주를 타고 떠났고, 황성은 진정한 황성으로 변했다. 남은 것은 축복받지 못한 하층민들뿐이었다. \n그들은 모두 버려졌다. \n\n그 이후로, 황성인들은 웃음, 시, 그리고 노래가 필요 없다고 결심했다. \n그들은 버려진 고통과 아픔을 기억하며, 백색의 사막 위에서 반복적으로 기어가면서, 행성이 파괴될 때까지 그대로 있을 것이다."
  },
  CollectionHall_127129_Title = {
    Text = "속박된 노래"
  },
  CollectionHall_127130_Desc = {
    Text = "대부분의 경우, 죽음은 항상 조용히 다가옵니다. 인간의 인식이 반응할 새도 없이, 죽음의 신은 조용히 다가와 그 연약한 생명을 거두어갑니다.\n하지만 전해지는 바에 따르면, 알려지지 않은 어느 사막에 호박색의 죽음의 신이 존재한다고 합니다. 그녀는 선포한 후 호박색의 불꽃, 호박색의 총으로 호박색의 죽음을 가져옵니다.\n남자는 달빛 아래 모래 해변에 서서 총을 움켜잡은 손이 계속 떨렸습니다. 그는 케이티 구라의 호박색 형체를 놓치지 않으려 애썼습니다.\n차가운 땀이 그의 이마에서 떨어져, 뒤에 있는 모든 사람의 마음에 떨어졌습니다. 그가 데려온 사람은 많았지만, 이 순간에 유용한 것은 거의 없었습니다.\n그는 이해하지 못했습니다. 단순히 의뢰를 받고 오래 전에 버려진 창고를 약식한 것뿐인데, 왜 전설 속의 죽음의 신을 만나게 되었는지.\n「너는 그 죽음의 신에 대해 말하고 있는 거구나? 단지 이전의 지루한 소문일 뿐이지.」\n케이티 구라가 무관심하게 말했습니다.\n「나는 그것들을 호박색으로 칠한 적이 있어. 아마 너는 그 위에서 떨어지지 않은 어떤 페인트를 찾을 수 있을 거야?」\n그녀는 앞에 있는 사람에게 손에 쥔 쌍권총을 보여주었습니다.\n「총구에서 나오는 호박색 불꽃은 어떤 특수 물질을 뿌린 것입니다.」\n그녀의 손가락이 총신으로 들어가 돌고 난 후, 알 수 없는 가루를 조금 가져왔습니다.\n「소위 죽음의 신은 예전에 내가 만든 하나의 형상일 뿐입니다.」\n「그것은 강력하고, 신비하며, 무엇이든 할 수 있습니다.」\n「그것은 나를 무능한 자들의 위협으로부터 지켜줄 수 있습니다.」\n그녀는 거만하게 말하며, 눈앞에 있는 사람의 점점 더 사나운 시선에는 전혀 신경 쓰지 않았습니다.\n그녀는 아무렇지 않게 말하며, 위험이 가까워지고 있음을 전혀 깨닫지 못했습니다.\n총알이 그녀를 향해 날아올 때, 그녀의 눈에는 충격과 혼란이 드러났습니다.\n그것은 단지 잠재의식 속의 흥분과 광기를 숨기기 위함이었습니다.\n…………………………\n총성이 멈추고 모든 것이 그녀가 생각한 대로 되었습니다.\n그녀는 전투의 한가운데 서 있었고, 주변은 모두 검게 그을려 있었습니다.\n케이티 구라는 두 가지 행동만을 했습니다——총을 들어올렸다, 사격했다.\n그녀가 긴 총을 드는 순간, 죽음의 신은 모든 것 뒤에서 춤추며 평등하게 죽음의 예고를 내렸습니다.\n그녀가 방아쇠를 당겼을 때, 불꽃은 모든 것을 휘감아 세상에 호박색의 꽃바다를 바쳤습니다.\n「그것들은 내가 수많은 해를 지나쳐 함께 했고, 수많은 피와 죽음을 목격했습니다.」\n「그것들은 한때 거짓의 외투를 쓰게 되었습니다, 나의 연약함과 무기력을 가리기 위해.」\n「이제 그들은 더 이상 소문이 아닙니다.」"
  },
  CollectionHall_127130_Title = {
    Text = "호박색 죽음"
  },
  CollectionHall_127131_Desc = {
    Text = "「당신은 후회하나요?」\n린랑의 유리잔에서 소생한 고대 신이 그녀를 냄새 맡으며, 허무하게 그녀의 어깨에 감돌고 창문을 밀어 열어, 은은한 향기를 동반한 밤바람을 불러온다. \n「내가 한 번 찡그리면, 연이어 성벽 위에 불길이 일어날 것입니다. 내가 한 번 미소를 지으면, 사방의 물줄기가 기이한 보물과 이국의 짐승, 꿀과 진미를 실타래어올 것입니다. 나는 이 왕조에서 가장 소중한 보물이니, 왜 후회해야 하죠?」\n그녀는 약간 취해 얼굴이 붉어지고, 킥킥 웃으며, 비단과 가죽으로 쌓인 높은 침대의 부드러운 베개에 누워 졸고 있다. \n……\n「당신은 후회하나요?」\n한 가닥 향선 위에 붙어 있는 고대 신이 그와 대화하며, 희미한 연기가 계단을 따라 흘러내려 이미 펼쳐진 꽃봉오리를 그린다. \n「그들은 난리법석으로 싸우고, 나는 그냥 앉아서 이익을 취할 뿐, 높이 올라갈수록 더 많이 떨어지겠죠. 나와는 다르게, 나는 모든 것을 가지고 있으니, 누가 후회할 일이 없어요.」\n그는 장난스럽게 다시 술을 따르고, 손쉽게 부드러운 가지를 따라가며, 우리 안에서 즐겁게 울고 있는 벌레들을 놀린다. \n……\n「당신은 후회하나요?」\n우물에서 기어 나온 고대 신이 그녀의 귀에 속삭이며, 감도는 안개가 그녀의 머리카락을 스치고, 꽉 찬 백목련 한 송이를 나뭇가지에서 흔들어 떨어뜨린다. \n「나는 사랑이 있고, 인연이 있으며, 일몰 귀가 시의 뜨거운 죽도 있고, 기쁜 모임의 술도 있으니, 어떻게 후회할 수 있겠어요, 나는 당연히 후회하지 않아요.」\n그녀는 꽃을 집어 머리 옆에 붙이고, 따뜻한 노란 촛불의 그림자가 그녀의 치마자락을 따라 흔들리며, 그녀의 시선은 창가에 매달려, 그녀가 기다리는 귀인을 바라본다. \n……\n「당신은 후회하나요?」\n어지러운 도망자의 치마핀은 궁문 앞의 더러운 흙점을 가득 묻혔고, 어제 정성을 다해 선물한 경호원은 그녀의 애통한 울부짖음을 듣지 못하는 듯, 두 개의 차가운 검이 교차하여 그녀의 남은 생존의 길을 막아버린다. \n안개가 유유히 한숨을 쉬고, 그러고 나서 한 송이 붉은 매화가 눈밭에서 피어나고, 다음 눈에 의해 완전히 묻힌다. \n……\n「당신은 후회하나요?」\n단목 상자에서 쏟아져 나온 남해의 보물이 청벽돌 위에 부서지고, 린랑이 떨어지는 소리는 과거의 관악기보다 더욱 듣기 좋다. \n그가 가장 소중히 여기는, 매일 상 앞에서 감상하는 글과 그림이 대청마루에 굴러 떨어지고, 묘수의 절필이 산수에 칼끝으로 찔리며, 마치 그가 보지 못하는 전쟁의 화염이 국가를 해치고 있는 것과 같다. \n안개가 조롱하듯 감돌고, 그러고 나서 불길이 일어나 그 조각 기둥과 화려한 장식이 전조의 잔재로 소멸된다. \n……\n「당신은 후회하나요?」\n그녀가 혀끝에 맴도는 이름의 주인은 더 이상 돌아오지 않고, 먼 강가의 해골과 베개 위의 미인이 있다. \n그가 황제의 문생 공주로서의 사위가 되었나요? 그가 꽃밭에서 10년을 떠나지 않았나요? 그가 유민의 배 속에서 죽어 재난 이후의 양식이 되었나요? \n안개가 애매하게 낮게 읊조리지만, 그녀가 애타게 묻는 질문에 대한 답은 주지 않는다. \n\n왕조가 번영할 때 가장 소중한 보물은 왕조가 무너질 때 가장 소중한 묘지가 된다. \n가족이 번창할 때 가장 여유로운 자식은 가족이 쇠퇴할 때 가장 이상적인 버림받은 자식이 된다. \n그리고 마지막 이야기는, 세상에는 정말로 너무나 많은 것이 있다."
  },
  CollectionHall_127131_Title = {
    Text = "억지로 미간을 찌푸리다"
  },
  CollectionHall_127132_Desc = {
    Text = "우울한 구름이 렌티니언 상공을 덮고 있어 월광을 차단했습니다. 자정의 종소리가 울렸고, 높은 굴뚝은 여전히 뜨거운 검은 연기와 증기를 내뿜었습니다. 눈송이들은 바람에 섞인 먼지로 인해 아직 땅에 닿기도 전에 어두운 회색으로 변했고, 가로등 위로 흩날리다가 불빛의 열기에 거의 즉시 녹아서 아래로 떨어져 지나가는 소녀의 몸에 떨어졌습니다. \n소녀는 갈색 옷을 입고 있었고, 너무 큰 소매는 서투르게 걷혀 있었으며, 두 개의 가는 팔이 드러났습니다. 그녀는 힘들게 달리며 가끔씩 옷소매를 들어 올려 앞서 걷는 여자를 따라가려고 노력했습니다. \n여자가 소녀를 쳐다보며 혀를 찼습니다. “더 빨리 움직여, 느리게 걷는다고 안 가면 되는 줄 알아?” \n“네, 네, 엄마,” 소녀는 여자 곁으로 뛰어갔으며, 숨을 헐떡이며 말했습니다. “죄송해요, 엄마.” \n“나를 엄마라고 부르지 마!” 여자는 소녀의 팔을 잡아끌며 걸음을 빠르게 했습니다. “쓸모없는 피 빨아먹는 것, 너 때문이 아니었으면 내가 이런 망한 곳에 왜 와 있어야 하겠니.” \n“죄송해요……” \n“조용히 해, 쓸모없는 것.” 여자의 손톱이 소녀의 팔에 파고 들어 깊은 자국을 남겼습니다. “내가 말하는데, 앞으로 방이 네 집이 될 거야. 나를 찾아오겠다는 생각도 하지 마. 나는 죽어서라도 널 보고 싶지 않아, 알았나?” \n“저……알았어요.” 소녀는 고개를 숙이고, 떨어진 눈물은 신발에 밟혀 더러운 눈물과 함께 돌길에 사라졌습니다. 멀리서 공장의 퇴근 경적이 울리고, 한 마리 야옹이가 골목을 뛰어넘어 두 사람의 발걸음 소리에 묻혔습니다. 그들은 모퉁이를 돌고, 습기 찬 뒷마당을 지나서 결국 금속 문이 있는 건물 앞에서 멈추었습니다. \n“여기서 기다리고 있어,” 여자의 목소리는 매우 차분했고, 심지어 무감각하게까지 들렸습니다. “하늘에 날이 밝으면 안쪽에서 사람들이 나오겠지. 그들이 너를 받아줄 거야. \n따라오지 마, 그렇지 않으면 내가 널 죽일지도 모른다.” \n여자는 돌아서 떠났고, 마찬가지로 마른 몸매와 약간 굽은 모습은 곧 어둠 속으로 사라졌습니다. 소녀는 자신의 손을 꽉 쥐며 여자가 떠난 곳을 바라보며, 소매로 얼굴의 눈물을 닦았습니다. \n그녀 뒤에서 희미한 노란빛이 비춰져 철문과 그녀의 그림자를 길게 만들었고, 한 손이 소녀의 어깨에 닿아 소녀를 놀라게 했습니다. \n“가엾은 아이, 어떻게 혼자 여기에 있니?” 온 사람은 젊은 여성으로, 수녀처럼 보이는 옷을 입고 있었습니다. “와, 사라 언니가 널 안으로 데려갈게. 곧 추위에서 벗어날 거야.”"
  },
  CollectionHall_127132_Title = {
    Text = "겨울밤의 추억"
  },
  CollectionHall_127133_Desc = {
    Text = "「내 명작이야? 음——그렇게 호기심이 많아? 좋아 좋아, VVIP의 요구니까. 하지만, 보통의 이야기는 마법사 대장으로서 내 이름에 걸맞지 않아. 화려한 공연으로 보여주겠어! \n어서와, 귀빈석에 앉으세요. 돈과 배반으로 가득 찬 미스터리한 행복한 마법 회상 쇼가 곧 시작될 거야!」\n-------\n손가락 튕김 소리와 함께 조명이 밝아졌고, 카시아의 마술모자가 공중에 떠올랐다. 노란색 모자의 입구가 열리고 닫히면서, 카시아의 목소리가 들려왔다.\n「오래전, 그리 멀지 않은 곳에서, 서커스단이 있었어요. 그 서커스단에는 토끼, 클라운, 사자, 코끼리가 있었죠——」\n모자가 흔들리며, 안에서 토끼, 클라운, 사자, 코끼리가 떨어져 나왔다. 백그라운드 음악의 리듬이 점점 빨라졌고, 연발포의 폭발음과 함께 화려한 의상을 입은 카시아가 모자에서 기어나와, 뒤돌아서 모자를 자신의 머리에 썼다.\n「가장 중요한 것은, 특성이 뛰어나고 재능이 많은 마법사 제자가 있었어요!」\n-------\n제자의 성장은 박수와 함께했고, 화려한 옷을 입은 투자가를 성공적으로 유혹했다. 이상하게도, 투자가가 함께 여행을 시작한 후, 토끼, 클라운, 사자, 코끼리…… 많은 사람과 동물들이 하나씩 사라졌다. 무대는 대부분 비어버렸지만, 제자는 아무런 의식 없이 원래의 생활을 반복했다. 투자가가 그녀 앞에 술 한 잔을 건넸을 때까지.\n제자는 술을 마시고 쓰러졌고, 무대가 어두워졌다. 어둠 속에서 약한 한숨이 흘러나왔다.\n「그때 나는 처음으로 후회를 알았어.」\n-------\n「하지만, 후회로는 부족해. 나는 후원자님의 울음소리, 관객들의 웃음소리를 알고 싶었어. 더 많이, 더 많이 알고 싶었어. 그때——\n나는 눈을 떴다.」\n종이 꽃이 하늘에서 터져 나와, 파편들이 날아다녔다. 카시아가 갑자기 무대 중앙에 나타나 모자의 가장자리를 두드리자, 모자가 입을 벌리고 눈부신 빛을 발산했다.\n「나는 눈을 떴고, 모든 감정이 빛이며, 내 마술모자에 담을 수 있다는 것을 발견했어요.\n지금부터 편안하게 해주세요, 제 귀빈님. 다음 단계는 아프지 않을 거예요, 오히려 약간의 마비감과 삶이 조금 무미건조하다는 느낌만 있을 거예요……」"
  },
  CollectionHall_127133_Title = {
    Text = "환희의 마법 공연"
  },
  CollectionHall_127134_Desc = {
    Text = "클레멘틴은 강하지 못한 아이였기 때문에, 괴상한 병에 걸려 고통과 점차 다가오는 죽음에 시달릴 때마다, 그녀는 tief 밤에 깨어 울었습니다.\n매번 눈물을 흘린 다음 날, 그녀의 침대 옆에는 「선물」이 놓여 있었습니다.\n화려하게 포장된 설탕 몇 개, 유행하는 머리 장식, 귀여운 곰 인형......\n하지만 그녀가 가장 인상 깊게 기억한 것은 곤충의 고치 표본이었습니다.\n그때 그녀는 병이 매우 심해져 침대에서 내려올 수도 없었고, 간신히 표본을 들어 올려 투광 고치 안의 생명을 응시했습니다.\n그 생명은 이미 잠들었지만, 그 생명은 영생을 얻었습니다.\n그리고 그녀는 진정한 죽음에 직면해 있었습니다.\n이렇게 생각하니, 그녀의 눈물이 소리없이 흐릅니다. 하지만 한 쌍의 손이 그녀의 눈물을 닦아 줍니다.\n「울지 마, 클레멘틴. 언젠가는 너도 이 고치처럼 새로운 생명을 얻게 될 거야.」\n「나는 너를 다시 태어나게 할 거야.」\n아버지는 거짓말을 하지 않았고, 최소한 그녀에게는 거짓말을 하지 않았기에, 클레멘틴은 그 말을 굳게 믿었습니다.\n그녀는 아버지를 믿었고, 그래서 신성 모독의 산맥에 들어갔을 때, 그녀는 망설임 없이 들어갔고, 혈육이 용해되는 격통을 참을 때, 그녀는 아무런 불평도 하지 않았습니다.\n그녀는 이 모든 것이 새로운 생명을 얻기 위한 대가와 필수 과정이라고 믿었습니다.\n모든 고통과 절망이 끝나면, 그녀는 회복될 것이고, 「집」이라고 불리는 곳으로 돌아와 그녀의 유일한 가족과 재회할 것입니다."
  },
  CollectionHall_127134_Title = {
    Text = "숨겨진 고통"
  },
  CollectionHall_127135_Desc = {
    Text = "그녀는 결코 꿈을 꾸지 않았다. \n\n젊은 조각가 수습생은 그녀의 차가운 작품처럼 절대적인 이성과 질서를 굳게 신념했다. \n하지만 그것을 처음 본 순간부터, 그녀는 매료되었다. \n부드럽고 순수한 — 완벽한 색칠 재료였다. \n그녀는 월광 아래에서 일하며, 무덤터에서 검은 슬라임을 스튜디오로 가져왔다. \n\n일주일 후, '《@2》'라는 이름의 조각상이 박람회에서 전시되었다. \n그날 밤, 그녀는 먼 곳에서 들려오는 파도 소리를 들었다. \n그녀는 처음으로 꿈을 꾸었다. \n조용한 아침 햇살 아래, 먼지로 뒤덮인 해저 궁전이 깊이 잠들어 있었다. \n그녀는 하얀 산호 사이를 거닐며, 숨 쉬는 것마다 고독과 망각의 기운이 느껴졌다. \n\n눈을 뜬 후, 그녀의 손가락은 구부러지고 검어졌으며, 결국 하얀 산호가 자라났다. \n그녀는 반복해서 냄새를 맡으며, 그 안에 담긴 수백만 년 동안 수많은 생물들의 중얼거리는 소리를 느꼈다. \n진정으로 부드러운 화석이었다. \n그녀는 신경질적으로 웃었다 — 이것이 바로 꿈이구나. \n그녀는 스튜디오에 자신을 가두고, 열중해서 창작을 시작했다. \n몰드 만들기, 진흙 조각, 색칠…… \n혼란스러운, 질서 있는. 무기물의, 유기물의. \n\n그녀는 영원히 꿈을 꾸게 될 것이다."
  },
  CollectionHall_127135_Title = {
    Text = "산호 여인의 죽음"
  },
  CollectionHall_127136_Desc = {
    Text = "어머니. 어머니.\n머피는 이미 그와 관련된 대부분의 기억을 잃었다.\n누군가 말하기를, 죽음 직전의 어머니가 그녀를 보호하며 피가 그녀의 목구멍으로 들어갔다고 한다.\n그러고 사람들이 달려와서 무자비하게 그들을 분리시켰다.\n그 순간, 머피는 어머니의 얼굴을 보았다. 그 얼굴은 광란처럼 보였지만 아름다웠다.\n기억이 생긴 후, 그녀는 새로운 “어머니”를 얻었다.\n온화하고 신중한 그녀는 머피의 모든 무리한 요구를 들어주었지만, 거리를 두며 가깝지도 멀지도 않게 지냈다.\n머피가 그들의 관계가 그렇게 계속될 것이라고 생각할 때, 마치 미리암의 표정이 영원히 변하지 않는 것처럼, 그녀는 검은색 왕좌 위로 높이 들어올려져 꿈에서 그 빛나는 “알”을 보았다.\n그것은 어둠 속에서 반짝이며, 눈 같기도 하고 별 같기도 했다. 희미한 노래가 성소 주변을 감쌌다:\n<Italic:그 딸로부터, @1의 신성이 @1에 강림한다……>\n그녀에게는 자신과 관련되면서도 관련되지 않은 위대한 사명이 주어졌다: 신성을 되살리는 어머니가 되는 것이다.\n정말 기묘하다. 그녀는 아직 어머니가 무엇인지, 딸이 무엇인지 이해하지 못했지만, “어머니”가 되는 법을 배워야만 했다.\n머피는 그 광란 같은 아름다운 얼굴을 떠올렸고, 혀끝에 달콤하면서도 쓴맛이 남아 있던 것을 기억해냈다.\n그 아름다운 사람은 내가 이렇게 무덤으로 떨어지는 것을 바라지 않았을 것이다, 그렇지 않겠는가?"
  },
  CollectionHall_127136_Title = {
    Text = "은밀한 탄생"
  },
  CollectionHall_127137_Desc = {
    Text = "완다의 정확한 출신에 대해 캄브리안의 시골 주민들은 의견이 분분하다. \n\n누군가는 그가 거대한 돌덩이를 타고 호수 옆으로 떨어지는 것을 직접 보았다고 한다. \n또 다른 사람은 그녀가 레무바시 출신의 여법왕이라고 말한다. 그는 미라에서 똑같은 등가시를 본 적이 있다고 한다. \n또 다른 사람들은 그녀가 프란 고원 출신의 여공작이라고 말한다. 네 명의 남편을 연속으로 잃은 후 막대한 재산을 상속받았다고 한다. \n……\n\n소문은 바람처럼 사라졌고, 시골 주민들은 계속해서 농사를 지으며, 직물 짜고, 방아를 찧었다. \n그 고통스러운 시절에, 무거운 세금은 머리 위에 드리워진 날카로운 칼날이었고, 모든 부차적인 일과 환상을 잘라냈다. \n하지만…… 여왕이 쉬는 호수 근처를 지날 때마다, 숲 속에서 들려오는 음악은 쉽게 사람들의 마음을 사로잡았다. \n여기서는 들을 수 없어야 할 멜로디였다. \n너무 즐겁고, 너무 게으르고, 마치 악마의 속삭임처럼 악랄했다. \n\n“오세요, 이 모든 것을 내던져버리세요.” \n“자비로운 왕은 호수 중앙에 앉아, 눈먼 종의 섬김을 기다리고 계십니다……” \n\n그래서, 어느 무풍의 밤, 피곤한 시골 주민은 농구를 내려놓고, 호기심을 만족시키기로 결심했다. \n그는 숲을 돌아, 작은 다리를 건너, 길 양쪽으로 꽃들이 활짝 피어 있었지만, 그는 한 번도 쳐다보지 않았다. \n그는 초록색 호수를 보았다. \n그것은 낮게 드리워진 별빛과 연결되어 있고, 가장자리에는 고대 성채가 솟아 있었다. \n\n가시를 머리에 쓴 여왕은 호수 중앙에 앉아, 순례를 오는 자식들을 인내심을 가지고 기다리고 있었다. \n그녀는 손을 뻗어, 인간의 입맞춤과 절을 즐겼다. \n구름이 흩어지고, 밝은 달이 떠올랐다. \n여왕은 그의 등뼈에 등가시를 찔러 넣었다. \n마비된 액체가 혈관을 따라 퍼졌고, 그는 무릎을 꿇고, 팔다리가 잘려나가고, 눈이 파헤쳐졌다. \n\n이제, 대지의 무거운 중력은 그를 더 이상 끌어당길 수 없었다. 그의 모든 시와 꿈은 그 여왕에게만 묶여 있었다. \n그는 마침내 자신의 운명을 맞이했다."
  },
  CollectionHall_127137_Title = {
    Text = "여왕의 계율"
  },
  CollectionHall_127138_Desc = {
    Text = "“온종일 고행을 하는 이여, 이 선물이 당신의 영혼을 따뜻하게 하기를 기원하며, 아버지 신의 자비가 당신 마음의 고통을 위로하고, 향기로운 아름다운 꿈을 가져다주기를 바랍니다.”\n은빛 서리의 밤이 끝나가고, 촛불이 낮아졌다. 오랜만에 무거운 석판을 내려놓고, 살바도르는 엄숙한 긴 로브를 벗고 따뜻한 붉은 모피 의상으로 갈아입었다. 내일의 겨울두제을 위해, 그는 다푸델의 작은 가게에 가서 미사그의 학생들을 위한 놀라움을 준비했다.\n“이것이 마지막 선물입니다……”\n살바도르는 캠퍼스 구석의 오래된 의자에 조용히 앉아, 피곤함에 무의식적으로 꿈속으로 빠져들었다.\n그것은 달콤한 아름다운 꿈이었다. 발치의 선물 상자가 이유도 모르게 조용히 열렸다——네 개의 생강빵 인형이 갑자기 튀어 나와, 설탕으로 장식된 눈이 반짝이며, 계피와 정향의 향기가 차가운 공기 속에서 원을 그리며 돌고 있었다.\n향기는 잠들어 있던 기억을 깨웠고, 그는 마치 어린 시절의 교회 회랑으로 돌아간 듯했다. 녹아내린 태피 록은 혀끝에서 달콤한 신호를 전했다. 고통과 전염병에 감염된 축복이 이 달콤한 왈츠에 따라 조용히 되살아나고 있었다.\n……\n그와 동시에, 네 명의 몰래 다가오는 그림자가 잠에 빠진 살바도르에게 조용히 다가왔다.\n“주인님…… 주인님은 우리를 나쁜 아이로 생각하실타래까요……?”\n“히히——아우레타가 너무 궁금해요! 빨리 열어봐요~ 하나, 둘…… 와, 생강빵 인형이 정말 많아요!”\n“너, 너…… 이름을 말해버렸어, 만약…… 그들이 우리를 싫어할까 봐……!”\n“헤헤, 우리는 훔치려던 게 아니에요! 다 브라운이 한 거예요!”\n살바도르는 작은 생강빵 인형들이 재잘거리며 대화하는 소리를 듣고, 한 생강빵 인형이 무릎에 뛰어오르는 느낌을 받았다. 계피의 숨결이 그의 주름진 손등을 스쳤다.\n아니, 꿈속의 생강빵 인형이 아니라, 현실타래의 장난꾸러기 아이들이다. 살바도르는 아이들이 몰래 선물 상자를 열 때, 얼굴에 가득한 행복한 미소를 상상할 수 있었다. 이 순간의 아름다움, 행복과 평화를 위해 그는 모든 고통을 감수할 준비가 되어 있었다.\n“오…… 내 수염, 이게 수염과 머리카락이 엉키는 건가?”\n살바도르는 여전히 잠을 자는 척하며 아이들이 이 즐거운 “비밀 작전”을 계속하도록 했다."
  },
  CollectionHall_127138_Title = {
    Text = "상자 속 천진난만"
  },
  CollectionHall_127139_Desc = {
    Text = "당신과 라모나는 다시 만날 약속을 한 적이 없었습니다.\n문살이 눈앞에서 천천히 닫히던 그 순간, 두 사람의 마음속에 새겨진 이별의 기한은 이미 영원으로 정해져 있었습니다.\n\n그러니, 그녀가 시간의 틈새에서, 순식간에 스쳐 지나가는 만남 속에 살며시 당신의 새끼손가락을 걸어왔을 때……\n이것은 이미 기대 밖의, 충분히 행운인 재회였습니다.\n\"당신은 조금도 변하지 않았네요.\" 그녀가 말했습니다.\n\n이 한마디를 위해, 손끝의 희미한 온기를 위해……설령 두 세계가 가로막혀 있다 해도, 당신은 모든 것을 바쳐 은하를 넘어 그녀를 만나러 가고 싶었습니다.\n내년 오늘, 새끼손가락을 걸고 맹세합니다."
  },
  CollectionHall_127139_Title = {
    Text = "당신과 나는 결국 다시 만날 것이다"
  },
  CollectionHall_127140_Desc = {
    Text = "“후퇴, 후퇴!”\n“@3으로 철수하라! 빨리 움직여!”\n“구해줘, 구해줘! 날 버리지 말아요!”\n“그만둬, 어서 후퇴해——엘바!”\n 총검을 든 병사가 한 걸음 크게 내딛으며 앞으로 돌진했다. 포화가 그녀의 옆에서 폭발했고, 병사들의 싸움 소리와 비명, 급박한 전쟁 나팔 소리가 뒤섞였다. 피로 흙이 검게 물들었으며, 화약 냄새조차 가릴 수 없는 짙은 피비린내가 진동했다. 쓰러진 병사들의 눈빛은 텅 비어 있었고, 어느 군복의 색깔이든 이 순간에는 모두 선명한 붉은색으로 변해 있었다. \n 엘바는 이를 악물고 연이어 달려드는 적들을 향해 앞으로 나아갔다. 그녀는 이제 보았다. 도움을 요청하던 젊은이를. 그는 땅에 쓰러져 양손으로 필사적으로 커다란 적군의 다거를 격파하려 하고 있었다. \n 폭발적인 총소리와 함께 극심한 통증이 동시에 찾아왔다. 멀리 있던 적이 천천히 쓰러졌다. 엘바는 즉시 몸을 돌려 칼을 휘두르며 다리의 통증을 참으며 앞으로 밀고 나갔다. 적이 균형을 잃는 순간, 그녀는 상대의 가슴을 관통하며 방아쇠를 당겼다. \n 총알이 육체에 박혀 피와 살점이 튀었다. 그녀는 얼굴을 대충 닦고 젊은이의 안전을 확인하려 돌아섰지만, 이미 그는 언제 어디론가 사라지고 없었다. \n 그녀는 아래를 내려다보았다. 왼쪽 무릎 위를 관통한 칼이 다리를 찌르고 있었고, 따뜻한 피가 솟아나와 흐르고 있었다. \n 그녀는 망토에서 천을 찢어 다리 뿌리 부분에 묶어 혈류를 겨우 제한하고, 총검을 임시 지팡이 삼아 절뚝이며 부상당한 다리를 끌고 부대를 따라갔다."
  },
  CollectionHall_127140_Title = {
    Text = "견고한 의지"
  },
  CollectionHall_127141_Desc = {
    Text = "역사는 항상 승자의 일방적인 이야기였다. 모나무가 소멸되고, 국가가 무너지면서 과거에 관한 모든 것이 조용히 변화하고 있다. \n시인들은 니느웨의 미인에 대한 스토리를 전하며, 여행자들은 불꽃 주변에 모여 귀를 기울여 듣는다. \n\n“은빛 사막을 통과하여, 이국의 미인이 니느웨로 들어섰다. \n하늘의 물이 그녀의 어깨에서 흘러내리고, 시나이 진주가 그녀의 눈에서 떨어졌다. \n황금빛 두 눈 속에는 다른 세계의 과거가 응시되고, \n꿀빛 피부 위에는 니느웨의 미래가 쓰여 있다.” \n\n그 후 어떻게 되었나요? 그 미인은 왕비가 되었나요? \n늙은 시인은 칠현금을 타며 길고 깊은 한숨을 내쉰다. \n\n“그녀는 마약과 같아서, 모든 생명체가 그녀에게 매료되었다. \n그녀는 독약과 같아서, 왕과 신하들의 폐부에 스며들었다. \n그녀는 홍수와 같아서, 모든 존재가 탈출할 수 없었다. \n그녀는 검은 역병의 사자였으며, 그녀는 질병과 악몽과 죽음, 그리고 니느웨의 종말을 가져왔다.” \n\n칠현금을 내려놓기도 전에, 술상 옆에서 한 사람이 일어서자 술집 손님들이 모두 그를 바라본다. \n그 사람의 가늘고 긴 손가락 사이로 몇 개의 동전이 떨어져 금과 은이 굴러 떨어지며 맑은 소리를 낸다. \n그녀가 지나가는 곳마다 시선이 따르고, 등불이 반짝임을 더했다. \n\n“시간은 흘러갔지만 상관없다. 그분은 이런 헛된 말에 답하지 않으실타래 것이다. \n언젠가, 너희도 그분의 자비와 너그러움을 이해하게 될 것이다... 나처럼...” \n그녀는 술집의 낡은 문을 밀어 열었는데, 마치 보석함을 여는 것처럼 월광이 그녀의 드러난 어깨에 떨어져 아름다운 빛을 비추었다. \n월광에 사랑받는 그 미인은 확실타래히 꿀처럼 부드러운 피부를 지니고 있었다."
  },
  CollectionHall_127141_Title = {
    Text = "자비로운 양육"
  },
  CollectionHall_127142_Desc = {
    Text = "그녀가 화원에서 눈을 떴을 때, 큰 불길이 이미 정원 전체를 휩쓸고 그녀 앞까지 다가와 있었다. \n화원의 문은 밖에서 잠겨 있었고, 공기 중에는 진한 알코올과 기름 냄새가 가득했다. 그녀는 코레트의 이름을 크게 부르며, 연기에 목소리가 쉬어버릴 때까지 외쳤지만, 그녀에게 답하는 것은 불꽃의 소리뿐이었다. \n그녀는 다행이라고 느꼈다. 코레트가 집을 나갔으니, 이렇게 큰 불길 속에서 위험에 처하지 않았을 것이다. \n그녀는 슬픔을 느꼈다. 인생의 마지막 순간에, 그녀는 친구와 마지막으로 마주치지 못했다. 코레트가 돌아와서 불타버린 정원과 자신을 보게 되면, 얼마나 슬플까? \n그녀는 아쉬움을 느꼈다. 그들의 삶이 점점 좋아지고 있었는데, 이 불길이 그들에게 종지부를 찍을 것이다. \n불탔다. 집이 불탔다. 하늘이 불탔다. 나뭇잎이 불탔다. 꽃잎이 불탔다. 정원에서 겪었던 장면들이 그녀 앞에서 펼쳐지고 흘러갔다: 그녀가 그녀를 정원으로 데려갔고, 그녀가 장미를 건넸으며, 하루의 노동으로 부드러운 빵을 만들어주었다. 그들은 놀고, 추격하며, 평온한 햇빛 아래 누워, 백작부인의 방에 들어가는 날을 상상했다. \n불탔다. 과거가 불탔다. 미래가 불탔다. 정원은 모든 이야기와 모든 감정을 담아서, 미친 듯이 타올랐다. \n눈물이 그녀의 얼굴을 타고 흘러내렸지만, 불길에 달아오르면서 곧 사라졌다. \n그녀는 아름다움을 느꼈다. 시에서 고통과 아쉬움은 아름답다. 그녀는 주변을 둘러보았고, 불길에 거의 다 타버린 종이와 펜을 찾았다. \n감사, 애정, 이별, 축복, 아름다움. 그녀는 이 가장 아름다운 모든 것을 코레트에게 남기고 싶었다. \n“……코레트에게. 오를라, 불길 속에서.” \n시전의 문장 끝에, 그녀는 마지막 서명을 남겼다. \n백미터 떨어진 정원 맞은편 도로에서, 코레트는 무언가를 감지한 것 같았다. 그녀는 고개를 들었고, 강한 불빛이 그녀의 얼굴을 비추었다. \n눈물이 그녀의 얼굴을 타고 흘러내렸지만, 불길에 달아오르면서 곧 사라졌다."
  },
  CollectionHall_127142_Title = {
    Text = "시첩의 끝구절"
  },
  CollectionHall_127143_Desc = {
    Text = "그들은 어두운 강을 노를 젓으며, 창백하고 침묵하며 지쳐 있었다. \n 희미한 안개가 손길을 뻗어 그들을 어둠으로 끌어들였고, 끝이 없는 영원한 밤에서 방황했다. \n\n 그 후, 그들은 한 줄기 빛을 보았다. \n 그것은 먼 강변에서 비치는 새벽빛이었는데, 가끔씩 번쩍이며 어두운 영혼을 비추기에 충분했다. \n 그래서 그들은 빛을 따라 어둠을 헤엄쳐 나와, 새벽의 여명 앞에 도착했다. \n 그리고 여러분 앞에 나타났다. \n\n 이는 아마도 잠시 동안의 만남일 뿐이겠지만, 그들은 양손을 힘껏 흔들며 목소리를 높여 외쳤다. \n 모든 사람이 신성한 새벽빛 아래에서 목욕하고, 모두가 웃고 있었다. \n 그들은 말했다 — \n 모든 만남의 순간이 축제처럼 소중하기를. \n 진실타래된 마음이 멈추지 않기를. \n 은열쇠가 전진을 안내하기를."
  },
  CollectionHall_127143_Title = {
    Text = "황혼과 새벽"
  },
  CollectionHall_127144_Desc = {
    Text = "바람이 사방에서 몰아쳐 오고, 당신은 촛불을 들고 미로의 입구에 서 있습니다. \n당신은 조금 혼란스러워합니다. \n몇 초 전까지만 해도 미사그의 식당에서 샬롯이 도서관 지하 미로에 대한 전설을 이야기하는 것을 듣고 있었던 것 같습니다. \n그리고 지금, 당신은 잠옷을 입고, 졸린 눈으로 하나하나의 통로를 걸어가고 있습니다. \n“샬롯, 샬롯……” \n살짝한 소리와 함께 하얀 거미들이 물결처럼 밀려듭니다. \n그들은 창백한 여자아이로 응결됩니다. 그녀는 고깃덩어리로 조각된 그네에 앉아, 앞뒤로 흔들리고 있습니다. \n\n“당신이 왔군요.” 그녀가 말합니다. \n“나는 샬롯을 찾으러 왔어요, 내 친구예요. 그녀가 길을 잃었어요, 나는 그녀를 찾아야 해요……” \n당신은 거의 울음을 터뜨릴 것 같습니다. \n소녀가 깔깔거리며 웃습니다. 그녀는 그네에서 뛰어내려 당신 앞으로 다가옵니다. \n“당신은 잊었나봐요, 우리의 거래를……” \n소녀가 손을 뻗어 당신의 배를 만지며 깨달았다는 듯 말합니다. \n“맞아요. 당신은 이미 나의 자손이 되었으니, 아무것도 기억하지 못하는 거예요.” \n“자손……?” \n당신은 머리를 숙여 두 사람이 피부가 닿는 곳을 느낍니다. \n따뜻한 감촉이 거미줄처럼 피부 아래로 스며들어 혈관 깊숙이 퍼져갑니다. \n소녀가 신비롭게 눈을 깜빡이며 당신의 귀에 대고 속삭입니다: \n“샬롯은 바로 당신의 배 속에 있어요.”"
  },
  CollectionHall_127144_Title = {
    Text = "창백한 후예"
  },
  CollectionHall_127145_Desc = {
    Text = "거대한 무대 위에서 한 소녀가 춤을 추고 있다. \n그녀의 머리는 꽉 끈으로 묶여 있고, 머리에는 하얀 깃털과 작은 왕관이 장식되어 있으며, 순백의 발레 드레스는 그녀의 동작에 따라 펼쳐져 슬픈 바이올린 소리 속에서 한 바퀴 또 한 바퀴 돌고 있다. \n팔은 편안하게 펼쳐지고, 발끝은 땅을 찍으며, 백조는 긴 목을 숙여 왕자에게 자신의 슬픔과 고민을 이야기하고 있다. \n아직 어린 리즈는 입을 살짝 벌리고, 무대 위에서 가볍고 우아하게 춤추는 소녀를 보고 있다. 그녀는 리즈의 사촌 누나로, 리즈가 태어나기 전부터 그녀의 집에 와서 할머니 밑에서 엄격한 훈련을 받았다. 평소에는 항상 소박하고 조용했던 사촌 누나는 오늘처럼 활기찬 모습을 보인 적이 없었다. 그녀는 마치 날개를 펼쳐 날아갈 준비를 하는 백조 같았고, 그녀, 그리고 그들, 극장 안의 모든 사람들은 그녀의 그림자 아래로 쓰러졌다. \n리즈의 심장은 점점 더 빨라지고, 점점 더 빨라졌다—얼마나 부러운가! 그녀도 그 백조가 되고 싶었다. 영원한 무대 위에서 오랫동안 자신의 그림자를 남기고 싶었다. 자신이 할 수 있다는 것을 알고 있었다. 할머니가 주목하지 않은 사이에 그녀의 다리가 길고 곧다고 칭찬하지 않았던가? 그녀의 오랜 수석 댄서 사촌 누나가 그녀가 춤에 재능이 있다고 말하지 않았던가? 맞다, 그녀가 시작하기만 하면, 그녀가 발레 신발을 신기만 하면, 사람들이 먼 도시에서 공연을 보기 위해 찾아올 것이다. 그녀는 이 세기 최고의 무용수가 될 것이며, 발레 예술의 화려한 별이 될 것이다! \n그때의 그녀는 아직 자신을 기다리고 있는 것이 뜨거운 불꽃뿐이라는 것을 알지 못했다."
  },
  CollectionHall_127145_Title = {
    Text = "돌고 도는 춤사위"
  },
  CollectionHall_127146_Desc = {
    Text = "이곳 미사그에 온 지 1년이 지났습니다. 대폭발에서 깨어난 후, 이 학교에 처음 발을 들였던 날이 여전히 기억납니다. 잘 맞고 깔끔한 교복이 지급되고, 나만의 기숙사를 가지게 되었으며, 처음으로 식당을 둘러보고 두 쌍의 식판을 모두 비웠습니다. 모든 여유로운 순간들은 이날 갑자기 멈췄고, 빈약한 지식과 아기처럼 매끄러운 뇌 주름 때문에 1년간의 예비 코스를 의무적으로 수강해야 했습니다. 언어 학습, 체력 특훈, 은심 능력 테스트, 특수 생물 상식 보충…… 견디기 힘든 기간이 지나면, 당신의 성적은 혼합되어 있으며, 낙제한 레오 통용어 점수와 세 개의 깨어남체를 한 번에 링크한 위업 덕분에 캠퍼스에서 유명해졌습니다. 다행히 당신의 특별한 능력과 뛰어난 재능 덕분에 조사원 능력 기준에 신속히 도달하여 예비 과정을 더 연장할 필요는 없었습니다. 당신의 미흡한 부분들은 서로 점점 호흡을 맞춰가는 동료들이 보완하고 지원해 주었습니다. 아, 여기서 생산되는 것은 악마이지만, 그것들도 믿을 만하면서도 다정한 악마들입니다. 이곳은 종종 흐리고, 비가 내리고, 맑은 날씨가 드문 곳으로, 수많은 잊혀졌거나 잊혀질 사람들이 늘 굳건히 지키고, 희생하며, 끊임없이 전진합니다. 이렇게 모든 일이 평범한 하루에, 미사그는 또 한 해의 개학일을 맞이했습니다. 당신은 거울 앞에서 교복의 옷깃을 정돈하고, 주름을 펼치고, 그러고 나서 기숙사 건물의 문을 열었습니다. 「하품, 드디어 왔군요. 곧 잠들 뻔했어요.」 「기숙사에서 알을 품고 있는 건가요? 신입생.」 당신은 로탄에게 쓴웃음을 지으며, 신체적 공포를 일으킬 수 있는 핑크빛 실타래루엣을 향해 목을 움츠리고, 옆에서 웃고 있는 라모나와 오질 뒤로 몸을 숨겼습니다. 다섯 개의 그림자가 아침의 캠퍼스에서 흔들리며 길게 늘어졌습니다. 「가자, 파트너.」 「오늘부터 당신은 미사그의 정식 일원이 되었어요.」"
  },
  CollectionHall_127146_Title = {Text = "개강일"},
  CollectionHall_127147_Desc = {
    Text = "테임 강을 따라 내려가 오른쪽으로 꺾어 베크만 거리로 들어가면, 대략 백 피트 정도 걸어가다 보면 그 눈에 띄지 않는 모퉁이에서 “레이크 탐정 사무소”를 볼 수 있을 것이다. \n\n런티니언에서 해결률이 가장 높은 탐정 사무소지만, 여기에는 전문 서적으로 가득 찬 큰 책장도, 신문 기사로 뒤덮인 벽도, 우아한 오후 차도 없다. \n대신 대부분의 경우 당신은 문 앞에 걸린 “외출 중” 표시와 옆에 웅크려 있는 지친 늙은 개를 마주하게 될 것이다. \n\n운이 좋다면, 어느 맑은 일요일 아침에 숙취를 품고 돌아오는 유명 탐정을 만날 수 있을지도 모른다. \n그는 도박에서 졌고, 주머니가 텅 비어 있을 때, 당신은 그에게 무리한 의뢰를 망설임 없이 제안할 수 있다: 고양이 찾기, 사이비 종교에 빠진 어머니 구출, 남편의 외도 증거 수집…… \n당신이 가지고 있으면, 그는 받아들일 것이다. \n\n“나는 죽음 직전의 순간을 즐기기 때문에, 나는 운명적으로 도박사가 되어야 한다.” \n“그렇다면 탐정이 되는 건 어떨까? 솔직히 말해, 고양이 찾기와 죽음 사이의 관련성을 이해할 수 없다.” \n“아니, 당신은 이해하지 못한다…… 진실타래을 찾아가는 과정 자체가 충분히 매력적이다. 크거나 작든 상관없이. 그것은……” \n“죽음과의 약속을 지키러 가는 것과 같다.”"
  },
  CollectionHall_127147_Title = {
    Text = "행운의 시간"
  },
  CollectionHall_127148_Desc = {
    Text = "폴룩스는 꿈을 꾸었다.\n그는 은색 갑옷을 입고 위엄 있는 왕의 손에서 달처럼 빛나는 긴 검을 받았다.\n그리고 그는 높은 백마에 올라타서 한 동굴로 향했다. 그가 지하 깊숙이 들어가자 동굴 입구의 나무들이 미세한 속삭임을 냈다.\n동굴 깊숙한 곳에 어두운 녹색의 그림자가 숨어 있었고, 그것은 살과 같이 커다란 괴물이었으며, 괴이한 두 눈에서 녹색 빛이 뿜어 나왔다.\n\"나라에 해를 끼치는 괴물이여, 나는 더 이상 당신이 이 신성한 나라를 위협하는 것을 허락할 수 없소, 오늘, 나는 이 정의의 검으로 너를 없애겠소!\"\n그 괴물은 떨며 마치 응답하듯 무서운 울부짖음을 냈다.\n폴룩스는 그 언어를 알지 못했고, 그 말을 이해할 생각도 없었다. 그는 보검을 들어 올려 사악한 기운을 발하는 괴물과 싸우기 시작했다. 괴물의 촉수가 동굴의 어두운 경계 곳곳에 뻗어 있었고, 빛나는 긴 검과 충돌하여 쨍하고 울리는 소리를 냈다.\n모든 영웅 이야기의 결말처럼, 용맹한 기사 용사는 괴물의 등을 타고 분노의 함성과 함께 칼끝을 괴물의 가슴에 꽂았다.\n괴물은 무너져 내렸고, 폴룩스는 홀가분한 호흡 속에 검 아래 서서히 퍼져가는 흔적을 멍하니 응시했다—그 추악하고 사악한 것의 몸에서 어떻게 이렇게 따뜻하고 붉은 피가 흐를 수 있을까?\n그는 꿈에서 갑자기 깨어났고, 그 피가 손에 묻은 끈적임이 떠나지 않는 듯했다. 그의 여린 시야는 카스토르가 소중히 간직한 오래된 책을 갑자기 봤는데, 침대 뒤 틈새에 신중히 숨겨져 있었다.\n그는 무심코 그 책을 펴자, 바로 카스토르가 자주 읽은 기사의 이야기가 나왔다. 책의 한가운데에는 다음과 같은 예언이 있었다:\n\"악한 괴물이 용사에게 패배했을 때, 모든 사람들은 하늘에서 이변을 보게 되리라, 태양은 어둠으로 변하고, 달은 피로 변하여리라.\"\n폴룩스는 미간을 찌푸리며 그 오래된 책을 제자리에 던져 놓고, 달빛 아래서 혼잣말로 기도를 시작했다.\n\"신의 하인들이 너희에게 축복을 베풀려 이곳에 보내졌으니, 너희의 죄악을 씻어내어 어둠에서 광명으로 돌아가고, 모든 순결하고 의로운 자들과 함께 순수한 땅에 들게 하소서……\"\n등불의 자는 그의 경건한 시종을 돌보지 않았고, 악몽이 가져온 불안은 여전히 그 마음 깊은 곳에서 떨고 있었다. 그것은 그가 잠들기 전 그의 혼이 꿈속에서 조용히 울고 있었기 때문이다."
  },
  CollectionHall_127148_Title = {
    Text = "왜곡된 기사 시"
  },
  CollectionHall_127149_Desc = {
    Text = "<Bold:1월 24일>\n몸에서 냄새가 났다.\n오늘 테레사 집사와 차로 집에 돌아가는 길에 남암프 구를 지나갔다.\n그것은 즐거운 경험이 아니었다.\n그곳은 위험한 곳이었고, @2몇몇 사람들은 이상한 상처가 나 있었는데, 마치 삼각형의 구멍 같았다.\n테레사 집사는 이것이 주님이 이단자들에게 내린 벌이라고 말했다.\n\n<Bold:2월 22일>\n한 달 동안 열이 났다.\n오늘 드디어 좀 먹었다. 신선한 스테이크였다, 부드럽고, 육즙이 많았고……\n그래, 육즙이 많았다.\n빨간색의 @2비릿하고 달콤한@2맛\n집 안의 모든 거울이 치워졌고, 포비조차도 나를 보지 못하게 됐다.\n히히. 그들은 모른다, 밤이 되면 나는 창문의 프로젝션에서 내 모습을 볼 수 있다.\n얼굴, 목, 가슴…… 위에서 아래까지, \n검은색 @2삼각형\n\n<Bold:3월 17일>\n내 눈막은 마치 붉은 얇은 천으로 덮인 것 같았다.\n세상은 혈액의 색깔로 변했다@3\n아버지가 혈안개 속에서 큰 소리로 나에게 소리를 질렀다. 이것은 그가 나에게 이렇게 큰 소리로 말한 처음이었다.\n그는 나에게 매우 가까웠지만, 그의 목소리는 매우 멀게 들렸다. 나는 절망, 혐오, 그리고 피의 냄새를 맡았다.\n하지 말아요@2나를 데려가지 마, 하지 말아요……"
  },
  CollectionHall_127149_Title = {
    Text = "탐식의 이야기"
  },
  CollectionHall_127150_Desc = {
    Text = "에리원 사람들이 회색의 돌 도시에 거주하며, 초록색 큰 호수와 인접해 있습니다. \n\n 큰 호수는 이름이 없습니다. 에리원 사람들이 기억하는 한, 그것은 이미 존재했습니다. \n 전설에 따르면, 악한 여마귀가 호수 깊은 곳에 봉인되어 있다고 합니다. \n 그녀는 큰 호수만큼 오래되었으며, 우주의 시작 때 무례하게 만들어진 공포스러운 존재입니다. \n 천진난만하고 겁 많은 에리원 사람들은 여마귀를 두려워하며, 그녀가 영원히 호수 바닥에서 조용히 머물도록 하기 위해 그녀를 달래려고 했습니다. \n\n “무엇을 해야 할까?” \n “그래, 무엇을 해야 할까?” \n “그럼 춤을 추자! 어쨌든 춤추는 건 언제나 좋은 일이야.” \n\n 그래서, 매번 볼록한 달이 뜰 때마다, 에리원 사람들은 호수 옆에 모여 종이로 만든 우상 앞에서 우아하게 춤을 추었습니다. \n 그때 달은 밝고 별은 드문드문 빛났으며, 모든 것이 평화로웠습니다. \n\n 수백 년 후, 에리원 사람들은 역사를 잊고, 우화를 잊고, 우상을 잊었습니다. \n 돌 도시 건립 1000년 기념 행사에서, 그들은 방종하게 웃고 맛있는 술을 마셨습니다. \n 시끄러운 소리가 호수로 투입되며, 돌이 물에 빠지는 것처럼, 무한한 원이 호수 중심에서부터 퍼져 나가 깊은 곳의 존재를 결국 건드렸습니다. \n 그래서, 볼록한 달이 뜰 때, 에리원 사람들은 청각 범위 외의 소리를 들었고, 시각 범위 외의 달과 불길을 보았습니다. \n 그들은 결국 침묵의 일부가 되었습니다. \n\n 이 무한한 공간 내의 영원한 침묵은 에리원 사람들에게 공포를 안겨주었습니다. \n 그들은 신비주의자처럼 움직이지 않고 앉아 있어야 했으며, 새로운 부족이 그들 앞에서 방종하게 웃고 맛있는 술을 마시며 오가고 반복되는 것을 지켜봐야 했습니다. \n 그래서 우주는 영원히 팽창할 것이며, 은하계는 점점 멀어지고, 모든 것이 사라질 것입니다. \n 그렇게 될 것입니다. \n 에리원 사람들이 그것 때문에 외롭다고 느끼는지는 중요하지 않습니다."
  },
  CollectionHall_127150_Title = {
    Text = "소리 없는 잔치"
  },
  CollectionHall_127151_Desc = {
    Text = "소녀가 눈을 뜨고 자신이 어둠 속에 있다는 것을 알았다. \n“안녕!” 그녀가 크게 외쳤다. “누가 있어?” \n울림이 보이지 않는 경계를 넘어서 흩어져 갔고, 소녀는 깊게 숨을 들이쉬고 다시 외쳤다. “누나, 브라운, 서쪽의 남자!” \n“누가 있어——” \n이전보다 더 큰 목소리로 물음이 멀리 날아갔다가 천천히 돌아왔다. 몇 줄기 형광 파란빛이 울림에 이끌려 멀리서 가까워졌고, 그것들은 수많은 떠다니는 먼지와 같은 입자들로 이루어져 있었으며, 뱀처럼 공중에서 구불구불 움직이고, 파도처럼 출렁였다. 한 줄기 한 줄기 빛이 자리에서 움직이지 않는 소녀를 스쳐 지나가며, 곧 하늘과 땅 전체를 별바다로 바꾸었고, 작은 입자들은 소녀의 손가락과 머리카락 사이를 통과했지만 흔적을 남기지 않았다. \n“이것은…… 무엇인가요?” \n발광하는 먼지는 그녀 주변에서 약간 출렁였지만 대답하지 않았다. \n“왁스상관을 기억해요, 누나를 기억해요, 나는…… 죽은 것 같아요, 여기가 천국인가요?” 그녀가 주위를 둘러보았다. “왜 천사조차 없을까요, 혹시 지옥일까요!” \n그녀의 목소리는 자신의 귀에 닿았지만, 이번에는 울림조차 나타나지 않았다. \n알 수 없는 외로움이 그녀의 마음속에서 일어났다. 황홀한 순간, 그녀는 누나와 브라운을 만났던 때 이전으로 돌아간 것 같았다. 어두운 하수도에서 냄새가 퍼져 있었고, 그녀는 추웠고 배가 고팠지만 떠날 수 없었다. 누군가가 그녀를 밀어내고 하수도 위에 큰 통을 올려놓았기 때문이었다. \n그녀는 자신의 얼굴을 두드렸고, 걸음을 내디뎠다. \n먼지가 그녀 앞에서 갈라지고, 그녀 뒤에서 모여들었다. 발을 들어올리고, 발을 내딛고, 발을 들어올리고, 발을 내딛고. 그렇게 그녀는 계속 걸었고, 얼마나 오래 걸었는지, 얼마나 멀리 걸었는지 알 수 없었다. 그녀 앞에는 더 많은 먼지와 어둠이 있었고, 그녀 뒤에는 온 길이나 온 방향 모두 흔적 없이 사라져버렸다. 그러다—— \n“깨어남에 성공했다, 젠킨, 젠킨, 들리나요？”"
  },
  CollectionHall_127151_Title = {
    Text = "길 없는 길"
  },
  CollectionHall_127152_Desc = {
    Text = "창조의 아버지 신은 별빛 속에서 왔다. \n그때의 땅은 붉은 불꽃으로 덮여 있었고, 불길이 치솟았다. 아버지 신의 발은 불 위에 내려섰다. \n아버지 신이 말했다, 불은 결국 꺼질 것이다. 그러자 불은 그렇게 되었다. \n움직이는 흙이 땅이 되었고, 아버지 신은 땅 위에 신언을 써놓았다: \n땅은 생명의 기반이 될 것이다. \n산은 산이 되고, 평원은 평원이 되었다. \n신언은 견고해졌고, 이것이 첫 번째 석판이었다. \n\n아버지 신이 구름이 무거워 보이자 말했다, 구름은 결국 비를 내릴 것이다. 그러자 구름은 그렇게 되었다. \n비가 모여서 물줄기가 되었고, 아버지 신은 그 위에 신언을 써놓았다: \n물은 온상이 될 것이다. \n물은 호수와 바다가 되었고, 바다는 땅을 잠겼다. \n신언은 견고해졌고, 이것이 두 번째 석판이었다. \n\n아버지 신이 물이 어둡게 보이자 말했다, 빛이 내려올 것이다. 그러자 빛은 그렇게 되었다. \n빛이 물 위에 내리자, 아버지 신은 빛 위에 신언을 써놓았다: \n빛은 양분을 제공할 것이다. \n빛은 따뜻함을 가져왔다. \n신언은 견고해졌고, 이것이 세 번째 석판이었다. \n\n아버지 신이 땅, 물, 빛이 모두 갖추어져 있다고 보고 말했다, 생명이 도래할 것이다. \n그는 자신의 피를 흘리며, 그 위에 신언을 써놓았다: \n피는 새로운 생명을 잉태할 것이다. \n아버지 신의 피가 흩어져 생명체가 되어 바다에서 번성했다. \n신언은 견고해졌고, 이것이 네 번째 석판이었다. \n\n아버지 신이 생명이 생겼다고 보고 말했다, 생물은 영원히 변화할 것이다. 생물은 그렇게 되었다. \n보이지 않게 작은 것이 물러간 바다의 땅 위로 기어올랐다. \n아버지 신은 변화하는 것 위에 신언을 써놓았다: \n변화는 멈춰서는 안 된다. \n육지 위로 기어올라온 것은 뿌리와 줄기, 사지를 자라게 하고 다양한 모습을 갖추었다. \n신언은 견고해졌고, 이것이 다섯 번째 석판이었다. \n\n아버지 신이 생명이 생겼고, 변화도 생겼다고 보고 말했다, 죽음도 도래할 것이다. 그러자 죽음이 왔다. \n늙은 것이 죽고, 약한 것이 죽었다. 아버지 신은 죽음 위에 신언을 써놓았다: \n죽은 것은 처음으로 돌아갈 것이다. \n죽은 자의 육체는 서서히 사라지고, 아버지 신의 품으로 돌아갔다. \n신언은 견고해졌고, 이것이 여섯 번째 석판이었다. \n\n아버지 신이 생명, 죽음, 변화가 모두 갖추어져 있다고 보고 말했다, 이 모든 것은 나의 유물이다. 나는 축복을 남겨두겠다. \n아버지 신은 자신의 뼈를 꺼내어 그 위에 신언을 써놓았다: \n모든 것의 끝에서, 나의 뼈를 사용하여 나의 권력을 대행할 수 있다. \n혈육의 대가로 생명을 부여한다. \n신언은 견고해졌고, 이것이 일곱 번째 석판이었다. \n\n아버지 신이 모든 것이 갖추어졌다고 보고 쉬기 시작했다. \n물이 아버지 신을 감싸주고, 빛이 아버지 신에게 따뜻함을 제공하며, 땅이 아버지 신을 가렸다. \n그 후 아버지 신은 깊은 잠에 빠졌고, 모든 것은 아버지 신의 말씀대로 살아가고 있다. 그것이 지금의 세상이다."
  },
  CollectionHall_127152_Title = {
    Text = "신언의 석판"
  },
  CollectionHall_127153_Desc = {
    Text = "그는 모든 것을 아는 왕이며, 리모리아의 최고 권위자이다. \n청금석은 그의 왕좌이고, 황금은 그의 관이다. 영혼은 그의 권세이며, 그는 가장 높은 곳에서 잠을 잔다. \n신을 섬기는 사제들도 그를 섬기며, 그 앞에 무릎을 꿇는다. \n그들은 그의 충실타래한 신하들이며, 그의 성실타래한 신도들이다. \n\n신은 밤에 월광을 파견하여, 그를 영원한 깊은 잠의 궁전으로 초대한다. \n거기서, 그들은 그에게 영혼의 양식을 나누어 주며, 신의 지혜를 부여한다. \n그들은 그에게 끝없는 꿈을 선사하여, 그가 만물의 초기를 보고, 시간의 종말을 볼 수 있게 한다. \n그는 깨달았다: 만물의 시작은 카오스이며, 신들은 그 속에서 깨어남하여, 다크에 떠 있는 궁전을 세웠다. \n그는 깨달았다: 시간의 끝은 어둠이며, 모든 것이 다시 카오스로 돌아간다. \n\n왕들의 왕이시여, 신의 사랑받는 자이시여, \n누가 당신과 같을 수 있겠는가? \n누가 당신처럼 꿈속에서 다스릴 수 있으며, 누가 당신처럼 위엄이 있을까? \n고귀한 신왕이시여, 어린 지배자이시여, \n당신은 마음껏 깊은 잠에 빠져들소서. \n당신의 신민들과 신도들은 인내하며 기다리리니, 당신이 신의 예언을 가져올 때까지. \n존경하는 나선 지배자, 심연의 주재자이시여, \n우리가 당신의 이름을 호출하는 것을 허락하시고, 우리에게 보호를 베풀어 주소서, \n투루, 투루."
  },
  CollectionHall_127153_Title = {
    Text = "신왕의 찬송가"
  },
  CollectionHall_127154_Desc = {
    Text = "다년간 나는 유우하시를 생각해 왔습니다. \n하지만 이 신전의 폐허에서야 비로소 그를 진정으로 볼 수 있었습니다. \n그는 무거운 족쇄에 감싸져 바닥에 엎드려 있어, 목을 빼고 애써 이미 상한 음식에 다가갈 수밖에 없었습니다. \n개처럼. \n\n칼리구라가 죽은 후, 그는 폭군의 공모자로 신전의 폐허에 묶여 있었습니다. \n나는 손에 든 족쇄를 끌어 당겨 토레스의 노예를 데려왔습니다. \n그는 즉시 몸을 일으키고 동공이 확대되었으며, 목에서는 급하게 삼키는 소리가 났습니다. \n\n“기다려.” \n나는 족쇄를 잡아 그가 닿지 않는 거리에 노예를 끌어당겼습니다. \n“나를 위해 한 사람을 죽여줘.” \n그는 입을 벌리며 날카로운 짐승의 이빨을 드러냈습니다. \n“너는 나에게 그렇게 말한 19번째 인간이지만, 나는 너를 거절해야 한다.” \n나는 최대한 표정을 굳히며 실타래망감을 숨기려 노력했습니다: \n“왜?” \n“네가 나에게 천 명을 죽이라고 하면, 나는 매우 기쁠 것이다. 하지만 한 명? 네 제안은 충분하지 않다.” \n“만약 그 사람이 현 황제라면?” \n나는 깊게 숨을 들이쉬었습니다. \n“이 제안이 충분한가?” \n유우하시는 크게 웃었습니다: \n“이것은 수학 문제다, 내 옛 친구. 하나는 하나이고, 천은 천이다.” \n\n“불탔다, 금궁이 불탔다!” \n먼 곳에서 거대한 불길이 일어났습니다. \n폭군, 폭군…… \n나는 절망에 차서 울었고, 세네카를 위해, 그리고 곧 폐허가 될 화려한 궁전을 위해. \n“그렇게 슬퍼?” \n유우하시가 다가왔습니다. \n그는 이미 토레스의 노예를 먹고, 만족스럽게 입술을 빨고 있었습니다. \n그래, 나는 그에게 약속했다. 폭군을 죽일 수 있다면, 자유뿐 아니라 천 명의 무고한 생명도 계속 즐길 수 있을 것이라고. \n그는 이 대화가 무엇을 의미하는지 이해할 수 있을까? \n그는 무고한 폭군을 섬기는 것이 무엇을 의미하는지 이해할 수 있을까? \n아마도 못할 것이다. \n그는 단지 짐승일 뿐이다. \n\n“로마는 폐허와 같다.” 짐승이 말했습니다. \n“혹은, 너희들의 나라, 세상…… \n내게는 무의미하고 끝이 없는 폐허일 뿐이다. \n너희들은 그것 때문에 눈물을 흘리고 서로를 죽이며, 모든 헛된 일과 무의미한 일을 했다…… \n솔직히, 나는 이해하지 못한다.” \n\n나는 그의 상처투성이의 신체를 바라보았습니다. \n이는 수백만의 혈육으로 이루어진 마상체로, 수백 년 동안 파괴되고 재조립되었으며, 로마와 같았습니다. \n“그럼 너는? 너도 폐허인가?” \n“아마도.” \n그는 허리를 펴며, 먼 곳에서 온 황금빛 불꽃이 그의 좁은 눈에서 뛰어올랐습니다. \n“하지만 나는 상관하지 않는다.”"
  },
  CollectionHall_127154_Title = {
    Text = "혈육의 광연"
  },
  CollectionHall_127155_Desc = {
    Text = "나선의 지배자여, 제 기도를 들어주소서. \n 당신의 예언을 내리시고, 저에게 계시를 주소서, \n 당신의 나라를 복원할 수 있도록 하소서. \n 이 무신앙의 땅, 바다로 둘러싸인 빙원에서, \n 당신의 석주를 세우고, 당신의 신전을 짓소서. \n\n 심연의 주인이여, 이는 당신을 위한 제물입니다. \n 순수한 혈육은 만월의 어린양에서, 강건한 마음은 성년의 소에서, \n 날카로운 눈은 하늘을 나는 독수리에서, 단단한 뼈는 순항하는 고래에서 나옵니다. \n 청금석은 당신의 왕좌, 금은 당신의 관입니다. \n 당신의 꿈을 저에게 주시고, 신의 말씀을 알려주소서, \n 당신의 몸을 복원할 수 있도록 하소서. \n 이 빙하 아래의 심연, 이 바다 아래의 영역에서, \n 올바른 시기에 태어난 모체를 바치겠습니다. \n\n 모든 것을 아는 리모리아의 왕이여, 제 기도에 응답해 주소서. \n 당신이 바다로 잠들어 있는 동안, 이미 수백 년이 흘렀습니다. \n 당신의 이름으로, 당신의 일을 행하며, 당신의 아름다운 이름을 전파하였습니다. \n 굳건한 것은 제 믿음, 경건한 것은 제 마음입니다. \n 당신은 유일한 신왕, 불멸자의 화신이십니다. \n 제 기다림을 마무리하시고, 다시 세상에 임하시어, 저가 당신의 지혜로운 말씀을 들을 수 있게 해주소서."
  },
  CollectionHall_127155_Title = {
    Text = "신앙의 힘"
  },
  CollectionHall_127156_Desc = {
    Text = "오레타가 태어났을 때, 대홍수로 인한 도시의 영향은 완전히 사라졌지만, 오지의 작은 마을에서는 사람들이 살아남기 위해 고생하고 있었다. \n\n 홍수는 사람들이 바다와 강을 두려워하게 만들었고, 떠날 수 있던 이들은 이미 떠났다. 지금 이 작은 어촌에 남아 있는 것은 외부에서 생활할 곳을 찾기 힘든 여자들과 아이들뿐이었다. \n 이 침울하고 한적한 곳에서 오레타는 유일한 아이였다. \n\n 그녀는 할머니가 들려준 동화를 고집스럽게 믿었다. 부모님은 이미 바다로 돌아갔고, 그들은 오레타가 자라기를 기다리고 있다. 오레타가 자라면 모두가 다시 만나 행복한 가족이 될 것이다. \n\n 말을 하지 못할 때, 따뜻한 품에서 잠이 들었던 것 같았지만, 부모님에 대한 다른 기억은 오레타가 거의 기억하지 못했다. \n 하지만 조용한 곳에서 태어나 자란 아이로서, 오레타는 '외로움'이나 '고독'을 이해하지 못했다. 그녀는 자신의 친구들이 있었다. \n\n 홍수로 겁을 먹은 어른들과 달리, 오레타는 바다를 두려워하지 않았다. \n 바다 왕국의 주민으로서, 바다와 친구가 되는 것이 당연했다. \n 오레타는 '동향'들과 함께 놀기 위해 배웠다. \n 그녀는 조개가 움직이는 모습을 흉내 내며 춤추고, 산호초 사이를 누비는 클라운피시의 행동을 따라했다. \n 그녀는 거북이 등에 엎드려, 파도에 실타래려 멀리멀리 떠났다. \n 그녀는 달빛이 가득 찬 바다에서 해파리 무리와 함께 놀았다. \n\n 그녀는 행복했고, 상상력이 넘쳤으며, 요정 같았다. \n\n 그녀는 꿈이었다. \n"
  },
  CollectionHall_127156_Title = {
    Text = "바다의 꿈"
  },
  CollectionHall_127157_Desc = {
    Text = "눈앞에서 시골 처녀가 화려한 드레스, 금은 보석, 깃털 부채를 차고 상류층의 세계로 잠입하는 것을 보았습니다……\n이보다 더 어울리지 않는 일은 없습니다. 하위 계층이 상위 계층을 침범하는 것이죠……!\n제 생각에는 하층민들이 적절한 표식과 배지를 착용하도록 강제해야 합니다. 그래야 우리와 혼동되지 않을 것입니다.\n——필립 하로드 공작\n\n만약 당신이 렌티니언에 산다면, 소위 말하는 「소렐 효과」에 대해 알고 있을 것입니다. \n아직도 집안 옷이 팔리지 않아 고민하고 있나요? 그렇다면 당신은 기도해야 합니다. 소렐 부인의 관심을 받을 수 있는 방법을 찾아야 해요——네, 아무리 바보 같고 우스꽝스러운 돼지 꼬리 모자라도, 소렐 부인이 머리에 쓰기만 하면 그 모자는 대박이 날 겁니다. \n그녀는 새로운 시대의 대중 아이콘입니다. \n——「소렐 부인의 명성 테스트」, 《숙녀 가이드》\n\n그것은 맑고 화창한 여름밤이었습니다. \n우리는 대리석으로 된 테라스에 앉아 오래된 귀부인 술을 마시며 시와 세계 평화에 대해 이야기했습니다. \n그런데 거기서 어떤 일이 있었죠@4\n핵심을 말해요? 기침기침, 죄송합니다……\n결론적으로, 이 여자는 저에게 3,000 레오방, 두 채의 수리란 부동산, 그리고 진실타래된 마음까지 속여 갔습니다! \n——익명을 요구한 한 마음이 상한 자작"
  },
  CollectionHall_127157_Title = {
    Text = "장미의 이름으로"
  },
  CollectionHall_127158_Desc = {
    Text = "분리. 경험. 몰려오다. 침략. \n\n페리시테인의 세미트 어근 'p-l-sh'의 진정한 의미에 대해서는 경전 학자들 사이에서 항상 의견이 분분했다. \n평생 처음으로, 고리아는 이들 노학자들이 실타래제로는 꽤 실타래력이 있다는 것을 느꼈다. 왜냐하면 이 네 개의 짧은 단어는 그가 페리시테인으로서 살아온 인생을 거의 요약하고 있기 때문이다. \n\n페리시테인은 진정한 해양 민족이었다. \n그들은 피 냄새를 따라 모여드는 긴 꼬리 상어처럼, 거주할 수 있는 섬을 찾아내고, 거기서 모든 원주민들을 죽였다. \n\n페리시테인은 지치지 않았다. \n그들은 머물지 않았다. 모든 것이 정리되면, 불안한 유전자들이 다시 그들을 떠나게 만들었고, 새로운 사냥감을 찾았다. \n\n페리시테인은 내일을 걱정하지 않았다. \n그들은 약식해 온 부를 놀라운 속도로 낭비했고, 마지막 한 방울의 포도주까지 마셨으며, 그 후에는 자녀를 낳고, 싸우고, 배반하는 것에 열중했다…… \n\n출항할 때, 고리아는 배가 바다 위에서 남긴 궤적을 돌아보았다. \n페리시테인의 피, 원주민의 피, 적의 피, 바다새의 피…… \n그들은 한 곳에 모여, 마치 검붉은 먹물이 무한한 푸른 바다로 흘러들어가는 것 같았다. \n\n다음 날, 태양은 평소와 같이 떠올랐고, 바닷물은 천만 개의 파편처럼 반짝임하며 흔적 없이 움직였다. \n그들은 바다 위에 있었지만, 바다는 이미 그들을 망각했다."
  },
  CollectionHall_127158_Title = {
    Text = "거인의 검"
  },
  CollectionHall_127159_Desc = {
    Text = "카슈리아 민간에는 침몰 문명의 전설이 전해져 내려오고 있습니다. \n\n전설에 따르면, 역사 기록 이전에 별들의 비정상적인 이동으로 인해 원시 문명이 바다 속으로 가라앉았으며, 카슈리아인들은 그 문명의 후예들이라고 합니다. \n상업과 어업 외에도, 카슈리아인들이 바다로 나가는 주요 목적 중 하나가 실타래종된 선조 문명을 찾는 것입니다. \n그들은 특정 별자리 아래에서 태어난 여자가 선조 문명과 연결되어 있다고 믿습니다. 이 여성들은 침몰한 문명의 위치를 안내하고, 풍랑 속에서도 선단을 보호할 수 있다고 합니다. \n\n힐레스트는 그렇게 선택되었습니다. \n그녀는 하얀 돛대 위에 묶여 있었고, 아래에서 분주히 움직이는 사람들에게 전혀 관심이 없었습니다. \n그녀는 호기심도 느끼지 않았습니다. \n\n힐레스트는 바닷바람과 바다새의 움직임을 통해 해상의 날씨를 감지할 수 있었고, 때때로 멀리 잠든 땅에서 온 기운도 느낄 수 있었습니다. \n그녀는 본능적으로 바다와 항해에 속해 있다는 생각이 들었습니다. — 힐레스트는 종종 그렇게 생각하며, 갇혀 있는 사실타래이 그녀의 마음에 어떤 파문도 일으키지 않는 것 같았습니다. \n때로는 그녀가 돛대를 떠나 하늘을 나는 흰 새들을 쫓아갔을 때, 배는 그녀를 놓치지 않기 위해 그녀를 뒤쫓았습니다. \n사람들은 소녀가 순조로운 항해의 상징이라고 믿었고, 축복받은 배는 안전하게 돌아와 막대한 부와 선진 문명을 가져올 수 있다고 생각했습니다. \n그녀는 그런 사실타래을 전혀 알지 못했습니다."
  },
  CollectionHall_127159_Title = {
    Text = "인도하는 돛"
  },
  CollectionHall_127160_Desc = {
    Text = "던, 던, 던. \n발자국 소리가 멀리서 가까워지며, 모자를 쓴 신사가 폐허를 지나 죽어가는 경비원 앞에 섰다. \n신사: 당신이 여기서 뭐 하는 거야? \n\n(신사는 심한 구어증을 앓고 있고, 경비원은 말을 돌리는 것을 좋아한다. 독자의 편의를 위해 필자는 대화의 핵심만 발췌하였다.) \n\n경비원: 나는 감옥을 지키고 있어요. \n신사는 주변의 무인 평원과 융식으로 인해 천천히 무너지고 있는 폐허의 잔해를 둘러보았다. \n신사: 하지만 여기에는 감옥도, 수감자도 없어요. 당신의 왕국은 이미 존재하지 않아요. \n경비원: 나는 감옥을 지키고 있어요. \n신사: 왜 그래? \n경비원은 고개를 들고, 아직 어린 얼굴에 당황스럽고 단호한 표정을 지었다. \n경비원: 모르겠어요…… 집으로 돌아가고 싶어요. \n경비원: 나는 그분을 위해 감옥을 지키고 있어요. 그분이 기뻐하시면, 나는 집으로 돌아갈 수 있어요. \n그분이 누구인지, 왜 그분을 위해 감옥을 지키는지는 본인도 잘 모르고 있었다. \n신사는 추궁하지 않았다. 마치 그것이 당연한 일인 것처럼. \n신사: 당신의 고향은 어떤 곳이었나요? \n경비원: 거기에는 겨울과 밤뿐이에요. 그리고 한눈에 끝이 보이지 않는 숲과 바다가 있어요. \n신사: 들어보니 살기 좋지 않은 곳 같아요. \n경비원: 난 낮을 싫어해요. 보시다시피, 나는 촛농으로 만들어졌어요. 태양에 닿으면 사라져버려요. \n경비원: 그래서 난 이곳에 숨어 있어요. 스스로 집으로 돌아갈 수가 없어요. \n신사는 무엇인가 생각하며 고개를 끄덕였다. 갑자기 들떠 보였다. \n신사: 정말 우연이네요, 당신은 촛농으로 만들어졌고, 나는 우연히 랍상사예요. \n신사: 우리 약속을 해봅시다——나는 당신이 햇빛 아래 걸을 수 있게 해줄 수 있어요, 또 당신에게 집으로 돌아가는 길을 찾아줄 수도 있어요. 대신, 당신은 나의 조수로 되어야 해요. \n경비원: 조수, 그게 뭔가요? \n신사: 당신은 내 왁스상관을 지켜줄 수 있어요. 그것은 이 감옥과 다르죠, 그것은 예술이고, 예술은 무너지지 않아요. \n경비원: 예술이 그렇게 대단해요? \n신사는 기쁘게 웃었다. \n신사: 네, 정말 그렇게 대단해요. \n\n이야기의 결말은, 경비원이 헷갈린 채로 신사를 따라갔다. 마치 그녀가 이 감옥에 헷갈린 채로 온 것처럼. \n그녀는 언제나 상황에 맞춰 살아가는 사람이었다."
  },
  CollectionHall_127160_Title = {
    Text = "떠도는 욕망"
  },
  CollectionHall_127161_Desc = {
    Text = "당신은 아무도 없는 황무지에 발을 내딛었다.\n인간의 활동의 흔적은 오래 전에 이미 소멸했고, 영혼이 고통받는 생명체가 재와 먼지 속에서 힘들게 나아갈 뿐이었다.\n여기서의 생존은 부러움의 가치가 전혀 없으며, 여행의 끝은 아무도 알지 못해 끝없는 순환의 풍경 속을 떠돌고 또 떠돈다.\n그들의 발걸음이 무겁게 멈추며, 땅에 쓰러지고는 하늘을 향해 손을 흔들며 부르짖는다——\n\n내가 헤매고 있는 끝에서,\n시신의 뼈를 기름진 땅, 자양분, 원천으로 삼아, 연약한 새싹이 다시 땅을 터뜨릴 수 있기를."
  },
  CollectionHall_127161_Title = {
    Text = "폐허로부터의 부활"
  },
  CollectionHall_127162_Desc = {
    Text = "그녀는 밤의 깊은 곳에서 수천 번 물었다. 왜 그녀가 이 끝없는 고통을 견뎌야 하는가? \n아무도 대답하지 않았다. \n속삭임이 갈라진 목을 지나 조각이 되어 어떤 신성의 귀에도 전달되지 않았다. \n그녀의 고통은 오래도록 사라지지 않았고, 점차 고름으로 변해 더욱 진한 증오로 변했다. \n어느 날 갑자기, 그녀는 주변 사람들의 몸에서 검은 액체가 흘러나오기 시작했다는 것을 발견했다. 자신의 몸에서 흘러나오는 피와 매우 비슷했다. \n그들은 곧 광기에 사로잡혔고, 마치 그녀와 같았다. \n아마도 그것이 그들의 고통이었을 것이다. 그녀는 냉정하게 관찰하며, 은근히 만족감을 느꼈다. \n하지만 만약 그것이 고통이라면, 자신은 이미 오래전에 검은색에 잠겨버렸어야 한다. \n그녀는 그들이 남긴 검은색에 접근했지만, 의외로 자유를 얻었다. \n자유는 그녀에게 해방을 가져다주지 않았다. 그녀는 지옥에서 천 년 동안 유배된 악귀처럼, 마음속 소망은 이미 증오에 의해 완전히 부식되었다. \n그녀의 몸은 족쇄에 박혀 있었고, 그녀의 영혼은 납덩이로 가득 찼다. \n오직 처절한 비명만이 그녀의 무거운 영혼을 씻어내어, 그녀가 시원하게 숨을 쉴 수 있게 해주었다. \n오세요, 내가 맛본 것을 맛보세요, 당신을 나로 만들어 주세요. \n그녀는 빨간색이 얼마나 아름다운 색인지 발견했다. \n그녀는 마침내 깨달았다. 고통에는 이유가 없다. \n스스로 고통을 마시거나, 다른 사람과 함께 맛보는 것뿐이다. \n오늘 밤, 그녀는 쓴 술을 가득 따랐고, 온 도시를 초대했다. \n"
  },
  CollectionHall_127162_Title = {
    Text = "진홍빛으로 가라앉다"
  },
  CollectionHall_127163_Desc = {
    Text = "내 배는 무언가에 꽉 끼여, 프로펠러가 힘겹게 투쟁하며 끔찍한 소리를 냈습니다.\n우리 머리 위에서 적운이 모이고, 검은 구름 속에서 번개가 치고 있었습니다.\n번개가 돛대를 친 순간, 프로펠러가 얽매임에서 벗어나 다시 움직이기 시작했습니다.\n나는 안도의 한숨을 내쉬었지만, 기관사는 비명을 지르기 시작했습니다.\n\n해수에 끈적한 액체가 섞였습니다. 폭풍 속에서 냄새는 바람에 날려 멀리 갔고, 나는 죽음만 맡을 수 있었습니다.\n하지만 나는 그 형광색 액체가 어떤 피라는 것을 깨달았습니다.\n나의 가장 소중한 동료, 나의 가장 신뢰하는 배는 가라앉기 전 마지막 힘을 다해 — 그녀의 해수를 갈라야 할 날개가 괴물의 팔을 무자비하게 잘랐습니다.\n\n이는 행운의 징조입니다! 우리는 곧 폭풍을 떠날 것입니다!\n나는 이를 통해 선원들을 안심시키려고 했지만, 고개를 들었더니 어두운 바다 중앙에 빛이 나타났습니다.\n그것은 등대인가? 어떻게 가능할까? 아니, 불가능합니다.\n여기는 대양의 중심이며, 가장 가까운 육지는 수백 해리 떨어져 있습니다. 어떻게 사람이 여기서 등대를 지을 수 있을까요?\n\n선원들은 울며, 기도하며, 고향의 노래를 함께 불렀습니다.\n그런데 그 등대가 갑자기 꺼졌습니다.\n모든 빛이 사라지고, 포효하던 폭풍이 갑판 위에 가는 비로 변했습니다.\n선원들은 자비로운 주님을 찬미하며, 재난 후 살아남은 기쁨에 잠겼습니다.\n하지만 나는 분명히 보았습니다.\n\n그 빛 속에서 사라진 것은 분명히 아름다운 여인의 모습이었습니다."
  },
  CollectionHall_127163_Title = {
    Text = "폭우 속에서"
  },
  CollectionHall_127164_Desc = {
    Text = "영웅이 마침내 그의 위대한 여정을 마치고, 사람들이 그림책의 마지막 페이지를 덮고 깊은 잠에 빠져든다. \n\n긴 밤이 찾아오면, 시로의 이야기는 이제 시작될 뿐이다. \n\n그녀는 긴 해안선을 따라 북쪽으로 계속 진행하며, 계곡을 건너고 산을 넘어 극한의 추위가 지배하는 땅의 끝까지 간다. \n그 충격적인 저항이 일어난 지 이미 오랜 세월이 흘렀지만, 시로가 가는 곳마다 바람은 순조롭고 모든 일이 잘 이루어진다. 노예와 주인 사이에는 미묘한 균형이 유지되고, 격렬한 저항은 어색하고 우스꽝스럽게 보인다. \n그녀는 의심받고, 조롱받고, 결국 잊혀졌다. \n하지만 그녀는 결코 변명하지 않는다. \n\n전사 시로는 어디서 왔다가 어디로 사라지는지 알 수 없다. 그녀는 육간해의 중심부에 자유의 씨앗을 깊이 묻어 두었다. 5년, 10년, 100년…… \n언젠가는 그것들이 흙을 뚫고 튼튼히 자라날 것이다. \n\n누구도 이 스파르타 달인의 최종 안식처를 모른다. 그녀의 옛 친구 이바미논다가 그녀의 시체를 수습했다는 말이 있다. \n여러 해 후, 자스민 꽃이 만발한 초록 언덕을 지나가다 보면, 작은 무덤 하나를 볼 수 있을지도 모른다. 그 무덤에는 이렇게 적혀 있다: \n\n이 풀밭 아래에는 전사가 묻혀 있다, 또는 \n그녀가 전사였다는 것을 \n그녀는 늙은 페리클레스의 딸이자, 제로섬의 자랑이었다 \n시인 플라쿠스는 그녀의 용감함을 찬양했다 \n검은 머리의 스파르타인들은 그녀의 공적을 더 잘 알고 있었다"
  },
  CollectionHall_127164_Title = {
    Text = "족쇄를 벗어던진 날"
  },
  CollectionHall_127165_Desc = {
    Text = "A.F.@1년@1월@1일\n\n08:00\n\n번호 107부터 133까지의 부품 조립 진행.\n\nC 유형 부품은 이것만 남았다. 완성 후 자동 인형 「틱택맨」의 에너지 코어로 투입할 예정.\n\n직접 조립하려 했지만, @2이(가) 말하길, 책임자는 자신의 동료를 신뢰하는 법을 배워야 한다고.\n\n잘도 말하는군, 부품 검수를 한밤중까지 하는 사람이 바로 자기인 주제에.\n\n-------\n\nA.F.@1년@1월@1일\n\n00:21\n\n전동기 MF311000 조립 완료, 기어 맞물림 양호, 배관 원활, 현재 각 기능 정상. 최종 수정 진행 예정.\n\n13:07\n\n특수 에너지 S 접속, 전동기 MF311000 운전 양호, EA307850호 인조 구체와의 적합성 양호, 인조 구체 정상 운전.\n\n@2은(는) 낙관적이다. 이번에는 이전보다 더 멀리 나아갈 수 있을 거라고 생각한다. 다섯 번째 깨어남 시도 때 무슨 일이 있었는지 잊지 말라고 상기시켰더니, 귀를 막고 안 들린다고 했다. 그때 내가 빠르게 대처하지 않았더라면, 에너지 코어 자연 발화의 불길이 그녀의 머리카락을 다 태워버렸을 것이다.\n\n한번 민머리를 경험하게 해줘야 하는데, 그래야 신중함을 배울지도 모르겠다.\n\n-------\n\nA.F.@1년@1월@1일\n\n14:55\n\n최종 준비 완료, 에너지 준비 완료, 구속 장치 가동, 구속 상태: 양호. 동체는 깨어남 완료 후 장착 예정.\n\n15:00\n\n「틱택맨」 제13차 기동 시도 개시.\n\n15:05\n\n동체 EA307853 운전 정상, 전동기 MF311000 운전 정상. 「틱택맨」 경부 관절 활동 정상, 「틱택맨」 두부 부품 운전 정상.\n\n15:15\n\n「틱택맨」 눈 깜빡임, 시선 추적, 입 벌리기 명령 성공적으로 수행. 전동기에 발열 현상이 있으나 허용 범위 내.\n\n사지 부품 장착 진행 예정, 이번에는 순조롭기를 빈다.\n\n18:07\n\n보행 명령 수행 시, 전동기 코어 용해, 회로 소실타래. 특수 에너지 S는 손상 없음.\n\n@2은(는) 이 특수 에너지를 매우 소중히 여기며, 나조차도 접촉을 금지한다. 이해할 수 있다. 그것은 정말 신비로운 물건으로, 겉보기에는 평범한 금속 은처럼 보이고 에너지 저장 능력이 있을 것 같지도 않은데, 실타래제로 자동 인형에 동력을 공급할 수 있으며, 그토록 높은 온도에도 손상되지 않았으니 정말 불가사의하다.\n\n만약 이것을 대량 생산하거나 대량 채굴할 수 있다면……\n\n언젠가 다시 그녀에게 물어봐야겠다. 이 인형에 얼마나 더 시간을 쏟을 생각인지도 모르겠고. 언젠가 그녀 자신이 인형이 되어도 나는 놀라지 않을 것이다.\n"
  },
  CollectionHall_127165_Title = {
    Text = "노심융해"
  },
  CollectionHall_127166_Desc = {
    Text = "「우리는 세속적인 구리와 철로 별의 궤적을 측정하지만, 끝없는 심연은 자신의 알고리즘을 가지고 있으며, 흐림과 맑음이 변동한다。」\n서서히 가라앉는 유람선 안에서, 클레퍼산트는 《항해사의 애가》를 읊조린다。\n그녀는 이미 자신의 운명을 알고 있었고, 자신의 운명을 선택했기에 죽음 앞에서도 두려움이 없었다. 오히려 평온함만이 있었다——평온하게 타오르고, 평온하게 마지막 항해를 마친다.\n그러나 불타오르는 화염이 너무 뜨거워 그녀는 앞길을 보지 못하고, 소리도 낼 수 없으며, 깃발을 흔들 수도 없다. 이렇게 결핍된 안내로 인해, 배가 올바르게 항해할 수 있을까?\n그녀는 알지 못했고, 그래서 두려움과 걱정을 느낀다.\n이때 《항해사의 애가》가 안내를 준다:「젊은 항해사여, 너는 결국 염수에 품겨, 길을 안내하는 인광으로 변하리라。」\n길을 안내하는 인광? 클레퍼산트는 침묵했다. 그녀는 확실타래히 수병들 사이에서 전해지는 성 에르모의 불에 대한 이야기를 들었던 기억이 있다. 하지만 빈약한 인간의 몸이 어떻게 세상을 비추는 성스러운 불이 될 수 있을까?\n하지만 희망이 희박하더라도, 클레퍼산트는 마음속으로 끊임없이 기도했다: 자신이 직무를 다하고, 마지막 안내 작업을 완수할 수 있도록.\n클레퍼산트를 제외하고는 누구도 이 기도를 들을 수 없었지만, 그건 이미 충분했다——\n어둠 속에서 은심은 부식 액을 영양으로 삼아 강렬한 빛을 발산하며, 그녀의 마지막 소원을 이뤘다.\n「조수의 검은 책이 너의 이름을 기록할 것이고, 울부짖는 격랑이 너를 위해 영원한 진혼곡을 연주하리라。」\n그녀는 결국 《항해사의 애가》가 말한 대로 바다에서 죽었다.\n그러나 그녀는 《항해사의 애가》를 초월했다.\n그것은 인간 항해사가 바다를 마주할 때의 교만과 충고였지만, 이제 그녀는 성 에르모의 불이 되어, 영원히 배를 안내하는 존재가 되었다."
  },
  CollectionHall_127166_Title = {
    Text = "성화 속 길잡이"
  },
  CollectionHall_127167_Desc = {
    Text = "그녀는 죽음과 함께 태어난 저주받은 아이, 축복받지 못한 딸로 불렸다. \n그녀와 그녀의 여동생의 “요람”이 막 깨졌을 때, 눈부신 빛이 틈 사이로 흘러나와 땅에 뿌리를 내렸다. 순식간에 푸른 잔디가 시들고, 꽃들이 시들었으며, 멀리 있는 커다란 나무와 호수 속의 물고기들까지도 그녀에게서 생기를 빼앗겨 영혼 없는 껍데기가 되었다. \n그녀의 부족 사람들은 크게 당황하며 모든 다른 요람들을 옮기기 시작했다. 그녀는 요람을 깨려고 애썼고, 마치 병아리가 알에서 나오듯 손을 뻗었지만, 모두 혐오스럽다는 듯 피했다. 그녀가 본 것은 오직 혐오로 가득 찬 얼굴들이었다. \n오직 그녀의 여동생만이, 그녀보다 늦게 태어났지만 더 일찍 성숙한 여동생만이, 항상 그녀를 안아주었다. 그녀는 영롱한 새처럼 맑은 목소리로 계속해서 요람곡을 불러주었다. \n자세요, 자세요, 내 사랑하는 누나; \n자세요, 자세요, 좋은 꿈이 곧 강림할 거예요. \n\n그녀는 존재하지 말았어야 했다. 만약 그녀가 존재하지 않았다면, 그녀의 빛나는 여동생은 죄악의 그림자에 물들지 않았을 것이다. \n내 가련한 여동생이여, 그녀는 늘 생각했다. 너는 감당해야 할 삶의 대가를 짊어지고 있다. \n내 가련한 여동생이여, 그녀는 늘 생각했다. 누나가 할 수만 있다면, 반드시 너를 위해 최선을 다할 것이다. \n자세요, 자세요, 내 사랑하는 여동생; \n자세요, 자세요, 꿈속에서도 너를 사랑해."
  },
  CollectionHall_127167_Title = {
    Text = "삼켜진 자장가"
  },
  CollectionHall_127168_Desc = {
    Text = "그는 교회의 첨탑이 초처럼 녹아 신부의 순백의 깃털을 적시는 것을 보았다. 스테인드글라스의 성자상은 급속히 부식되어 해골이 되었다가 순간적으로 아기로 되돌아갔다. 신도들의 입에서 날카롭고 둥근 기하체들이 송영되어 전체 공간을 가득 채웠다.\n그는 기차역의 공간이 반복적으로 엇갈려 유클리드 밖의 공간이 되는 것을 보았으며, 멀리 있는 플랫폼은 가까이 있고 가까운 티켓 게이트는 닿지 못할 거리에 있었다. 기차역의 시계는 시계 반대 방향으로 회전하고, 마른 해골 같은 사람들은 보이지 않는 선으로 잡아당겨지며 후퇴하며 걸어갔다. 진한 보라색 연무는 구름에서 기차의 연기구멍으로 흘러들어갔다.\n그는 숲속의 「텅 빈 곳」이 실타래체로 응고되는 것을 보았다. 나무, 바위, 덩굴은 단지 「텅 빈 곳」의 경계를 묘사하는 반투명한 윤곽선일 뿐이었다. 백조의 깃털은 계속 변화하는 모자이크 색조각이다. 그것들이 지나간 곳은 호수물이 반투명의 컬러 유리로 응고되었다. 커플이 기대 있는 벤치 아래에서는 눈길을 끄는 오렌지색 그림자가 주인의 발목을 시도하고 있었다.\n그는 오페라 하우스의 음표가 빗방울처럼 관객석을 때리는 것과 묘지가 숨쉬듯 미세하게 떨고 있는 것을 보았다. 크고 호흡하는 괴물의 피부처럼 보였다... 그가 본 것은 많고 많았다. 그는 어머니, 선생님, 친구들에게 그가 본 것을 이야기했다. 그리고 본 것을 그림 속에 그려 넣었다. 그는 그의 눈에 보이는 세계를 사람들 앞에 가져오고 싶었다. 하지만 그 주위 사람들은 점점 줄어들었고, 하나의 세계는 점점 멀어져 갔다.\n그 이유는 무엇일까? 그는 단지 본 것을 기록했을 뿐이다. 피크멘은 아무리 생각해도 알 수 없었다.\n슬픈 피크멘은 거울 앞에 서 있었다. 그는 그를 향해 이빨이 가득 찬 입을 쩍 벌린 구울을 보았다.\n「보는 것 이상의 중요한 것은 없습니다. 광기, 혼돈, 탐욕... 볼래? 피크멘?」\n피크멘는 그에게 미소를 지었고, 거울 속으로 들어갔다.\n그는 단지 그가 보게 될 극단적인 광기의 진실타래을 자신의 캔버스 위에 진실타래하게 그리고 싶었다.\n그는 인간도, 구울도 아니었다.\n그는 그냥 사실타래주의 화가 피크멘이었다."
  },
  CollectionHall_127168_Title = {
    Text = "사실타래주의 패뮤"
  },
  CollectionHall_127169_Desc = {
    Text = "한 사람이 과거와 미래의 전부를 알 수 있을 때, 그를 기다리는 것은 전지의 기쁨이 아니라 무한한 연민과 절망이다. \n 그녀의 두 눈은 모든 것 뒤에 숨은 실타래을 볼 수 있다. 이쪽 끝은 과거와 연결되고, 저쪽 끝은 미래와 연결된다. \n 그 실타래은 운명이라고 불린다. \n 그녀는 자신을 따르는 사람들에게 어떻게 생각하고 있을까? \n 사람들이 선량하고 자비롭지만, 또한 교만하고 착취적이다. \n 그러나 그 사람들의 운명과 인류의 운명은 매번 만남의 시작에서 이미 정해져 있다. \n 그녀는 반드시 그들을 사랑했을 것이다. 그렇지 않았다면 왜 그렇게 반복해서 도움의 손길을 내밀었겠는가. \n 그녀는 반드시 그들에게 기대를 걸었을 것이다. 그렇지 않았다면 왜 파괴 속에서도 굳건히 윤회의 그림자로 들어갔겠는가. \n 사랑 때문에 그녀는 항상 슬픔을 품고 있다. \n 기대 때문에 그녀는 자주 실타래망한다. \n 그녀는 검은 진창에 깊이 빠져, 수많은 검은 실타래을 끊임없이 정리하며 지치지 않는다. \n 운명의 바퀴는 계속해서 회전한다. \n 그녀는 탐욕의 불꽃이 하늘을 휩쓸어가는 것을 본다. \n 그녀는 어리석은 착취가 자해로 이어지는 것을 본다. \n 그녀는 맹목적인 망상이 파괴를 가속시키는 것을 본다. \n 무질서한 카오스는 늘 늦게 찾아온다. \n 희망과 절망은 무용하게 번갈아가며, 결코 끝나지 않는다. \n 그러던 어느 순간, 그녀는 어둠 속에서 한순간의 별빛을 보았다. \n 그 빛은 미약했지만, 그녀는 이미 너무 오랜 시간 어둠 속에 있었다. \n 그 순간을 직시하는 순간, 눈물이 흘러내렸다. \n"
  },
  CollectionHall_127169_Title = {
    Text = "감춰진 수레바퀴"
  },
  CollectionHall_127170_Desc = {
    Text = "새로운 한 해, 당신은 전례 없는 의식을 개최하기로 결정했습니다. 가장 엄숙한 방식으로 시간의 변화를 맞이하기 위해서입니다. \n 이를 위해 오랫동안 준비해왔습니다. 촛불을 밝혀 따뜻한 빛이 겨울 밤의 캠퍼스를 비추게 하고; 훈련장 중앙에 높은 단을 세우고, 꽃무늬가 가득한 깊은 빨간색 벨벳을 깔았습니다. 당신은 심지어 손수 금박과 은사로 엮인 수많은 리본을 잘라내며, 이 카운트다운의 순간이 이별의 아쉬움을 초월하고, 연말과 새해가 서로 포옹할 때 결코 바래지 않는 흔적으로 남기를 바랐습니다. \n 하지만…… 뭔가 부족합니다. \n 당신은 오래된 창고 깊숙이 들어가, 여러 겹의 먼지를 털어내고, 마침내 그 고풍스러운 시계를 찾아냈습니다. 그것의 외관은 낡고, 바늘은 이미 시간의 침식 아래 부러지고 떨어져, 분명히 사용할 수 없었습니다. \n 절망에 빠져 있을 무렵, 테이스가 나타났고, 그녀 뒤에는 새로 만든 시계가 조용히 서 있었습니다. \n 그 시계는 매우 익숙했습니다. 그녀는 여전히 경박하게 웃고 있었지만, 눈속에는 어떤 부드러운 확신이 숨겨져 있었습니다. \n “어때요, 이 시계와 제 춤이 어우러지면 가장 성대한 의식이 될 거예요.” \n “이…… 혹시 타비의 시계가 아닐까요?” \n “아, 그녀가 외롭게 수조에 있는 걸 아시네요, 너무 우울해요.” \n “이렇게 그녀를 우리의 의식에 초대해 제 사랑을 느끼게 하면, 아마 조금 흥미를 느낄지도 몰라요~” \n 자정이 조용히 다가오고, 테이스는 거대한 시계 앞에 서 있습니다. 마치 시간이 직접 포장한 선물처럼요. \n 리본은 아직 타지 않은 불꽃처럼 그녀의 몸을 감싸고, 흐르는 빛 아래에서 금붉은 물결과 은빛 파동을 일으킵니다. 허리에서 풍성한 나비 모양의 리본은 새해가 직접 묶은 마지막 매듭—그녀는 연말 가장 성대한 선물이며, 기쁨의 비단으로 감싸여 시간이 열리기를 기다리고 있습니다. \n 그녀의 팔이 천천히 올라가고, 손끝이 빛의 그림자를 따라 움직이며 결국 뒤에 걸린 시계를 가리킵니다. 12개의 숫자가 시계판 위에서 빛의 고리를 이루며, 그녀의 손끝에서 뛰어납니다. \n 미사의 모든 사람들이 테이스의 자유로운 춤을 바라보며, 마치 즐거운 분위기에 감염된 듯 그녀의 리듬에 따라 함께 흔들기 시작합니다. \n 그리고 종소리가 울릴 때, 그녀의 손끝이 가볍게 터치하며 영원의 시작에 닿습니다. 그 묶인 선물이 두 팔을 벌리며 연말에 저장된 모든 축제를 하늘에서 흩날리는 축복으로 변환시켜, 세상에 뿌려집니다."
  },
  CollectionHall_127170_Title = {
    Text = "카운트다운 순간"
  },
  CollectionHall_127237_Title = {
    Text = "해성 구소식"
  },
  CollectionHall_127239_Title = {
    Text = "판룡 고국"
  },
  CollectionHall_129601_Desc = {
    Text = "<Title:소개>\n세상과 단절된 섬에서 사는, 명랑하고 야성적인 소녀. \n활발한 성격과 타고난 괴력 때문에, 많은 사람들이 처음 접할 때 그녀의 지나치게 열정적인 접근에 적응하기 힘들다. 하지만 잠시 함께 지내다 보면, 그녀는 단지 친구를 도와주고 싶어 한다는 것을 알게 된다. \n때때로 그녀의 도움 방식은 일반적이지 않지만, 결과적으로는 대부분의 경우 도움을 받는 이의 문제를 해결해 주었다고 할 수 있다. \n억제 상태를 해제하면 자신의 능력을 제어할 수 없어 실타래험실타래이 자주 폭발한다. \n필요한 교육이 부족해 가끔 모스크는 상대방이 자신의 뜻을 이해할 때까지 손짓 발짓을 해야 한다. 물론 모스크는 상대방이 그렇게 오랜 시간 동안 손짓을 할 필요는 없으며, 그녀의 뛰어난 직감이 이 문제를 잘 해결해 준다. \n노틸라와 수호자와 매우 친하다. 그녀의 말에 따르면, 세 사람 사이에는 함께 모험을 하겠다는 약속이 있었지만, 노틸라는 이에 대한 기억이 전혀 없고, 수호자는 그 경험에 대해 입을 열지 않는다. \n가끔 모스크 곁에서 미사그 모자를 쓴 수달을 볼 수 있으며, 모스크는 그것을 “꼬마 석탄 2세”라고 부른다. 이럴 때마다, 본래 완료되어야 할 과제가 이유도 없이 사라지곤 한다."
  },
  CollectionHall_129601_LockTip = {
    Text = "깨어남 “모스크” 후 해금"
  },
  CollectionHall_129601_Title = {Text = "모스"},
  CollectionHall_129803_LockTip = {
    Text = "기간 한정 이벤트 「질주하는 환희 특급 열차: 열차 출발」의 임의의 스테이지를 클리어해야 합니다."
  },
  CollectionHall_129803_Title = {
    Text = "질주하는 환희 특급 열차: 열차 출발"
  },
  CollectionHall_129810_Desc = {
    Text = "기록할 수 없는 어떤 루프 속에서, 회귀·라모나가 종탑 뒤의 화단을 밟았다. \n여유로운 시선으로 장미 정원에서 무리 지어 피어나는 꽃들을 보았다. \n드물게 잠깐 멈춘 후, 그녀는 모든 쓸데없는 생각을 던져버리고 최후의 전장으로 계속 달려갔다. \n진흙이 피처럼 짙은 꽃잎에 튀어 오르고, 순식간에 검은색 융식점액에 포식당해 오직 바람 속에서 당당한 뒷모습만 남았다."
  },
  CollectionHall_129810_Title = {
    Text = "진창을 밟고 있는 장미"
  },
  CollectionHall_130218_LockTip = {
    Text = "기간 한정 이벤트 「뒤바뀐 새 삶: 암실타래 수기」의 스테이지 중 하나를 클리어해야 합니다"
  },
  CollectionHall_130218_Title = {
    Text = "뒤바뀐 새 삶: 암실타래 수기"
  },
  CollectionHall_130219_Desc = {
    Text = "이곳은 어떤 해도에 기록되지 않은 섬이다.\n이 섬이 태어난 이래로, \"문명\"이라는 바이러스는 이 깨끗한 땅에 발을 들여놓지 않았다.\n여기에는 해변, 밀림, 끝없이 펼쳐진 바다, 그리고…… 한 작은 소녀가 있다.\n………………………………\n「아빠, 엄마, 물고기！」\n「아우~~」\n두 마리 돌고래가 느긋하게 소녀의 발 옆으로 수영하며 아름답고 맑은 소리를 냈다.\n그 중 한 마리는 소녀를 업었고, 다른 한 마리는 소녀가 방금 기절시킨 물고기를 받아 한 입에 삼켰다.\n「아우~~」\n「헤헤, 모스크! 대단해！」\n세상과 동떨어진 아이처럼, 소녀는 \"아빠\"와 \"엄마\"의 칭찬에 힘 있는 동작으로 응답했다.\n「오늘, 태양! 좋아！」\n「모스크! 아빠! 엄마! 산책！」\n소녀의 말을 들은 소녀를 업고 있는 돌고래가 한숨을 내쉬고 작은 섬 주위를 천천히 수영하기 시작했다.\n따뜻한 햇살이 소녀에게 내려앉아 며칠 전 사라지지 않았던 습기와 추위를 쫓아내고, 부드러운 바람이 소녀의 머리카락을 스치며 바다의 게으른 숨결을 가져왔다.\n웃음소리, 물소리, 놀이소리가 세상과 격리된 이 작은 섬에서 \"문명\"이 가져오는 걱정 없이, 가장 원시적이고 순수한 웃음만이 남아 있다.\n두 짐승과 한 사람은 평소와 다름없이 원시적이고 걱정 없는 하루를 보냈다.\n………………………………\n그때, 끝없는 호출이 이 평화를 완전히 포식했다.\n「돌아와…… 돌아와……」\n「@1이 필요해……@2……@4……이 필요해……」"
  },
  CollectionHall_130219_Title = {
    Text = "먼 곳의 에덴"
  },
  CollectionHall_130220_Desc = {
    Text = "민들레, 날짐승보다 작고, 미풍보다 가벼운 존재.\n\n민들레가 첫 번째 황무지를 지날 때, 사방으로 흩어진 회전초에게 물었다: 너희는 어떻게 번식하니?\n회전초가 말했다: 「우리는 씨앗을 사방에 떠돌게 해, 뿌리내릴 수 있는 토양을 찾을 때까지.」\n떠도는 나그네에게는 집이 없구나, 민들레는 그렇게 한숨지으며 또 다른 바람결에 올라 날아갔다.\n\n민들레가 두 번째 사막을 지날 때, 드문드문 분포한 선인장에게 물었다: 너희는 어떻게 생존하니?\n선인장이 말했다: 「우리는 뿌리를 땅속 깊이 묻어, 귀한 수원을 길어 올려.」\n혹독한 환경 속에서도 끈질기게 살아가는구나, 민들레는 그렇게 생각하며 떠났다.\n\n얼마 후, 민들레는 도시 상공을 지나갔다.\n어둠 속에 떠오르는 도시 가득한 불빛은, 인간 삶의 흔적이었다.\n긴 여정의 끝에서, 민들레의 씨앗은 마침내 그 대지 위로 내려앉으려 하고 있었다."
  },
  CollectionHall_130220_Title = {
    Text = "세상이 향기로 물들기를"
  },
  CollectionHall_130221_Desc = {
    Text = "아라크네는 자신이 필연적으로 실타래패할 일을 하고 있다는 것을 알고 있었다. \n 그녀는 가볍게 물레를 돌리며, 날마다 인간의 슬픔과 기쁨, 왕조의 흥망, 별불꽃 같은 시와 사랑을 시공을 초월한 거대한 그물에 엮어 넣었다. \n 그녀는 매우 잘하고 있었다, 정확하고, 억제하며, 부드럽게. 잘못된 것들을 배제하고, 올바른 것들을 선택했다. \n 대대손손 새 생명의 미소가 드러나고, 수많은 문명이 재 속에서 새로운 역사를 써내려갔다. 그러나 엮음에서 비롯된 기쁨과 엮음에서 생긴 피로, 모든 부드러운 감정은 영원한 고역의 마모 속에서 조용히 시들어 버렸다. 그녀는 스스로 취약함을 끊어내고, 오직 깨어 있는 의지만을 남겨두었다. 매 선택이 연약함이 아닌 책임에서 비롯되도록 하기 위해서였다. \n 그러나 가장 깊은 비극은 고역 그 자체가 아니라, 그녀가 어떻게 수선하고 엮어도, 세상은 여전히 그 조용한 공허로 나아갈 것이라는 것을 분명히 알고 있다는 것이다. 문명은 취약한 모래성처럼, 조수는 결국 찾아온다. 그녀의 노력은 관중 없는 공연, 결코 회상이 없는 지켜봄이었다. \n \"운명은 이미 우리를 영원한 고독에 유죄 판결을 내렸으니, 왜 이 잔인한 처벌을 받아들여야 하는가?\" \n \"찢고, 파괴하라… 그러면 이 고역에서 탈출할 수 있다…\" \n 그녀는 시선을 아래로 향하고, 그 불필요한 생각들을 가볍게 잘라내며, 계속해서 지루하고 집중하여 엮고, 유지하고, 울고, 견디고 있었다… \n 모든 무의미한 몸부림과 모든 해결되지 않은 운명은 이미 이 그물에 엮여 있었다. \n 그리고 그물의 중심에서, 그녀는 자신을 보았다."
  },
  CollectionHall_130221_Title = {
    Text = "영원한 직조의 그물"
  },
  CollectionHall_131000_LockTip = {
    Text = "제한 시간 이벤트 “머스크스의 호출: Mosk와 바다”의 임의의 단계를 클리어해야 합니다"
  },
  CollectionHall_131000_Title = {
    Text = "머스크스의 호출: 모스크와 바다"
  },
  CollectionHall_131388_Desc = {
    Text = "금빛으로 화려한 클럽 입구에서, 흰 셔츠를 입은 접수원이 한 손을 들어 공손하게 라이커를 막았다. \n「선생님, 초대장이 없으시고 저희 회원도 아니시기에 들어가실타래 수 없습니다. \n」\n「그렇군요…… 이거 곤란하네요……」\n라이커는 손으로 턱을 만지며 생각하는 척했다. 사실타래 그는 단지 기다리고 있었다. \n손에 쥐고 있는 사건의 용의자를. \n운명으로 정해진, 운명의 축복을 기다리고 있었다. \n과연,그는 기다렸다—— \n「이곳에서 유명한 렌티니언의 운 좋은 탐정이 아닌가요! 오오, 제가 당신의 추천인이 되어드리겠습니다.」\n「저는 당신의 전설적인 운을 보고 싶었어요, 실타래망시키지 말아주세요……」\n신사는 말하며 온화해 보이지만 악의가 가득한 미소를 지었다. \n이런 표정은 클럽에서 흔히 볼 수 있는 것, 결국 신나는 도박을 쫓는 도박꾼들이 규칙을 지킬 것이라고 기대할 수는 없다. 그래서 자신이 함정에 빠진 것을 깨닫게 되었을 때, 라이커는 개의치 않고 단지 미소 지으며 여유롭게 위스티 카드 한 장을 집어 들었다. \n서두르지 마세요, 게임은 이제 시작일 뿐이니까요, 그렇죠? \n그래서 첫 번째 게임, 두 번째 게임, 세 번째 게임…… 한 판 한 판 이어졌다. \n결국 라이커는 모든 칩을 잃어버렸다. \n「운 좋은 탐정, 오늘 당신의 운은 좋지 않은 것 같군요. 그렇죠, 누구도 영원히 운명의 축복을 받을 수는 없으니까요……」\n「계속 할까요? 탐정, 아쉽게도 당신은 이미 아무것도 남지 않았습니다.」\n「아무것도 남지 않았다? 그렇지 않습니다.」연속으로 지고 있는 탐정은 미소를 지으며 자신을 가리켰다, 「저는 이 멋진 정장과 이 비싼 지팡이, 그리고……」\n탐정은 잠시 멈추고 정장 가슴 주머니에서 작은 기기를 꺼내어 목소리를 낮추며 미소 지으며 만지작거렸다, 「나는 당신의 속임수 기술이 매우 교묘하다는 것을 인정합니다, 이 클럽의 주인조차도 풀 수 없죠, 저의 도움을 구할 수밖에 없었습니다. 하지만 아무리 정교한 기술이라도 시간과 작업, 협력이 필요합니다.」\n「불행히도, 이 미사그에서 제작한 작은 장치가 당신과 당신의 동료가 방금 클럽에서 속임수를 쓴 증거를 명확히 기록했습니다.」\n신사는 잠시 멈추고 놀라움과 분노가 섞인 표정을 지었고, 그의 동료는 더욱 화가 나서 탐정에게 교훈을 주고 싶어 했다. 그러나 많은 사람들 앞에서 신사는 함부로 행동할 수 없었고, 게다가 탐정은 그에게 선택지를 주었다, 그가 거부할 수 없는 선택지를. \n「한 번 더 도박해 볼까요? 만약 당신이 이긴다면, 이 작은 장치와 제 목숨이 모두 당신 것입니다. 제 뜻을 이해하시겠죠.」\n「그렇다면 제가 지면요?」\n「지면 자수하셔야 합니다.」라이커는 미소 지으며 어깨를 으쓱이며 반짝이는 송곳니를 드러냈다, 「당신은 자신이 질 것이라고 생각하나요? 진정한 도박꾼은 자신이 이길 것이라고 믿기를 원합니다.」\n맞습니다, 모든 도박꾼은 자신이 이길 것이라고 생각합니다. 그래서 누구도 이 도박을 거부할 수 없습니다. \n그래서, 위스티 카드는 다시 카드 테이블 위에서 돌고, 카드를 내고, 패를 깔고, 마지막으로 승부가 나왔다. \n「Lucky~」\n패배자를 한 번도 보지 않고, 라이커는 웃으며 손을 들어 그가 딴 돈을 공중에 던졌다. 그래서 이미 시끄러운 클럽은 더욱 열광적으로 변하고, 사람들의 싸움 소리, 재산을 얻는 비명과 웃음으로 가득 찼다. \n그리고 이 소리와 비명, 웃음 속에서 라이커는 미사그에서 발급된, 각자 하나씩 받는 장식품을 가슴 주머니에 다시 넣고, 자신의 이름이 적힌 초대장을 주머니에서 가볍게 두드리며 입꼬리를 올렸다. \n진정한 도박꾼은 자신이 이길 것이라고 믿기를 원합니다. \n왜냐하면 그는 확신하니까요, 무엇을 하든 운명의 축복은 항상 그와 함께 할 것이라는 것을. \n"
  },
  CollectionHall_131388_Title = {
    Text = "도박의 지혜"
  },
