  CollectionHall_131664_Desc = {
    Text = "저에게 생각해 보게 해주세요, 오늘의 이야기는 무엇을 말해야 할까요……\n아, 저 알겠어요, 작은 아가씨와 작은 아저씨들에게 할 이야기는 ~ 한밤중에 마음에 걸리는 잘못을 말하지 말고, 세 시에 원혼이 방양에 올라온다는 것입니다."
