  CollectionHall_131667_Title = {Text = "환혼"},
  CollectionHall_131668_Desc = {
    Text = "기괴하고 괴상한 고, 망한 아내가 삼경에 땅에서 나와, 방탕한 놈이 마음을 잃어 솥에서 삶는다.\n무상의 신녀가 고통을 구해주시기를, 얼굴을 가르고 마음을 열어 연인의 뼈를 취하여, 나의 대전에 무상의 주님께 바칩니다."
