  },
  CollectionHall_131668_Title = {
    Text = "현녀무상"
  },
  CollectionHall_131669_Desc = {
    Text = "최대 그녀를 베고, 그녀가 너를 죽여서 함께 저승에 가는 쌍쌍 귀신이 되는 거야. \n쉬 쉬, 걱정할 필요 없어."
