    Text = "그녀 그분 그녀 그녀 그녀 그분 그분 그분 그분 그녀 그녀 어머니 어머니 아름다운 눈 어머니 어머니 어머니 친친친친 어머니 어머니 어머니 그녀 그분 그분 그녀 그녀 그녀 그녀 @4@3@4"
