  CollectionHall_131790_Title = {Text = "중독"},
  CollectionHall_132222_Desc = {
    Text = "만약 소원이 정말로 이루어질 수 있다면, 폰토스는 이별이 찾아오기 전에 인사라도 나눌 수 있기를 바랐다.\n그의 부모는 소리 없이 사라졌고, 어느 평온한 오후, 누나 레이사가 돈을 내어 인력거를 불렀다. 그리고 길고 긴, 그때는 아직 알지 못했던 철제 괴물이 경유 냄새와 굉음 속에 그를 그 해변 마을로 데려다주었다.\n부모의 행방에 대해 레이사는 한 마디도 하지 않았고, 격렬한 다툼 끝에 그는 짭조름한 냄새가 가득한 항구로 뛰쳐나갔다.\n눈 간격이 지나치게 넓은 해민들이 기묘한 형태의, 사람의 힘으로는 결코 닿을 수 없는 심연에서 온 물고기들을 팔고 있었다.\n\"여보세요, 좀 멀리 떨어지세요, 저 물고기들은 잡아온 것들과 마찬가지로 저주에 물들었을지도 몰라요.\"\n행인이 목소리를 낮췄다. 아무도 이 처음 온 잘생긴 청년이 혼탁한 물에 발을 담그는 것을 보고 싶지 않았다.\n그는 습관적으로 상대에게 미소를 지었지만, 시선은 자신도 모르게 그 어둡고 부패한 루어에 떨어졌다. 크게 벌린 입 안에는 날카로운 이빨이 가득했고, 추하고, 왜곡되고, 과시적이었으며, 어떤 망상 속의 목소리가 이 죽은 물체의 일생을 이야기했다.\n어둡고 빛 없는 해저에서 그것은 유혹하고, ndaltə하고, 수단과 방법을 가리지 않았다. 그것의 몸은 견고한 감옥이 되어 자식들, 연인들, 원수들, 그리고 먹잇감들을 가두었다.\n그것의 삶 속 아름다운 것들은 본래 순식간에 사라져야 했지만, 그것은 그들 모두를 붙잡아 두었다. 그들은 그것의 몸을 매개로 긴밀히 의지하며, 영원히 분리되지 않았다.\n폰토스는 갑자기 고개를 세차게 흔들며, 귀 옆에서 날카롭게 울리는 소음 속에서 공포에 질려 주위를 둘러보았다.\n소리는 파도처럼 사라졌고, 그는 모든 것을 한순간의 멍함으로 여기며 속으로 자신의 신경질적인 반응을 비웃었다.\n그리고 아무것도 눈치채지 못한 채 정해진 숙명 속으로 떨어져 갔다."
  },
  CollectionHall_132222_Title = {
    Text = "살아있는 감옥"
  },
  CollectionHall_133709_Desc = {
    Text = "아침 승마에서는 군의 신사들과 나란히 말을 달리며 개혁안에 대한 입장을 탐문해야 하고, 냉찬회에서는 각 가문의 부인들과 격식 있는 칭찬을 주고받아야 하며, 긴 만찬에서는 은촛대의 빛 아래 장황하고 위선적인 식전 기도를 경청해야 하고, 오페라가 끝난 후에는 특별석 복도에서 끝없는 사교적 인사를 감당해야 한다.\n\n「오직 후원 잔디밭 위의 오후 차 시간만이, 진정으로 나만의 시간이에요.」\n「이건 제가 처음으로 오후 차 손님을 초대하는 거예요. 화제를 선택할 권한을 당신에게 양도하겠어요.」\n\n소레이유가 갓 따른 홍차를 들어 올렸다.\n「드 크레메 백작이 최근 제출한 의회 개혁안에 대한 입장을 알고 싶으신가요? 아니면 보몽나 가문이 양당 사이에서 벌이는 미묘한 베팅? 혹은 순수하게 어느 자작 영애의 비밀에 관심이 있으신 건가요?」\n「전부 필요 없다고요? 그저 제 테이블 위의 분홍색 디저트 맛이 궁금하다고요?」\n그녀가 한 모금 홀짝이며, 원래 먼 곳을 바라보던 시선을 당신에게로 돌렸다.\n「그럼 잘 음미해 보세요.」\n「어떤 맛은, 직접 손을 대야만 진정으로 공감할 수 있는 법이니까요.」\n「그렇지 않나요, 존경하는 — 그분?」\n\n미사그 교복을 입은 방문객의 옷깃과 소매에서 검은 안개가 피어올랐고, 안개는 곧 짙은 혼돈의 덩어리로 뭉쳤다.\n「히히히, 정말로 자신이 숙명에서 벗어날 수 있다고 생각하나요?」\n「햇살이 좋으니, 먼저 드문 한가로운 시간을 즐기고 싶어요. 요즘 유행하는 홍차와 스펀지 케이크를 맛보고 싶으시다면 마음대로 하세요. 다른 일은, 오후 휴식 시간이 끝난 후에 다시 와주세요.」"
  },
  CollectionHall_133709_Title = {
    Text = "은밀한 오후 휴식 시간"
  },
  CollectionHall_133710_Desc = {
    Text = "미사그의 우등생으로서, 라모나는 이성과 합리를 행동의 절대적 논리로 삼는 데 성공하여, 냉정함을 유지하고, 유머를 유지하고, 비할 데 없는 신뢰성을 유지해 왔다.\n하지만 가끔, 이런 라모나도 사색에 빠질 때가 있다. 세계의 절대적인 공포, 혹은 절대적인 찬란함 앞에서——\n끝없이 펼쳐져 시야를 가득 채운 분홍빛을 바라보며, 라모나는 말없이 침묵했다.\n그녀가 아는 바로는, 3주도 채 되지 않아 벚꽃은 처음 피어나서 모두 지고 만다. 그러니 가지를 묵직하게 뒤덮은 이 꽃들, 종횡으로 무성한 가지와 잎사귀도 곧 시들어, 황량함과 쓸쓸함에 빠지게 될 것이다.\n그리고 인간의 예상 수명은 3주보다 훨씬 길고, 3년보다 훨씬 길고, 30년보다도 훨씬 길지만, 이 벚나무들처럼 단 한 번뿐이다.\n인간의 가장 큰 착각은 자신이 영원히 살 것이라 믿는 것이다.\n라모나는 알고 있다.\n꽃이 피고 지는 것은 자연계에서 지극히 평범한 법칙이며, 인간의 삶과 죽음도 결국 자연계의 현상에 불과하다는 것을.\n라모나는 그것도 알고 있다.\n하지만 인간으로 태어난 이상, 자신의 존재에 의미를 부여하고 싶어 하는 법이며, 모든 신입생도 바로 그 때문에 미사그의 문을 두드린 것이다.\n그들은 융식에 맞서는 선봉이자, 인류의 미래를 지켜보는 중요한 방어선이다.\n그들의 생명은 단순히 객관적인 자연 현상이 아니며, 설령 소멸이 정해져 있다 해도, 이 세계의 궤적을 실타래질적으로 바꾸고 있다.\n그리고 그 과정에서, 그들은 어깨를 나란히 하고 싸우며, 비바람 속을 함께 걸어간다.\n마치 한 나무 위의 한 송이 꽃이 다른 한 송이 꽃에 기대어, 함께 봉오리를 맺고, 함께 흔들리며 떨어지고, 함께 피어나고 시드는 것처럼.\n이제, 돌아가야 할 때다.\n그녀가 기댈 수 있고, 그녀가 기대할 가치가 있는 그 꽃이, 아직 그녀를 기다리고 있으니."
  },
  CollectionHall_133710_Title = {
    Text = "벚꽃 아래의 미혹"
  },
  CollectionHall_133768_Desc = {
    Text = "소용돌이의 중심은 차갑고, 침묵하며 고독하다.\n그것은 빛조차 관통할 수 없는 암류."
  },
  CollectionHall_133768_LockTip = {
    Text = "의식 잠수“중독”"
  },
  CollectionHall_133768_Title = {
    Text = "소용돌이 속 암류"
  },
  CollectionHall_133769_Desc = {
    Text = "침몰. 침몰. 침몰.\n칠흑의 소용돌이 속으로 가라앉는다.\n그 대가로, 그분은 더 이상 크릴새우 한 마리도 삼킬 수 없게 되리라."
  },
  CollectionHall_133769_LockTip = {
    Text = "의식 잠수“중독”"
  },
  CollectionHall_133769_Title = {Text = "침몰"},
  CollectionHall_133770_Desc = {
    Text = "승객 여러분, 안녕하십니까!\n기세 명절이 다가오고 있습니다. 온 가족이 모이고 묵은해를 보내며 새해를 맞이하는 이 아름다운 순간, 이번 열차의 전체 승무원 일동은 먼 길을 귀향하시며 여정에 지치신 당신께 가장 진심 어린 축복을 전합니다—\n기세 명절 즐겁게 보내시고, 온 가족 환희 가득하시며, 내내 질주하시어 만사형통하시길 바랍니다! <(￣︶￣)↗[GO!]"
  },
  CollectionHall_133770_LockTip = {
    Text = "특파대 기록“기도의 해를 향한 기차”"
  },
  CollectionHall_133770_Title = {
    Text = "질주: 환희 특급열차"
  },
  CollectionHall_133771_Desc = {
    Text = "승객 여러분, 안녕하십니까. 매우 죄송하게도 알려드립니다. 열차장의 개인적인 심기로 인해 이번 환희 특급열차는 이 지점에서 임시 정차하게 되었습니다. 구체적인 출발 시간은 자중지란이 끝난 후 즉시 방송으로 안내해 드리겠습니다.\n정차 중에도 열차의 에어컨, 조명, 화장실타래은 정상적으로 이용 가능하오니, 살육 필요에 따라 적절히 사용하시어 위험이 발생하지 않도록 유의해 주시기 바랍니다.\n결국, 환희 특급열차의 의무는 모든 승객에게 웃음을 전하는 것이니까요～(￣▽￣～)(～￣▽￣)～"
  },
  CollectionHall_133771_LockTip = {
    Text = "특파대 기록“기도의 해를 향한 기차”"
  },
  CollectionHall_133771_Title = {
    Text = "긴급 정차!"
  },
  CollectionHall_133772_Desc = {
    Text = "주의하세요: 열차가 곧 판룡 고국에 도착합니다. 판룡 고국에서 하차하실타래 승객분들께서는 미리 \"모리화\"의 노래 기술을 익혀두시기 바랍니다.\n왜냐하면, 여러분은 이미 하차할 기회가 없으니까요 φ(≧ω≦*)♪"
  },
  CollectionHall_133772_LockTip = {
    Text = "특파대 기록“기도의 해를 향한 기차”"
  },
  CollectionHall_133772_Title = {
    Text = "아름다운 재스민 꽃"
  },
  CollectionHall_133773_Desc = {
    Text = "빛이 바다 속으로 가라앉아, 푸름보다 더 깊은 푸름을 비춘다."
  },
  CollectionHall_133773_LockTip = {
    Text = "의식 잠수“중독”"
  },
  CollectionHall_133773_Title = {
    Text = "푸름과 더 깊은 푸름"
  },
  CollectionHall_134293_Desc = {
    Text = "<Title:소개>\n운명 극장의 주인, 극작가, 배우, 운명 영원한 짜는 자와 영원한 수인……\n태어날 때부터, 아라크네는 운명의 실타래선을 볼 수 있는 능력을 가지고 있었다. \"모이라이\"라고 불리는 그 방적기를 이용하여, 그녀는 끊임없이 세계를 위해 운명을 짜고, 운명의 취약한 균형을 유지하고 있었다. 이를 위해 그녀는 자신의 모든 아름다움과 취약함을 놓아버리고, 모든 운명에 대해 가장 올바른 선택을 하며, 혼자서 모든 운명의 죄책을 감당했다.\n그녀는 이미 알고 있었다, 운명의 그물의 끝에서, 파멸은 결국 피할 수 없는 것이라는 것을. 그러나 그녀는 여전히 고대처럼 끊임없이 짜고, 자신이 사랑하는 모든 것이 서서히 그 모든 것을 소멸시키는 끝으로 떨어지는 것을 지켜보았다.\n그녀는 짜고, 대기하고, 그녀가 결코 예상하지 못했던, 깊은 심연에서 운망을 구할 실타래선을 기다린다."
  },
  CollectionHall_134293_LockTip = {
    Text = "깨어남 \"아라크네\" 후 해제"
  },
  CollectionHall_134293_Title = {
    Text = "아라크네"
  },
  CollectionHall_134294_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_134294_Title = {
    Text = "저버린 자비"
  },
  CollectionHall_134295_LockTip = {
    Text = "조사 작전 성신편 5-1 완료 시 해제"
  },
  CollectionHall_134295_Title = {
    Text = "운명이 엮어낸 그물"
  },
  CollectionHall_134429_Title = {
    Text = "운명 극장"
  },
  CollectionHall_139856_LockTip = {
    Text = "다차원 연결 \"Kusunyi kǝragǝbe njestǝna\" 클리어 시 해금"
  },
  CollectionHall_139856_Title = {Text = "전령"},
  CollectionHall_140337_Desc = {
    Text = "당신은 성운 사이를 거닐며, 유성이 하나씩 떨어지는 것을 목격한다.\n어떤 것은 뜨겁고, 어떤 것은 눈부시며, 어떤 것은 차갑고, 어떤 것은 어둡다——작별을 고할 틈도 없이, 긴 꼬리를 끌며 하늘에서 하나둘 사라져 간다.\n당신은 재를 두 손에 담아, 존재의 흔적을 마음에 새기려 한다.\n하지만 그 영상들은 결국 손가락 사이로, 점점 희미해지는 기억 사이로 빠져나가, 무한한 시공 속으로 흩어진다.\n알고 보니 당신도 수많은 별비 중 하나에 불과했다.\n그러나 당신은 멈추지 않을 것이다. 기나긴 적멸을 지나, 다음 기원까지 걸어갈 것이다.\n별이 하늘 가득 찰 때까지."
  },
  CollectionHall_140337_Title = {
    Text = "별들에게"
  },
  CollectionHall_140428_LockTip = {
    Text = "조사 작전 성신편 5-1에서 해제 가능"
  },
  CollectionHall_140428_Title = {
    Text = "숙명의 무대"
  },
  CollectionHall_141369_LockTip = {
    Text = "영원한 에포얀스·고지 순렵 한시 이벤트의 임의 단계를 클리어해야 함"
  },
  CollectionHall_141369_Title = {
    Text = "영원한 에포얀스·고지 순렵"
  },
  CollectionHall_141453_LockTip = {
    Text = "다차원 연결 \"Kusunyi kǝragǝbe njestǝna: 血ﾝ肉ｲw世ｮ\" 클리어 시 해금"
  },
  CollectionHall_141453_Title = {
    Text = "Kaya kuruwuro letəbe"
  },
  CollectionHall_141528_Desc = {
    Text = "전설에 따르면 아이가 숲 속에서 야생 토끼를 쫓아 달리기만 하면, 이세계로 통하는 나무 구멍에 빠질 확률이 있다고 한다. 릴리의 매끄러운 작은 발이 조약돌 오솔길을 밟았다. \"릴리는 이곳이 좋아……바닥에 유리 조각도 없고, 공기 중에 소독약 냄새도 없어.\" 릴리는 신선한 공기를 깊이 들이마셨고, 숲 사이를 스치는 바람이 기묘한 꽃향기를 실타래어왔다. 머리 위의 나뭇잎들이 스테인드글라스 같은 천장을 이루었고, 부서진 햇살은 마치 바닥 가득 뛰노는 보석 같았으며, 화려하고 몽환적인 풍경에 릴리는 어느 방향을 봐야 할지 거의 알 수 없었다. \"아, 아까 그 토끼 씨!\" 풀숲에서 익숙한 회색 긴 귀가 솟아올랐고, 릴리는 급히 뒤를 쫓았다. 발 아래 이끼는 한 걸음 밟을 때마다 작은 은빛 꽃을 피웠지만, 릴리는 그럴 여유가 없었다. 토끼 씨에게 더 중요한 말을 해야 했다. 꿀빛 광채가 흐르는 시냇물을 건너고, 노래하는 갈대밭을 지나. 숨을 헐떡이던 릴리는 마침내 솜뭉치 같은 토끼 씨의 꼬리를 잡았다. \"토끼 씨, 리사와 친구가 되어줄 수 있어?\" \"리사는 내 친구인데, 다른 사람들은 지금 모두 그녀를 무서워해……토끼 씨라면 분명 그녀와 친구가 될 수 있을 거야!\" 토끼 씨가 뒤를 돌아보는 순간, 하늘 가득 반딧불이 피어올랐다. \"물론이지, @2은 모든 사람의 친구야. 그런데, 지금은, 쉬어야 할 시간이야.\" 그리하여 릴리는 이미 친구가 된 토끼 씨를 안고, 숲 깊은 곳의 크고 높은 거목 아래로 기어갔다. 흩날리는 반딧불이의 따뜻한 품 속에서, 릴리는 거목의 뿌리에 기대어 조용히 잠들었다. \"피험자: 릴리. 임상 소견: 호흡 안정, 안구 회전 속도 정상. 제359차 의식 간섭 실타래험, 성공.\" 그것은 꿈처럼 아름다운 환상의 세계였다."
  },
  CollectionHall_141528_Title = {
    Text = "이상한 나라의 릴리"
  },
  CollectionHall_141832_LockTip = {
    Text = "기간 한정 활동 「초승달과 깊은 눈: 우모파티의 보물」 임의 단계 클리어 필요"
  },
  CollectionHall_141832_Title = {
    Text = "초승달과 깊은 눈: 우모파티의 보물"
  },
  CollectionHall_142131_Title = {
    Text = "잊혀진 사랑의 씨앗"
  },
  CollectionHall_142154_Title = {Text = "마을"},
  CollectionHall_142155_Desc = {
    Text = "이해할 수도, 식별할 수도 없는, 역겨운 기형의 존재가 다가올 때, 방어적 공격을 가하는 것은 생물의 본능이다.\n따라서, 이것은 죄악이라 할 수 없다."
  },
  CollectionHall_142155_LockTip = {
    Text = "다차원 연결 「잊혀진 사랑의 씨앗」 어려움 난이도 완료"
  },
  CollectionHall_142155_Title = {
    Text = "무죄의 폭력"
  },
  CollectionHall_142156_Desc = {
    Text = "\"내 목소리가 들리나요? 그림자가 바람 속에 소멸한다 해도.\"\n바람 속에서 멀리서 오는 호출이 들려온다, 그것은 아득한 시간을 넘어, 광활하고 차가운 겨울밤, 망각의 저편에서 전해오는 탐색의 소리."
  },
  CollectionHall_142156_LockTip = {
    Text = "다차원 연결 「잊혀진 사랑의 씨앗」 완료"
  },
  CollectionHall_142156_Title = {
    Text = "忘却の彼方"
  },
  CollectionHall_142157_Desc = {
    Text = "기억은 반짝임 속에 겹쳐지고, 결말의 진위는 불분명하다.\n하지만 그것이 정말 중요한가?\n결국, 모든 이야기가 사랑으로 시작되는 것은 아니지만, 모두 죽음으로 끝을 맺는다."
  },
  CollectionHall_142157_LockTip = {
    Text = "다차원 연결 「잊혀진 사랑의 씨앗」 완료"
  },
  CollectionHall_142157_Title = {
    Text = "사중 회상"
  },
  CollectionHall_142158_Desc = {
    Text = "언젠가 당신도 나처럼, 혈육이 뒤엉키고 썩어 문드러진 광경에 빠져든다면.\n그렇다면 당신도 반드시 이해할 수 있을 것이다—\n그녀의 작고 여린 손끝과 닿는 순간이, 이 세상에서 다시없을 기적임을."
  },
  CollectionHall_142158_LockTip = {
    Text = "다차원 연결 「잊혀진 사랑의 씨앗」 완료"
  },
  CollectionHall_142158_Title = {Text = "기적"},
  CollectionHall_142159_Desc = {
    Text = "당신도 평범하고, 반복적이고, 지루하고, 하루하루 똑같은 삶에 지쳐있지 않은가?\n새로운 것을 경험해보라, 또 다른 세계가 아가리를 크게 벌리고 당신에게 환영의 초대를 보내고 있다."
  },
  CollectionHall_142159_LockTip = {
    Text = "다차원 연결 「잊혀진 사랑의 씨앗」 완료"
  },
  CollectionHall_142159_Title = {Text = "혈역"},
  CollectionHall_142160_Desc = {
    Text = "사랑은 숭고하고, 사랑은 욕심이다; 사랑은 축복이고, 사랑은 저주이다.\n사랑은 물과 함께 생겨나고, 또한 물과 함께 사라진다.\n그리고 우기는 다시 오지 않는다."
  },
  CollectionHall_142160_LockTip = {
    Text = "다차원 연결 「잊혀진 사랑의 씨앗」 어려움 난이도 완료"
  },
  CollectionHall_142160_Title = {Text = "우기"},
  CollectionHall_142161_Desc = {
    Text = "모든 생명은 무지함을 안고 태어나, 만물에서 양분을 흡수하고, 환경을 개조하며, 자원을 ndaltə하고, 자신을 공양한다.\n이것은 피할 수 없는 원죄이다."
  },
  CollectionHall_142161_LockTip = {
    Text = "다차원 연결 「잊혀진 사랑의 씨앗」 완료"
  },
  CollectionHall_142161_Title = {Text = "원죄"},
  CollectionHall_142162_Desc = {
    Text = "민들레라는 식물은 씨앗을 바람에 실타래어 떠나보낸다.\n솜털 같은 씨앗은 바람을 따라 떠돌며, 고향을 아주 멀리 떠나간다.\n홀로 떠도는 그 씨앗은, 언제 자신의 안식처를 결정하게 될까?\n그것은, 사막 속에 오직 한 사람이 그 민들레를 사랑할 때이다."
  },
  CollectionHall_142162_LockTip = {
    Text = "다차원 연결 「잊혀진 사랑의 씨앗」 완료"
  },
  CollectionHall_142162_Title = {
    Text = "민들레는 어디로 가는가"
  },
  CollectionHall_142163_Desc = {
    Text = "광활한 천지, 아득한 모래 바다.\n그곳은 오직 너와 나만의 무인지경.\n그곳은 영원한 자유의 사랑의 유랑."
  },
  CollectionHall_142163_LockTip = {
    Text = "다차원 연결 「잊혀진 사랑의 씨앗」 완료"
  },
  CollectionHall_142163_Title = {
    Text = "사막 바다 유랑"
  },
  CollectionHall_142164_Desc = {
    Text = "당신의 이름을 부를 수 있을까요? 세상이 사라진다 해도.\"\n모든 기억이 소멸하고, 칠흑 같은 망각이 미처 그리워하지 못한 모든 지난 일을 포식한다면.\n그러니 손을 잡아요, 은빛 광채로 당신과 나를 링크해요.\n새로운 꿈속에서, 부드러운 씨앗이 싹트는 이른 봄날에."
  },
  CollectionHall_142164_LockTip = {
    Text = "다차원 연결 「잊혀진 사랑의 씨앗」 완료"
  },
  CollectionHall_142164_Title = {
    Text = "Song of Memento"
  },
  CollectionHall_142165_Desc = {
    Text = "노래하라, 빛나는 HP이 자유를 찬미하며, 희망의 우종을 파종하여 닿는 곳 모두에 퍼뜨리리."
  },
  CollectionHall_142165_LockTip = {
    Text = "다차원 연결 「잊혀진 사랑의 씨앗」 어려움 난이도 완료"
  },
  CollectionHall_142165_Title = {
    Text = "개막 송가"
  },
  CollectionHall_142868_Desc = {
    Text = "<Title:소개>\n폰토스는 가문의 역사를 알게 된 날의 심정을 항상 기억하고 있었다. 그 전까지 그는 어떤 책임을 질 준비도 되어 있지 않았고, 모든 사람이 그를 좋아했으며, 그는 잘생기고, 재미있고, 근심 걱정이 없었다.\n@1왕항을 연중 오가는 선박들 덕분에 그는 단조로운 일상을 마주하지 않아도 되었고, 수많은 이야기를 들어온 그를 많은 사람들이 견문이 넓다고 했다. 그래서 그는 자신이 여럿이 속에 묻혀버릴 수 있다는 사실타래을 인정하려 하지 않았다.\n그래서 그는 예상치 못했지만 당연한 듯 찾아온 거대한 광희에 압도되었다. 더욱이, 가문 대대로 부려온 악몽의 배후에 있는, 더욱 헤아릴 수 없이 위대한 존재가 그를 인정했다—그는 태어날 때부터 남달랐다.\n그러나 \"N\"의 한 마디 농담으로 인해, 광신도들은 무차별적인 해안 습격으로 마을 전체를 파괴했다.\n갑작스러운 재앙을 마주할 수 없었던 폰토스는 심연의 힘을 얻기 위해 @3에게 자신의 몸을 헌신의 제사로 바쳤고, 자신의 모든 가능성도 함께 바쳤다.\n하지만 그게 무슨 상관이겠는가, 이제 어떤 것도 그의 통제를 벗어나지 않을 것이다.\n그는 더 이상 아무것도 잃지 않을 것이다."
  },
  CollectionHall_142868_LockTip = {
    Text = "폰토스를 깨어남한 후 해금"
  },
  CollectionHall_142868_Title = {Text = "폰토스"},
  CollectionHall_142901_Title = {
    Text = "영원한 에뷔노스"
  },
  CollectionHall_143468_Desc = {
    Text = "조종이 이미 울렸고, 배신자는 가장 광란의 공연을 올린다.\n수많은 실타래들이, 어떤 결말을 엮어낼 것인가——\n당신이 결정한다."
  },
  CollectionHall_143468_LockTip = {
    Text = "조사 작전·어려움 성신편 5-11 완료 시 해제"
  },
  CollectionHall_143468_Title = {
    Text = "함께 짜는 결말"
  },
  CollectionHall_143469_Desc = {
    Text = "어서 오세요, 어서 오세요, 모든 사람이 당신을 기다리고 있어요.\n긴 복도를 지나, 영원한 무대에 발을 내딛으세요.\n당신이야말로 이 작품 전체의, 유일한 주인공이니까요."
  },
  CollectionHall_143469_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143469_Title = {
    Text = "끝없는 나선"
  },
  CollectionHall_143470_Desc = {
    Text = "그들은 함께 노래하고, 각자의 역할을 다한다.\n하지만 그들 모두는 그녀다.\n이것은 그녀만의 영원히 아디오스 없는 1인극이다."
  },
  CollectionHall_143470_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143470_Title = {
    Text = "외로운 연극"
  },
  CollectionHall_143471_Desc = {
    Text = "Act I: 실타래 잣기\nAct II: 측량\nAct III: 재단\n이렇게 반복되고, 이렇게 반복된다......"
  },
  CollectionHall_143471_LockTip = {
    Text = "조사 작전·어려움 성신편 5-11 완료 시 해제"
  },
  CollectionHall_143471_Title = {Text = "3막극"},
  CollectionHall_143472_Desc = {
    Text = "그저 한 명의 열광적인 청년이, 평범한 길모퉁이에서 총을 쏘았을 뿐이다.\n적어도 그때는, 모든 사람이 그렇게 생각했다."
  },
  CollectionHall_143472_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143472_Title = {
    Text = "전화의 서막"
  },
  CollectionHall_143473_Desc = {
    Text = "삐걱, 삐걱.\n운명이여, 그대의 룰렛은 쉬지 않고 돌아가네.\n빈곤과 권력 모두 그대에 의해 얼음처럼 소멸되고.\n그대는 스스로를 가리고, 또 얼굴을 숨기지만,\n그래도 나를 향해 빛나고......"
  },
  CollectionHall_143473_LockTip = {
    Text = "조사 작전·어려움 성신편 5-11 완료 시 해제"
  },
  CollectionHall_143473_Title = {
    Text = "운명이여, 그대는 얼마나 잔인한가"
  },
  CollectionHall_143474_Desc = {
    Text = "안녕히, 마지막 선율 속에서.\n안녕히, 운명의 시선 아래에서.\n이야기의 주인공은, 새로운 여정을 떠날 것이다."
  },
  CollectionHall_143474_LockTip = {
    Text = "조사 작전·어려움 성신편 5-11 완료 시 해제"
  },
  CollectionHall_143474_Title = {
    Text = "그래도 나는 여전히 노래한다"
  },
  CollectionHall_143475_Desc = {
    Text = "그대여, 술기운을 빌려 한 곡 더 함께 춤추어요."
  },
  CollectionHall_143475_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143475_Title = {
    Text = "술기운이 약간 오른 무도회"
  },
  CollectionHall_143476_Desc = {
    Text = "관중은 이별에 눈물 흘리고, 재회에도 눈물 흘린다.\n그리고 무대 중앙의 죄인들도, 서로를 위해 박수를 보내야 할 때."
  },
  CollectionHall_143476_LockTip = {
    Text = "조사 작전·어려움 성신편 5-11 완료 시 해제"
  },
  CollectionHall_143476_Title = {
    Text = "수인은 막을 내리고"
  },
  CollectionHall_143477_Desc = {
    Text = "세상 사람들은 한 발의 총성에 전쟁의 책임을 돌리기 좋아한다.\n하지만 운명은 비웃는다 — 이것은 전 인류의 자기기만이라고."
  },
  CollectionHall_143477_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143477_Title = {
    Text = "나비가 날개 퍼덕이기 할 때"
  },
  CollectionHall_143478_Desc = {
    Text = "후일담 없는 공연은 완전하지 않다.\n대사를 조금 바꾸고, 무대를 조정하고, 배우를 교체하면——매번의 앙코르는 새로운 한 막이 된다."
  },
  CollectionHall_143478_LockTip = {
    Text = "조사 작전·어려움 성신편 5-11 완료 시 해제"
  },
  CollectionHall_143478_Title = {
    Text = "앙코르 변주"
  },
  CollectionHall_143479_Desc = {
    Text = "펜 끝이 백지 위를 달리며 문자를 쫓고, 그 문자는 이미 정해진 결말로 향한다.\n모든 것은, 당신이 책을 펼치기 전에 이미 일어난 일이다."
  },
  CollectionHall_143479_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143479_Title = {
    Text = "정해질 일, 이미 정해진 일"
  },
  CollectionHall_143480_Desc = {
    Text = "약간의 비터, 20ml의 스위트 베르무트, 약간의 셰리주, 얼음을 가득 채워 저으면 — 이것은 훌륭한 식전주이자, 오백 번 상연된 연극이다."
  },
  CollectionHall_143480_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143480_Title = {
    Text = "아도니스"
  },
  CollectionHall_143481_Desc = {
    Text = "운명을 광대로 여기면, 운명에 지배당하지 않을 것이다.\n끝없는 폭소로 그를 맞이하자, 함께 그의 이름을 불러내자 —\n환희."
  },
  CollectionHall_143481_LockTip = {
    Text = "조사 작전·어려움 성신편 5-11 완료 시 해제"
  },
  CollectionHall_143481_Title = {
    Text = "어릿광대의 방문"
  },
  CollectionHall_143482_Desc = {
    Text = "\"나는 당신이 미워, 스스로 고치를 짓는 당신이, 무능력한 당신이, 자신을 버린 당신이 미워.\"\n\"......하지만 이 증오는 나 자신도 태우고 있어, 왜냐하면, 나도 당신을 사랑하니까.\""
  },
  CollectionHall_143482_LockTip = {
    Text = "조사 작전·어려움 성신편 5-11 완료 시 해제"
  },
  CollectionHall_143482_Title = {
    Text = "복수귀의 비가"
  },
  CollectionHall_143483_Desc = {
    Text = "세계는 당신에게 수많은 갈림길을 제시하지만, 그것들은 모두 같은 곳으로 합류한다 — 파멸이라 불리는, 종말이라 불리는 그곳으로."
  },
  CollectionHall_143483_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143483_Title = {
    Text = "세계의 복사본"
  },
  CollectionHall_143484_Desc = {
    Text = "막이 오르내리고, 공연이 바뀌어도, 그녀는 여전히 극장 안에 있다 — 그녀는 극작가이자, 관중이자, 배우이기도 하다.\n운명의 여주인이여, 당신은 이토록 잔인하고, 영원히 침묵하면서도, 왜 눈물을 흘리는가?"
  },
  CollectionHall_143484_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143484_Title = {
    Text = "운명으로 짜인 연극"
  },
  CollectionHall_143485_Desc = {
    Text = "만약 파멸이 결국 피할 수 없다면, 운명의 그물을 찢어야만 진정한 구원을 맞이할 수 있는 것일까?\n아무도 대답할 수 없고, 어떤 신도 대답할 수 없다.\n하지만 적어도, 끝없는 고난도 함께 사라질 것이다."
  },
  CollectionHall_143485_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143485_Title = {
    Text = "신성모독의 공연"
  },
  CollectionHall_143486_Desc = {
    Text = "세상을 거닐며, 더없이 진실타래하고 자유로워 보이는 얼굴들은, 무대 위의 잠금된 장치에 불과하다.\n일거수일투족, 모두 운명의 실타래에 이끌린다."
  },
  CollectionHall_143486_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143486_Title = {
    Text = "중생의 실타래"
  },
  CollectionHall_143487_Desc = {
    Text = "꿈에서 깨어나면 모든 것이 사라지고, 완전히 망각될 것이다 — 저택, 화원, 노래, 그림......\n그것은 존재하지 않는 봄이었다."
  },
  CollectionHall_143487_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143487_Title = {
    Text = "봄을 잣는 환몽"
  },
  CollectionHall_143488_Desc = {
    Text = "현악이 서서히 울려 퍼지고, 메이드가 노래한다.\n막 뒤의 인물이 무대 앞으로 나와, 당신에게 예를 갖추며, 이미 정해진 운명의 궤도를 증언하도록 초대한다."
  },
  CollectionHall_143488_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143488_Title = {
    Text = "그녀의 베일을 벗기다"
  },
  CollectionHall_143489_Desc = {
    Text = "이것은 일생에 단 한 번만 공연할 수 있는 즉흥 춤이다.\n하지만 괜찮다, 이것은 표본이 되는 영광을 누리며 영원히 멈춰 있을 것이다."
  },
  CollectionHall_143489_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143489_Title = {
    Text = "무용극: \"백조의 죽음\""
  },
  CollectionHall_143490_Desc = {
    Text = "막이 열리고, 황당한 인물들이 차례로 등장한다.\n그들은 노래하고, 그녀들은 춤추며, 운명이 내려오기 전까지, 집요하게 공연을 무대에 올린다 — 결말이 이미 쓰여 있을지라도."
  },
  CollectionHall_143490_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143490_Title = {
    Text = "막이 오르는 이중창"
  },
  CollectionHall_143491_Desc = {
    Text = "모든 것을 올바른 궤도에 올려놓기 위해, 언제나 제거되고 버려져야 할 것들이 있다.\n선택받지 못한 존재들은 모두 칠흑 같은 심연으로 떨어지고, 그들의 울부짖음과 욕은 결국 아무도 듣지 못한다."
  },
  CollectionHall_143491_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143491_Title = {
    Text = "버려진 「나」"
  },
  CollectionHall_143492_Desc = {
    Text = "이렇게 죽는 것도 참 아름답네. 그녀는 생각했다."
  },
  CollectionHall_143492_LockTip = {
    Text = "조사 작전 성신편 5-16 완료 시 해제"
  },
  CollectionHall_143492_Title = {
    Text = "지극히 아름다운 보상"
  },
  CollectionHall_143592_LockTip = {
    Text = "의식 잠수 \"영원한 에뷔노스\" 임의 단계 클리어 시 해금"
  },
  CollectionHall_143592_Title = {Text = "중독"},
  CollectionHall_144377_Desc = {
    Text = "기나긴 시간 속에서, 한때 타비 또한 어떤 땅을 밟은 적이 있었다. 그녀는 모든 생물의 움직임을 세심히 관찰하며, 눈치 없는 척 인간계의 가장자리를 걸어갔다. 어느 평범한 날, 해가 뉘엿뉘엿 넘어가려 하고 있을 때, 성 외곽 쪽 빼곡한 등불이 그녀의 시선을 사로잡아버렸다. 무대, 가무, 과자를 팔고 있는 노점상, 떠들썩하게 뛰어노는 아이들과 술잔을 들고 마시는 한가로운 사람들. 그것은 생명의 숨결, 찰나의 여유였다. 그 풍경은 타비에게는 동경 그 자체였다. 결국 그녀는 참지 못하고 자신의 모습을 드러내버리고 말았다.\n\n「안녕하세요, 저... 설탕 뽑기 하나 주시겠어요?」\n「네, 잠시만 기다려주십쇼. 어떤 모양으로 그려드릴까?」\n\n타비는 가볍게 고개를 갸웃거렸다. 그녀는 자신이 우연히 주운 주인을 잃은 화폐를 내밀어야 한다는 것만 기억할 뿐, 자신의 바람을 어떻게 표현할 수 있는지는 까맣게 잊고 있었다.\n\n「아이구야, 생각이 안 떠오르시나 보네. 그럼 내가 아가씨의 모습을 따서 하나 그려주는 게 어떨까나? 아가씨가 마치 선녀처럼 우아하셔서 그려.」\n\n타비는 미소 지으며 고개를 끄덕였고, 노점상은 그 한마디를 외친 후 엿 국자를 들어 올려 붓을 내리기 시작했다. 똑, 똑, 똑. 그런데 석판 위에 떨어진 것은 꿀빛 엿이 아니었다. 마치 검은 비처럼 눈에 보이지 않는 높은 하늘에서 검은 점액이 뚝뚝 떨어져 내렸고, 하늘에 섬뜩한 균열을 녹여 내었다. 그리고 타비는 위를 향한 추락하기 시작했다. 그것은 세계가 가라앉는 것이었다. 노점상의 미소는 타비의 기억 속 한 편의 필름으로 굳어간 채, 만물과 함께 검은 바다로 가라앉아 수많은 사라진 별들 중 하나가 되어 그녀에게는 닿을 수 없는 지난날이 되었다. 이것은 그녀가 일으킨 진동이었고, 그녀가 감당해야 할 징벌이었다. 그녀는 멀리 바라보며, 말없이 침묵만 이어갔다. 그녀는 그저 위를 향한 추락할 뿐이었다. 이것이야말로 그녀가 지켜야 할 자리, 그 「시공을 초월한」 은빛 문이었다. 그녀는 이곳에서 영원히 내려다볼 것이다."
  },
  CollectionHall_144377_Title = {
    Text = "위를 향한 추락"
  },
  CollectionHall_144448_Desc = {
    Text = "당신은 결코 가까이 갈 수 없는 유토피아를 약속받았다. 그곳에는 당신의 기억 속 모든 정겨운 낡은 영혼들이 담겨 있다."
  },
  CollectionHall_144448_LockTip = {
    Text = "의식 잠수 「영원한 에포얀스」 완료"
  },
  CollectionHall_144448_Title = {
    Text = "낡은 영혼"
  },
  CollectionHall_144449_Desc = {
    Text = "살아있는 자는 추모에 쓸 수 있는 묘비를 애타게 찾는다.\n죽은 자는 단지 죽었을 뿐이다."
  },
  CollectionHall_144449_LockTip = {
    Text = "의식 잠수 「영원한 에포얀스」 완료"
  },
  CollectionHall_144449_Title = {
    Text = "비석의 흔적"
  },
  CollectionHall_144450_Desc = {
    Text = "태양은 이미 수면 아래로 가라앉았고, 마지막 한 줄기 햇살이 그의 등 뒤로 숨어들었다.\n새벽과 황혼은 다음 순간 교차할 것이며, 그는 이곳의 모든 것을 평소와 같게 할 것이다."
  },
  CollectionHall_144450_LockTip = {
    Text = "의식 잠수 「영원한 에포얀스」 어려움 난이도 완료"
  },
  CollectionHall_144450_Title = {
    Text = "지려는 석양"
  },
  CollectionHall_144451_Desc = {
    Text = "달이 히히 웃고, 달이 소곤소곤 속삭인다.\n달이 말한다, 운명이여, 운명이여, 운명이 내려오려 한다고."
  },
  CollectionHall_144451_LockTip = {
    Text = "의식 잠수 「영원한 에포얀스」 완료"
  },
  CollectionHall_144451_Title = {
    Text = "지려는 달"
  },
  CollectionHall_144452_Desc = {
    Text = "그는 아무것도 모른 채 사람들이 무언가를 남기게 했다.\n그는 아무것도 모른 채, 그들처럼 무언가를 잃어버렸다."
  },
  CollectionHall_144452_LockTip = {
    Text = "의식 잠수 「영원한 에포얀스」 완료"
  },
  CollectionHall_144452_Title = {
    Text = "그들의 에로스"
  },
  CollectionHall_144453_Desc = {
    Text = "물고기 떼에게 있어, 질식은 그들이 바다를 떠난 후 유일하게 가질 수 있는 감각이다."
  },
  CollectionHall_144453_LockTip = {
    Text = "의식 잠수 「영원한 에포얀스」 어려움 난이도 완료"
  },
  CollectionHall_144453_Title = {
    Text = "바다에 갇히다"
  },
  CollectionHall_144454_Desc = {
    Text = "어리석고, 피상적이며, 오만하고, 겉만 강한 이탈자가 자신만의 나라를 세웠다.\n변함없는 껍데기들은 진실타래을 털어놓지 않는다. 왜냐하면 그 어떤 것도, 변화를 너무 두려워한 나머지 너무 일찍 부서져버린 그 마음을 골짜기에서 다시 이어 붙일 수 없기 때문이다."
  },
  CollectionHall_144454_LockTip = {
    Text = "의식 잠수 「영원한 에포얀스」 완료"
  },
  CollectionHall_144454_Title = {
    Text = "끝없는 개선"
  },
  CollectionHall_144476_Desc = {
    Text = "이 짧은 춤이 흐름 속에서 영원으로 화하게 하라.\n다음 기세의 밤, 우리는 반드시 달빛 아래서 재회하리라.\n*부녀지정이 깊어 가슴을 울린다 (ノへ￣、)"
  },
  CollectionHall_144476_LockTip = {
    Text = "특파대 기록“기도의 해를 향한 기차”"
  },
  CollectionHall_144476_Title = {
    Text = "기세 불꽃놀이"
  },
  CollectionHall_145434_LockTip = {
    Text = "클리어 기간 한정 이벤트 「임시 텍스트」의 어느 스테이지든 필요함"
  },
  CollectionHall_145434_Title = {
    Text = "레비아탄의 놀음: 살육의 각축"
  },
  CollectionHall_145460_Desc = {
    Text = "태어난 그 순간부터, 그 존재는 영원한 허기에 빠져 있었다.\n\n항성의 시체가 그 이빨 사이에서 부서져 내리고, 문명의 잔해가 그 배 속에서 썩어갔다. 그 존재의 허기은 시간보다 더 오래된 저주였다. 그 존재는 거듭해서 힘을 삼키고, 부하들을 부추겨 권력의 유희를 벌이게 했지만, 자신의 의미가 대체 무엇인지는 결코 알지 못했다.\n\n어느 날, 로탄이라는 전사가 그 존재 앞에 다가설 때까지는.\n\n「레비아탄.」\n\n자신의 이름을 마지막으로 들은 것이 언제였는지 기억나지 않았다. 엎드려 절한 왕들은 감히 그 이름을 입에 올리지 못했고, 미친 제사장들은 찬송가로만 그 이름을 대신했으니까.\n\n그런데 그녀는 쉽게 그 존재를 불렀다. 마치 오랜 숙적을 부르듯이.\n\n「네가 나설 차례다!」\n\n그 존재는 만 이천 년을 살아왔다. 이 기나긴 영원 속에서, 행성은 식량이었고, 생명체는 개미와 같았으며, 수많은 강자들은 그저 잠깐의 오락거리에 불과했다. 그 어떤 것도 그 존재를 배부르게 할 수 없었고, 그 어떤 것도 그 존재를 두렵게 할 수 없었다. 오늘까지는.\n\n이 필멸의 인간, 이 전사가 거대한 검을 들어 올려, 폭풍처럼 그 존재에게 덤벼들었다.\n\n거대한 검이 비늘 갑옷을 찢었다. 그 존재의 귀에, 자신이 혼돈 속에서 태어날 적의 포효가 울려 퍼졌다. 그 존재의 분노는 천체를 무너뜨렸고, 그 존재의 허기은 성운을 삼켰다.\n\n거대한 검이 발톱을 잘라냈다. 그 존재는, 흰 베일을 두른 「신」이 자신 앞에 나타나, 자신의 힘과 의지를 분리해 갔던 순간을 떠올렸다.\n\n거대한 검이 심장을 꿰뚫는 그 순간, 레비아탄은 웃음을 터뜨렸다.\n\n만 이천 년. 잃어버렸던 의지가, 마침내 다시 자신 앞에 도래하여, 자신을 베고, 자신을 정복하고, 자신을 삼켰다. 그녀는 자신을 이끌어, 모든 영역을 밟고 지나가며, 더 먼 별의 바다로 나아가, 모든 강력한 존재들을 정복할 것이다.\n\n그날, 태고의 혼돈의 짐승이 다시 태어났다. 그녀에게로 귀환한 그 순간, 그 존재는 완전히 깨달았다. 그와 그녀는, 순수하고 철저한 힘을 위해 태어났다는 것을.\n\n힘 그 자체가, 곧 모든 의미였다."
  },
  CollectionHall_145460_Title = {
    Text = "하늘의 추락"
  },
  CollectionHall_146400_Desc = {
    Text = "<Title:소개>\n오래된 신은 별하늘의 고래가 내뿜는 태고의 분노를 잠재울 수 없어, 결국 그의 영과 육을 분리할 수밖에 없었다. 그의 의지는 황량한 땅에 내려앉아, 침식·로탄이라는 전사로 재탄생했다.\n\n그녀는 천성적으로 호전적이며, 극한의 힘을 추구하는 것을 유일한 본능이자 영광으로 여긴다. 그리하여 그녀는 별하늘의 고래의 선발에 뛰어들어 그와 계약을 맺었고, 힘이 정점에 달했을 때에는 대검으로 자신의 주재자를 참살하고, 그 별을 삼키는 거수의 권능을 자신의 몸에 흡수하였다.\n\n날카로운 고래의 뼈가 살을 찢고, 어두운 골갑이 육체를 감쌌으며, 별하늘을 품은 그 두 동공에는 오직 적에 대한 냉철한 심판만이 남아 있었다.\n\n그녀는 파괴를 즐기지 않으며, 무의미한 살육에도 관심이 없다. 그녀가 갈망하는 것은 오직 더욱 흥미진진한 적과 더욱 강대한 힘뿐이다.\n\n가장 순수한 전사는 강적의 그림자를 쫓아 별의 바다 구석구석을 밟아 나아갔다. 모든 강자가 검 아래 쓰러질 때까지, 모든 길이 끝에 다다를 때까지."
  },
