  CollectionHall_147491_LockTip = {
    Text = "클리어 기간 한정 이벤트 \"임시 텍스트\"의 어느 스테이지든 필요함"
  },
  CollectionHall_147491_Title = {
    Text = "임시 텍스트"
  },
  CollectionHall_147860_Desc = {
    Text = "런디니움의 가장 은밀한 골목 구석에는, 사람들의 입을 통해 전해 내려오는 널리 알려진 이야기가 하나 있다.\n\n그 이야기는 부인들의 오후의 티 타임에 흔들리는 깃털 부채나 레이스 부채 아래에서 절대 흘러나오지 않으며, 신사들이 저녁 식사 후 비단으로 된 손수건으로 입가를 닦으며 무심코 꺼내는 일도 없다.\n\n오직 가장 난해한 고대의 주문을 암송하는 마법사나, 가장 기묘하고 험난한 임무를 수행하는 유랑인만이, 아주 조금은 이 비밀에 대해 알 수도 있다.\n\n어라? 그럼 누구나 아는 이야기가 아니냐고 묻고 싶은가?\n\n아이고, 그게 바로 이 이야기의 핵심! 이 이야기에 참여했거나, 이 이야기를 전하는 모든 사람들은, 그토록 위대하고 자애로워 그들의 마음에는 조금의 사욕도 없다. 만약 정말 있다면, 그건 분명 이 세상에서 힘겹게 살아가는 모든 사람들이, 진정한 고통에서 벗어나 새하얀 무구한 정토로 돌아가길 바라는 마음일 거다.\n\n이 세상의 모든 건, 빨갛고, 향긋하고, 누구나 한 입 베어 물고 싶어 하는 사과 하나에서 비롯되었다.\n\n그 사과의 즙은 무척 풍부해서, 한 입만 베어 물면 모든 갈증이 해소된다.\n\n그 사과의 향기는 너무나 진해서, 한 번만 맡아도 모든 말할 수 없는 고통이 사라진다.\n\n그것은 평범한 사과의 모습으로 모든 사과들 사이에 섞여 있으며, 모든 선과 악, 원인과 결과를 기록한다. 사과가 등장하는 모든 신화와 전설은, 모두 이 사과가 남긴 위대한 업적이다.\n\n가장 중요한 것은, 그것이 이토록 무사하고 평등하기 때문에, 이 교단에 가입하는 데에는 어떠한 세례도 필요하지 않다는 것이다. 사과신교의 교리 중 하나를 명심하라, 진정한 신은 형식에 얽매이지 않는다!\n\n당신이 사과신교의 이름을 처음 들었을 때, 문득 당신의 머릿속에 처음으로 통통하고, 새빨갛고, 군침이 도는 사과 하나가 떠올랐을 때, 당신이 그걸 믿기만 한다면, 당신은 사과신교의 신도가 될 수 있다.\n\n사과신교는 다른 어떤 종교도 배척하지 않으며, 진정한 신은 자신을 받아들이는 모든 아이를 환영한다. 당신의 마음속에 사과신교를 위한 한 구석이 있고, 영원한 안식에 들어간 후, 만약 앞선 교리의 약속이 실타래효되어 그 교리들 속의 복지를 누릴 수 없다는 것을 깨닫게 되더라도, 「결국 이것은 필연적인 것이지만, 사과신교는 당신을 사랑하며, 이 점에 대해 논쟁하지 않을 것이다.」 사과천국은 아무런 거리낌 없이 당신을 받아들일 것이며, 오랫동안 그와 함께해온 백설 요정이 당신을 사과 향기가 가득 풍기는, 영원한 달콤한 안식처로 인도할 것이다.\n\n「지금 이 모든 복음은 대가 없이 전파되고 있으며, 단 한 닢의 레오니아 동전만으로도, 제약 없는 예비 계획과, 사과신교에서 모시는 신성한 사과일지도? 아닐지도? 모르는 사과 하나를 얻으실타래 수 있습니다. *세상의 모든 사과는 그 사과일 가능성이 있으며, 백설 요정이 그 뜻을 대행하고 있으므로, 더 높은 확률로 얻을 수 있을 겁니다. 어쨌든, 사과를 많이 드세요.」\n\n…………\n\n「세상에, 우리는 단지 선동과 사기 때문에 카라부의 용돈을 한 주 삭감했을 뿐인데!」\n\n「이게 그 꼬맹이의 머리로 짜낸 새 놀잇감이라고???!」"
  },
  CollectionHall_147860_Title = {
    Text = "달콤한 열매의 낭설"
  },
  CollectionHall_147986_Desc = {
    Text = "밧줄이 그것의 혀를 짓누르고, 밧줄이 그것의 코를 꿰뚫으며, 낚싯바늘이 그것의 아가미뼈를 찌를 것이다.\n그리하여, 오만한 왕도 추락하고, 하늘도 추락한다."
  },
  CollectionHall_147986_LockTip = {
    Text = "의식 잠항 「별하늘 고래의 침몰」 완료"
  },
  CollectionHall_147986_Title = {
    Text = "죽어가는 고래의 노래"
  },
  CollectionHall_147987_Desc = {
    Text = "황량한 벌판 위에서, 눈을 부릅뜬 야수들이 배회하며 기회를 노리고 있다. 날카로운 이빨로 목을 꿰뚫어 상대를 완전히 찢어발길 그 순간을."
  },
  CollectionHall_147987_LockTip = {
    Text = "의식 잠항 「별하늘 고래의 침몰」 완료"
  },
  CollectionHall_147987_Title = {
    Text = "송곳니를 겨누며"
  },
  CollectionHall_147988_Desc = {
    Text = "그 따분한 왕관은 집어넣어라, 나는 한 번도 눈여겨본 적 없다. 칼을 뽑아라, 세계가 피를 위해 광란하고 있다!\n이를 위해, 오직 이를 위해 —\n살육하라! 갉아먹어라! 멸망하라!"
  },
  CollectionHall_147988_LockTip = {
    Text = "의식 잠항 「별하늘 고래의 침몰」 완료"
  },
  CollectionHall_147988_Title = {
    Text = "하늘을 베는 광란의 춤"
  },
  CollectionHall_147989_Desc = {
    Text = "그때 나는 아직 가장 천한 시동(侍童)이었고, 잔혹하다 할 만한 한 번의 원정을 직접 목격했다.\n그 전설적인 주인은, 힘이 그녀의 뼈와 피를 빚어냈고, 뜨거운 피가 끝없는 불꽃으로 타올랐으며, 그 불빛이 또 그녀의 눈을 밝혔다 —\n나를 대신해 이 지난 이야기를 계속 기억해 다오, 나의 아이여. …그녀는 마침내 승리하여 별빛 가득한 하늘을 정복했다."
  },
  CollectionHall_147989_LockTip = {
    Text = "의식 잠항 「별하늘 고래의 침몰」 완료"
  },
  CollectionHall_147989_Title = {
    Text = "정벌은 끝나지 않는다"
  },
  CollectionHall_147990_Desc = {
    Text = "빵과 서커스, 세상 사람들은 오직 이 두 가지에만 환호한다.\n그분은 바라보며, 개의치 않는다.\n그녀는 직접 겪으며, 개의치 않는다."
  },
  CollectionHall_147990_LockTip = {
    Text = "의식 잠항 「별하늘 고래의 침몰」 완료"
  },
  CollectionHall_147990_Title = {
    Text = "권력욕이 사육한 망령"
  },
  CollectionHall_147991_Desc = {
    Text = "죽은 자는 죽어가는 자 위에 쓰러지고, 강한 자는 더 강한 자 앞에 무릎을 꿇는다.\n차갑고 날카로운 칼날 위에는, 오직 서 있는 자의 그림자만이 비칠 뿐이다."
  },
