  },
  CollectionHall_148015_Title = {Text = "원칙"},
  CollectionHall_148138_Desc = {
    Text = "텅 빈 실험실 안에서, 각종 정밀 기기들이 가지런히 놓여 있었고, 오직 수많은 관선(管線)만이 뒤엉켜 마치 구불구불 감긴 뱀처럼 바닥에 엎드리고 공중에 매달려 있었다.\n사유의 신호는 마치 아무도 볼 수 없는 강물과 같았지만, 천재는 이미 그것을 다루는 데 익숙해져 있었다. 뇌가 그것들의 발원지이고, 기계적인 관선을 따라 흘러, 마침내 이 새로 만들어진 육체 속에 모여들었다.\n의식이 전달되는 동시에, 오랫동안 봉인되어 있던 많은 기억들도 오랜만에 꺼내졌다. 가족, 미사그, 미완성의 실험……어렴풋한 가운데, 천재는 수년 전, 아직 최초의 육신이라는 굴레를 벗어나지 못했을 때, 한 따분한 학생이 흥미롭다는 듯 그녀 주위를 맴돌며 호기심이라는 이름의 빛을 눈 속에 반짝이던 것을 떠올렸다.\n「선생님은, 인공적인 육체가 진정한 영혼을 담을 수 있다고 생각하십니까?」\n범인(凡人)들은 언제나 자신들의 시야를 훨씬 뛰어넘는 것들을 상상하기 좋아한다. 진부한 질문이었다. 하지만 교사로서, 그녀는 눈 하나 깜짝하지 않으면서도 몇 마디 대답을 내놓았다.\n「네 몸도 인공적인 것이 아니라고 할 수 없어. 심장, 사지, 오감 같은 기관들의 작동이 기계와 무슨 차이가 있지?」\n「됐어, 그런 쓸데없는 생각을 하느니, 차라리 시간을 내서 녹슨 네 뇌를 제대로 단련시키는 게 낫겠어. 그렇지 않으면, 피가 흐르는 그 육체는 더욱 쓸모없어질 뿐이야.」\n이제, 질문을 던졌던 그 사람은 이미 시간의 모래에 묻혀 더 이상 존재하지 않는다. 오직 지혜를 담은 뇌 탱크만이 여전히 사유하고, 영원히 사유한다.\n세상 사람들이 말하는 이른바 영혼이란 860억 개의 뉴런이 교차하여 이루어진 전기화학적 활동에 불과하다. 혈육이든, 기계든, 원재료의 차이는 그것들이 단지 담체(擔體)에 불과하다는 본질을 바꾸지 못한다.\n그렇다, 범인은 어쩔 수 없지만, 천재인 그녀는 할 수 있었고, 이미 해냈다 — 오직 그래야만, 세계의 진리를 해명하고 지식의 정점에 도달할 수 있다.\n시각이란, 빛이 안구를 통과하여 최종적으로 망막 위에 초점을 맺는 것에 불과하다.\n후각이란, 냄새 분자가 수용체와 결합하여 신경을 스치는 화학적 감지 경로에 불과하다.\n청각이란, 음파가 달팽이관에서 변환되어 피질로 전달되는 전기 신호로 바뀌는 것에 불과하다.\n인형이 있는 곳은 너무나 어두웠고, 희미한 불빛이 흔들려 그림자조차 비추지 못했다. 그녀는 두 눈을 살며시 감았다. 설령 눈을 떠도 눈에 들어오는 것은 변함없는 풍경뿐임을 알고 있었기 때문이다.\n방은 티끌 하나 없이 청소되어 있었고, 병과 단지 속의 약액도 단단히 봉인되어 있었다. 기체(機體)는 호흡이 필요 없고, 감각을 시험하기 위해 이 무미건조한 공기를 흡입할 필요도 없었다.\n오직 차가운 기계음 하나만이, 텅 빈 실험실 안에 울려 퍼졌다.\n「의식 동조 완료, 기체 가동 확인.」\n충분하다.\n무기질적인 소리이지만, 듣기에는 오히려 친근하게 느껴졌다. 마치 물질 세계의 실재를 닻처럼 고정시켜 주는 것 같기도 하고, 그저 짧은 휴식이 끝났으니 새로운 연구에 몸을 던질 시간이 되었다고 단순히 상기시켜 주는 것 같기도 했다."
  },
  CollectionHall_148138_Title = {
    Text = "영혼의 동조"
  },
  CollectionHall_148140_Desc = {
    Text = "<Title:소개>\n뼛속까지 시리도록 눈보라가 내렸던 밤, 맨발의 소녀는 자신의 영혼을 벌레에게 바쳤다.\n그토록 값싼 것을 대가로, 수많은 이들이 평생 갈망해도 얻지 못할 행복을 살 수 있다면, 망설이며 미련을 가질 이유가 없지 않겠는가.\n그날 이후, 그녀는 새하얀 그림자처럼 황량한 세상을 떠돌았다. 거짓말로 신전을 엮어내고, 사탕으로 축복을 꾸며내어, 겨우 연명할 만큼의 공물을 받아 살아갔다.\n그녀와 벌레는, 가장 완벽한 동업자였다.\n\n그러던 어느 날, 산꼭대기에서 새로운 계시가 전해져 내려왔다.\n모든 소원을 이루어주는 성지의 존재를 온 세상에 선포하는 소식이.\n그녀는 그 불꽃으로 설산 전체를 녹여버릴 것이다."
  },
  CollectionHall_148140_LockTip = {
    Text = "조사 작전 별의 시대 제6장 「산의 연회」 클리어 시 해금"
  },
  CollectionHall_148140_Title = {Text = "카라부"},
  CollectionHall_148143_Title = {
    Text = "최북단 대륙"
  },
  CollectionHall_148163_Title = {
    Text = "산의 연회"
  },
  CollectionHall_149045_Desc = {
    Text = "「화환을 잘 써라, 이것이 너의 서훈식이다, 사랑하는 어린 기사여.」\n데이지꽃이 들판에 가득 피어날 때면, 언제나 게으른 병사들이 호위라는 명목으로 소년을 이끌고 이곳을 거닐곤 했다.\n아키텐 공국에서 가장 흔한 꽃으로 엮은 장식품이, 금빛 머리카락 위에 살며시 얹혔다.\n「각하, 어쩌면……훈련을 해야 하지 않을까요?」\n소년은 그렇게 말하면서도, 순순히 새하얀 화환을 바로 썼다.\n이 작고 앙증맞은 식물은 언제나 빛 속에 잠겨 있었고, 소년의 나라에서는 희망의 상징이기도 했다.\n다시 눈을 떴을 때, 그 밝고 아름다운 광경은 이미 사라지고 없었다.\n전마(戰馬)가 울부짖고, 적들이 경멸하듯 우르르 몰려들었으며, 수많은 군마 속에서 그는 홀로였다.\n그리고, 귀를 찌르는 소란이 갑자기 멈추었다 —\n검은 조류가 그의 영혼 속으로 밀려들었다.\n이어서 울려 퍼진 것은 긴 창이 살을 꿰뚫는 찢어지는 소리, 피가 요동치는 소리, 적들의 울부짖는 소리였다.\n그 얼굴들 위에 가득하던 경멸은 흔적도 없이 사라지고, 그 자리를 하늘을 뒤덮는 두려움과 물러섬이 대신했다.\n소년은 그저 기계적으로 손을 들어 찌르고, 뽑고, 다시 들어올렸다.\n마지막 병사가 쓰러질 때까지.\n연기와 먼지가 수많은 얼굴을 삼켰고, 정복자와 피정복자의 잔해가 땅 위에 쌓여 더 이상 구별이 없었다.\n그림자가 그의 등에 달라붙어 비웃으며 말했다. 「계속해. 창을 내려찍어, 한 번 더.」\n「수호자와 파괴자 사이에는, 원래부터 한 끗 차이밖에 없었다. 이제, 너는 이미 선택을 했다.」\n어둠이 하늘을 가리고, 피가 대지를 적셨다.\n그는 멀리 교외의 들판을 바라보았다 — 단 하룻밤 사이에, 그곳은 영원히 예전의 빛깔을 잃어버렸다.\n바람이 소년의 옷자락을 날리고, 요행히 남아 있는 그 풀밭을 스쳐 지나갔다.\n소리 없는 밤의 어둠 속에서, 악마조차 알지 못하는 구석에서, 희미하게 알아채기 어려운 순백의 빛이 여전히 그의 눈 속에 남아 있었다.\n그것은 이 나라의 마지막 데이지꽃으로, 아무도 신경 쓰지 않는 곳에서 묵묵히 자라고 있었다.\n붉은 빛에 물들고 꽃대가 꺾였지만, 그래도 아직 쓰러지지 않았다."
  },
  CollectionHall_149045_Title = {
    Text = "그래도 데이지는 만발한다"
  },
  CollectionHall_149759_Desc = {
    Text = "<Title:소개>\n오지에는 결국 인정할 수밖에 없었다. 자신의 나이와 힘으로는 아직 나라를 지키는 기사가 되기에 부족하다는 것을.\n이 세계에서 그는 그 결정적인 지지의 말을 얻지 못했다.\n그리하여 공주의 설득에 따라, 그는 아버지의 영지로 돌아가 평범한 귀족 도련님처럼 살아갔다.\n\n전화(戰火)가 밀어닥쳤을 때, 기사의 신분을 끝내 버리지 못한 오지에는 왕궁으로 달려갔지만, 이미 때는 늦어 있었다.\n공주는 가장 잔혹한 방식으로 스스로를 파멸시켰고, 낯익은 동료들은 단 한 명도 살아남지 못했다 — 그들은 마지막 순간까지 자리를 지켰다.\n적군이 이미 폐허가 된 궁전에 쳐들어와 모든 것을 약탈하려 했을 때, 그는 분노와 슬픔을 억누를 수 없어 유혹으로 가득한 어둠의 힘에 몸을 내맡기는 것을 선택했다.\n적들은 대형을 재정비할 틈도 없이 모두 그의 손에 쓰러졌지만, 복수를 마친 후에도 소년은 조금도 해방감을 느끼지 못했다.\n\n칠흑 같은 그림자가 그의 육체를 점령하고 영혼을 물들였으며, 그 혼미한 나날들 속에서 그는 수많은 과오를 저질렀다.\n\n— 살육, 파괴, 맹세에 어긋나는 모든 것을......그러던 어느 날, 한 줄기 햇살이 끝없는 허무 속에서 그를 각성시켰다.\n\n어쩌면, 지금부터 후회해도 아직 늦지 않을지도 모른다.\n그에게는 아직 다시 창과 방패를 들고, 미덕을 수호하기 위해 싸울 기회가 남아 있었다."
  },
  CollectionHall_149759_LockTip = {
    Text = "「맹세를 저버린 자·오지에」 각성 후 해금"
  },
  CollectionHall_149759_Title = {
    Text = "서약을 저버린·오지에"
  },
  CollectionHall_149927_LockTip = {
    Text = "조사 작전 별의 시대 6-1 클리어 시 해금"
  },
  CollectionHall_149927_Title = {
    Text = "소원 없는 첨탑"
  },
  CollectionHall_149928_LockTip = {
    Text = "조사 작전 별의 시대 6-17 클리어 시 해금"
  },
  CollectionHall_149928_Title = {
    Text = "눈보라 치는 밤"
  },
  CollectionHall_48609_LockTip = {
    Text = "조사 작전 1-8에서 해제 가능"
  },
  CollectionHall_48609_Title = {
    Text = "녹슨 열쇠"
  },
  CollectionHall_48611_Desc = {
    Text = "<Title:물질 차원>\n물질이 존재하는 차원, 인간의 일상생활이 이루어지는 “현실타래 세계”입니다.\n물질 차원에서는 공간이 세 가지 차원으로 표현되며, 시간은 선형으로 흐르고, 물질은 감지 가능하며, 감정과 정신은 추상적이고 보이지 않습니다.\n모든 것이 그렇게 자연스럽게 느껴져, 이해할 수 없는 것들이 결코 존재하지 않았던 것처럼 보입니다.\n\n<Title:정신 차원>\n정신이 존재하는 차원으로, “환몽 차원”이라고도 불립니다.\n정신 차원에서는 감정, 기억, 집착 등이 다양한 개체를 형성할 수 있습니다.\n물질 차원의 개체들의 정신 외에도, 이곳에는 다양한 정신 차원의 생물들이 서식하고 있습니다. 이러한 생물들은 육안으로는 관찰하기 어려우며, 특수 장비를 이용하거나 미경에서만 탐색할 수 있습니다."
  },
  CollectionHall_48611_Title = {Text = "차원"},
  CollectionHall_48612_Desc = {
    Text = "<Title:정의와 특성>\n물질이 특수하게 분해되고 용해되는 현상입니다.\n소수의 개인을 제외하고 대부분의 인간은 융식 현상을 눈으로 관찰할 수 없습니다.\n융식이 진행됨에 따라 융식된 존재 자체가 사라집니다. 생활 흔적, 서면 기록, 그리고 그와 관련된 기억까지 모두 사라집니다.\n그들은 세상에서 완전히 잊혀질 것입니다.\n\n<Title:융식 전파>\n전파 경로는 확인할 수 없습니다.\n융식의 발생과 소멸은 완전히 무작위이며 예측할 수 없고 추적할 수도 없습니다. 현재 특정 방법과 수단, 예를 들어 특별한 의식이나 유물 등을 통해 융식을 확산시킬 수 있습니다.\n\n<Title:융식 개입>\n은심 및 은심 제품을 통해만 개입 치료가 가능합니다.\n대부분의 경우 융식이 더 쉽게 침식되며, 완전히 소멸되기 전에 은심 제품을 통해 개입할 수 있습니다.\n극소수의 개인은 융식에 일정한 저항성을 가지고 있지만, 정신적 손상은 복구할 수 없으며 은심 제품으로도 치료할 수 없습니다. 현재 효과적인 개입 수단은 발견되지 않았습니다."
  },
  CollectionHall_48612_Title = {Text = "융식"},
  CollectionHall_48614_Title = {Text = "문"},
  CollectionHall_48616_Desc = {
    Text = "<Title:설립일>\nA.F.187, 전신인 미사그 학원은 A.F.90에 설립\n\n<Title:설립자>\n화드·필립스, 크라르크슈, 타웨이\n\n<Title:개요>\n융식에 대한 저항을 사명으로 삼는 특수 대학.\n각국 정부로부터 완전히 독립된 제3자 기관으로, 어떠한 정치적 분쟁에도 참여하지 않으며 어떤 세력에도 귀속되지 않는다.\n전체 교직원과 학생을 합쳐 겨우 천여 명에 불과하며, 경제·인문·과학 등의 일반 과정 외에도 조사원, 비밀수호자 및 깨어남체를 위한 특수 과정을 개설하고 있다.\n본교는 레오 왕국에 위치하며, 세계 각지에서 융식 현상이 발생하면 조사대와 조사원, 비밀수호자를 파견하여 해결한다.\n이론과 실타래전을 동등하게 중시하는 특수 조직으로, 낙제의 결과 역시 매우 심각하다."
  },
  CollectionHall_48616_LockTip = {
    Text = "클리어 프롤로그 해금"
  },
  CollectionHall_48616_Title = {
    Text = "미사그 대학교"
  },
  CollectionHall_48618_Title = {Text = "서"},
  CollectionHall_48619_Desc = {
    Text = "<Title:설립일>\nA.F.186\n\n<Title:설립자>\n《미스디아 협정》 서명국\n\n<Title:개요>\n보통 인간으로 구성된 세계적인 조직입니다.\n각국 정부가 공동으로 자금을 제공하여 설립되었으며, 정부와는 독립적으로 존재하며, 융식 현상의 공식 관리자이자 첫 대응자입니다.\n회원들은 대부분 신비학적 배경이나 초자연적 능력이 없는 보통 사람들로, 융식에 대항하는 것이 최우선 과제이자 유일한 목표입니다.\n세계 각국에 여러 사무소를 두고 있으며, 각기 다른 지역을 담당합니다.\n엄격하고 딱딱한 것이 모든 사람들의 첫인상이며, 지나치게 세탁된 하얀 제복은 그들의 등과 같이 펴져 있습니다."
  },
  CollectionHall_48619_LockTip = {
    Text = "조사 작전 제2장 「밀랍인형의 이름으로」 완료 시 해제"
  },
  CollectionHall_48619_Title = {
    Text = "미스티아 협정 심사 위원회"
  },
