  },
  CollectionHall_48624_Title = {Text = "은심"},
  CollectionHall_48625_LockTip = {
    Text = "의식 잠수 클리어 “한 걸음 차이: 비와 같은 눈물” 해금"
  },
  CollectionHall_48625_Title = {
    Text = "생명의 여운"
  },
  CollectionHall_48628_Desc = {
    Text = "어우, 어우!\n고독한 늑대가 위에 마스크를 쓰고 포효하며 달려온다."
  },
  CollectionHall_48628_Title = {
    Text = "황야 늑대"
  },
  CollectionHall_48629_Desc = {
    Text = "모든 사람이 하얀 털 토끼를 좋아할 거예요, 귀여운 앨리스도 포함해서."
  },
  CollectionHall_48629_Title = {
    Text = "저주받은 토끼"
  },
  CollectionHall_48630_Desc = {
    Text = "손에 찔리지 않도록 조심하세요."
  },
  CollectionHall_48630_LockTip = {
    Text = "조사 작전에서 해제가 가능합니다"
  },
  CollectionHall_48630_Title = {
    Text = "<WhiteQuality:무명부지>"
  },
  CollectionHall_48631_Desc = {
    Text = "이 작은 소황나사의 출신은 고귀하며, 완벽하고 흠잡을 데 없는 기원을 가지고 있습니다."
  },
  CollectionHall_48631_LockTip = {
    Text = "조사 작전에서 해제가 가능합니다"
  },
  CollectionHall_48631_Title = {
    Text = "<WhiteQuality:소황나사>"
  },
  CollectionHall_48635_Desc = {
    Text = "<Title:요약>\n미사그 대리 학장.\n클로리 맥킨농에게 사사받아 헤버트의 직계 후배가 되었다.\n헤버트가 스승을 살해한 사건의 증언자 중 한 명으로, 스승 사후 계속해서 학원 관련 업무를 처리해오고 있다.\n절대적인 효율 우선주의자로 결코 지각하지 않으며, 단발머리를 유지하는 이유는 머리를 빗는 시간을 절약하기 위해서이다.\n전쟁으로 인해 조국 엘크에서 레오로 밀입국했다.\n오른손 검지가 정상적으로 구부러지지 않는데, 이는 수용소에서 잔혹하게 대우받은 증거라고 한다."
  },
  CollectionHall_48635_LockTip = {
    Text = "클리어 프롤로그 해금"
  },
  CollectionHall_48635_Title = {Text = "코르트"},
  CollectionHall_48636_Desc = {
    Text = "<Title:요약>\n세 명의 창립자 중 한 사람으로, 월드 필립스와 클라르크시와 함께 미사그 대학의 전신인 미사그 학원을 창설했습니다.\n첫 번째 “깨어남체”이며, 깨어남체 기술을 제공하는 존재입니다.\n블랙풀에서 오랜 시간 동안 지키고 있으며, 그 얼굴을 본 사람은 손가락으로 꼽을 정도로 적습니다. 미사그 대학의 최고 기밀 중 하나입니다.\n“쉿…… 당신의 @2를 시험하지 마세요.”"
  },
  CollectionHall_48636_LockTip = {
    Text = "클리어 프롤로그 해금"
  },
  CollectionHall_48636_Title = {Text = "타비"},
  CollectionHall_48941_LockTip = {
    Text = "조사 작전 1-8에서 해제 가능"
  },
  CollectionHall_48941_Title = {Text = "녹슨 문"},
  CollectionHall_48942_Desc = {
    Text = "내 영혼은 무덤이다."
  },
  CollectionHall_48942_Title = {Text = "추방"},
  CollectionHall_48943_Desc = {
    Text = "깊게 숨 쉬기, 도미니크."
  },
  CollectionHall_48943_Title = {Text = "흡입"},
  CollectionHall_48944_Desc = {
    Text = "불멸불패."
  },
  CollectionHall_48944_Title = {Text = "축복"},
  CollectionHall_48945_Desc = {
    Text = "죽음 직전, 삶에 대한 갈망이 분출된다."
  },
  CollectionHall_48945_Title = {Text = "활성"},
  CollectionHall_48946_Desc = {
    Text = "눈으로 보아야 믿는다."
  },
  CollectionHall_48946_Title = {Text = "통찰"},
  CollectionHall_48947_Desc = {
    Text = "우리는 공허인, 우리는 허수아비."
  },
  CollectionHall_48947_Title = {Text = "숙성"},
  CollectionHall_48948_Desc = {
    Text = "쉿……여기까지, 나에게 멈춰. \n그의 출신을 조사하지 말라."
  },
  CollectionHall_48948_Title = {Text = "욕심"},
  CollectionHall_48949_Desc = {
    Text = "하몬쿠루스여, 당신에게 순수하고 결점 없는 육체를 바칩니다."
  },
  CollectionHall_48949_Title = {
    Text = "소녀의 번데기"
  },
  CollectionHall_48950_Desc = {
    Text = "그것은 영원하고 무구한 진실타래의 한 번의 순간입니다."
  },
  CollectionHall_48950_Title = {
    Text = "달콤한 점액동물"
  },
  CollectionHall_48968_Desc = {
    Text = "드렉슬러 경의 지팡이에 대해 미사그 캠퍼스 내에서는 많은 추측이 돌고 있습니다. \n\n“분명히 말해두지만, 경의 지팡이는 그의 미소처럼 비밀을 간직하고 있습니다. \n은심을 박아 깨어남체의 힘을 일으킬 수 있는 것인지, 아니면 화약을 숨겨 언제든 총으로 변신할 수 있는 것인지, \n드렉슬러 경이 우리에게 그 비밀을 밝혀주실타래 것입니다!” \n\n한나는 개회사를 빠르게 메모하며 카메라를 드렉슬러 경에게 대고, 소유자 본인의 후속 이야기를 기대했습니다. \n\n“그것인가요? 특별한 건 없어요, 단지 드렉슬러 가문에서 주문 제작한 일상용 지팡이일 뿐입니다. \n제 지팡이에 사용된 보석은 형제보다 덜 귀중하죠. \n만약 꼭 특별한 점을 말해야 한다면…… \n부모님과 형제의 피를 묻힌 적이 있다는 점이겠네요. 이건 어떻게 생각하시나요?”"
  },
  CollectionHall_48968_Title = {
    Text = "귀족의 지팡이"
  },
  CollectionHall_48969_Desc = {
    Text = "렌티니언의 지하세계에는 이런 스토리가 전해져 내려오고 있습니다. \n\n바쁜 부두, 조용한 골목길, 시끄러운 주점에서…… \n당신은 언제 어디서 카메라를 들고 안경을 쓰고 제복을 입은 소녀를 만날 수 있을지 모릅니다. 하지만 그녀를 찾으면 원하는 모든 정보를 살 수 있으며, 대가는 단 하나입니다. \n\n당신만이 알고 있는 비밀 하나를 제공하는 것입니다. \n\n누군가는 바에서 들은 술김에 털어놓은 진심으로 경쟁자의 치명적인 약점을 샀습니다. \n누군가는 자신의 약점을 대가로 연인이 말하지 않는 과거를 샀습니다. \n소녀는 무수히 많은 정보를 가지고 있지만, 오직 하나만은 어떤 비밀로도 바꿀 수 없습니다. \n\n“저에 대한 일? 죄송합니다, 이건 비매품이에요.”"
  },
  CollectionHall_48969_Title = {
    Text = "정보가 곧 생명"
  },
  CollectionHall_48970_Desc = {
    Text = "미사그 캠퍼스에서 가장 건들지 못할 사람은, 돌이 두 번째라면 첫 번째는 단연 실타래비아 양이다. \n\n미사그 유일한 심리치료사로서, 이 신비로운 사람은 미션 중 놀란 조사원들을 달래는 것뿐만 아니라 깨어남체의 불안한 감정을 다스리는 것도 그녀의 미션다. \n깨어난 자들을 전혀 두려워하지 않을 뿐만 아니라, 정신적으로도 그들과 대등하게 맞설 수 있다니—— 과연 어떤 강자일까요? \n\n미지의 세계에 대한 호기심으로 가득 차 경외심이 부족했던 신입생들은 어느 밤늦은 시각, 실타래비아 양의 진료실타래로 몰래 들어갔다. \n\n그러나 그들은 곧 의식을 잃었다. \n다음 날 아침, 캠퍼스 광장에서 깨어났을 때 머리는 욱신거렸지만 마음은 전례 없는 명료함을 느꼈다. \n누군가가 그들의 주머니에서 떨어진 편지를 발견했다: \n\n“심리 상담이 필요하시다면, 미리 에리카 양에게 신청해주세요—— \n실타래비아”"
  },
  CollectionHall_48970_Title = {
    Text = "마음의 장벽"
  },
  CollectionHall_48971_Desc = {
    Text = "귀족 부인의 동정과 혐오로 손수건으로 코를 가리고 하인을 시켜 필요 없는 보석을 주었을 때, 그녀는 생각했다: \n참 좋다，빈민원 아이들이 고기를 한 끼 먹을 수 있겠구나. \n\n그녀가 자신의 식사를 모두 아이들에게 나누어 주고, 오랜 기아로 복도에서 쓰러진 후, 그녀는 말했다: \n괜찮아, 의사 부르지 마. 진료비가 여러 개의 빵 값이니까. \n\n착한 예술가가 친분 있는 의사와 함께 방문하여 장기적인 협력을 제안했을 때, 그녀는 생각했다: \n우선 내 몸에서 시험해봐야겠어，그렇지 않으면 아이들이 이 치료를 받는 것에 대해 안심할 수 없겠어. \n\n사라는 모든 것을 참을 수 있었지만, 유일하게 참을 수 없었던 것은 자신이 한 모든 일이 결국 비극적인 결과로 이어지는 것이었다."
  },
  CollectionHall_48971_Title = {Text = "임계점"},
  CollectionHall_48972_Desc = {
    Text = "손이 어둠 속에서 주인을 찾기 위해 여기저기 둘러대고 있다. \n\n그 피비린 밤에, 그것은 주인의 몸에서 잔인하게 분리되었다. \n이 순간, 그 죄괴가 주변에서 흐르며 특이한 윙윙 소리를 내고 있다. \n \n“포기해, 우리와 함께 떠나자. 랍상사는 너를 완전히 잊어버릴 거다.” \n\n손은 동요하지 않았다. 자신이 자랑하는 긴 손가락을 움직였다. \n\n“주인은 나를 잊지 않을 거야. \n나는 그의 예술을 실타래현하는 유일한 방법이니까— \n너희들은 내가 그에게 어떤 의미인지 이해하지 못해.” \n\n“사람은 연인을 잊고, 시간을 잊지만, 자신을 잊지는 않아.” \n\n어둠 속에서 동정의 웃음소리가 들려왔다. \n“정확히 반대야. 사람들은 가장 먼저 자신을 잊어. \n하지만 상관없어—” \n\n시간이 모든 것을 설명할 것이다. 손은 결국 이 사실타래을 깨달을 거다: \n잊혀질 수 없는 것은 아무것도 없다. \n그들은 한 세기를 또 다른 세기를 흐르며, 인생의 이야기들이 그들 주변에서 일어나고, 다음 날에는 잊혀진다. \n그리고 그들은 여전히 쉬지 않고 흐르고 있다."
  },
  CollectionHall_48972_Title = {
    Text = "망각의 손"
  },
  CollectionHall_48973_Desc = {
    Text = "워드 필립스 씨에게 수용된 이후로, 알리스타는 그와 함께 여러 번 미사그의 고위 회의에 참석했습니다. \n\n 고위라는 표현이지만, 실타래제로는 매달 한 번씩 열리는 토론 대회와 같았습니다: \n 필립스 씨는 부드러운 말투로 차근차근 설득했습니다; \n 켈라르크시는 말이 날카롭고, 한 치도 물러서지 않았습니다. \n 그들은 번갈아 가며 정방 또는 반방을 맡아, 미사그의 미래나 다음 달의 깨어남계 자원 배분을 놓고 끊임없이 논쟁했습니다. \n 타비 양은 조용한 관찰자였으며, 자신의 의견을 쉽게 내놓지 않았습니다. \n 자신은 정직한 점수 기록원으로 노력하며, 때때로 심판 역할도 겸했고, 한 번은 싸움 기술을 사용해 작은 회의 테이블이 피해를 입지 않도록 해야 했습니다. \n\n 이제 회의 구성원은 두 명뿐입니다. 하나는 영원히 블랙풀을 떠날 수 없고, 다른 하나는 그 가능성이 있는 “미래”를 위해 지하에서 벗어날 수 없습니다. \n 그리고 그 테이블은 그 사건 이후로 다시는 찾을 수 없었습니다."
  },
  CollectionHall_48973_Title = {
    Text = "모임의 순간"
  },
  CollectionHall_48974_Desc = {
    Text = "타비는 블랙풀의 바닥에서 잠들어 있다.\n\n그곳은 연중 무음무광이며, 오직 절망적인 어둠만이 있을 뿐이다.\n여기에는 결코 손님이 찾아온 적이 없고, 결코 소리가 도달한 적이 없다.\n여기는 파멸이 닿을 수 없는 곳——\n\n왜냐하면 재앙이 이미 강림했기 때문이다.\n\n시서의 주관자로서, 그녀는 너무 많은 비통한 결말을 목격해왔다.\n규칙의 일원으로서, 그녀 또한 어둠의 강림을 막을 수 없다.\n그렇다면, 존재하지 않는 곳에 잠복하며 존재하지 않는 모습으로 '변수'라 할 수 있는 사람의 도착을 기다릴 수밖에 없다.\n\n그 사람은 결국 도착할 것이다."
  },
  CollectionHall_48974_Title = {
    Text = "존재하지 않는 곳"
  },
  CollectionHall_48975_Desc = {
    Text = "과학은 분광분석이고, 예술은 광합성이다."
  },
  CollectionHall_48975_Title = {
    Text = "광합성 제례"
  },
  CollectionHall_48976_Desc = {
    Text = "회전하고, 그다음 잊어버리기——이것이 그녀의 생명의 전부입니다."
  },
  CollectionHall_48976_Title = {
    Text = "36실타래의 고리"
  },
  CollectionHall_48977_Desc = {
    Text = "네 무덤을 멸시한다.\n너는 죽음 속에서 귀한 평화를 찾았기 때문이다."
  },
  CollectionHall_48977_Title = {
    Text = "묘지의 속삭임"
  },
  CollectionHall_48978_Desc = {
    Text = "영원히 계시 속에서 던져진 한 줄기 시선.\n순수하고, 무구하며 진실타래한."
  },
  CollectionHall_48978_Title = {
    Text = "무구의 계시록"
  },
  CollectionHall_48979_Desc = {
    Text = "탯줄은 모체와 연결되어 태아가 끝없는 미래를 짜낼 수 있도록 합니다."
  },
  CollectionHall_48979_Title = {
    Text = "생명력 추출"
  },
  CollectionHall_48980_Desc = {
    Text = "귀환하라, 그 실타래종된 도시가 재현될 것이다.\n귀환하라, @3!"
  },
  CollectionHall_48980_Title = {Text = "적도선"},
  CollectionHall_48981_Desc = {
    Text = "나비는 외로움, 사랑, 그리고 절망으로 죽어가고 있다."
  },
  CollectionHall_48981_Title = {
    Text = "유기 형태"
  },
  CollectionHall_48982_Desc = {
    Text = "회전하고, 그다음 잊어버리기——이것이 그녀의 생명의 전부입니다."
  },
  CollectionHall_48982_Title = {
    Text = "4월의 찬가"
  },
  CollectionHall_48983_Desc = {
    Text = "천 년 전, 5분은 40온스(약 1134그램)의 고운 모래와 같았다."
  },
  CollectionHall_48983_Title = {
    Text = "약재의 꿈"
  },
  CollectionHall_48984_Desc = {
    Text = "필연적인, 우연적인. 유한한, 무한한."
  },
  CollectionHall_48984_Title = {
    Text = "이율배반"
  },
  CollectionHall_48985_Desc = {
    Text = "대리학장은 미사그 캠퍼스의 특이점입니다. \n\n각기 다른 능력을 가진 몬스터들이 판을 치는 미사그 조사원들 중에서 그녀는 극소수의 인간 기본 능력 이상의 능력을 전혀 가지고 있지 않은 개인 중 하나입니다. 그러나 그녀는 중요한 직무인 대리학장을 맡고 있습니다. \n엘크 왕국의 보통 가정에서 태어난 그녀는 현지 특유의 문화적 영향으로 용감하고 강한 성격을 갖추게 되었습니다. \n\n그 후, 포로 수용소에서 동료 소피아가 그녀에게 학술 연구에 대한 열정을 불태웠습니다. \n우수한 학술 성취로 그녀는 그녀의 스승, 미사그 대학 생물학과 전임 학장의 가장 인정받는 제자가 되었습니다. \n따라서, 스승이 실타래종된 후 그녀는 당연히 대리학장의 직책을 이어받았습니다. \n그녀의 견고한 지키기에 생물학과의 연구는 체계적으로 진행되고 있습니다. \n\n“폭력에 두려움을 느끼지 않고, 패권에 두려움을 느끼지 않으니, 직무 소재에 대한 두려움도 없을 것입니다.”"
  },
  CollectionHall_48985_Title = {
    Text = "책임의 무게"
  },
  CollectionHall_48986_Desc = {
    Text = "조사원들 사이에는 공식적으로는 아니지만 암묵적으로 지켜지는 규칙이 있다: \n\n요총 의식이 끝난 밤, 경력이 더 오래된 조사원들이 신입 조사원들을 기숙사 뒷마당으로 데려가 모임을 갖는다. \n그들은 촛불을 켜고 자신의 은 열쇠를 중심으로 원을 그리며 앉는다. \n경력이 오래된 조사원들은 각각의 신인에게, 그들이 손에 들고 있는 고유한 번호가 새겨진 열쇠가 어떤 이야기를 가지고 있는지 말해준다. \n\n이런 이벤트는 결국 어떤 종류의 스토리 대회로 변하게 되고, I-0001과 K-0001, 이 두 개의 “초대”를 상징하는 열쇠는 자연스럽게 논의의 중심이 된다. \n많은 사람들이 모르는 사실타래이지만, 초대 수호자가 직접 만든 K-0001번 은 열쇠는 지금도 주인과 함께 지하에서 영원히 거주하며, 낮과 밤을 구분할 수 없는 긴 기다림 속에서 이미 사라진 사람에 대한 저어를 듣고 있다. \n\n“알리스타, 네가 진짜 여기에 있는 건 아니라는 걸 알아.” 돌이 말했다, “그것은 네 선생님의 은심을 사용해 만들어졌을지도 모르지만, 그것이 그의 영혼으로 볼 수는 없어.” \n“그냥 집중력을 유지하기 위한 방법일 뿐이야, 돌.” 알리스타가 웃으며 말했다, “걱정하지 마, 나는 안정적이니까. 우리 신입 수호자들이 성장하기 전에 쓰러질 수는 없으니까, 그렇지 않겠니?”"
  },
  CollectionHall_48986_Title = {
    Text = "정신 집중"
  },
  CollectionHall_48987_Desc = {
    Text = "그의 생명의 전반부는 카오스, 다크 그리고 피로 가득했다. \n\n먹고 자고, 자고 먹는 것이 전부였다... 나중에, 그는 눈을 떠 의식을 갖게 되었다. \n\n그들은 그가 자신의 모든 형제자매를 먹어치웠으며, 유일한 생존자였다고 말한다. \n또한 그들은 그가 위대한 뱀 신과 인간이 합쳐서 낳은 자식이라고 말한다. \n그의 목에는 검은 저주가 둘러져 있으며, 그것들은 그의 생명을 유지하면서도 그를 통제하여, 평생 교회에 반항할 수 없게 한다. \n그는 이 세상에 대해 많은 의혹과 호기심을 가지고 있지만, 탄생 초기부터 다른 모든 가능성이 박탈되었다. \n\n아름답고 위험한. 은폐하고 대담한. 이것이 바로 그다. \n유감스럽게도, 위의 진술은 그의 본질의 십분의 일조차 닿지 못한다. \n알비노에 대한 이러한 진술로 인해 동정심을 느끼는 것은 당신에게 영원한 재앙을 가져올 것이다."
  },
  CollectionHall_48987_Title = {
    Text = "고통의 저주"
  },
  CollectionHall_48988_Desc = {
    Text = "의사의 천직은 본래 환자를 치료하는 것이다. \n\n하지만 우연히 그런 치료 방법이 하나 있는데, 가장 날카로운 칼날로 피부를 베고 근육을 뚫고 가슴을 열어 병소를 제거한 후 인체가 자가 치유 능력으로 재생되기를 바라는 것이다. \n\n이는 원래 그녀의 죄가 아니다. \n하지만 매번 수술을 끝낸 후 그녀는 여전히 보상하듯 그 소녀에게 이야기를 들려주곤 한다. \n그녀는 훌륭한 이야기꾼이 아니라, 말이 끊어지고 부서지지만, 그 허구적인 이야기들은 여자아이가 진지하게 집중해서 듣게 만든다. \n그녀가 직접 절개한 곳은 마치 느리지만 강하게 그 말들의 힘을 흡수하며 점차 자연스럽게 치유되어 간다…"
  },
  CollectionHall_48988_Title = {
    Text = "절단과 상처"
  },
  CollectionHall_48989_Desc = {
    Text = "거대한 짐승이 밤의 어둠 속에 숨어 있다. \n\n 작은 집 안에서, 사랑하는 딸을 잃은 슬픔의 울음이 매일 밤 하루 동안 억눌렸던 인내심과 감정을 터뜨리며, 전혀 숨김없이 격렬하게 터져 나온다. \n 흐느낌에서 애곡으로 변하며, 결국 그 거대한 짐승에게 더 이상 속하지 않는 그 이름을 부르며, 통증의 외침으로 거대한 짐승의 인간과 다를 바 없는 심장을 관통한다. \n\n 돌아와, 리사. \n 오, 내 리사. \n 거대한 짐승은 침묵하며, 밤의 어둠 속에 숨어 있다. 몸을 웅크리고, 깊이 잠든다. \n 언젠가는, 그녀는 돌아가야 한다. “집”이라는 이름의 곳으로."
  },
  CollectionHall_48989_Title = {
    Text = "밤의 그림자 속에서"
  },
  CollectionHall_48990_Desc = {
    Text = "누구도 선장으로 태어나지 않았다. 적어도 엘튼은 그렇지 않았다. \n\n선장이 되기 전까지 그는 해군과 상선 사이를 전전했으며, 몇 번이나 해적이 될 뻔했지만, 결국 한 척의 탐험선에서 자리를 잡았다. \n\n탐험선은 극지 대륙을 돌며 항해했고, 매번 상륙은 새로운 모험을 의미했다. \n그의 미션은 몸이 약한 과학자들을 위해 배낭을 짊어지는 것이었고, 그는 그것에 대해 자부심을 느꼈다. 배낭 안에는 세상을 바꿀지도 모르는 무언가가 들어 있을 수 있었다, \n그리고 그들은 역사의 흐름을 바꿀 사람들일 수도 있었다. \n\n하지만 얼음 폭풍이 그들을 얼음 동굴에 갇히게 하기 전, 그리고 한 무리의 수수께끼 같은 신도들이 밤중에 그들을 습격하기 전까지만 해도, 엘튼은 그렇게 믿고 있었다."
  },
  CollectionHall_48990_Title = {
    Text = "모험 가방"
  },
  CollectionHall_48991_Desc = {
    Text = "그는 항상 조용하고 성실타래한 학생이었습니다. \n\n오전 8시, 다른 연구원들이 빵을 물고 서두르며 도착할 때, 그는 이미 한 편의 실타래험 보고서를 작성해놓았습니다. \n밤 12시, 실타래험동의 불이 전부 꺼졌을 때, 그는 느릿느릿 짐을 챙겨 떠났습니다. \n\n맞다, 그는 매일 근처의 작은 길냥이들을 돌보곤 했습니다. \n나중에 작은 길냥이들이 사라졌지만, 아무도 그것들이 어디로 갔는지 몰랐습니다. \n\n지도교수 클로리는 그의 실타래험 기록과 보고서를 분석했습니다. \n간결하고 세밀했지만, 특출난 점은 없었고—— 아울러 어떤 파열점도 없었습니다. \n이 학생은 그에게 의혹을 남겼습니다. \n하지만 의혹은 좋은 것이었습니다. 그것은 호기심으로 이어지는 스위치였으니까요. \n\n물론, 그때의 클로리는 예상치 못했습니다: 그것은 또한 죽음으로 이어지는 스위치일 수도 있다는 것을."
  },
  CollectionHall_48991_Title = {
    Text = "죽음의 해부"
  },
  CollectionHall_48992_Desc = {
    Text = "“모르고 있는 중, 당신은 이렇게 오래 떠나 있었네요. \n\n저는 아직도 종종 그날의 꿈에 갑니다. 왼팔의 총상으로 인한 통증, 출혈로 인한 환각, 폭동하는 쥐 무리의 추격…… \n그 혼란 속에서 미사그 교복을 입은 당신이 나타나, 저를 그 불길한 기운이 가득한 성에서 구해냈습니다. \n\n그 꿈의 마지막에는, 당신이 병상 앞에서 저에게 경고했습니다. 조사원에게 죽음은 늘 그림자처럼 따르는 것이라고. \n이제 저는 그것이 현실타래인지 환상인지 판단할 수 없습니다. \n그럴 때마다 저는 왼팔을 만져봅니다. 차가운 정교한 금속 표면을 만지게 된다면, 그것은 현실타래입니다. \n\n하지만 대부분의 꿈에서는, 저는 단지 공허함만을 잡을 뿐입니다.”"
  },
  CollectionHall_48992_Title = {
    Text = "나의 소중한 친구에게"
  },
  CollectionHall_48993_Desc = {
    Text = "크라우리가 재임 기간 동안 항상 “인기 있는 멘토”라는 영예로운 칭호를 유지했습니다. \n\n그의 서부 콘스턴트 억양과 진실타래한 미소는 많은 학생들의 마음을 사로잡았으며, 이 중에는 헤버트도 포함되었습니다. \n\nA.F.2@1년, 크라우리는 여러 의견에 반대하여 눈에 띄지 않는 헤버트를 자신의 제자로 받아들였습니다. \n헤버트는 그와 함께 산을 넘고, 계곡을 건너며, 사막을 가로질러 하나하나의 융식 균열 외곽에 발자국을 남겼습니다. \n그는 처음으로 융식 균열을 보았을 때의 충격을 아직 기억하고 있습니다. \n\n크라우리는 끓어오르는 검은 안개 앞에 서 있었고, 그의 모습은 그렇게 작아 보였습니다. \n“쉿— 들었나?” \n헤버트는 눈을 감고, 조용한 바다의 끊임없는 파도 소리를 들었습니다. 세상이 그에게서 멀어진 것 같았습니다. \n크라우리는 매우 흥분해서 말했습니다: \n“이것은 시. 우주에서 가장 신비롭고 깊은 시.” \n\n수년 후, 헤버트는 크라우리에 대한 기억이 이미 희미해졌습니다. \n예를 들어, 어떻게 협력하고 다투었는지, 어떻게 그를 “실타래수로” 죽였는지 등등. \n하지만 그는 그 검은 안개 아래의 미소를 영원히 기억할 것입니다. \n그 순간, 그는 시를 보았습니다."
  },
  CollectionHall_48993_Title = {
    Text = "기억증후군"
  },
  CollectionHall_48994_Desc = {
    Text = "우리의 뇌가 여전히 미스터리라면, 그 안에 촉수가 가득해도 놀랄 일이 아니다."
  },
  CollectionHall_48994_LockTip = {
    Text = "조사 작전에서 해제가 가능합니다"
  },
  CollectionHall_48994_Title = {
    Text = "<WhiteQuality:열두구더기>"
  },
  CollectionHall_48995_Desc = {
    Text = "꿈은 별빛 바다야!"
  },
  CollectionHall_48995_LockTip = {
    Text = "조사 작전에서 해제가 가능합니다"
  },
  CollectionHall_48995_Title = {
    Text = "<WhiteQuality:잠수 헬멧>"
  },
  CollectionHall_48996_Desc = {
    Text = "보이지 않는 것을 보고, 들리지 않는 것을 듣는다."
  },
  CollectionHall_48996_Title = {Text = "계시"},
  CollectionHall_48997_Desc = {
    Text = "모든 악의 근원"
  },
  CollectionHall_48997_Title = {Text = "징벌"},
  CollectionHall_48998_Desc = {
    Text = "만물이 자신의 것이 된다."
  },
  CollectionHall_48998_Title = {Text = "폭식"},
  CollectionHall_48999_Desc = {
    Text = "과거를 잊고, 미래를 고민하지 않는다."
  },
  CollectionHall_48999_Title = {Text = "광란"},
  CollectionHall_49000_Desc = {
    Text = "세계에 사랑과 죽음을 바칩니다."
  },
  CollectionHall_49000_Title = {Text = "총애"},
  CollectionHall_49001_Desc = {
    Text = "오랜 시간 동안 쌓아온 것을 여기서 선언한다—"
  },
  CollectionHall_49001_Title = {Text = "발현"},
  CollectionHall_49002_Desc = {
    Text = "그의 이름을 호출하세요: 에렉스."
  },
  CollectionHall_49002_Title = {Text = "환각"},
  CollectionHall_49003_Desc = {
    Text = "“그분”과의 대화."
  },
  CollectionHall_49003_Title = {Text = "밀담"},
  CollectionHall_49004_Desc = {
    Text = "싹과 태아에 내리는 축복입니다."
  },
  CollectionHall_49004_Title = {Text = "희망"},
  CollectionHall_49015_Desc = {
    Text = "재앙이 갑자기 사라지고 위험이 일시적으로 해제된 후, 미사그 특별 작전대는 “의외의 수확”을 가지고 아쿠트를 떠났다. \n덕스터 양반님은 마지막으로 폭발 중심부의 거대한 구덩이를 돌아보았다. 이름 모를 식물의 어린싹이 언제부터인지 조용히 흙을 뚫고 나왔다. \n그녀는 안도의 한숨을 내쉬며 기분이 좋아졌다. \n아쿠트 숲은 봄을 맞이할 것이다. \n버들은 다음 봄에 가지를 뻗을 것이고, 진달래는 다음 우기 후에 조용히 피어날 것이다. 모든 생명이 신생을 맞이할 것이다. \n그리고 그들이 미지와 대항하는 여정은 새로운 출발점에 설 것이다. \n"
  },
  CollectionHall_49015_Title = {
    Text = "아쿠트의 봄"
  },
  CollectionHall_49018_Desc = {
    Text = "A.F. 314, 겨울의 한 밤중, 폭발음이 아쿠트 숲을 울렸다. \n대지가 떨리며, 숲은 백주처럼 밝아졌다. 생명의 비명과 자연의 울부짖음 속에서 마을이 평지가 되었다. \n“아쿠트 재앙 조사”에 참여한 깨어남계 예과생 덱스터에 따르면, 그 밤 하늘을 가득 채운 불꽃 속에는 검은색과 은색이 빛나고 있었다."
  },
  CollectionHall_49018_Title = {
    Text = "태양의 추락"
  },
  CollectionHall_49025_Desc = {
    Text = "진한 검은색의 혈제, 쌍둥이가 당신의 육체를 보호해 주기를."
  },
  CollectionHall_49025_Title = {
    Text = "왜곡된 쌍둥이·검은색"
  },
  CollectionHall_49026_Desc = {
    Text = "흰 안개의 축복, 쌍둥이가 당신의 영혼을 보호해 주기를."
  },
  CollectionHall_49026_Title = {
    Text = "왜곡된 쌍둥이·백"
  },
  CollectionHall_49027_Desc = {
    Text = "즐겁게 잔치를 즐겨라, 노래 속에서, 파멸된 고향을 축하하자."
  },
  CollectionHall_49027_Title = {
    Text = "먼 곳의 잔치"
  },
  CollectionHall_49028_Desc = {
    Text = "전설에 따르면 최초의 마우를 창조한 자는 피로 마우를 키웠다."
  },
  CollectionHall_49028_Title = {
    Text = "진홍빛 심동"
  },
  CollectionHall_49029_Desc = {
    Text = "쉿……비밀은 부드러운 패드에 숨겨져 있다."
  },
  CollectionHall_49029_Title = {
    Text = "기계장치의 신"
  },
  CollectionHall_49030_Desc = {
    Text = "번식하라, 번식하라. 모나무의 피가 흐르는 영혼이 세상에 가득 차게 하라."
  },
  CollectionHall_49030_Title = {
    Text = "다시 진화"
  },
  CollectionHall_49031_Desc = {
    Text = "전설에 따르면 최초의 마우를 창조한 이가 자신의 두 손으로 마우를 죽였다."
  },
  CollectionHall_49031_Title = {
    Text = "스칼렛 애매트"
  },
  CollectionHall_49033_Desc = {
    Text = "시간의 현이 뿌리째 끊어지고, 흐르는 건반들이 산산이 부서진다. \n그들은 현실타래 바깥에 서서, 현실타래을 이용해 부족한 부분을 채우며, 영원히 아디오스하지 않는 악장이 다시 창공에서 울려 퍼지게 한다. \n잠시 꿈에서 깨어났을 때 흘린 눈물이 어디로 흘러갔는지는 아무도 모른다."
  },
  CollectionHall_49033_Title = {
    Text = "영혼의 탄생"
  },
  CollectionHall_49082_Title = {
    Text = "렌티니언 실타래외"
  },
  CollectionHall_49084_Title = {
    Text = "02 밀랍인형의 이름으로"
  },
  CollectionHall_49104_LockTip = {
    Text = "조사 작전 6-1 완료 시 해제"
  },
  CollectionHall_49104_Title = {
    Text = "뒤틀린 별들"
  },
  CollectionHall_49105_LockTip = {
    Text = "통관 특수 미션 기록「혈액의 색깔: 후회」해금"
  },
  CollectionHall_49105_Title = {
    Text = "영혼의 목자"
  },
  CollectionHall_49740_LockTip = {
    Text = "조사 작전 7-0 완료 시 해제"
  },
  CollectionHall_49740_Title = {
    Text = "만물의 어머니"
  },
  CollectionHall_49747_Desc = {
    Text = "융식 흔적에서 자라난 군더더기 조직.\n현재까지 군더더기 조직의 성장 여부, 서로 다른 유형의 분포 등에서 어떠한 규칙도 도출할 수 없었다.\n추가적인 사지나 촉수일 수도 있고, 톱니바퀴나 금속 등의 무기물일 수도 있다."
  },
  CollectionHall_49747_Title = {
    Text = "부식 종양"
  },
  CollectionHall_49748_Desc = {
    Text = "<Title:정의와 특성>\n직경이 5미터를 초과하며 여전히 확대 가능성이 있는 거대한 융화자국입니다.\n융식 균열의 크기에 따라 C, B, A, S, SS, SSS 등급의 균열로 분류될 수 있습니다.\n시간이 지남에 따라 지속적으로 확대되며, 일반적인 융식 확산 외에도 해일, 태풍 등의 비정상적인 자연 현상을 유발할 수 있습니다.\n\n<Title:대응 방식>\n은심으로 정제된 은 열쇠는 일정 정도까지 균열을 억제하거나 심지어 “닫기”를 할 수 있습니다.\n수호자는 은 열쇠를 통해 자신의 정신을 확대하여 정신 차원과 공명시키고, 융식 균열 위에 고차원 장벽을 형성하여 일시적으로 “닫히게” 합니다."
  },
  CollectionHall_49748_Title = {
    Text = "부식 균열"
  },
  CollectionHall_49749_Desc = {
    Text = "융식 균열의 핵심은 일반적으로 수호자가 외부 태스크에서 해결해야 하는 주요 적입니다. \n 융식 현상을 확산시킬 수 있으며, 자체 특성에 따라 인근의 융식 현상에 영향을 미쳐 지역적 특성을 갖게 합니다."
  },
  CollectionHall_49749_Title = {Text = "재앙"},
  CollectionHall_49750_Desc = {
    Text = "<Title:정의와 특성>\n융식 현상은 개체가 변이, 소멸, 사망하는 현상을 말합니다.\n인간, 동식물 등 유기체뿐만 아니라 광물, 금속 등 무기물에서도 발생할 수 있습니다. 융식 균열 부근에 있는 개체는 융식 침식 가능성이 더 높습니다.\n현재까지 융식 현상에 면역인 물질은 발견되지 않았습니다.\n\n<Title:각 시기 특징>\n초기: 체표면에 역삼각형 검은색 융화자국이 나타나며, 융해진흙이 분출됩니다.\n중기: 융화자국이 확대되고, 지속적으로 융해진흙이 분출되며, 개체의 정신 상태가 손상됩니다. 융식 잡초가 생길 수도 있습니다.\n후기: 융화자국이 급속도로 확대되고, 융해진흙의 분출 속도가 가속화됩니다. 대부분의 개체는 이 단계에서 완전히 이성을 잃습니다.\n말기: 개체의 신체가 붕괴되어 생리적으로 사망하지만, 정신은 계속 침식됩니다. 정신이 완전히 침식되면 개체는 완전히 사라지고, 다시 깨울 수 없습니다.\n\n<Title:특수 사례>\n신체적 특수 사례: 융식된 개체는 신체와 오감이 강화되는 현상을 보입니다. 일부 개체는 잡초, 재앙 등의 영향으로 비행, 정신 영향, 사고 제어 등의 특수 능력을 갖습니다.\n정신적 특수 사례: 융식된 개체의 정신이 융식의 영향을 덜 받아 기본적인 이성을 유지합니다. 소수의 개체는 정상적으로 행동하며, 융식되지 않은 개체와 다를 바 없습니다."
  },
  CollectionHall_49750_Title = {
    Text = "융식침식"
  },
  CollectionHall_49751_Desc = {
    Text = "<Title:정의와 특성>\n개체가 융식침식으로 인해 육체를 잃고 융해진흙 및 융식 분진으로 변하는 현상입니다.\n해체된 개체는 그 존재 자체가 세상에서 지워집니다.\n\n<Title:각 시기의 특징>\n초기: 융식된 개체와 친하지 않은 사람은 그 존재를 망각합니다.\n중기: 융식된 개체와 친한 사람들의 기억이 약화되고, 관련 서적에 융화자국이 나타나며 모호해집니다.\n후기: 융식된 개체와 친한 사람들의 기억이 더욱 감소하여 희미한 인상만 남다가 결국 완전히 망각됩니다.\n\n<Title:존재성 소멸>\n해체가 최종 단계에 도달하면, 융식된 개체의 존재와 그 흔적은 완전히 말소됩니다.\n그들이 세상에 존재했음을 증명할 수 있는 어떠한 것도 남지 않게 됩니다. 대부분의 사람들처럼."
  },
  CollectionHall_49751_Title = {Text = "해체"},
  CollectionHall_49752_Desc = {
    Text = "은심은 융식의 종점일 수 있다: 생명이 융식침식을 당한 후 확률적으로 석출되는 은색 물질이다. 이는 막대한 물리적 에너지를 포함하고 있을 뿐만 아니라 정신 차원과도 일정한 연관성을 가진다. 특정 상황에서는 이러한 연관성이 “정신 차원”에 영향을 미칠 수도 있다. 은심은 인류가 융식에 대항하는 핵심 중 하나이다. 하지만 형성 방식의 특수성 때문에 은심은 수량이 적고 가치 또한 매우 소중하다."
  },
  CollectionHall_49752_Title = {Text = "은심"},
  CollectionHall_49753_Desc = {
    Text = "<Title:개요>\n은핵을 활용하는 모든 기술을 통칭하여 은핵 과학기술이라 한다.\n세상의 대다수 사람들은 은핵의 존재를 알지 못하며, 오직 미사격 대학만이 은핵 과학기술을 보유하고 있다. 은핵 연구 및 응용 전공을 개설하여 은핵에 대한 연구와 개발을 지속하고 있다.\n《미스티아 협정》에 따라, 미사격 대학은 미스티아 협정 심사회에 은핵 과학기술을 제공하여 함께 융식에 대항하고 위기에 대응한다.\n\n<Title:깨어남체?>\n미사격 대학의 깨어남체 기술에서, 깨어남체의 형성은 은핵을 중심으로 이루어진다.\n깨어남체 형성은 《은핵 기술 지도 매뉴얼》에 기록되어 있지 않지만, 적지 않은 깨어남체들이 이렇게 자조하곤 한다:\n「이봐, 우리도 은핵 과학기술의 일종이잖아?」\n\n<Title:융식 관측 장비>\n안경, 마스크 등 다양한 형태가 있다. 은핵으로 제조되며, 착용자가 밀경을 관측하고 융식을 볼 수 있게 해준다.\n\n<Title:미사격 대학 통신기>\n가장 흔한 형태는 교휘 모양의 브로치이다. 핵심은 특수 처리된 은핵으로, 통신기는 서로 연결될 수 있을 뿐만 아니라 미사격 교내와의 초장거리 통신도 가능하다. 신호가 안정적이며, <Italic:일반적인 상황에서는> 자연 현상의 간섭을 받지 않는다.\n\n<Title:미사격 출입 증명서>\n은핵이 내장된 특수 증명서로, 증명서를 소지한 사람만이 미사격 대학의 안개 장벽에서 길을 잃지 않을 수 있다.\n증명서가 없는 사람은 대학 밖의 숲에서 끝없는 지각 장애에 빠져, 순찰 조사원의 퇴거 조치를 기다리게 될 뿐이다."
  },
  CollectionHall_49753_Title = {
    Text = "은심 테크"
  },
  CollectionHall_49754_Desc = {
    Text = "<Title:원리>\n은심에서 깨어남하거나 실타래험으로 변형되었거나 사고로 탄생했을 수 있습니다……\n그들은 고대적이면서도 새로운 존재들입니다. 고대적이라는 것은, 수세기 전의 파피루스에 마법사들이 깨어남체의 존재를 은밀히 기록해 두었기 때문입니다.\n그들이 새로운 이유는, 아직 완전히 이해하지 못한 상태에서도 세계를 구하는 여정에 함께해야 하기 때문입니다.\n그들에게 신뢰를 주되, 방비를 갖추지 않는 것은 금물입니다.\n\n<Title:특성>\n각각의 인격을 가진 깨어남체는 그들의 “생전” 기억을 유지하고 있지만, 특수 능력 때문에 인간형 무기로 취급받았습니다.\n세속 사회의 안정을 유지하기 위해, 각국에서는 깨어남체의 존재를 극도로 비밀로 유지하고 있습니다.\n현재, 《협정》은 오직 미사그 대학에서 깨어남시킨 깨어남체만을 인정하며, 미사그 대학 이외에서 깨어남시킨 깨어남체는 《협정》 위반으로 간주되어 공식적으로 기록되고 격리됩니다.\n\n<Title:영역>\n깨어남체의 능력은 다양하지만, 연구원들은 서로 다른 능력 사이에서 일정한 유사성을 발견할 수 있습니다.\n이러한 유사성을 바탕으로, 미사그 대학은 여러 개의 깨어남체 영역을 인위적으로 구분하였습니다.\n같은 영역 내의 깨어남체들은 서로 더 잘 협력할 수 있지만, 다른 영역 간에는 일정한 배척 현상이 있을 수 있으며, 카오스 영역만이 이러한 현상을 보이지 않습니다.\n영역 간 배척의 원인은 불명확하며, 미사그 대학 환경학과 교수 돌의 분석에 따르면, 일부 알려지지 않은 존재가 정신 차원에 미치는 영향과 관련이 있을 가능성이 있지만, 현재로서는 이를 증명할 증거가 없습니다."
  },
  CollectionHall_49754_Title = {
    Text = "깨어남체 인식 기초"
  },
  CollectionHall_49755_Desc = {
    Text = "<Title:개요>\n은심을 유일한 원료로 하는 열쇠 형태의 아이템입니다. 사용자의 정신을 집중시키고 확대하며, 정신 차원과 연결하고 영향을 미치는 능력을 지니고 있습니다.\n은열쇠는 미사그 조사원과 수호자의 신분 상징으로, 각 은열쇠에는 고유한 번호가 부여되어 있습니다. 일반 조사원의 은열쇠 번호는 I로 시작하고, 수호자의 번호는 K로 시작합니다.\n조사원이 특정 이유로 외근 임무를 계속 수행할 수 없게 되면, 미사그 교육 기관에서는 해당 조사원이 소지한 은열쇠를 회수하여 이후 다른 조사원에게 재배포합니다.\n하지만 아쉽게도 회수 기록에 따르면, 지난 100년 동안 정상적으로 작동하는 은열쇠는 10개도 채 회수되지 않았습니다. 대부분의 은열쇠는 주인과 함께 파괴되었습니다.\n\n<Title:제작 및 획득>\n■■기밀 문서 제■■■호\n은■■열쇠의 제작은 블랙풀에서 ■■■■■에 의해 이루어져야 합니다.\n성형된 후에는 번호가 새겨지고, 요총 의식에서 적합한 사용자에게 부여됩니다."
  },
  CollectionHall_49755_Title = {Text = "은열쇠"},
  CollectionHall_49756_Desc = {
    Text = "<Title:개요>\n밀경은 현실타래 세계와 정신 차원이 함께 만들어낸 특수한 영역입니다.\n미사그 대학의 필립스 씨는 노트에 이렇게 적었습니다: 세상의 모든 비정상적인 현상은 인간의 마음에서 비롯되거나, 밀경에서 탄생됩니다.\n여기서 생명과 죽음, 현실타래과 환영이 얽혀 있으며, 진실타래을 배척하고, 진실타래을 숨깁니다.\n\n<Title:정의와 특성>\n밀경은 인간이 육체로 들어갈 수 있는 가장 가까운 정신 차원의 공간이지만, 여전히 그에 대해 잘 알려져 있지 않습니다. 정신 차원과의 융합 현상인 융식에 대해서도 마찬가지입니다.\n하지만 확실타래한 것은, 융식 현상이 심각할수록 밀경 차원의 범위가 더 넓어진다는 것입니다.\n\n<Title:밀경 속의 사물>\n밀경은 매우 취약한 경계 지역으로, 쉽게 영향을 받습니다.\n밀경에서 나타나는 특수한 존재들, 예를 들어 환영, 융흔, 안개 등은 감정과 사고의 투사로 여겨집니다. 이러한 특수한 투사 메커니즘을 통해 미사그는 밀경에서 일부 연락점을 투사하여 조사원의 정신을 안정시키고, 깨어남체의 상처를 치유할 수 있습니다.\n하지만 현실타래에 실타래제로 존재하는 사물, 예를 들어 지면, 건물 등은 밀경에서 일반적으로 영향을 받지 않습니다. (걱정하지 마세요, 밀경의 도로는 <Italic:대부분의 시간> 동안 안전합니다.)"
  },
  CollectionHall_49756_Title = {Text = "밀경"},
  CollectionHall_49757_Desc = {
    Text = "<Title:설립일>\n홍적기 이전\n\n<Title:설립자>\n불명\n\n<Title:개요>\n판라우라시아 대륙에서 가장 널리 퍼진 종교로 알려져 있습니다.\n신도가 많고 규모가 크며, 매년 특정 시기에 각지에서 축제가 개최됩니다. 그 중 가장 널리 알려진 것이 은상야와 동두절입니다.\n조직 내의 성직자들은 자신을 “부신의 대행자”라고 칭하며, 부신의 뜻을 실타래천하는 자들로서 세상의 고통을 제거하는 것을 미션으로 삼습니다.\n사람이 죽으면 부신의 품으로 회귀하여 영원히 낙토에서 안식하며, 세상의 고통에서 벗어날 수 있다고 믿습니다.\n이처럼 보편적인 교리 덕분에 이 종교는 당연히 인기 있는 종교가 되었습니다."
  },
  CollectionHall_49757_LockTip = {
    Text = "통관 특수 미션 기록「혈액의 색깔: 후회」해금"
  },
  CollectionHall_49757_Title = {
    Text = "생명의 교단"
  },
  CollectionHall_49758_Desc = {
    Text = "<Title:설립일>\n홍적기 이전\n\n<Title:설립자>\n미리암\n\n<Title:개요>\n옛 대륙에서 유래된 고대 조직입니다.\n회원들은 주로 상반신이 물고기, 하반신이 사람인 특징을 나타내며, 주로 바다와 연안 지역에서 활동하고 육지 깊숙이 진입한 적은 없습니다.\n그들이 바다를 건넌 것은 왕의 발자취를 따르기 위해서라고 합니다. 그들이 바다를 통해 온 것은 왕의 나라를 가져오기 위해서였습니다.\n모든 희생은 그 잃어버린 나라 리모리아와 그곳의 피곤한 왕을 위해 이루어졌습니다."
  },
  CollectionHall_49758_LockTip = {
    Text = "조사 작전 제5장 「스톰아이즈」 완료 시 해제"
  },
  CollectionHall_49758_Title = {Text = "도해자"},
  CollectionHall_49759_Desc = {
    Text = "<Title:설립일>\n홍적재변 시기\n\n<Title:설립자>\n불명\n\n<Title:개요>\n은밀한 종교 조직입니다.\n융식을 신의 선물로, 은심을 신의 몸으로 보며, 융식이 죄악을 정화하고 인간을 무죄의 청정한 땅으로 인도한다고 믿습니다.\n인원이 많지만 행방이 은밀하며，융식이 있는 곳에서는 항상 그들의 모습을 암시적으로 볼 수 있습니다.\n고대의 명문가에서 유래했다고 전해지며, 그 가족 구성원들이 집단으로 사라진 이유는 아직 역사학자들 사이에서 논쟁의 대상입니다."
  },
  CollectionHall_49759_LockTip = {
    Text = "조사 작전 제4장 「무성한 곳에서」 완료 시 해제"
  },
  CollectionHall_49759_Title = {
    Text = "등불 교회"
  },
  CollectionHall_49760_Desc = {
    Text = "<Title:영성 지수>\n은 은핵에서 정신 파편의 안정성을 측정하는 수치입니다.\n영성 지수가 높은 깨어남체는 정신 파편의 안정성이 강하고, 광기의 정도가 낮아 제어 불능 현상이 덜 발생하며, 제어 불능 상태가 되더라도 가능한 피해가 더 적습니다.\n각각의 깨어남체는 영성 지수가 다르며, 일부 깨어남체는 개인적인 상황에 따라 영성 지수가 변동되거나 정확히 측정되지 않는 현상이 나타날 수 있습니다.\n\n<Title:깨어남체 제어 불능>\n은핵은 깨어남체들에게 세상에 존재하지 않아야 할 힘을 제공하지만, 동시에 그들에게 광기의 씨앗을 심어두었습니다.\n깨어남체들은 창조될 때 대부분 통제 불가능한 광기 상태에 있었으며, 조사원의 즉시 링크 없이는 그들이 세계에 엄청난 파괴를 초래할 것입니다. 따라서 링크는 '증폭기'일 뿐 아니라 필수적인 '안정기'입니다.\n미사그 대학의 아카이브 기록에 따르면, 현재 학내에서는 돌·@2가 깨어남체 초기에 이성을 유지했습니다.\n또한, “문 안의 존재” 타비와 초대 수호자 알리스타가 L-01번 융식 균열 아래 거대한 은핵의 안정을 유지했기 때문에 미사그 대학 내에서 깨어남체들은 오랜 시간 동안 이성을 유지할 수 있었습니다. 링크가 끊어져도 제어 불능 상태에 빠지지 않습니다.\n\n<Title:깨어남체 사망>\n깨어남체는 신체 기능 면에서 인간보다 훨씬 강하지만, 이형체, 재앙, 융식 균열 및 융식 자체로부터의 위협에 직면하면 여전히 손상을 입을 수 있으며, 그들의 신체가 파괴될 가능성이 있습니다.\n연구원들은 깨어남체의 신체가 파괴된 후, 은핵 내의 의식이 정신 차원으로 돌아가 재깨어남을 기다릴 것으로 믿습니다.\n은핵의 손상은 진정한 “사망”을 의미할 수 있습니다.\n\n<Title:재깨어남>\n재깨어남 후, 깨어남체의 외모, 성격, 취향, 능력은 일반적으로 변하지 않으며, 기억도 보존됩니다. 그러나 일부 깨어남체는 그것이 현재의 자신과 독립된 개체라고 생각하며, 미사그 대학은 이러한 소리에 대해 보존 태도를 취하고 있습니다."
  },
  CollectionHall_49760_Title = {
    Text = "깨어남체 인식 업그레이드"
  },
  CollectionHall_49761_Desc = {
    Text = "<Title:개요>\n일부 깨어남체는 능력과 외형의 변이 특성이 매우 일관되게 나타났습니다. 연구원들은 이로 인해 깨어남 과정에서 어떤 미지의 존재가 (일부 사람들은 오염이라고 생각합니다) 이 깨어남체들의 정신에 영향을 주고 강력한 힘을 부여했음을 추측했습니다.\n현재, 연구원들은 이러한 깨어남체를 영향받은 힘을 “본원”이라고 부르고 있습니다.\n\n<Title:본원 깨어남체>\n본원 깨어남체는 동명의 깨어남체의 \"다른 자신\"입니다.\n그들은 유사한 특성을 가지고 있지만, 인생 경험이나 성격, 취미, 행동, 심지어 힘까지도 본원의 특징을 더 많이 띠고 있을 수 있습니다.\n본원 깨어남체에 대한 기록은 매우 제한적이고, 미사그는 이러한 현상의 원인에 대해 거의 알려진 것이 없습니다. 일부 연구원들은 본원 깨어남체의 출현을 바탕으로 \"평행 세계\"의 존재 이론을 추측하고 발전시켰지만, 이 이론은 아직 공개되지 않았으며 추가 연구가 진행 중입니다."
  },
  CollectionHall_49761_Title = {Text = "본원"},
  CollectionHall_49762_Desc = {
    Text = "<Title:코어>\n깨어남체의 핵심은 은심입니다. 심지어 육체가 완전히 해체되더라도 은심이 남아 있다면, 해당 깨어남체를 두 번째로 깨어남시킬 수 있습니다.\n\n<Title:육체>\n깨어남체의 육체는 다양한 재료로 구성될 수 있으며, 구체적인 구성 재료와 구조는 깨어남체 자체의 선호도와 특성에 따라 다릅니다.\n깨어남체의 육체는 미사그 대학의 직원들이 사전에 제공하지 않고, 깨어남 의식에서 은심 내부의 정신 에너지가 용해되어 형성됩니다. 따라서 깨어남 의식에서는 필요한 은심과 은 열쇠 외에도, 깨어남체가 육체를 합성하기 위해 많은 양의 재료를 준비해야 합니다. 자세한 재료 목록은 제3호 부록을 참조하세요.\n또는，미사그 대학에는 깨어남체의 육체 손상을 관리하는 프로페셔널한 부서와 연구원들이 있습니다."
  },
  CollectionHall_49762_Title = {
    Text = "깨어남체 구성"
  },
  CollectionHall_49763_Desc = {
    Text = "<Title:일상>\n깨어남체는 미사그 대학 내에서 교직원과 동등한 권리와 혜택을 누립니다. 그들은 학내 시설을 이용하고 조사 보상을 받을 수 있는 권리를 가지고 있습니다.\n파트너 조사원이 외근 임무가 없는 경우, 깨어남체들은 캠퍼스 내에서 자유롭게 활동할 수 있습니다. 대부분의 깨어남체들은 생전의 취미와 습관을 따르며 자신이 하고 싶은 일을 찾습니다. 일부 깨어남체들은 강의실타래로 들어가 이 시대를 이해하거나 조사원들과 친구를 사귀는 것을 선택하기도 합니다.\n특수한 상황을 제외하고, 깨어남체는 원칙적으로 음식을 먹거나 잠을 자지 않아도 됩니다. 하지만 깨어남체가 이러한 일을 하고 싶다면, 어떠한 부정적인 영향도 주지 않습니다.\n\n<Title:작전>\n전투 지휘와 링크 유지에 필요한 에너지를 균형 있게 분배하기 위해, 미사그 대학은 “영지 전송기”라는 특수 장비를 개발했습니다.\n외근용 가방에 내장된 “영지 전송기”는 깨어남체의 능력을 카드 형태로 전송하여, 깨어남체를 지휘할 수 있도록 합니다."
  },
  CollectionHall_49763_Title = {
    Text = "깨어남체 행동"
  },
  CollectionHall_49764_Desc = {
    Text = "<Title:설립일>\nA.F.306\n\n<Title:설립자>\n헤버트 로젠탈\n\n<Title:개요>\n급진적인 민간 연구 조직.\n인류를 재앙 세계에서 생존하기 위해 융식 산물과 결합하는 방식으로 진화를 추구.\n20여 명의 급진적 구성원들로 이루어져 있으며, 무고한 사람들을 실타래험 소재로 간주하며 수단이 매우 잔인함.\n설립자는 미사그 대학의 악명 높은 배신자 헤버트 로젠탈로, 등불 교회와 긴밀한 협력 관계를 맺고 있음.\n조직의 상징은 조각용 평평한 머리의 정으로. 이는 조각상에 반한 키프로스 왕에게 경의를 표하기 위한 것이라고 전해짐."
  },
  CollectionHall_49764_LockTip = {
    Text = "조사 작전 제3장 「맹견 주의」 완료 시 해제"
  },
  CollectionHall_49764_Title = {
    Text = "조각가 협회"
  },
  CollectionHall_49765_Desc = {
    Text = "<Title:개요>\n미사그 대학에서 특수 프로세스를 통해 선별 및 양성된 전문 인력으로, 강력한 정신력을 가지고 있으며, 연결된 깨어남체가 가져오는 소모를 견디고 정신 명령을 내릴 수 있습니다.\n그들은 융식에 직면하여 인간의 존속을 위해 싸우지만, 알려지지 않습니다. 융식에 죽은 조사원은 이름과 기록조차 완전히 남기지 못합니다.\n그들의 이름은 알려지지 않았지만, 그들의 공적은 영원히 기억되기를 바랍니다.\n\n<Title:선별>\n조사원의 정신 구조와 잠재력에 관한 이론적 기반을 바탕으로, 미사그는 개인과 은열쇠 사이의 정신 공명 강도를 관찰하여 강력한 정신력을 가진 개인을 선별하여 양성합니다.\n\n<Title:양성>\n선별 후, 조사원은 먼저 1년 동안 예과 과정을 거칩니다.\n교육 내용은 융식 기초 이론, 은심 기술 입문, 깨어남체 이론 등 기초 과목과 기본 체력, 깨어남체 연결, 깨어남체 지휘 등 전투 관련 훈련을 포함합니다.\n\n<Title:요총 의식>\n1년간의 학습과 시험을 통과한 후, 조사원들은 학교 창립 기념일에 열리는 요총 의식에 참석합니다.\n의식에서 조사원들은 서약을 낭독하고 자신의 이름을 비석에 새깁니다.\n그 후, 각 조사원에게 고유한 번호가 부여된 은열쇠가 주어지며, 그 시작 글자는 모두 \"I\"입니다.\n이제 그들은 평범한 자신과 작별을 고합니다. 그들이 죽은 후, 이 비석은 그들이 존재했음을 증명하는 물건이 됩니다.\n\n<Title:퇴임>\n조사원이 여러 이유로 외근 임무를 수행할 수 없는 경우, 미사그는 이를 존중하며, 물자부, 정보지원부 등 더 안전한 부서로 이동시킵니다.\n그럼에도 불구하고, 퇴임한 조사원들은 종종 신체적, 정신적 고통에 시달립니다.\n세상을 진실타래의 한 부분을 엿본 사람들에게, 여생을 평온하게 보내는 것은 사치스러운 환상입니다."
  },
  CollectionHall_49765_Title = {Text = "조사원"},
  CollectionHall_49766_Desc = {
    Text = "<Title:개요>\n조사원 중 특별한 개인으로, 일반 조사원보다 더 강력한 정신력을 갖추고 있습니다.\n조사원보다 높은 권한을 가지고 있어 더 깊은 비밀에 접근할 수 있으며, 그들이 맡는 미션은 종종 가장 복잡하고 어려운 것입니다.\n이 긴 융식과의 전쟁에서 그들은 모든 인간 앞에 서 있습니다.\n\n<Title:선발>\n일반적으로 미사그가 조사원 선발 과정에서 특별한 개인을 선택합니다.\n은열쇠에 대한 반응이 특히 강한 개인을 발견할 때, 선발 인원은 《보안인의 정신 구성 및 잠재력》의 설명과 항목을 참조하여 일정 기간 동안 관찰한 후, 해당 개인이 보안인으로 양성될 수 있는지 평가합니다.\n\n<Title:양성>\n기본적인 이론 교육과 전투 훈련 외에도, 보안인은 추가적인 정신력 훈련을 받습니다.\n그들은 다른 조사원들보다 더 일찍 깨어남체와 접촉하고 외근 임무를 수행하여 자신의 능력을 다듬습니다.\n\n<Title:요총 의식>\n평가를 통과한 보안인은 일반 조사원들과 함께 요총 의식에 참여하여 자신의 은열쇠를 획득합니다.\n조사원과 달리, 보안인의 은열쇠 번호는 「K」로 시작합니다.\n이제 은열쇠는 보안인의 신분을 나타내며, 이후의 외근 임무에 큰 도움이 됩니다.\n\n<Title:보안인과 깨어남체>\n보안인은 깨어남체의 힘을 빌려 융식과 맞서 싸울 수 있습니다. 따라서, 깨어남체를 지휘하는 능력은 매우 중요합니다.\n그들은 예비 과정에서 엄격한 지휘 전투 훈련을 받으며, 요총 의식 후에는 교사의 감독 하에 파트너가 된 깨어남체와 함께 외근 임무를 수행하여, 향후 독립적으로 외근 임무를 수행할 수 있는 능력을 확보합니다.\n\n<Title:퇴임>\n보안인이 여러 이유로 외근 임무를 수행할 수 없는 경우, 미사그는 이를 존중하며 물자부, 정보지원부 등 안전한 부서로 이동시킵니다.\n보안인은 열쇠를 반납하고, 기록을 봉인하며, 비밀유지 협약을 체결하여 퇴임할 수 있지만, 지금까지 그렇게 하는 사람은 거의 없습니다."
  },
  CollectionHall_49766_Title = {Text = "수호자"},
  CollectionHall_49767_Desc = {
    Text = "<Title:깨어남체 링크>\n깨어남체는 성형 과정에서 미지의 오염을 받기 쉽고, 이로 인해 쉽게 광기에 빠질 수 있으므로 조사원이 정신적 링크를 통해 마음을 안정시키는 것이 필요합니다. 대부분의 조사원에게는 깨어남체와의 링크를 위해 은열쇠의 힘을 빌려야 합니다.\n은열쇠는 소유자의 정신력을 강화하여 깨어남체와 장시간 링크를 유지하고, 깨어남체를 지휘하여 전투를 수행하며, 소유자에게 정신력 보조를 제공할 수 있습니다. 또한, 소유자는 은열쇠를 통해 깨어남체에게 일정한 도움을 줄 수도 있습니다.\n이론적으로, 소유자의 정신력이 강할수록 연결할 수 있는 깨어남체의 수가 많아집니다. 하지만 지금까지 여러 깨어남체와 링크하는 데 따른 정신적 부담을 견딜 수 있는 사람은 단 한 명뿐입니다.\n\n<Title:깨어남 의식>\n은열쇠를 사용하여 주관하는 깨어남 의식은 모든 조사원이 반드시 배워야 하는 과정입니다.\n깨어남 의식 중, 은열쇠는 사용자와 대상 은핵 사이의 감각을 확대하여 은핵의 성형을 강화하고, 결국 특별한 능력을 가진 깨어남체로 만들 수 있습니다.\n\n<Title:정신 추적 및 위치 파악>\n깨어남체와 분리되었을 때, 소유자는 은열쇠를 사용하여 “정신 추적”을 통해 깨어남체의 특성을 가진 정신을 대략적으로 위치 파악할 수 있습니다.\n하지만 이는 찾은 모든 정신이 당신의 친구라는 의미는 아닙니다. 따라서 “정신 추적”을 할 때는 반드시 차분하게 유지해야 합니다.\n\n<Title:균열 폐쇄>\n소유자는 은열쇠를 사용하여 융식 균열을 폐쇄할 수 있습니다. 자세한 내용은 융식 균열 - 대응 방식을 참조하세요."
  },
  CollectionHall_49767_Title = {
    Text = "은열쇠 사용"
  },
  CollectionHall_49768_Desc = {
    Text = "<Title:개요>\n각 수호자는 조금씩 다른 특수 능력을 지니고 있다.\n미사그 기록에 따르면, 현재까지 알려진 수호자의 능력으로는 기억 읽기, 감정 공유, 심리 감지 등이 있다.\n\n<Title:초대 수호자>\n초대 수호자는 알리스타이어 오웬이다.\n대부분에게 그는 역사의 틈새에서 발견되는 희미한 흔적으로만 존재하며, 극소수만이 그가 여전히 미사그 지하에서 맡은 미션을 수행 중임을 알고 있다.\n직립 보행이 불가능하다고 전해지는데, 이는 미사그를 위해 치른 “필요한 희생”이라고 한다.\n미사그에서 가장 효율적인 도구인 그의 위장은 이미 완전히 절제되었으며, 먹고 마실타래 필요가 없어 큰 비용을 절감했다.\n\n<Title:새로운 수호자>\n새로운 수호자가 가진 능력은 단연 독보적이다.\nTA는 특정 물건, 감정, 또는 회상을 통해 깨달음을 얻고, 이를 통해 은열쇠가 새로운 힘을 발휘하도록 자극할 수 있다. 이는 전문 학자들과 역사가들의 인식을 거의 뒤집었다.\n모든 사람이 알고 있는 사실타래은, 이 수호자가 반드시 새로운 폭풍을 일으킬 것이라는 점이다.\n문제는, 이 폭풍이 그들을 어디로 이끌지 모른다."
  },
