  CollectionHall_50271_Title = {
    Text = "라이 마을"
  },
  CollectionHall_51019_Desc = {
    Text = "<Title:설립일>\n홍적기 이전\n\n<Title:설립자>\n불명\n\n<Title:개요>\n아시리아 제국에서 분리된 유목민족입니다.\n렘바히 사막의 연중 내내 격렬한 폭풍 속에 숨어 살며, 생활이 매우 원시적이며 외부와의 교류가 거의 없습니다. 아란인들은 “풍성한 모나무”를 신봉하며, 풍성한 모나무와 성하의 물로 인해 종족 규모를 유지합니다.\n‘레무바시 작전’ 이후, 아란족은 소식이 끊겼습니다."
  },
  CollectionHall_51019_LockTip = {
    Text = "조사 작전 제7장 「욕하」 완료 시 해제"
  },
  CollectionHall_51019_Title = {Text = "아란족"},
  CollectionHall_51038_Title = {Text = "07 욕하"},
  CollectionHall_51373_Title = {Text = "미지"},
  CollectionHall_51374_Desc = {
    Text = "<Title:요약>\n미사그 대학 교수, 사회 활동가, 귀족.\n과거에는 금을 흙처럼 쓰는 화려한 플레이보이였으며, 약간의 해롭지 않은 범죄를 저질러 범죄와 법 집행 기관 모두에서 명성을 얻었다.\n그 후 가문이 사교 집단에 의해 몰살당해 유일한 생존자가 되었다. 그 이후의 일은 본인만이 말할 수 있다.\n라몬나의 양부이지만, 라몬나의 출생에 대해서는 입을 굳게 다물고 있다.\n젊었을 때 모든 과목에서 불합격했으나, 나중에 미사그 대학의 교수로 변신했다.\n성격이 자유분방하고 풍류를 즐기지만, 어떤 여성이나 남성과도 스캔들이 전해진 적이 없다.\n결국 모순으로 가득 찬 인물이다."
  },
  CollectionHall_51374_LockTip = {
    Text = "클리어 프롤로그 해금"
  },
  CollectionHall_51374_Title = {Text = "덱스터"},
  CollectionHall_51375_Desc = {
    Text = "<Title:요약>\n덕스터의 양녀로, 주인공이 가장 신뢰하는 조사 파트너입니다.\n어릴 때부터 학교의 여러 학과 강의실타래을 드나들며, 융식 현상, 깨어남체 등에 대한 지식을 상당히 많이 알고 있습니다.\n\n아직 어렸을 때, 라몬나도 “친생부모”를 동경한 적이 있었지만, 덕스터와 선생님들의 돌봄과 사랑으로, 이미 학교를 진정한 집으로 여기고 있습니다.\n\n차가우면서도 이성적이고 적절한 선에서 선한 마음을 가진 그녀는 어떤 “기괴함”도 없습니다. 미사그의 이 괴인들의 대비 아래, 그녀의 “정상”이 오히려 더 돋보이게 됩니다.\n비록 항상 표정이 굳어있지만, 익숙한 사람들은 이것이 단지 “천재”의 피로일 뿐이라는 것을 압니다."
  },
  CollectionHall_51375_LockTip = {
    Text = "“라몬나” 깨어남 후 해금"
  },
