  CollectionHall_51603_Desc = {
    Text = "우아하고 신비로운 검은색 짧은 털 고양이, 어떤 먼 사막 국가에서 신의 화신으로 여겨졌다고 전해진다. 하지만 그 신의 이름은 이제 아무도 모른다. \n숭배받고, 존경받고, 잊혀지는 것이 신의 숙명일지도 모른다."
