  },
  CollectionHall_56369_Title = {
    Text = "시중세계"
  },
  CollectionHall_57597_Desc = {
    Text = "<Title:요약>\n렌티니언 대교구의 현 주교이며, 전대 주교가 우연히 깨운 깨어남체입니다.\n창조부신의 열렬한 신자로, 부신의 가르침을 삶으로 실타래천하며, 인애와 관용의 마음으로 세상의 모든 것을 대합니다. 민중 사이에서 높은 명성을 누리고 있으며, 일부 신자들은 그를 \"렌티니언의 성인\"이라고 부릅니다.\n비극적으로도, 이 모든 만물에 대한 연민과 동정이 그의 인간으로서의 생명을 앗아갔습니다.\n생전에는 융식을 치료하려고 노력했으며, 이를 위해 생명석판에 자신의 살과 피를 바쳤습니다. 이는 교구 내의 \"환자\"들에게 고통을 완화하고 생명을 연장시키기 위한 것이었습니다. 그가 죽은 후, 석판은 행방불명되었으나, 그가 깨어남체로 다시 깨어났을 때 나타났습니다.\n수건과 밴드로 감긴 눈은 영혼의 빛을 볼 수 있어, 그는 비밀지킴이를 만난 후 바로 확신했습니다. 비밀지킴이가 부신의 예언에 등장하는 창백한 사자라는 것을, 그리고 이 어두워질 운명의 세계를 구원할 수 있다는 것을."
  },
  CollectionHall_57597_LockTip = {
    Text = "통관 특수 미션 기록 “혈액의 색깔” 해금"
  },
  CollectionHall_57597_Title = {
    Text = "살바도르"
  },
  CollectionHall_57598_Desc = {
    Text = "<Title:요약>\n사전 문명 리모리아에서 가장 어린 유왕입니다.\n어릴 때부터 특출난 재능을 지녔으나, 하루에 20시간 이상을 잠으로 보내며 깨어 있을 때에도 항상 피곤한 모습이었습니다.\n가끔씩 신들의 감정을 느끼고, 다양한 시공간의 잔편을 꿈꾸며 숭배받고 두려움의 대상이 되었으며 왕으로 추앙받았습니다.\n하지만 어린 왕은 이러한 것들에 관심이 없었습니다. 그는 신의 계시와 예언을 소극적으로 회피했습니다.\n결국 리모리아의 파괴라는 숙명을 예견했지만 이를 어떻게 바꿀지 몰랐기에 침묵을 유지할 수밖에 없었습니다.\n재앙이 강림한 날, 사람들은 절망에 빠졌습니다. 신민들의 기대에 부응하기 위해 그는 거짓된 예언을 만들어냈습니다.\n불멸의 왕과 그가 다시 세상에 내려온다는 예언이었습니다.\n결국, 옛 세계는 홍수로 인해 잠겼고, 세월이 흘러 새로운 인간들이 대지에서 번식하며 사전의 일은 더 이상 아무도 알지 못하게 되었습니다.\n아마 그는 자신의 무심코 한 예언이 후세에 의해 계속 파생될 줄은 몰랐을 것입니다.\n그는 결국 믿음의 힘을 과소 평가했던 것입니다."
  },
  CollectionHall_57598_LockTip = {
    Text = "“투루” 깨어남 후 해금"
  },
  CollectionHall_57598_Title = {Text = "툴루"},
  CollectionHall_57599_Desc = {
    Text = "<Title:요약>\n아란족의 이방인 사자, 꿈의 계시를 따라 레무바시로 왔다고 주장한다.\n아란족의 팀을 이끌고 스톰월드 밖에서 오랫동안 머물며, 아란족의 성스러운 나무 — 풍성한 모나무를 부활시킬 가능성을 찾고 있다.\n실타래제로는 등불 교회에 소속되어 있다. 그녀의 영원한 자비로운 미소 뒤에 숨겨진 진실타래된 동기는 아직 아무도 알지 못하지만, 여정이 계속될 때 조금씩 드러날지도 모른다."
  },
  CollectionHall_57599_LockTip = {
    Text = "클리어 조사 작전 제7장 “욕하” 해금"
  },
  CollectionHall_57599_Title = {
    Text = "유리에트"
  },
  CollectionHall_57600_Desc = {
    Text = "<Title:소개>\n선사 문명 레무리아에서 살았으며, 가족 모두가 독실타래하게 신을 섬기는 수행자였다.\n어릴 때부터 부지런히 수행하여, 성장한 후 소원대로 수도의 신전에 들어가 사제가 되었다.\n그녀는 신의 기적을 갈망하고, 영적인 체험을 갈구했지만, 그것들은 결코 찾아오지 않았다.\n\n투루가 왕위에 오를 때, 그녀는 곁에서 모시는 대사제가 되었다.\n새로운 왕을 처음 만났을 때, 그녀는 극도의 황홀함과 기쁨을 느꼈고, 이것이야말로 자신이 갈망하던 신의 인간 세상의 화신임을 즉시 깨달았다.\n그렇다. 그녀가 존재하는 의미는 바로 이 어린 왕을 모시는 것이었다.\n\n홍수가 대륙과 레무리아의 문명을 바다 밑으로 가라앉힐 때까지, 그녀는 이 신념을 한 번도 흔들린 적이 없었다."
  },
  CollectionHall_57600_LockTip = {
    Text = "이몽시계 클리어 “모독” 해금"
  },
  CollectionHall_57600_Title = {Text = "미리암"},
  CollectionHall_57601_Desc = {
    Text = "<Title:소개>\n종자를 퍼뜨려 차원의 벽을 넘기 위해, 또한 「사랑」 때문에 종족의 번식 본능을 포기했다.\n우연히 이 우주로 흘러든 사야는, 성간을 횡단하던 틴크트에 의해 은핵에서 깨어나, 방향을 찾지 못한 채 황무한 행성에 머물렀다. 미사그의 수밀인과 만나기 전까지.\n탐구 속에서, 깊은 대화 속에서, 서로 닮지 않은 두 존재는 「사랑」의 정의에 대해 비슷한 답을 내렸다.\n기억은 어쩌면 흐릿해질지 모르지만, 한때 소중한 이와 맺은 인연은 다시 한번 그녀에게 앞길을 비춰줄 것이다.\n망각이 만연한 이 세계에서, 그녀는 사랑이라는 이름의 질병을 굳건히 지키고 있다."
  },
  CollectionHall_57601_LockTip = {
    Text = "「사야」 깨어남 후 해금"
  },
  CollectionHall_57601_Title = {Text = "사야"},
  CollectionHall_57602_Desc = {
    Text = "<Title:요약>\n고대 전설에 따르면, 세상에는 물의 깊은 심연과 에덴 동쪽에 각각 거주하는 두 마리의 거대한 짐승이 존재한다.\n이 두 거대한 짐승은 시간이 끝나야 만날 수 있으며, 그들은 생명의 어머니 티아마트에게 제물로 바쳐져 생명의 순환을 얻기 위해 희생된다.\n\n로탄은 전설 뒤에 숨겨진 ‘짐승’이다.\n그녀는 행성의 자연산물로, 전설과는 달리 그녀는 심연의 물이자 에덴의 영혼이다.\n그녀는 순수한 혼돈의 힘, 자유로운 영혼, 정의되지 않은 질서이다.\n파괴와 규칙은 세계가 그녀에게 부여한 권능으로, 이 두 가지 극단적으로 반대되는 본능이 로탄의 몸에서 충돌한다. 그녀는 자신을 찢어놓을 만큼 강력한 힘을 균형 있게 유지하기 위해 전투를 통해 파괴 욕망을 발산해야 한다.\n로탄은 행성이 부여한 역할인 역사 보호자의 미션를 맡고 있다. 그녀의 '일'은 행성의 의지에 따라 행성의 운명에 영향을 미치는 자들을 청소하고 처벌하는 것이지만, 그런 사람은 수천 년 동안 한 명도 나오지 않는다.\n무한한, 미션가 내려질 때까지의 지루함 속에서 로탄은 적의 등장에 대한 갈망을 느낀다.\n\n그래서 그녀는 젊은 왕자에게 시선을 돌렸고, 심지어 재앙을 불러일으키기도 했다.\n그러나 그 어떤 것도 그녀의 거세게 일렁이는 전투 의지를 해치지 못하며, 그것들은 그녀의 부활에 따라 더욱 강렬해진다."
  },
  CollectionHall_57602_LockTip = {
    Text = "“로탄” 깨어남 후 해금"
  },
  CollectionHall_57602_Title = {Text = "로탄"},
  CollectionHall_57603_Desc = {
    Text = "<Title:소개>\n장례 도시의 한때 왕세자였던 그는 이제는 신으로 숭배받는 식사 시체왕이다.\n그는 똑똑하고 공정한 청년이지만 독특한 식사「취향」— 시체 먹기로 인해 왕실타래의 경계에 처해 있다.\n아버지는 퇴위 전날 두레세인을 독살했다. 분해되고 포식되는 과정에서 그의 의식은 신전에서 숭배받는 그것과 융합되어 자신의 육체의 맛을 음미하게 되었고, 그 놀라운 단맛은 그를 괴롭히게 했다.\n그는 식사를 낭만적인 예술로 간주하며, 이는 단순한 입과 혀의 욕구를 충족시키는 것이 아니라 잊혀진 기념을 위해서이다.\n부식은 모든 것을 파괴하고 과거를 잊게 하지만 두레세인은 모든 생자의 전설과 평범함을 증언하며, 자신의 기억 속에 피와 육체를 보존하게 되며, 영원히 지속될 것이다."
  },
  CollectionHall_57603_LockTip = {
    Text = "깨어남 「두레사인」 후 해제"
  },
  CollectionHall_57603_Title = {
    Text = "도어세인"
  },
  CollectionHall_57604_Desc = {
    Text = "<Title:요약>\n한때 한 지역을 다스리던 저택의 영주였다.\n모성행성이 융식과 파괴로 사라진 후, 거대한 운석을 타고 캠브리안 계곡으로 추락했다.\n가축 관리, 토지 병합, 위험 자산 관리에 능숙하다.\n외출할 때마다 뒤에는 언제나 거대한 언데드 하인들이 따라다닌다.\n하나는 발판으로, 둘은 음유시인이 즐거움을 주고, 넷은 마부로…\n교황조차 자신의 단순한 행렬에 부끄러움을 느낄 것이다."
  },
  CollectionHall_57604_LockTip = {
    Text = "의식 잠수 클리어 “타오르는 군연” 해금"
  },
  CollectionHall_57604_Title = {Text = "완다"},
  CollectionHall_57605_Desc = {
    Text = "<Title:소개>\n틴크트가 깊이 사랑하는 쌍둥이 언니.\n부화 초기부터 남다른 「천부적 재능」을 보였으나, 통제할 수 없는 능력 탓에 피인트는 영원히 「포대기」 속에 웅크린 채 성장하지 못했다.\n종족에게 불행을 가져올 개체로 여겨져, 틴크트와 함께 원래의 생활 공간에서 쫓겨났다.\n\n동생은 상류층의 시혜에 의지해 생활에 필요한 양분을 마련했고, 대부분의 물자를 피인트를 부양하는 데 사용했다.\n어느 재난이 발생한 후, 단 한 장의 「티켓」을 벌어 피인트를 속여 황폐한 행성을 떠나는 여정에 태웠다.\n이륙하는 순간, 피인트는 처음이자 마지막 반항을 했다:\n포대기를 벗어나 모든 이의 생명 에너지를 흡수하는 것을 대가로, 틴크트에게 떠나라고 협박했다……\n자신이 「결함이 있는 존재」이기에 매우 자격지심이 강하다.\n\n한때 먹기를 거부하며, 하루빨리 굶어 죽어 틴크트의 짐이 되지 않기를 바랐다.\n오랜 세월이 지나면서 편식하는 나쁜 습관이 생겼다.\n\n어두운 구석을 좋아한다. 보통 지하실타래 같은 곳에 가야 피인트를 찾을 수 있다."
  },
  CollectionHall_57605_LockTip = {
    Text = "「파인트」깨어남 후 해금"
  },
  CollectionHall_57605_Title = {Text = "파인트"},
  CollectionHall_57606_Desc = {
    Text = "<Title:소개>\n케이티굴라는 사막 지역에서 태어난 고아로, 그녀가 소녀였을 적에 많은 동네 아이들을 수용했습니다.\n이 아이들을 이끌어 세상에서 생존하기 위해, 그녀는 악의 해침을 막기 위해 정교하게 만들어진 가면을 썼습니다.\n많은 이들에게 그녀는 잔혹함과 광기의 화신으로 여겨집니다.\n어떤 충돌이든, 그녀는 가장 미친 열정과 가장 잔혹한 수단으로 다가오는 적들에 응답할 것입니다.\n시간이 흐르면서, 심지어 지역의 아기들이 세상의 무한한 모래 바다 위에 호박색의 사신이 존재한다는 것을 인식하게 되었습니다.\nN과의 충돌 중, 그녀는 당연히 그 게임에서 패배하였고, 그로 인해 모든 것을 잃게 되었습니다.\n그러나 N도 모르고 있습니다, 그녀는 이미 별들 중 어느 존재의 주목을 받게 되었습니다.\n운명적인 죽음을 겪고 나서, 그녀는 그 힘과 그가 정한 사명을 물려받았습니다.\n그녀의 내부에는 별들 중의 존재가 내재하고 있으며, 그녀는 그들 중 하나가 될 수 있습니다.\n만약 그 마지막 시점의 도래가 막을 수 없다면, 그는 모든 것을 버리고 다시 하늘로 돌아가, 그 처음이자 마지막의 피난처가 될 것입니다."
  },
  CollectionHall_57606_LockTip = {
    Text = "통과 의식 잠수「불멸의 극주」 이후 해제"
  },
  CollectionHall_57606_Title = {
    Text = "카티구라"
  },
  CollectionHall_57607_Desc = {
    Text = "<Title:요약>\n멜트·도어는 원래 미사그와 인류 과학의 자랑이었다. 융식 현상과의 긴 대립 중에 그녀는 융식 현상이 몸을 해체하는 동시에 진리로 통하는 길을 열어놓았다는 것을 깨달았다.\n우연히 신비한 계시가 새겨진 고대 석판을 접한 후, 그녀는 이 어두운 무한한 길을 걷기로 결심하고, 인형 몸체를 교체하여 생명을 연장하는 것을 포기하고 융식이 뇌통을 침식하도록 내버려 두었다.\n결국 그녀는 소원대로 융식의 본질을 이해했지만, 완전히 파괴와 공허로 향하게 되었다.\n그녀의 믿음과 이성이 마치 등불과 같이 다른 사람들을 이끌던 것이 사라진 후, 멜트·도어는 학교 구성원들이 알지 못하는 곳에서 파괴의 길을 걷기 시작했고, 여러 사망 사건을 일으킨 후에야 미사그에 의해 발견되어 최고 수준의 감시와 억제를 받게 되었다.\n그러나 붕괴된 인형 뒤에는 천재의 불멸의 영혼이 여전히 세상 뒤에 더 깊고 더 어두운 곳과 멀리서 응답하고 있는 것 같다."
  },
  CollectionHall_57607_LockTip = {
    Text = "깨어남 “용해·도르” 이후 해금"
  },
  CollectionHall_57607_Title = {
    Text = "융해·돌"
  },
  CollectionHall_57608_Desc = {
    Text = "<Title:요약>\n출신이 낮았지만, 아름다움으로 인해 많은 인기를 얻어 상류층에서 겨우겨우 활동하던 가수였다.\n\n재앙이 발생했을 때, 약간의 동정과 은혜로 유일한 생존을 위한 “비행기 티켓”을 얻게 되었다.\n\n모든 사람이 그 명단이 당연히 자신에게 돌아가야 한다고 생각했지만, 그녀는 비밀리에 결심하여 언니 파인트를 안전하게 항로에 태우려고 했다.\n\n그러나 마지막 순간, 언니는 힘을 사용하여 위협하며 그녀를 좌석에 묶어 놓고 폐허의 별에서 멀리 보내버렸다.\n\n\n의외로 깨어난 후, 틴커트는 마음속으로 끝없는 죄책감을 느꼈고, 언니가 죽지 않았거나 어떤 형태로 자신과 같은 형태로 부활했을 것이라고 믿었다.\n\n그 이후로, 그녀는 언니의 행방을 찾기 위해 온갖 수단을 동원하며 최선을 다하고 있다."
  },
  CollectionHall_57608_LockTip = {
    Text = "“틴커트”를 깨어남 후 해금"
  },
  CollectionHall_57608_Title = {Text = "틴커트"},
  CollectionHall_57609_Desc = {
    Text = "<Title:요약>\n‘미사그의 뇌’라고 불리는 천재 학자, 미사그의 외근 자문관 중 한 명입니다.\n14세에 미사그에 입학하여 알리스타의 생존 장치를 개선한 적이 있습니다.\n외출 도중 융식에 감염되어, 80페이지에 달하는 깨어남 단계 설명을 작성한 후 평온하게 세상을 떠났습니다.\n죽은 후 동료들은 그녀의 설명에 따라 은심을 기계를 깨우는 기계에 넣어 ‘돌 깨어남체’를 만들었습니다.\n깨어남한 후 그녀는 평온하게 일어나 옷을 입고, 평온하게 연구실타래로 들어가서 생전에 남겨둔 연구를 계속했습니다.\n어허! 천재의 세계는 이렇게 지루하고 평범합니다."
  },
  CollectionHall_57609_LockTip = {
    Text = "“돌”을 깨어남한 후 해금"
  },
  CollectionHall_57609_Title = {Text = "돌"},
  CollectionHall_57610_Desc = {
    Text = "<Title:요약>\n융식에 의해 삼켜진 행성에서 도망쳐 온 외계 종족의 정신체가 최근 사망한 소녀의 몸을 차지하여 부모와 같은 운명을 피했습니다. \n하지만 오래가지 않았습니다. 이 인간의 육체에서 융식 증상이 나타나면서 그녀의 정신체도 융식에 의해 몸에 잠금되어 다시 도망칠 수 없게 되었습니다. \n융식 감염의 공포 속에서 정신적 붕괴를 겪으며 미사그에게 연락하여 자신을 깨어남체로 만들어달라고 요청하고, 자신의 종족의 지식과 기술을 대가로 제시했습니다. \n깨어남체가 된 후 학원에서 기계, 전기, 정신 관련 연구를 수행하였지만, 융식에 대한 극도의 공포로 인해 융식 연구는 할 수 없었고, 심리적 그림자로 인해 어둠을 무서워하며 잠을 자는 것을 두려워하여 매일 예민하고 신경질적인 상태로 살아가고 있습니다."
  },
  CollectionHall_57610_LockTip = {
    Text = "깨어남“벤코르”후 해금"
  },
  CollectionHall_57610_Title = {Text = "윙클"},
  CollectionHall_57611_Desc = {
    Text = "<Title:요약>\n정신계에서 탄생한 정신체는 넓고 아무것도 없는 회색 바다에서 외롭게 떠돌고 있었습니다. 가끔 찾아오는 정신 여행자와 함께 지구로 왔습니다. 다른 소원을 체험하며 그들의 머리를 베어 바다에 모으고, 그들의 지혜와 감정을 흡수했습니다.\n1600년 전에 깨어났으며, 깨어난 자의 머리를 베어 그녀의 몸에 붙였습니다. 정신력을 흡수하는 특성 때문에 여전히 머리를 수집하여 존재를 유지하며, 즐기기 위해 필요한 것보다 훨씬 많은 머리를 베어 모았습니다. 진정한 주인공을 만난 후 제압되어 거래를 맺고, 주인의 부하로 따라가서 그녀의 생명이 끝날 때까지 함께했습니다.\n주인과 진정한 우정을 맺은 괴물은 자신의 진정한 욕망을 깨닫고, 주인의 머리를 베어 그녀의 모습과 상점을 계승했습니다. 그 후로는 무작위로 머리를 베지 않고, 신비학 의뢰를 해결하여 머리를 교환하고, 손님들과 대화를 통해 주인을 잃은 외로움을 덜었습니다.\n현재의 소원은 상점과 주인이 사랑했던 도시를 지키는 것입니다."
  },
  CollectionHall_57611_LockTip = {
    Text = "통관 특수 미션 기록 「비 마을의 그림자」 해금"
  },
  CollectionHall_57611_Title = {Text = "다포딜"},
  CollectionHall_57612_Desc = {
    Text = "<Title:요약>\n살아생전에는 세계를 여행하는 마술사였습니다. \n커다란 서커스에서 자라며, 생활은 많은 “이상한 이들”로 가득 차 있었습니다. 도둑, 범죄자, 고아, 장애인, 기형아…… \n카시아 역시 “이상한 이”였습니다: 그녀는 감정을 느끼거나 스스로 감정을 표현할 수 없었습니다. \n그녀는 틀림없는 공연의 천재였으며, 항상 관객의 응원을 받았습니다. \n그 후 @2를 겪고 이단자의 피해자가 된 유령이 되었지만, 그녀는 여전히 살아있을 때와 같이 마술을 공연하며 관객을 ‘환상적인 세계’로 초대했습니다. \n기묘하게도, 모든 관객이 마술쇼를 본 후에는 ‘뭔가 부족하다’고 느꼈고, 삶은 점점 더 무미건조해졌습니다. \n그들은 혼란스러워하고, 무감각해지고, 심지어 자살하기도 했습니다. \n그리고 우리의 마술사 양반님은 막 뒤에 숨어서, 자신이 거둔 달콤한 ‘보상’을 즐겁게 섭취했습니다. \n화려한 공연은 비용이 많이 들지만, 그녀는 단지 지속 가능한 발전을 위해 그렇게 했습니다."
  },
  CollectionHall_57612_LockTip = {
    Text = "“카시아” 깨어남 후 해금"
  },
  CollectionHall_57612_Title = {Text = "카시아"},
  CollectionHall_57613_Desc = {
    Text = "<Title:소개> \n우연히 세계선 장벽을 넘어선 신비로운 개체, 또한 라모나의 또 다른 가능성. \n「그 사건」에서 비밀 지키는 사람의 안전을 위해 깨어남체의 힘이 신체를 제어하도록 내버려 두어야 했음. \n\n사건이 끝난 후, @2가 라모나에게 남긴 영향이 사라지지 않았음. \n@2의 의식이 그녀의 몸에 남아, 매일 의식의 존재 공간을 압박하고 있음. \n그래서 그녀는 끝없는 고통과 괴로움에 빠짐. \n\n남을 걱정하게 하고 싶지 않아서, 겉으로는 모든 게 괜찮은 것처럼 가장하며 \n자신의 머리카락과 생활을 단정하게 관리함. \n가끔 의식이 흐려져, 공허한 상태가 되기도 하며 \n심지어 다른 어조로 말하기도 함. \n이에 대해 걱정할 필요는 없음. 비록 출처가 다르지만, 행하는 모든 것은 비밀 지키는 사람과 이 세계의 평화를 위한 것임."
  },
  CollectionHall_57613_LockTip = {
    Text = "의식 잠수 클리어 “한 걸음 차이” 해금"
  },
  CollectionHall_57613_Title = {
    Text = "회귀·라모나"
  },
  CollectionHall_57614_Desc = {
    Text = "<Title:요약>\n그녀는 시와 장미의 나라에서 태어났습니다. 그녀는 시의 요정입니다.\n요정은 글로 짜여진 꿈 속을 떠돌며, 각 빛줄기의 피어남에 기쁨을 느끼고, 각 꽃의 시들음에 눈물을 흘립니다.\n그녀는 읊조리고, 슬퍼하며, 다른 영혼의 동반을 갈망합니다.\n\n그 후, 꽃이 만발한 정원에서 젊은 정원사가 그녀 앞에 장미 한 송이를 놓았습니다.\n그래서 그녀는 부끄러워하며 웃었고, 조용히 그 꽃을 받아들였습니다.\n“마침내 혼자가 아니게 되었어요.”\n그때의 그녀는 그렇게 굳게 믿었습니다."
  },
  CollectionHall_57614_LockTip = {
    Text = "통관 특수 미션 기록 “장미의 거처” 해금"
  },
  CollectionHall_57614_Title = {Text = "오를라"},
  CollectionHall_57615_Desc = {
    Text = "<Title:요약>\n원시 시대부터 이어져 온 아란족의 유일한 여왕. \n어린 시절 나무의 사자로 추앙받으며 왕의 명령을 전달했다. 첫 번째 저항 후 아란족의 신성한 강에 희생물로 던져졌지만, 나무의 의지를 깨우쳤다. \n그녀의 혈육에는 나무의 진액이 스며들었고, 나무의 뿌리에는 그녀의 피가 흐르고 있다. 그녀는 곧 풍성한 모나무이며, 풍성한 모나무는 곧 그녀이다. \n그러나 융식의 힘이 아란족의 혈통을 오염시키자, 그녀는 스스로 모나무를 대신해 오염을 받아들이며 아란족의 생존 가능성을 지켰다. \n오늘날 아란족이 역사의 긴 강물 속에서 소멸된 지금, 땅에서 솟아올랐다가 무너진 풍성한 모나무만이 그녀와 관련된 스토리를 증언하고 있다."
  },
  CollectionHall_57615_LockTip = {
    Text = "“테이스”를 깨어남하면 해금."
  },
  CollectionHall_57615_Title = {Text = "타이스"},
  CollectionHall_57616_Title = {Text = "별들"},
  CollectionHall_57617_Desc = {
    Text = "<Title:요약>\n미사그 대학의 심리교수로, 조사관들의 심리 상담을 담당하고 있습니다.\n온화하고 친절하여 학내에서 많은 사랑을 받고 있지만, 일부 미사그 구성원들은 그녀를 매우 두려워합니다.\n성분 불명의 홍차는 말할 것도 없고, 그녀가 웃지 않는 모습을 본 사람은 없기 때문에, 이 점만으로도 충분히 무서울 정도입니다."
  },
  CollectionHall_57617_LockTip = {
    Text = "클리어 프롤로그 해금"
  },
  CollectionHall_57617_Title = {
    Text = "실타래비아"
  },
  CollectionHall_57618_Title = {
    Text = "어리석은 자"
  },
  CollectionHall_57619_Title = {Text = "혼종"},
  CollectionHall_57620_LockTip = {
    Text = "「피크먼」을 깨어남한 후 잠금 해제"
  },
  CollectionHall_57620_Title = {Text = "이방인"},
  CollectionHall_57621_Desc = {
    Text = "<Title:요약>\n미사그의 베테랑 조사원으로, 수호자들로부터 \"선배\"라는 존칭을 받는 존재입니다.\n어떤 말할 수 없는 이유로 외출을 두려워했으며, 학교에서 공부하면서 정보팀원으로 겸임했습니다.\n친구가 죽은 후, 과거의 모습을 버리고 전선으로 투신하여, 사라진 친구를 기리는 방식으로 \"그가 한 일을 하기\"로 결심했습니다.\n파손된 은색 열쇠를 항상 휴대하며, 점점 사라져가는 기억들을 간신히 유지하고 있습니다."
  },
  CollectionHall_57621_LockTip = {
    Text = "클리어 프롤로그 해금"
  },
  CollectionHall_57621_Title = {Text = "윌리엄"},
  CollectionHall_57622_Desc = {
    Text = "<Title:요약>\n서대의 정원사, 오를라의 어린 시절 친구. \n오를라가 가장 무력할 때, 코레트는 정원 하나로 그녀에게 잊을 수 없는 행복한 시간을 선사했습니다. \n오를라의 재능이 뿌리를 내리고 자라는 순간, 코레트는 큰 불길로 그녀의 부, 명예, 그리고 생명을 앗아갔습니다. \n그녀는 헤버트와 협력하여, 오를라의 시집으로 시중세계를 창조했습니다. 아마도 추모하기 위해서일 수도 있고, 혹은 지배하기 위해서일 수도 있습니다. 아무도 모릅니다. \n코레트는 언제나 아름다운 시구들 속에서 그녀가 유일하게 이해한 것이 욕망뿐이라고 주장했습니다. \n그녀는 그것 때문에 고통받았습니다. 그녀는 그것을 자랑스러워했습니다."
  },
  CollectionHall_57622_LockTip = {
    Text = "통관 특수 미션 기록 “장미의 거처” 해금"
  },
  CollectionHall_57622_Title = {Text = "코레트"},
  CollectionHall_57623_Desc = {
    Text = "<Title:요약>\n미리암은 두 명의 데보라를 만난 적이 있다: 한 명은 리모리아의 사제이고, 다른 한 명은 오언 가문의 시녀였다. 한 명은 그녀의 친구였고, 다른 한 명도 그녀의 친구였다. \n만 년이 넘는 시간을 사이에 둔 두 시대, 서로 다른 두 사람, 같은 이름, 같은 모습, 같은 선함. 이는 드물고 신비로운 우연이며, 미리암에게는 신성한 예고였다. \n미리암은 두 명의 데보라의 최후를 증언했다: 한 명은 리모리아와 함께 바다 속으로 가라앉았으며, 다른 한 명은 그녀의 손에 의해 제단 위에서 배를 갈라 죽음을 맞았다. \n신국에 관한 이 거대한 서사에서, 데보라의 이야기는 단 두 줄의 짧고 붉은 주석에 불과하다."
  },
  CollectionHall_57623_LockTip = {
    Text = "이몽시계 클리어 “모독” 해금"
  },
  CollectionHall_57623_Title = {Text = "데보라"},
  CollectionHall_57624_Desc = {
    Text = "<Title:요약>\n미사그 대학의 첫 정보중개인, 학교 추리동아리 회원입니다.\n비교할 수 없는 정보 수집 및 발굴 능력을 가지고 있어 런디니움 전역에서 소문이 나 있습니다.\n원래 아그로 공화국 출신으로, 가족 사정으로 런디니움에 왔으며, 미사그의 비밀을 이용해 성공적으로 입학했습니다.\n그녀의 밝은 미소에 현혹되지 마세요—그녀는 미사그에 대해 일반 사람이 생각하는 것보다 훨씬 더 잘 알고 있습니다."
  },
  CollectionHall_57624_LockTip = {
    Text = "조사 작전 제1장 「동부 지구의 비밀」 완료 시 해제"
  },
  CollectionHall_57624_Title = {Text = "한나"},
  CollectionHall_57625_Desc = {
    Text = "<Title:요약>\n그린 재단의 전 연구원이자 라 이 요양원 원장.\n남편과 딸이 죽은 후, 그녀는 딸을 부활시킬 수 있는 방법을 찾아다녔다.\n긴 시간 동안의 탐색 과정에서 그녀는 딸의 모습을 잊어버렸고, 그녀를 지탱해왔던 사랑과 따뜻함도 잊어버렸다.\n그녀는 오직 고통만 기억하고 있다."
  },
  CollectionHall_57625_LockTip = {
    Text = "조사 작전 제4장 「무성한 곳에서」 완료 시 해제"
  },
  CollectionHall_57625_Title = {
    Text = "프랜시스"
  },
  CollectionHall_57626_Desc = {
    Text = "<Title:소개>\n소나니엘호의 선장.\n고향은 부식으로 인해 사람들의 기억에서 사라졌고, 오직 그만이 모든 것을 기억한다. 그 때문에 사람들은 그를 미치광이라 부른다.\n바닷가의 작은 마을, 가족, 형제... 그것들은 미치광이가 필사적으로 찾고 싶어하는 과거이다.\n그는 밀리암과 협약을 맺고 그녀가 필요한 물품을 운송하는 대가로 그녀는 그에게 오랜 시간 잠들어 있던 기억을 깨어남시키는 것을 돕기로 한다.\n그리고 그는 청풍과 흰 새들로 둘러싸인 소녀를 보았다.\n\n「이름은 실타래레스트, 당신이 나를 필요로 할 때 나는 여기 존재할 것입니다.」\n그녀는 한때 있던 고향의 흔적이며, 그가 어린 시절 노인에게 들었던 동화이다.\n\n알고 보니 그리워하던 과거가 실타래제로 존재했다."
  },
  CollectionHall_57626_LockTip = {
    Text = "조사 작전 제6장 「역전의 별들」 완료 시 해제"
  },
  CollectionHall_57626_Title = {Text = "엘튼"},
  CollectionHall_57627_Desc = {
    Text = "<Title:소개> \n신의 축복 대성당의 사무원, 주교 및 기타 성직자들이 성당의 일상 운영을 유지하도록 돕는 역할. \n아버지가 별세한 후 능력 있는 언니가 가업을 이어 받아 유명한 상인이 되었으며, 모든 것이 그렇게 순조롭게 느껴졌지만—그때 그 정교하게 계획된 사기 사건이 발생함. \n하룻밤 사이에 모녀 셋이 아무것도 잃게 되었음. 하지만 괜찮았고, 룬티니언의 주교가 그녀에게 손을 내밀었으며, 가족이 곁에 있다면 어떤 어려움도 두렵지 않았음. \n그리고 그녀의 언니가 죽어버렸음. \n어머니는 깊은 슬픔에 빠져 우울하게 세상을 떠났음. \n동시에 그녀의 조상 집을 점령한 망나니는 예술 샐롱을 열어 유흥을 즐기고 있었음. \n혼란, 분노, 이해할 수 없음… 수많은 감정이 그녀의 가슴 속에 눌려, 그녀를 재로 만들듯이 증오로 변형 되었음. 하지만 그녀는 그러면 안 됨, 주교가 말한 대로 과거에 얽매여서는 앞으로 나아갈 수 없으며, 오직 용서만이 구속을 해방할 수 있음. \n그녀는 할 수 없음. \n「자신을 억지로 참지 마세요,」 그를 자칭하는 등불 여인이 그녀의 귀에 부드럽게 속삭이며, 「용서는 방종입니다. 선인은 의로워야 하여야 하고, 악인은—악인들은 마땅히 마땅한 처벌을 받아야 합니다.」 \n그래서 그녀는 그의 손에서 거울을 가져와 판결 의식을 시작했음."
  },
  CollectionHall_57627_LockTip = {
    Text = "통관 특수 미션 기록 “혈액의 색깔” 해금"
  },
  CollectionHall_57627_Title = {Text = "소피아"},
  CollectionHall_57628_Desc = {
    Text = "<Title:소개>\n출신 불명의 노예로, 골리앗의 뒤를 이어 부족의 수장이 되었다.\n8살에 주인을 죽이고 나무통 속에 숨어 블레셋인의 섬까지 떠내려왔다.\n몸속에 비천한 혈통이 흐르며, 나약하고 비열하며 야심만만했다.\n수장이 된 지 한 달도 되지 않아 참수당했으며, 재위 기간은 역대 수장들과 비교해 13위에 해당한다.\n블레셋인의 수장은 편하게 은퇴할 수 있는 자리가 아니다."
  },
  CollectionHall_57628_LockTip = {
    Text = "의식 잠수 클리어 “거인의 몰락” 해금"
  },
  CollectionHall_57628_Title = {Text = "이글렌"},
  CollectionHall_57629_Desc = {
    Text = "<Title:요약>\n\n\n그녀는 영원한 왕국의 중계소였으며, 왕국과 외부 세계의 출입구를 지키고, 길을 잃은 신민들을 고향으로 안내하는 역할을 맡았습니다.\n왕국이 잠에 빠져 바다의 소용돌이 속으로 끊임없이 떨어질 때, 팔로스는 그녀의 고향과 링크가 끊어졌습니다.\n그녀는 왕도와 연락을 할 수 없었으며, 광활한 바다에서 어떤 흔적도 찾을 수 없었습니다.\n\n바다의 등대로서, 고향으로 돌아가는 길을 밝히지 못하는 것은 얼마나 아이러니한지 모릅니다.\n\n긴 시간 동안 고독하게 지내며 점차 미쳐가고 기능을 상실타래했으며, 이로 인해 역사상 여러 해양 재앙이 발생했습니다. 힘이 다해진 후에 어느 고대 영웅에게 토벌당했습니다.\n\n후일의 연구에서는 파로스의 광기가 대양주 침몰의 원인이었다는 학자들도 있었습니다.\n모든 것은 추측일 뿐입니다. 지금까지 이 열렬한 신도의 과거는 여전히 미스터리입니다."
  },
  CollectionHall_57629_LockTip = {
    Text = "“팔로스” 깨어남 후 해금"
  },
  CollectionHall_57629_Title = {Text = "파로스"},
  CollectionHall_57630_Desc = {
    Text = "<Title:요약>\n어느 공국의 소귀족 집안의 아들로, 귀족 출신이지만 아버지는 아무런 업적도 이루지 못했고, 미래는 평범한 미래로 가득 차 있었다.\n그러던 중 크리스마스 파티에서 아버지와 함께 대공을 알현하게 되었고, 파티에서 병든 동년배 공주를 돌보며 대공의 시선을 끌었다. 대공의 장난스러운 말에 따라 공국 기사 예비생이 되어 기사단의 훈련에 참여하기 시작했다.\n전화가 찾아오자, 공국의 약한 군대는 철기의 침략을 막지 못했고, 사망자가 속출하는 가운데 오지르는 마지막으로 공주를 지키는 \"기사\"가 되었다.\n그는 아직 너무 큰 창을 잡고, 공주의 문 앞에서 영원히 방패가 되었다."
  },
  CollectionHall_57630_LockTip = {
    Text = "의식 잠수 클리어 “기사의 소원” 해금"
  },
  CollectionHall_57630_Title = {Text = "오지에"},
  CollectionHall_57631_Desc = {
    Text = "<Title:요약>\n불꽃 속에서 춤추는 천재 무용수입니다.\n수백 년 동안 그녀의 가족은 궁중 무용수로 살아왔습니다. 따라서 왕국이 바뀌고 학교가 사라져도 그녀는 고상하고 아름다운 춤의 영혼을 잃지 않았습니다.\n18세 때 그녀는 현지 발레단에 합류하여 곧 당연히 수석이 되었습니다.\n\n그러나 초연 성공 후, 트루프 매니저는 \"소개\"라는 명목으로 리즈를 부자 상인의 방으로 보냈습니다.\n기실타래 발레는 이미 순수하지 않아졌고, 고상한 내면은 여자아이들이 자신의 가치를 높이는 자본이 되었습니다.\n그래서 그녀는 도망쳤다가 잡혀 돌아오고, 다시 도망치는 것을 반복했습니다. 결국 그녀의 \"고결함\"이 권력자들을 화나게 했습니다.\n그들은 리즈를 정신적, 육체적으로 괴롭혔습니다. 그녀는 멈출 수 없었고, 발끝이 찢어지고 검은 피가 바닥에 떨어져도 계속해서 돌고, 계속해서 뛰어야 했습니다.\n\n마침내 평범한 공연 중, 춤이 절정에 달했을 때, 불길이 그녀의 발바닥에서부터 번져 올랐습니다.\n그녀는 모든 부당함과 악을 불태울 것입니다."
  },
  CollectionHall_57631_LockTip = {
    Text = "“리즈” 깨어남 후 해금"
  },
  CollectionHall_57631_Title = {Text = "리즈"},
  CollectionHall_57632_Desc = {
    Text = "<Title:요약>\n노예로, 입양아로, 버림받은 자로… 이 이야기는 다른 세계선의 시로와 크게 다르지 않지만, 같은 피가 결국 다른 잔가지를 키웠다.\n감옥에 갇힌 후, 진정한 지옥이 시작되었다. 그녀는 경악했다. 원래 함께 노예주를 증오했어야 할 동족들이 오히려 그녀를 증오했고, 그 증오는 더 강렬했다.\n매일매일, 그녀는 끝없는 고문과 고통 속으로 빠져들었고, 운명의 선물은 그녀의 정신을 완전히 부수었다.\n그녀의 노예주에 대한 증오는 모든 사람을 향한 증오로 변했고, 그녀 역시 모든 이에게 증오받으며 자신의 위치를 잃었다.\n융식을 이용해 감옥에서 탈출했을 때, 그녀의 마음에는 오직 광기만 남아 있었다. 새로 얻은 힘을 움켜쥔 채, 그녀는 무한한 분노와 증오를 즉각적으로 풀어놓았다.\n그날 밤, 도시 전체에 붉은 피비가 내렸고, 그녀는 붉게 물든 강물 속에서 고개를 들어 미친 듯이 웃었다."
  },
  CollectionHall_57632_LockTip = {
    Text = "깨어남“혈연·시로”이후 해금"
  },
  CollectionHall_57632_Title = {
    Text = "혈쇄·히로"
  },
  CollectionHall_57633_Desc = {
    Text = "<Title:요약>\n조각가 협회 창립자, 회장.\n유년 시절 척수염을 앓아 집에서 자학해야 했고, 그때부터 인간의 신체적 한계를 인식하게 되었다.\n성인이 된 후 미사그에서 공부하며 멘토의 도움으로 연구 방향을 찾았고, 동시에 자신의 병도 치료했다.\n항상 따뜻한 미소를 띠고 있지만, 실타래제로는 인간의 감정에 무관심하다.\n외모 관리에 소홀하여 머리와 책상이 똑같이 어지럽다.\n책상 서랍에는 클로리가 매년 발표한 논문을 정리해놓은 파일이 들어 있다. 이는 헤버트가 가장 체계적으로 한 일이다.——"
  },
  CollectionHall_57633_LockTip = {
    Text = "조사 작전 제1장 「동부 지구의 비밀」 완료 시 해제"
  },
  CollectionHall_57633_Title = {Text = "허버트"},
  CollectionHall_57634_Desc = {
    Text = "<Title:요약>\n페리시테인들이 역사상 가장 용맹한 리더로 여기는 인물이다.\n키가 크고 다부진 체격으로, 짧은 기간 동안 주변 여러 부족들을 모두 정복하며 패배를 모르는 전설을 썼다.\n칭송과 찬사 속에서 명성이 높아졌으나, 동족의 만류에도 불구하고 적을 과소 평가하는 큰 잘못을 저질렀다.\n작은 실타래수가 비리시테인 군대를 무너뜨렸고, 그는 스스로 처벌을 받아들여 유일한 추종자와 함께 바다로 망명했다.\n분노와 억울함…… 이 치욕적인 순간은 반드시 기억될 것이며, 그는 자신의 모든 것을 되찾기 위해 약함이 깃든 목덜미를 “마녀”에게 내어주려 했다.\n그는 이미 피로 물든 복수의 길을 걷고 있다."
  },
  CollectionHall_57634_LockTip = {
    Text = "의식 잠수 클리어 “거인의 몰락” 해금"
  },
  CollectionHall_57634_Title = {Text = "골리아"},
  CollectionHall_57635_Desc = {
    Text = "<Title:요약>\n원래는 천한 노예였지만, 어릴 때부터의 영리함과 아름다움은 마치 그녀의 비참한 운명을 예고하는 듯했다. \n그러나 갑작스러운 행운으로 그녀는 집정관 부부의 죽은 딸을 대신하여 그들의 순종적인 양녀가 되었고, 더 이상 누구도 그녀를 노예로 보지 않았다. \n그녀는 너무 어릴 때 집을 떠났기 때문에, 오랜 세월 동안 그 온화한 부인을 진정한 어머니로 여겼다. 그러던 어느 날, 그녀가 우연히 과거의 부족 사람들에게 손을 내밀었을 때, 노예와의 동맹을 극도로 혐오했던 집정관 부부는 즉시 그녀를 버렸다. \n운명은 잔인하게 본 모습을 드러냈고, 그녀는 하루 아침에 수감자가 되어 감옥에서 증오를 발효하며 청춘기를 보내야 했다. \n감옥에서 융식이 폭발했을 때, 그녀는 이 검은 액체가 족쇄를 부식할 수 있다는 것을 발견하고, 복수의 여신은 마침내 감옥을 떠났다. 다시 나타났을 때, 그녀는 집정관의 머리로 티로스인의 완전한 해방을 맞이했다. \n그녀의 나머지 인생은 과거의 노예주들을 추적하며 보내졌고, 결국 무명의, 찬가가 새겨진 무덤으로 변모했다."
  },
  CollectionHall_57635_LockTip = {
    Text = "“시로” 깨어남 후 해금"
  },
  CollectionHall_57635_Title = {Text = "히로"},
  CollectionHall_57636_Title = {
    Text = "어둠의 주민"
  },
  CollectionHall_57637_Desc = {
    Text = "<Title:요약>\n그 시대의 대부분의 여성들이 전장에서 간호사로 활동했던 것과 달리, 그녀는 생전에 용감한 전사였으며 이를 자랑스러워했습니다.\n그녀는 조국이 신성하다고 굳게 믿었으며, 조국이 다른 땅을 정복하여 세계에 더 나은 미래를 가져올 것이라고 확신했습니다.\n열정적인 전투 중, 그녀는 한 신병을 구하기 위해 심각한 부상을 입었지만, 겨우 살아남아도 이동에 어려움을 겪는 후유증이 남았습니다. 조국을 위해 계속 봉사하기 위해 그녀는 군대를 떠나지 않았지만, 전방 부대에서 물러나 신병 교관으로 직무를 변경했습니다.\n\n시간이 흐르면서, 교만한 신병들은 자신들의 교관이 '불구'라는 사실타래에 불만을 품기 시작했고, 군대 내에서는 그녀에 대한 수군거림이 점점 늘어났습니다.\n그녀가 이 점을 인식한 후, 그녀가 구한 신병에게 의견을 제시하려고 했습니다. 그러나 그 병사는 다른 사람들처럼 그녀의 다리를 비웃었습니다.\n이런 모욕에 분노한 그녀는 군대를 떠났습니다.\n군대와 전장 밖에서, 그녀는 마침내 세상의 전모를 보았습니다. \"전쟁 영웅\"이 동포들에게 배신당하고, 그녀가 자랑스러워했던 \"해방\"은 현지 주민들에게 식민지와 고통만 가져다주었습니다.\n그녀의 마음은 크게 변했고, 그 후 그녀는 진정한 해방에 전념하며, 강한 정의감과 죄책감이 그녀를 진정으로 \"옳은\" 일을 하도록 이끌었습니다.\n불행히도, 다리의 괴저는 치료되지 않았고, 그녀는 죄를 속죄하기 전에 고통스럽게 죽었습니다.\n다시 깨어난 후, 그녀는 태이스의 은혜에 감사하며, 아란 부족이 계속 이어질 수 있도록 최선을 다해 도왔습니다."
  },
  CollectionHall_57637_LockTip = {
    Text = "“엘바” 깨어남 후 해금"
  },
  CollectionHall_57637_Title = {Text = "엘바"},
  CollectionHall_57638_Desc = {
    Text = "<Title:소개> \n한때 고대 로마의 마법상, 스타 검투사, 마지막의 유일한 전사. \n황제 칼리굴라의 미친 의지를 관철하기 위해 태어났고, 그의 모든 정치적 적들을 제거함: 삼촌, 형, 여동생… \n소년 황제는 친척의 시체 더미 앞에서 무릎을 꿇고 두 팔을 높이 들며 울고 웃음. \n유우하시는 혼란을 느꼈습니다: 마법상은 울 수도, 웃을 수도 있지만, 크게 웃으면서 눈물을 쏟을 수는 없음. \n나중에 폭군 황제가 처형당함. 사형 직전, 그는 유우하시를 안음. \n그러나 그는 아무것도 말하지 않음. \n주인을 잃은 무기는 끊임없이 방황하며, 다음 주인을 만날 때까지 기다림. \n그는 여전히 인간에 대해 혼란스러움을 느낌."
  },
  CollectionHall_57638_LockTip = {
    Text = "의식 잠수 클리어 “피와 모래” 해금"
  },
  CollectionHall_57638_Title = {
    Text = "유우하시"
  },
  CollectionHall_57639_Desc = {
    Text = "<Title:요약>\n“렌티니언의 가장 빛나는 명주”로 불리며, 그녀의 모든 언행은 만인의 주목을 받는다.\n최악의 신과 계약을 맺었으나, 자신의 “죽음”으로 인해 신생을 얻었다.\n그녀의 정체성에 대해 사람들은 다양한 추측을 하고 있다.\n명류, 정부인, 상인, 정치가, 패션의 여왕……\n그녀의 진실타래한 모습은 이미 흐릿해졌다.\n아니면, 이러한 변화무쌍함이 바로 그녀의 본모습일까?"
  },
  CollectionHall_57639_LockTip = {
    Text = "특파대 기록 “장미의 찬미” 해금"
  },
  CollectionHall_57639_Title = {Text = "소렐"},
  CollectionHall_57640_Desc = {
    Text = "<Title:요약>\n고대 로마 귀족의 딸이었으며, 아버지는 검투사 훈련소를 운영하고 있었다.\n주변에 강력한 검투사 노예들이 둘러싸고 있어 카푸아에서 횡행하며 오만했다.\n비꼬듯이, 결국 가장 싫어하는 노예에게 자신을 죽여달라고 애원해야 했다.\n더 비꼬듯이, 깨어남체가 된 후 불행하게도 그 “노예”와 학교에서 다시 만났다.\n상상할 수 있듯이, 그들을 맞이한 것은 당연히 따뜻한 장면이 아니었다."
  },
  CollectionHall_57640_LockTip = {
    Text = "의식 잠수 클리어 “백색 후예” 해금"
  },
  CollectionHall_57640_Title = {
    Text = "아그리파"
  },
  CollectionHall_57641_Desc = {
    Text = "<Title:요약>\n수레주인들의 무지한 전통에 의해 성녀로 만들어진 배의 성녀는 사실타래 가난한 집에서 팔려나온 딸일 뿐이다. 매일매일 항해를 보호하기 위해 갑판에 묶여 있었다.\n자유와 선택이 없는 삶은 그녀를 슬픔도 기쁨도 없는, 거의 자아가 없는 존재로 만들었다. 배가 그녀에게 가장 익숙한 피난처일 뿐이다.\n힘없는 삶이지만 아름다운 소망을 담고 있으며, 선원들과 대화하는 것이 금지되어 있어 멍하니 있는 것이 익숙해졌다. 가장 강렬한 소망과 갑판 옆을 날아다니는 바다새들만이 그녀의 시선을 끈다.\n마지막으로 보호하던 배가 융식으로 인해 많은 사상자를 내자, 분노한 사람들은 그녀를 물에 빠뜨려 죽게 했다."
  },
  CollectionHall_57641_LockTip = {
    Text = "“힐레스트”를 깨어남하면 해금"
  },
  CollectionHall_57641_Title = {
    Text = "셀레스트"
  },
  CollectionHall_57642_Desc = {
    Text = "<Title:요약>\n서대에서 온 조각사.\n명문가 출신으로, 예술을 위해 가족과 결별하고 홀로 서대로 전향하여 유명한 조각 대가 아우구스트에게 배움.\n절망적인 천재성을 지녔으나 예술 역사에 단 한 줄의 언급도 남기지 않음.\n깨어남체가 된 후, 조각과 조각술에 대한 새로운 이해를 얻었으며 모두가 아는 광기 어린 예술가가 됨.\n수호자를 새로운 영감의 원천으로 여기며, 수호자를 바라보는 눈빛에는 언제나 기묘하면서도 순수한 온기가 담겨 있음.\n아, 그것은 사랑하는 소재를 바라보는, 어떠한 잡념도 섞이지 않은 시선임."
  },
  CollectionHall_57642_LockTip = {
    Text = "의식 잠수 클리어 “노래 같은 조각” 해금"
  },
  CollectionHall_57642_Title = {Text = "산"},
  CollectionHall_57643_Desc = {
    Text = "<Title:요약>\n고대 아케메네스 왕조의 시녀였습니다.\n백년 연회에서 손님을 모시는 데 선택되지 않자, 호수에서 동료를 익사시키고 그녀를 대신했습니다.\n마지막으로 연회에서 추한 초록색 괴물로 변했습니다.\n머리와 몸이 민첩하여 동시에 열 개의 접시를 들고 사람들 사이를 오갈 수 있습니다.\n미식에 대한 정의가 현대 식문화와 크게 벗어나 있습니다.\n때로는 자신이 살인으로 처벌받아 괴물이 되었다고 의심하기도 하지만,\n절대로 교훈을 얻지 않고 곧 아무 일도 없었다는 척을 합니다.\n결국, 에리완 사람들은 역사에서 얻을 수 있는 유일한 교훈은:\n에리완 사람들은 결코 교훈을 얻지 않는다는 것입니다."
  },
  CollectionHall_57643_LockTip = {
    Text = "깨어남 후 “가렌” 해금"
  },
  CollectionHall_57643_Title = {Text = "카렌"},
  CollectionHall_57644_Desc = {
    Text = "<Title:요약>\n@2에 위치한 감옥의 경비원으로, 수형자들을 고문하는 것을 즐깁니다.\n상급자는 그녀에게 3년 후 렌티니언으로 돌아가게 하겠다고 약속했지만, 융식 현상의 악화와 지맥의 변화로 인해 그녀는 이 먼 땅에서 잊혀졌습니다.\n소녀는 포기하지 않았습니다. 그녀는 폐허를 지키며 리콜되는 그날을 기다렸습니다.\n마지막 수형자가 사망할 때까지, 그녀는 섬에서 유일한 생존자가 되었습니다.\n수형자가 없는 경비원이란, 수형자와 무엇이 다를까요?\n소녀는 생각하기를 거절했습니다. 그녀는 여전히 리콜되는 그날을 기다리고 있습니다."
  },
  CollectionHall_57644_LockTip = {
    Text = "“판디아” 깨어남 후 해금"
  },
  CollectionHall_57644_Title = {Text = "판디아"},
  CollectionHall_57645_Title = {Text = "불멸"},
  CollectionHall_57646_Desc = {
    Text = "<Title:요약>\n프랜시스가 기른 “펫”.\n본래는 “리사”라는 명랑한 소녀였으나, 조각가 협회의 개조로 인해 인간과 짐승이 결합된 왜곡된 형태로 변화했으며, 이후 리리에 의해 거두어져 현재는 정신병원에서 임시로 생활하고 있다.\n인간의 외모와 발성 능력을 상실타래했음에도 불구하고, 쿰은 리사의 일부 마음을 간직하고 있어 단순한 신체 동작으로 자신의 의도를 전달할 수 있다.\n그녀는 자신의 선택을 했다."
  },
  CollectionHall_57646_LockTip = {
    Text = "조사 작전 제4장 「무성한 곳에서」 완료 시 해제"
  },
  CollectionHall_57646_Title = {Text = "쿰"},
  CollectionHall_57647_Desc = {
    Text = "<Title:요약>\n출처가 불분명한 약제사로, 현재 조각가 협회의 과학 자문관이다.\n어머니는 시골 농부였으며, 그녀는 위대한 뱀 신의 자식을 임신하게 되었다고 전해진다.\n어머니로부터 알비노 증후군과 온화한 성격을 물려받아, 헤르베르트가 유일하게 신뢰하는 친구이다.\n해부학, 방향족 탄화수소, 그리고 벨라도나의 연기 향기에 열중하다.\n저서가 많으며, 대표작은 독성학의 성경으로 알려진 <약물지>이다.\n다양한 독물에 오래 노출되어 있어, 숨을 내쉬는 기체조차도 극독성을 띤다. 그에게서 멀리 떨어져 있는 것이 필자로서의 유일한 충고이다."
  },
  CollectionHall_57647_LockTip = {
    Text = "조사 작전 제2장 「밀랍인형의 이름으로」 완료 시 해제"
  },
  CollectionHall_57647_Title = {Text = "알비노"},
  CollectionHall_57648_Desc = {
    Text = "<Title:요약>\n워드 필립스의 학생, 미사그의 첫 번째 수호자.\n상시 지하의 비밀 구역에 머물며, 그 존재를 아는 이는 극소수에 불과하다.\n정신력이 뛰어나 다년간 특수한 방법으로 생명을 유지하며 미사그의 안전을 지켜왔다.\n미래의 변화에서 수호자가 중요한 역할을 할 것이라 예견하고, 예외적으로 수호자가 자신과 언제든 접촉할 수 있도록 허락했다.\n이는 양성과 동시에 관찰의 의미를 담고 있다."
  },
  CollectionHall_57648_LockTip = {
    Text = "조사 작전 제2장 「밀랍인형의 이름으로」 클리어 시 개방"
  },
  CollectionHall_57648_Title = {
    Text = "알리스테어"
  },
  CollectionHall_57649_Desc = {
    Text = "<Title:요약>\n희박한 해양도약자 혈통을 가진 인간으로, 고대 오른 가문에서 태어났다. 이 가문은 과거에 변고를 겪었으며, 일부 사람들은 성인이 된 후 점차 추한 몬스터로 변해 결국 고통스럽게 죽었다. 아버지는 그의 출생 후 병변을 견디지 못하고 자살했다.\n어릴 때 어머니의 혐오와 또래들의 괴롭힘 속에서 자라며 성격이 음침하고 외로워졌다.\n16세 때 숨겨진 삼촌의 수기에서 가문의 고귀한 혈통에 대해 암시적으로 언급된 것을 보고, 정신적인 승리를 얻었다. 하루는 초월적인 힘을 얻을 것이라는 환상을 가지며, 주변 사람들의 괴롭힘을 운명의 자식이 겪어야 할 필연적인 시련으로 여겼다. 그리고 그들이 나중에 자신에게 비굴하게 구걸할 모습을 기대했다.\n성인이 되어 동굴에 숨어 변화를 맞이했지만, 반인반어의 상태에서 멈추어 어머니의 비명에 쫓겨 집으로 돌아갈 수 없었다.\n결국 미발달된 아가미로 인해 바다에 뛰어들어 익사했다."
  },
  CollectionHall_57649_LockTip = {
    Text = "“케이크스” 깨어남 후 해금"
  },
  CollectionHall_57649_Title = {
    Text = "카이커스"
  },
  CollectionHall_57650_Desc = {
    Text = "<Title:요약>\n왕국에서 가장 오래된 카벤디시 가문 출신으로, 부모님의 애정을 한몸에 받았지만, 불행히도 융식에 감염되었다.\n지하에 3년 동안 갇혀 있었으며, 피에 대한 갈망이 점점 깊어졌다.\n형은 동네를 배회하는 노숙자나 거리에서 일하는 여성들을 찾아 동생의 매일의 “음식”으로 제공하도록 명령했다.\n일시적으로 도시 내에서 공포가 퍼졌고, 경찰서는 총력을 다해 형제를 체포했다.\n이로써 렌티니언 성에서 큰 충격을 준 “흡혈귀 사건”이 마무리되었다."
  },
  CollectionHall_57650_LockTip = {
    Text = "“레이아” 깨어남 후 해금"
  },
  CollectionHall_57650_Title = {Text = "레이아"},
  CollectionHall_57651_Desc = {
    Text = "<Title:요약>\n렌티니언 동부 출신의 직물 노동자입니다.\n융식에 감염되어 조각가 협회에 납치되어 왁스상으로 만들어졌습니다.\n“24”는 실타래험 번호이자 처음으로 확진된 인격 수를 나타냅니다.\n필자가 기록하는 시점에서 그녀의 인격 수는 계속 증가하고 있습니다.\n시간이 지나면 “24”들로 구성된 왕국은 반드시 인구가 늘어나며, 장관을 이룰 것입니다."
  },
  CollectionHall_57651_LockTip = {
    Text = "통관 특파대 기록 “평온한 분열” 해금"
  },
  CollectionHall_57652_Desc = {
    Text = "<Title:요약>\n생전에 아버지와 함께 융식에 감염되어 가족들의 고통 속에서 온순하게 치료를 받아왔다.\n어머니는 남편과 딸을 동시에 잃으면서 성격이 크게 변했고, 엘워스의 탐사 중 등불 교회의 의식에 잘못 들어가 리리를 우연히 깨웠다. 비정상적으로 깨워진 리리는 무표정한 인형이 되어 명령을 받을 때만 움직였다.\n어머니는 융식으로 인해 리리의 모습을 잊어버리고, 깨어난 리리를 괴물로 여기며 진정한 딸이 부활하기를 바라며 끊임없이 실타래험을 진행했다.\n마지막으로 수호자와 함께 미사그로 이동했으며, 수호자를 어머니라고 부른다. 매우 의존하고 있다."
  },
  CollectionHall_57652_LockTip = {
    Text = "통관 특수 미션 기록 “이야기의 마법” 해금"
  },
  CollectionHall_57652_Title = {Text = "릴리"},
  CollectionHall_57653_Desc = {
    Text = "<Title:소개>\n로저스의 왁스 인형.\n\n객차 안에서 시끄럽게 떠들던 아이들처럼, 버릇없이 자란 녀석.\n믿는 구석이라곤 그 회녹색 눈뿐—그것은 「왁스상 선생님」이 로저스에게 남긴 유일한 것.\n'24'의 인공 미궁에서 거스를 수 없는 힘과 맞닥뜨려 납작한 조지가 되었고, 로저스의 분노를 성공적으로 자아냈다."
  },
  CollectionHall_57653_LockTip = {
    Text = "조사 작전 제2장 「밀랍인형의 이름으로」 완료 시 해제"
  },
  CollectionHall_57653_Title = {Text = "조지"},
  CollectionHall_57654_Desc = {
    Text = "<Title:소개>\n릴리안 구빈원의 고아로, 젠킨의 가장 친한 친구.\n조각가 협회에 의해 개조되었으며, 다른 고아들이 비참하게 죽는 것을 직접 목격하고, 자신이 살아남아 침묵을 지킨 것에 깊은 죄책감을 느꼈다.\n결국 종탑에서 뛰어내려 완전한 해방을 얻었다.\n항상 곰 인형을 품에 안고 다니며, 그녀는 그것에게 「보비」라는 이름을 붙여주었다.\n선물, 작은 치마, 금색 사탕을 좋아한다.\n약간 어둠을 무서워하여, 항상 「보비」를 안아야 잠들 수 있다. 당신이 그녀에게 자장가를 불러줄 수 있다면, 소녀는 영원히 당신에게 감사하며 당신을 좋아할 것이다.\n젠킨이 한때 그녀를 위해 그렇게 해주었던 것처럼."
  },
  CollectionHall_57654_LockTip = {
    Text = "“에이지스” 깨어남 후 해금"
  },
  CollectionHall_57654_Title = {
    Text = "아이기스"
  },
  CollectionHall_57716_Desc = {
    Text = "<Title:소개>\n원래는 자동 인형 제작에 몰두하던 연구원으로, 다프다엘에게서 은심을 핵심으로 한 에너지 부품을 얻었다.\n연구원의 친구가 에너지 부품을 탐내면서 두 사람은 여러 차례 다투었고, 결국 결별에 가까운 분노 속에서 벌어진 쟁탈전이 실타래험실타래 폭발로 이어졌다. 어찌 된 영문인지 인형의 몸에서 깨어난 그녀는 경악스러운 사실타래을 깨달았다. 생명이 없어야 할 자동 인형 안에 자신 외에도 또 다른 의식이 존재한다는 것을.\n그녀가 어떤 신념으로 불타는 폐허에서 친구를 구해냈는지, 또 어떤 신념으로 교외까지 걸어갔는지는 이제 아무도 알지 못한다. 세상에 알려지지 않은 이 기계 천재는 그렇게 세상에서 사라졌고, 남은 것은 폭발에 관한 뉴스 하나, 흩어진 부품들, 그리고 잔존하는 은심 하나뿐이었다.\n그 안에서 깨어난 것은, 과연 어떤 존재일까?"
  },
  CollectionHall_57716_LockTip = {
    Text = "의식 잠수 클리어 「왜곡된 핵심」 해금"
  },
  CollectionHall_57716_Title = {Text = "에리카"},
  CollectionHall_57717_Desc = {
    Text = "<Title:요약>\n@2의 사자겸 대행자로, 종종 인간의 모습으로 세상을 돌아다닌다.\n순수한 악마——미래도, 신념도, 이상도 없다.\n욕망을 미끼로, 혼란을 먹고 살아가며, 인간을 속이고 유혹하는 것을 즐긴다.\n규칙을 놀리는 데 능숙하며, 그와 계약을 맺은 인간들은 결국 모두 깨끗이 잃게 된다.\n가장 영리한 변호사조차도 그에게서 아무런 이익도 얻지 못한다.\n때로는 아이의 모습으로 변하기도 하지만, 이는 사람들이 그를 경계하지 않게 하지는 않는다.\n결국 그의 무서움은 겉모습에 있지 않다."
  },
  CollectionHall_57717_LockTip = {
    Text = "특파대 기록 “장미의 찬미” 해금"
  },
  CollectionHall_57718_Desc = {
    Text = "<Title:요약>\n정신의학자로, 간질, 히스테리, 불안 및 수면장애 등의 질병을 전문으로 합니다.\n환자가 심성을 드러내도록 유도하는 최면술에 능합니다.\n그녀의 환자들은 종종 매우 “예술적”인 방식으로 자살로 마무리된다는 소문이 있지만, 그녀는 경찰이 찾아오기 전에 신분을 바꾸고 다시 문을 열곤 합니다.\n많은 명사들이 그녀의 진료소를 찾아왔으며, “렌티니언의 반쪽 비밀을 쥐고 있는 여자”로 묘사되었습니다.\n로저스는 그녀의 장기 고객이었는데, 그의 특이한 예술적 열정도 이 의사와 무관하지 않을 가능성이 있습니다?"
  },
  CollectionHall_57718_LockTip = {
    Text = "조사 작전 제1장 「동부 지구의 비밀」 완료 시 해제"
  },
  CollectionHall_57718_Title = {
    Text = "클레멘타인"
  },
  CollectionHall_57719_Desc = {
    Text = "<Title:요약>\n우수한 왁스 조각사로, 로저스 왁스 박물관의 현관장입니다.\n어린 시절 말더듬이 때문에 배척받았으며, “가난해서 돈밖에 남은 게 없다”는 놀림을 받았습니다.\n높은 지위의 아버지, 정신이 혼란스러운 어머니, 그리고 전국을 충격에 빠뜨린 납치 사건……\n다양한 비극적인 요소들이 작용하여 로저스는 기대를 저버리지 않고 어머니를 능가해 스카보로에서 가장 유명한 미치광이가 되었습니다.\n조각가 협회에서 여성들에게 가장 인기 있는 회원이며, 예술에 대해 언급하지 않는 한 감정적으로 매우 안정적인 신사입니다."
  },
  CollectionHall_57719_LockTip = {
    Text = "조사 작전 제2장 「밀랍인형의 이름으로」 완료 시 해제"
  },
  CollectionHall_57719_Title = {Text = "로저스"},
  CollectionHall_57720_Desc = {
    Text = "<Title:요약>\n어머니는 뛰어난 기계 수리공으로, 기술이 뛰어나고 가격이 저렴하여 많은 사랑을 받았습니다. \n8살 때 아버지가 바다로 나갔다가 돌아오지 않았고, 그 이후로 어머니와 함께 기계 수리점에서 생활하며 서로 의지하며 살아갔습니다. 두 사람은 모은 부품으로 단일 바퀴 오토바이를 만들려고 노력하며, 언젠가 함께 오토바이를 타고 모험을 하여 어머니의 젊은 시절 꿈을 이루고자 했습니다. \n13살 때 어머니가 병으로 세상을 떠났습니다. 오토바이를 완성하기 위해 더 많은 부품을 얻기 위해 고액의 보상을 제공하는 선박 미션을 맡았습니다. \n선박이 귀항 중 폭풍으로 인해 큰 소용돌이에 휘말렸을 때, 유일한 잠수복을 친구에게 주고, 어머니가 남긴 나우티루스 목걸이를 손에 쥐고 융식이 가득한 물줄기 속에서 죽었습니다. 오직 잔해와 은심만이 양류에 떠다니며 여행을 계속했습니다."
  },
  CollectionHall_57720_LockTip = {
    Text = "깨어남 “노디라” 후 해금"
  },
  CollectionHall_57720_Title = {Text = "노틸라"},
  CollectionHall_58148_Desc = {
    Text = "<Title:소개>\n도해주제가 길러낸 작은 공주이자, '성녀'라 불리는 존재.\n어릴 때부터 곱게 자라 그야말로 진정한 숙녀다. 손에 든 작은 양산은 하얀 피부를 보호할 뿐만 아니라, 모든 부정하고 불길한 것들을 차단해 준다.\n자신 또한 어떤 '불길함'의 산물이라는 것을 잘 알고 있지만— 그녀의 탄생은 자연의 섭리가 아니라, '어머니'가 되어 예언의 아이를 낳기 위한 것이었다.\n먹다 남을 만큼의 과자, 최신 유행의 양장, 그녀를 둘러싼 수많은 하인들…… 그녀는 화려한 물질세계를 누비며, 마음속 불안과 두려움을 꽁꽁 가두었다.\n하지만 이 시도는 결국 실타래패로 끝났으니, 자유로운 마음은 어떠한 타협도 받아들이지 않기 때문이다."
  },
  CollectionHall_58148_LockTip = {
    Text = "깨어남 “머피” 후 해금"
  },
  CollectionHall_58148_Title = {Text = "머피"},
  CollectionHall_59454_Desc = {
    Text = "<Title:요약>\n어느 해안 어촌에서 온 소녀로, 부모는 원양 선원이고, 할머니와 함께 살면서 할머니가 지어낸 동화 이야기를 천진하게 믿었다. 그들은 아틀란티스의 후예라고 하며, 그녀가 잘 자라서 많은 친구들을 사귀면, 친구들이 그녀를 바다 속 고향으로 데려다 줄 것이라고 했다.——\n할머니가 돌아가신 후, 수족관 주인이 물고기를 수거하러 왔을 때, 밝고 활발한 그녀를 안내원으로 고용하여, 그녀는 행운을 누리며 다채로운 어린 시절을 보냈다.\n융식된 물고기가 전체 수족관을 오염시킨 후, 수족관은 파산을 선언했고, 실타래업 상태인 그녀는 가장 좋아하는 해파리를 병에 담아 멀리 떨어진 마을로 가져갔지만, 곧 융식이 그녀와 마을 전체를 잠식했다…\n깨어남 후 기억이 약간 혼란스러웠지만, 자신이 '바다 사람'이라고 굳게 믿으며, 친구들을 자신의 고향으로 초대해 방문하도록 끊임없이 요청했다."
  },
  CollectionHall_59454_LockTip = {
    Text = "의식 잠수 클리어 “일상” 해금"
  },
  CollectionHall_59454_Title = {Text = "오레타"},
  CollectionHall_59455_Desc = {
    Text = "<Title:소개> \n「절대적인 행운」을 가진 남자로 불림. \n그런 재능을 가지고 도박꾼이 되는 것은 당연한 일. \n하지만 그는 또한 꽤 훌륭한 탐정이기도 함. \n게다가 그는 빚쟁이로, 항상 가장 빠른 속도로 이긴 원금을 탕진함. \n모순과 복잡함. 이것이 우리가 이 남자에 대해 가진 전부의 평가임. \n운명의 여신은 그를 편애하고, 정체불명의 「N」은 그를 사랑하며, 가장 인색한 술집 주인도 그에게 약간의 할인 혜택을 주고 싶어함. \n모든 사람들이 그를 사랑하지만, 그는 결코 걸음을 멈추지 않고 새로운 모험 게임을 시작함. \n그는 오직 미지의 것을 사랑함."
  },
  CollectionHall_59455_LockTip = {
    Text = "통관 특수 미션 기록 “사냥 즐겁게!” 해금"
  },
  CollectionHall_59455_Title = {Text = "라이커"},
  CollectionHall_59456_Desc = {
    Text = "<Title:요약>\n하류 귀족 가정에서 태어났지만, 선천적으로 심각한 천식을 앓고 있었음에도 불구하고 부모님으로부터 많은 사랑을 받았습니다. \n병으로 인해 집을 나서지 못하며 자주 자살을 생각했지만, 부모님이 그녀의 기분을 풀기 위해 드물게 멀리 여행을 데려갔다가, 의외로 융식에 감염되었습니다. \n귀향 후, 부모님은 죄책감을 느끼며 그녀를 요양원에 보내고, 바다로 상업 활동을 하러 가서 치료비를 벌면서 동시에 세계를 돌아다니며 치료 방법을 찾았습니다. \n융식이 점점 더 심해지면서 그녀의 자살 욕구도 더욱 강해졌지만, 부모님에게 짐이 되었다는 죄책감 때문에 부모님을 더 슬프게 하지 않기 위해 죽음과 해방에 대한 동경을 참아냈습니다. \n부모님이 그녀를 보러 오는 길에 배가 침몰하여 사망했다는 소식을 접한 후, 세상에 더 이상 연연할 것이 없어진 그녀는 밤중에 조용히 요양원을 떠나 바다 속으로 걸어갔습니다. \n머리 위까지 물이 차올랐을 때, 삼각형 융식 흔적에서 떨어진 검은 액체가 흩어지고, 오랜 병으로 고통받던 몸이 말로 표현할 수 없는 해방감을 얻었습니다. 이는 처음이자 유일하게 숨을 편안히 쉴 수 있었던 순간이었습니다."
  },
  CollectionHall_59456_LockTip = {
    Text = "“닝피아”를 깨어남하면 해금됩니다"
  },
  CollectionHall_59456_Title = {Text = "님피아"},
  CollectionHall_61045_LockTip = {
    Text = "조사 작전 8-1 완료 시 해제"
  },
  CollectionHall_61045_Title = {
    Text = "A단조: 종말의 교향곡"
  },
  CollectionHall_62183_Title = {
    Text = "08 종말의 교향곡"
  },
  CollectionHall_62184_Desc = {
    Text = "<Title:요약>\n세계적으로 유명한 지휘자이자 음악가입니다. 겉보기에는 젊지만, 그가 지휘한 교향악 공연은 이미 전 세계를 돌며, 각 공연마다 수많은 관객을 끌어모았습니다. \n고전 음악계에서 가장 명성이 높은 천재인 함린의 개인 정보는 아무도 알지 못하며, 이는 심사회로부터 관심을 받게 되었습니다. 오랜 조사 끝에 심사회는 함린의 공연 장소와 등불 교회의 활동 궤적이 매우 일치한다는 것을 발견했습니다. \n그들이 진실타래을 찾기 전에, 진실타래이 먼저 그들을 찾아왔습니다——등불 교회가 미사그를 침입한 사건에서 함린은 중요한 역할을 했습니다. \n이제 사람들은 비로소, 이 천재 지휘자의 진정한 무대가 극장 밖에 있었음을 깨달았습니다."
  },
  CollectionHall_62184_LockTip = {
    Text = "조사 작전 제8장 「종말의 교향곡」 완료 시 해제"
  },
  CollectionHall_62184_Title = {Text = "하멜른"},
  CollectionHall_65503_Title = {
    Text = "엘워스의 귀환자"
  },
  CollectionHall_65509_Desc = {
    Text = "<Title:요약>\n동부 출신의 소년 범인으로, “24”의 여동생이다.\n세 가지 독특한 기술을 가지고 있다: 절도, 싸움, 그리고 상황이 안 좋아지면 도망치는 것.\n누구도 그녀에게서 이익을 얻을 수 없다.\n아, 맞다. 그녀는 항상 “브라운”이라는 이름의 소년쥐와 함께한다.\n브라운은 성숙하고 차분하여, 젠킨의 성격과 잘 어울린다.\n따라서, 렌티니언 동부에서 굶주린 사람들이 쥐를 잡아먹는 일이 자주 발생하지만, 젠킨은 그런 생각을 한 번도 해본 적이 없다."
  },
  CollectionHall_65509_LockTip = {
    Text = "조사 작전 제2장 「밀랍인형의 이름으로」 완료 시 해제"
  },
