  CollectionHall_70553_LockTip = {
    Text = "기간 한정 이벤트 「이야기의 마법: 각본의 수수께끼」의 스테이지를 하나 이상 클리어하면 개방됩니다."
  },
  CollectionHall_70553_Title = {
