  },
  CollectionHall_70555_LockTip = {
    Text = "제한 시간 내 캐릭터 활동“봄이 시들기 전에: 정원의 추억”의 아무거나 하나의 관문을 클리어해야 합니다"
  },
  CollectionHall_70555_Title = {
    Text = "봄이 시들기 전에: 정원의 추억"
  },
  CollectionHall_70839_Desc = {
    Text = "<Title:요약>\n아첨하고 세속적이며 위선적이다. 리덴니움의 명예와 이익을 위해 자신을 낮추어 연기하는 릴리안 자선 병원의 원장은 서투른 배우처럼 행동한다. \n그녀는 여기저기 돌아다니며, 유명인사들의 손가락 틈에서 몇 푼의 돈을 구걸하여 자선 병원의 어려운 운영을 유지한다. 그녀는 조롱과 욕설을 혼자 삼키고, 부드러운 노래로 자선 병원의 아이들을 재운다. \n리덴니움은 그들을 버렸지만, 릴리안 자선 병원은 그렇지 않았다. 사라는 준비를 마쳤고, 자신의 모든 힘을 다해 이 아이들을 보호하여 리덴니움의 안개와 찬바람 속에서 살아남도록 하겠다고 결심했다. \n하지만 그녀의 겸손한 이상은 실타래패했고, 그녀와 아이들은 조각가 협회의 음모에 의해 죽었다. 조각가 협회에게 있어, 그녀와 그녀가 소중히 여긴 아이들은 웅장한 건물 속에서 무시할 수 있는 모래알에 불과했다. 가치도 미학도 부족했다. 그들의 삶은 가볍고, 그들의 죽음은 중요하지 않았다. \n그녀는 자신의 모든 것을 태워버렸다. 그 불꽃은 빠르게 사라졌고, 남은 것은 리덴니움의 여전히 차가운 바람뿐이었다."
  },
  CollectionHall_70839_LockTip = {
    Text = "제1장 클리어 해금"
  },
  CollectionHall_70839_Title = {Text = "사라"},
  CollectionHall_70884_Desc = {
    Text = "<Title:A.F.185>\n각국 대표가 콘스탄 연방에서 《미스디아 협정》을 체결하여 함께 재앙에 저항하고 부식 균열을 억제하기로 결정했습니다. 동시에 각국은 재앙의 존재 및 부식 현상의 비밀 지침에 대한 공감대를 형성했습니다.\n이번 협정에 따라, 학원은 독립성을 유지하며, 어떤 국가의 소속도 아니고, 각국에 지부를 설립할 권리와 각국 지도자와 직접 소통할 권리, 각국의 재앙 및 부식 관련 정보를 얻을 권리가 있습니다.\n미사그는 공식적으로 완전 중립의 초국적 조직이 됩니다.\n\n<Title:A.F.186>\n협정 수정 및 서명에 참여한 인원은 미스디아에 상주 심사 위원회를 설립했습니다. 심사 위원회는 협정의 이행을 보장하기 위해 자체 실타래시 팀을 두고, 비밀 회의를 구성하여 기본 조직 구조를 확립했습니다.\n\n<Title:A.F.187>\n미사그 학원은 공식적으로 미사그 대학교로 이름을 변경했습니다.\n이후 부식 현상이 빈번히 발생하고 규모도 커지기 시작했습니다. 미사그 대학교는 최전선에 서서 인류의 부식 저항의 중추 역할을 합니다."
  },
  CollectionHall_70884_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_70885_Desc = {
    Text = "<Title:A.F.75>\n알리스테어는 레오 왕국 내에서 거대한 균열의 출현을 예견하였고, 와드는 조사원들을 이끌고 대응하기 위해 나섰다. 많은 조사원들이 이번 사고로 희생되었다.\n\n<Title:A.F.77>\n균열은 닫히지 않았지만 점차 안정화되었다. 정부의 협력과 지원 아래, 와드는 거대한 균열 위에「진리의 시각」의 주둔지를 건설하였다.\n거대한 균열은 공식적으로 L-01로 번호가 매겨졌으며 별명은「검은 연못」이다.\n\n<Title:A.F.88>\n「검은 연못」이 돌연 변이하고 외부로 확산되며, 이 시점에서 주변 지역의「진리의 시각」은 큰 피해를 입었고, 와드도 대응 과정에서 부상을 입었다.\n검은 연못은 닫히지 않았고, 타비는 그 속에 빠져 직접 수호하며 검은 연못의 잠정적인 안정을 유지하였다.\n\n<Title:A.F.90>\n「진리의 시각」주둔지가 확장되고, 미사그 학원이 설립되며, 와드는 초대 원장이 되었다.\n이로써 사람들은 충분한 정신력을 갖춘 조사원들을 체계적으로 양성하기 시작하여 점점 심각해지는 융식 위기에 대응할 수 있게 되었다.\n\n<Title:A.F.92>\n와드가 검은 연못 사건에서 입은 상처가 악화되어 결국 사망하였다.\n와드의 유해는 학원 내에 묻히고, 그의 묘비 형상은 열쇠로 되어 있어 미다 열쇠 무덤 개설의 전통을 이었다.\n죽은 후 분리된 은심은 알리스테어가 직접 제작한 은열쇠로 번호 K-0001이 부여되었고, 그 후 알리스테어는 초대 비밀 지키는 사람이 되어 외부에서 활발하게 활동하게 되었다.\n같은 해, 와드를 치료하기 위한 방법을 찾으러 르무바쉬로 조사하러 간 클라랄크쉬는 실타래종되었고, 이후 행방이 묘연해졌다."
  },
  CollectionHall_70885_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_70886_Desc = {
    Text = "<Title:A.F.306>\n허버트는 그린 재단의 자금을 수령하고, 등불 교회의 도움으로 조각가 협회를 설립하였다.\n같은 해, 돌이 미사그에 입학했다. 천재 학자로서, 돌은 입학하자마자 곧바로 석사 및 박사들이 진행하는 연구에 참여하며, 이후에 미사그의 은심 기술 발전에 큰 추진력이 되었다.\n\n<Title:A.F.307>\n허버트는 등불 교회를 습격하여, 예전에 도둑맞았던「성녀」를 되찾으려 하였다.\n\n<Title:A.F.309>\n어떤 융식 사건의 생존자 윌리엄은 조사원 핀골의 추천으로 미사그에 합류하였다.\n\n<Title:A.F.310>\n미사그 대학교 연합 심사 위원회는, 조각가 협회가 더 성장하기 전에 대부분의 멤버를 체포하였다. 허버트와 몇몇 핵심 멤버는 도망쳤고, 지하 작업으로 전환하였다. 이후 허버트는 로저스와 협력하기 시작하였다.\n같은 해, 살바도르가 대 성당 구주로 임명되고, 코르트가 대리 원장으로 취임하였다.\n\n<Title:A.F.313>\n허버트의 지시에 따라 로저스는 릴리안 자선 구제원에 기부하여, 구제원의 유일한 후원자가 되었다.\n\n<Title:A.F.314>\n아쿠트 대폭발이 발생하였다.\n알리스테어의 파견으로, 윌리엄과 라모나는 아쿠트로 가서 폭발 후 유적에서 모든 기억을 잃은 @3를 찾아서 미사그로 데려가 특별 훈련을 진행하였다."
  },
  CollectionHall_70886_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_70887_Desc = {
    Text = "<Title:A.F.263>\n프란시스 태어나다.\n\n<Title:A.F.289>\n딸을 잃은 후에 프란시스는 과학 탐사대에 합류하여 앨워스로 향합니다.\n같은 해에 탐사대 전원이 전멸합니다.\n\n<Title:A.F.290>\n로저스 태어나다.\n같은 해에 앨워스에서 우연히 릴리를 소환한 후, 프란시스는 라이로 가서 재단의 도움으로 정신병원을 세우고 정체된 시공간을 구축합니다.\n\n<Title:A.F.292>\n돌 태어나다.\n\n<Title:A.F.297>\n허버트가 신입생으로 미사그에 입학하다, 당시 17세입니다.\n\n<Title:A.F.298>\n등불이 쌍생 성자를 사용하여 신을 강림시키는 의식을 수행합니다. 덱스터가 의식에 잠입하여 신으로 태어날 예정인 라모나를 몰래 데리고 나가 덕분에 의식을 방해했습니다.\n의식은 실타래패로 선언되었습니다. 라모나는 덱스터의 양녀가 됩니다.\n\n<Title:A.F.300>\n로저스가 「밀랍상」에게 납치당합니다. 이후 「밀랍상」이 사망하며 로저스는 구출됩니다.\n같은 해에 살바도르는 당시 대성당 구역 주교에게 깨어남하여 보조 사제로서 대성당 구역에서 근무합니다.\n\n<Title:A.F.304>\n코르트가 신입생으로 미사그에 입학합니다.\n\n<Title:A.F.305>\n미사그 대학교의 깨어남 체계 학생 허버트가 규정을 위반하여 실타래험체를 만들어 내고, 행동이 드러난 후에 허버트는 자신의 멘토 크로울리를 죽이고 도주합니다. 당시 25세입니다."
  },
  CollectionHall_70887_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_70888_Desc = {
    Text = "<Title:B.F.？？？>\n전 세계를 휩쓴 재앙은 광대한 육지를 파괴했습니다. 지진, 홍수, 자기장 혼란, 기후 이상 등이 연달아 발생하고, 도시와 정착지는 물속에 잠기며 원래 바다 깊은 곳에 묻혀있던 견고한 바위들이 새로운 산봉우리가 되었습니다. 인류 문명은 중상을 입었습니다.\n\n<Title:A.F.0>\n옛 땅이 바다에 잠기고, 새로운 땅이 수면 위로 떠올랐습니다.\n이렇게 완전히 변모한 세계에서 사람들은 옛 달력을 버리고 문명의 잔해를 품고 힘겹게 재건에 나서며 새로운 시대인 홍적기에 접어들었습니다."
  },
  CollectionHall_70888_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_70889_Desc = {
    Text = "<Title:A.F.55>\n케라르크쉬는 자신의 조사 등을 통해 능동적으로 은열쇠 비밀결사를 찾아내고 성공적으로 가입하여, 비밀결사의 힘을 빌려 인류 재건을 돕고자 했다.\n같은 해, 케라르크쉬는 화드와 타웨이의 행동을 주목하고 그 동향을 관찰하기 시작했다.\n\n<Title:A.F.58>\n케라르크쉬는 일회용 은열쇠를 제작하여 새로운 비밀결사 지도자인 열쇠장인이 되었고, 비밀결사를 이용해 은밀히 지식을 전파하여 인류 재건을 도왔다.\n같은 해, 케라르크쉬는 화드, 타웨이와 접촉하여 화드에게 일정한 자금과 인력 방면의 지원을 약속했다.\n\n<Title:A.F.62>\n알리스테어·오웬스가 룬디니엔 교외의 평범한 시골 의사 가정에서 태어났다.\n\n<Title:A.F.64>\n조사를 마친 케라르크쉬는 화드의 추구를 인정했고, 비밀결사의 규칙에 얽매이길 원치 않는 화드와 타웨이의 제안 및 입회하에 대등한 협력 관계를 맺었다.\n비밀결사의 자금과 인력 등의 지원을 받은 후, 화드의 연구는 더욱 진전되어 융식의 특성, 융식과 이변체 사이의 관계를 확인했으며, 융식 침식의 각기 다른 단계별 특징을 초보적으로 정리했다.\n\n<Title:A.F.65>\n케라르크쉬, 화드, 타웨이와 여러 비밀결사 구성원이 함께 융식을 추적하고 융식 확산을 저지하는 것을 사명으로 하는 최초의 조사원 소대를 결성하고, 이를 「진리의 눈」이라 명명했다.\n\n<Title:A.F.70>\n화드는 융식 및 융식 침식의 특성과 규칙을 다시 정리하고, 융식의 지역적 특징을 최초로 기록하여 《융식과 융식 규칙 초고》를 저술했으며, 새로 조사대에 합류한 구성원들이 열람할 수 있도록 했다.\n\n<Title:A.F.72>\n화드는 융식으로 인해 파멸한 한 가정에서 알리스테어를 구출하고 그를 제자로 삼았다.\n같은 해, 화드와 그 휘하의 「진리의 눈」 규모가 점차 확장되어 당국의 주목을 받게 되었다."
  },
  CollectionHall_70889_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_70890_Desc = {
    Text = "<Title:A.F.30>\n워드 필립스는 아그로 공화국 동부의 고대 도시 샬롬에서 부유한 상인 가문에 태어났습니다。\n\n<Title:A.F.38>\n클라르크슈가 태어났습니다. 태어난 지 얼마 지나지 않아 부모가 사망하여 누나와 함께 생존을 위해 힘겹게 싸워야 했습니다。\n\n<Title:A.F.48>\n워드는 어릴 때부터 화학과 물리 영역에서 특성을 드러내어 18세에 모스웨이투주립대학 화학과에 입학하여 유명 화학자 나사니엘 밀턴의 제자가 되었습니다。\n\n<Title:A.F.50>\n워드의 조부 로저 필립스 신부가 사망하였고 그 후 아버지가 실타래종되었습니다. 워드는 조상의 집을 조사하고 아버지의 발자취를 따라 레오 왕국에 도착하여 가문이 숨겨온 비밀을 발견했습니다 - 그것은 마녀 사냥 시기에 은열쇠의 비밀 모임에서 이교도에게서 빼앗아 온 신비한 조제입니다。\n고대의 조제는 양피지에 기록되어 있으며, 일부가 파괴된 상태에서 워드는 다년간의 실타래험을 통해 이를 간신히 보완했습니다。\n\n<Title:A.F.53>\n보완된 조제를 바탕으로 워드는 첫 번째 은열쇠를 성공적으로 만들었습니다. 조제의 결함 때문에 이 은열쇠는 한 번 사용하면 파괴되어 다시 사용할 수 없었습니다。\n어떻게든, 워드는 이 일회용 열쇠를 이용하여 지혜의 본질의 대행자 타비와 만나게 되었고, 타비를 통해 세계가 곧 「검은 재앙」을 직면할 것을 알게 되었습니다。\n재앙을 막기로 결심하고 워드는 타비와 동의하에 링크를 형성하여 깨어남체 제조 방법과 완전한 은열쇠 조제를 얻었습니다。\n이후 워드는 다양한 지역을 탐험하며 융식과 균열을 연구하고 이에 대한 명명하고 융식을 방어할 방법을 찾으려고 노력했습니다。"
  },
  CollectionHall_70890_LockTip = {
    Text = "조사 작전 완료 시 9-13 해제"
  },
  CollectionHall_70891_Desc = {
    Text = "1년간의 예비 과정 학습과 훈련을 거쳐 @3은 공식적으로 수호자로 임명되어, 깨어남체와 학내의 다른 세력들과 함께 융식 관련 사건을 조사하기 시작했습니다. \n같은 해에, 등불 교회는 미 학내의 유령들과 함께 다시 한 번 미사그를 침략하여 블랙풀의 혼돈을 일으키고, 궁극의 문을 열어 최고의 의지가 시선을 보내도록 만들었습니다. \n카다스가 융식에 의해 흡수될 위기에 처했을 때, @3은 삼질체의 권능을 흡수하여 문살 안에서 최고의 의지의 시선과 대결했습니다. \n결국, 최고의 의지는 다시 잠들었고, 카다스는 구원받았습니다. \n@3은 희생했습니다. \n그의 모든 관련 기록이 융식으로 인해 보존될 수 없게 되자, 미사그는 예외적으로 그가 생전에 사용한 은열쇠를 학교 역사 기념관에 봉인하기로 결정하여, 그의 공적을 기리기로 했습니다. \n%hisorher% 이름은 알려지지 않았습니다. K-0617이라는 번호는 영원히 남아 있을 것입니다."
  },
  CollectionHall_70891_LockTip = {
    Text = "조사 작전 9-13 완료 시 해제"
  },
  CollectionHall_71007_Desc = {
    Text = "정신력의 파도가 고대의 여파를 밀어오고, 은심에 깃든 혼이 고차원 의지를 비춘다."
