  CollectionHall_71026_Title = {
    Text = "안개 밤의 전투"
  },
  CollectionHall_71027_Desc = {
    Text = "진리가 문안에 숨겨져 있으며, 오직 “그분”이 숨을 쉬는 찰나에만 가면 뒤의 진실타래을 엿볼 수 있다. \nA.F.315  은열쇠 번호 K-0617  은문이 처음 열리다"
