  CollectionHall_71027_Title = {
    Text = "은열쇠로 처음 열린 문"
  },
  CollectionHall_71028_Desc = {
    Text = "왁스상관의 규칙은 세 가지입니다. 첫째, 왁스상을 만지지 말아야 합니다. 둘째, 왁스상의 덮개를 벗기지 말아야 합니다. 셋째, 피를 왁스상관에 떨어뜨리지 말아야 합니다. 반드시, 절대로 이 규칙들을 어기지 마세요."
