  },
  CollectionHall_71041_Desc = {
    Text = "수술대를 벗어날 수는 있어도, 빈민원을 벗어날 수 있을까? 안개를 벗어날 수는 있어도, 가난한 동쪽 지역을 벗어날 수 있을까? 아이들은 도망칠 곳이 없다."
