  CollectionHall_89342_Title = {
    Text = "기괴한 빛의 장막"
  },
  CollectionHall_89343_Desc = {
    Text = "혼의 깊은 곳에서 링크가 부르짖는다.\n기사단이 약속을 지키고 주군의 곁에 도착한다."
