  },
  CollectionHall_89343_Title = {
    Text = "먼 곳의 호출"
  },
  CollectionHall_89344_Desc = {
    Text = "검은 비닐 음반이 끈끈한 목을 찢어내며, 억지로 느끼는 슬픈 비명을 낸다."
