  },
  CollectionHall_89344_Title = {
    Text = "비명 경음"
  },
  CollectionHall_89345_Desc = {
    Text = "그녀는 인간으로서 죽는 것을 선택했고, 그 영혼을 담은 재는 결국 이 인간 형상의 관에 잠들게 되었다."
