  CollectionHall_89345_LockTip = {
    Text = "의식 잠수 “왜곡된 핵심” 어려움 난이도 완료"
  },
  CollectionHall_89345_Title = {
    Text = "혼의 잔재"
  },
  CollectionHall_89346_Desc = {
    Text = "괴물을 묶고 있던 족쇄가 파괴되었고, 죽일 수 없고 도망칠 수 없는 사냥꾼이 왔다."
  },
  CollectionHall_89346_LockTip = {
    Text = "조사 작전 4-16 완료 시 해제"
  },
  CollectionHall_89346_Title = {
    Text = "차원을 찢고 오다"
  },
  CollectionHall_89347_Desc = {
    Text = "사람들은 죄를 씻겠다며 서로 미리 싸우고, 순수하고 결점 없는 신국에 먼저 발을 내딛으려 합니다."
  },
  CollectionHall_89347_LockTip = {
    Text = "특파대 기록 “혈액의 색깔” 완료"
  },
  CollectionHall_89347_Title = {Text = "망상"},
  CollectionHall_89348_Desc = {
    Text = "아름답고! 풍요로우며! 이상적인 고향 리모리아! \n강력하고! 강인하며! 신왕의 보호를 받는 리모리아! \n위대하고! 위대하고! 영원한 나라 리모리아!"
  },
  CollectionHall_89348_LockTip = {
    Text = "조사 작전·어려움 5-10 완료 시 해제"
  },
  CollectionHall_89348_Title = {
    Text = "영원한 국토"
  },
  CollectionHall_89349_Desc = {
    Text = "버림과 배신은 고위자들의 일상이다. 그들에게 등지를 보이지 말고, 마지막의 빛과 열이 되는 것을 막아라."
  },
  CollectionHall_89349_LockTip = {
    Text = "조사 작전·어려움 3-10 완료 시 해제"
  },
  CollectionHall_89349_Title = {
    Text = "버림받은 자"
  },
  CollectionHall_89350_Desc = {
    Text = "그녀의 혼은 당신 뒤에 있으며, 당신 혼자서 지금 이 순간 유일한 성벽이고, 운명의 무력감이 당신을 꽉 잡고 있으므로, 당신은 그 결말을 바꿀 수 없다.\n그녀가 검은 조수에 잠식당한 결말."
  },
  CollectionHall_89350_LockTip = {
    Text = "의식 잠수 완료 “왜곡된 핵심”"
  },
  CollectionHall_89350_Title = {
    Text = "고독한 구원"
  },
  CollectionHall_89351_Desc = {
    Text = "너는 누군가가 네 귀에 부드럽게 속삭이는 소리를 들었고, 입안의 속삭임이 사각사각하게 들렸다.\n너는 그 모호한 말을 분별하려고 귀를 기울였고, 같은 사각사각한 소리가 고막 안쪽에서 들리자, 그것이 수많은 벌레의 날개가 함께 밀집해 진동하는 소리인 것을 깨달았다—촤르륵, 촤르륵, 집으로, 집으로."
  },
  CollectionHall_89351_LockTip = {
    Text = "조사 작전 성신편 2-18 완료 시 해제"
  },
  CollectionHall_89351_Title = {
    Text = "수많은 벌레 소리"
  },
  CollectionHall_89352_Desc = {
    Text = "인생의 중요한 순간에는, 항상 은은한 빗방울이 동반되는 듯하다.\n그 미세한 빗방울 속의 기억들과 이별하라. 만들어진 쓴 술은 마음 깊이 숨기고, 손에 쥔 은열쇠를 굳게 쥐어 새로운 여정을 시작하자.\n은열쇠가 우리를 인도하길."
  },
  CollectionHall_89352_LockTip = {
    Text = "조사 작전·어려움 성신편 1-10 완료 시 해제"
  },
  CollectionHall_89352_Title = {
    Text = "안녕, 피피"
  },
  CollectionHall_89353_Desc = {
    Text = "봄날의 따스한 태양, 꿈같은 궁전, 회전하는 드레스, 웃음이 넘치는 무도회, 그리고 아름답고 부드러운 공주. \n이 모든 것이 기사들이 지키고 싶은 것 전부이다."
  },
  CollectionHall_89353_LockTip = {
    Text = "의식 잠수 완료“기사의 소원”"
  },
  CollectionHall_89353_Title = {
    Text = "궁정 봄날 연회"
  },
  CollectionHall_89354_Desc = {
    Text = "핏물, 살육, 혁명...... 끝없는 황사 아래에 묻힌 것은 시간의 흐름 속에서 잔혹하고 흔한 역사다."
  },
  CollectionHall_89354_LockTip = {
    Text = "의식 잠수 “백색 후예” 어려움 완료"
  },
  CollectionHall_89354_Title = {
    Text = "황사 아래"
  },
  CollectionHall_89355_Desc = {
    Text = "어떻게 답해야 할지 모를 때는, 그냥 귀엽게 리액션하면 돼, 헤헤~"
  },
  CollectionHall_89355_LockTip = {
    Text = "조사 작전 3-14 완료 시 해제"
  },
  CollectionHall_89355_Title = {Text = "아이헤~"},
  CollectionHall_89356_Desc = {
    Text = "전략적 후퇴는 부끄럽지만 유용하다."
  },
  CollectionHall_89356_LockTip = {
    Text = "의식 잠수 완료 “백색 후예”"
  },
  CollectionHall_89356_Title = {
    Text = "미로 탈출"
  },
  CollectionHall_89357_Desc = {
    Text = "심연에서 피어난 순백의 꽃이 여러 사람 앞을 단단히 막고 있다.\n“이렇더라도, 그것은 내가 유일한 엄마야.”\n“내 엄마——돌려줘!”"
  },
  CollectionHall_89357_LockTip = {
