  },
  CollectionHall_89359_Title = {
    Text = "눈 속의 소녀"
  },
  CollectionHall_89360_Desc = {
    Text = "주민들은 열정적으로 손님들과 어울렸다."
  },
  CollectionHall_89360_LockTip = {
    Text = "조사 작전 3-14 완료 시 해제"
  },
  CollectionHall_89360_Title = {
    Text = "“환대하는” 주민"
  },
  CollectionHall_89361_Desc = {
    Text = "하늘은 이미 존귀한 신모를 내려주셔서, 우리를 그의 나라로 인도하고자 합니다.\n「우리 주님」을 찬양합니다!"
  },
  CollectionHall_89361_LockTip = {
    Text = "조사 작전 5-15 완료 시 해제"
  },
  CollectionHall_89361_Title = {
    Text = "존엄한 신모"
  },
  CollectionHall_89362_Desc = {
    Text = "충실타래하고 용감한 개는 스스로 훈련 계획을 세우고, 모든 슬픔과 피로를 위로해 줄 수 있습니다. 단지 당신의 격려의 눈빛이 필요할 뿐입니다."
  },
  CollectionHall_89362_LockTip = {
    Text = "의식 잠수 완료“기사의 소원”"
  },
  CollectionHall_89362_Title = {
    Text = "강아지 훈련"
  },
  CollectionHall_89363_Desc = {
    Text = "그 어리숙한 기사, 창보다도 큰 모습이 아니지만, 공주에게 서약한 모든 말을 부끄럽지 않게 지키고 있다."
  },
  CollectionHall_89363_LockTip = {
    Text = "의식 잠수 완료“기사의 소원”"
  },
  CollectionHall_89363_Title = {
    Text = "부끄럽지 않은 영광"
  },
  CollectionHall_89364_Desc = {
    Text = "원거리 항해하는 배가 사람들을 어디로 데려가나요?\n그 순백의 여신이 높은 마스트 위에서 노래하고 있습니다.\n탐욕, 망상, 투쟁 그리고 배신, 그녀는 모두 무시하고, 그녀는 운명의 뒤집힘을 노래하지 않고, 그저 늙은 선장의 귀환만 노래합니다"
  },
  CollectionHall_89364_LockTip = {
    Text = "조사 작전 5-15 완료 시 해제"
  },
  CollectionHall_89364_Title = {
    Text = "심포의 유령선"
  },
  CollectionHall_89365_Desc = {
    Text = "제발… 누구든지 좋으니… 나를 구해줘…"
  },
  CollectionHall_89365_LockTip = {
    Text = "조사 작전·어려움 3-10 완료 시 해제"
  },
  CollectionHall_89365_Title = {
    Text = "홈리스를 잃은 아이"
  },
  CollectionHall_89366_Desc = {
    Text = "위대한 아버지여, 당신의 빛이 세상을 비추기를."
  },
  CollectionHall_89366_LockTip = {
    Text = "특파대 기록 “혈액의 색깔” 완료"
  },
  CollectionHall_89366_Title = {
    Text = "창백한 성인"
  },
  CollectionHall_89367_Desc = {
    Text = "물결이 솟구치고, 날카로운 외침이 울려 퍼지며, 고통스러운 기억이 마음에 밀려들어 소녀의 정신을 갈갈이 찢습니다. 그녀의 눈가에서 흐르는 검은 눈물은 그녀의 소리 없는 도움 요청입니다."
  },
  CollectionHall_89367_LockTip = {
    Text = "조사 작전·어려움 3-10 완료 시 해제"
  },
  CollectionHall_89367_Title = {
    Text = "고통스러운 기억"
  },
  CollectionHall_89368_Desc = {
    Text = "그녀가 어떻게 글을 써도, 일기에 검은 결함만 남길 뿐이다."
  },
  CollectionHall_89368_LockTip = {
    Text = "조사 작전 4-16 완료 시 해제"
  },
  CollectionHall_89368_Title = {
    Text = "내리지 않은 눈"
  },
  CollectionHall_89369_Desc = {
    Text = "달빛이 밤하늘에 쏟아지며, 바람이 영원한 속삭임을 읊조리고, 얼룩진 거대한 배가 천천히 앞으로 나아갑니다.\n 당신은 안개가 자욱한 갑판 위에 서서 혼자서 난해한 야곡을 엮고 있습니다."
  },
  CollectionHall_89369_LockTip = {
    Text = "조사 작전 5-15 완료 시 해제"
  },
  CollectionHall_89369_Title = {Text = "대항해"},
  CollectionHall_89370_Desc = {
    Text = "그것은 살아 있는 묘비들이며, 각 알껍질에 그들의 묘비명이 새겨져 있다.\n그들은 희망을 가득 담고, 존경의 마음으로 이웃의 무덤으로 들어간다."
  },
  CollectionHall_89370_LockTip = {
    Text = "조사 작전 성신편 2-18 완료 시 해제"
  },
  CollectionHall_89370_Title = {
    Text = "점성 묘비"
  },
  CollectionHall_89371_Desc = {
    Text = "은은한 향기, 다채로운 상품, 하지만 과연 몇 사람이 수선 부인이 제시한 가격을 지불할 수 있을까?"
  },
  CollectionHall_89371_LockTip = {
    Text = "조사 작전 3-14 완료 시 해제"
  },
  CollectionHall_89371_Title = {
    Text = "수선화 작은 집"
  },
  CollectionHall_89372_Desc = {
    Text = "따뜻한 두 손이 소녀의 머리 위를 부드럽게 어루만지며, 불안한 마음을 달래준다."
  },
  CollectionHall_89372_LockTip = {
    Text = "조사 작전 3-14 완료 시 해제"
  },
  CollectionHall_89372_Title = {
    Text = "걱정하지 마세요, 제가 있으니"
  },
  CollectionHall_89373_Desc = {
    Text = "시간이 울부짖고, 시간은 포효하며, 시간은 세 번 사냥감을 잃은 자를 쫓고 있다. 도망치려 하지 마십시오, 결과는 이미 정해져 있으니."
  },
  CollectionHall_89373_LockTip = {
    Text = "조사 작전·어려움 4-12 완료 시 해제"
  },
  CollectionHall_89373_Title = {
    Text = "인과의 괴물"
  },
  CollectionHall_89374_Desc = {
    Text = "심판은 멈추지 않으며, 심판은 반드시 집행되어야 한다.\n괴물들은 거울에서 탄생하고, 자신의 혈육으로 심지하여 정화의 불꽃을 세상에 퍼뜨린다."
  },
  CollectionHall_89374_LockTip = {
    Text = "특파대 기록 “혈액의 색깔” 어려움 완료"
  },
  CollectionHall_89374_Title = {
    Text = "혈육의 등불"
  },
  CollectionHall_89375_Desc = {
    Text = "입장과 의지가 충돌할 때, 인류는 종종 자신의 기준만을 확신할 뿐이다.\n대부분의 사람들에게 자신이 믿는 것이 유일한 정의다."
  },
  CollectionHall_89375_LockTip = {
    Text = "조사 작전 4-16 완료 시 해제"
  },
  CollectionHall_89375_Title = {
    Text = "대립하는 정의"
  },
  CollectionHall_89376_Desc = {
    Text = "만남은 너무 이르고, 진실타래은 너무 늦어, 잔인한 현실타래에 찢겨진 영혼이 어린 두 손의 한가운데에서 점차 치유되고 있다.\n눈보라를 넘어 서로를 쫓는 두 사람은 마침내 시간을 초월하는 틈새에서 서로를 안고 울었다."
  },
  CollectionHall_89376_LockTip = {
    Text = "조사 작전 4-16 완료 시 해제"
  },
  CollectionHall_89376_Title = {
    Text = "예기치 않은 재회"
  },
  CollectionHall_89377_Desc = {
    Text = "귀부인으로서, 물론 항상 우아함을 유지해야 합니다!\n물론 제 말은, 귀부인이 하는 일은 뭐든 우아하다는 거예요!"
  },
  CollectionHall_89377_LockTip = {
    Text = "조사 작전 5-15 완료 시 해제"
  },
  CollectionHall_89377_Title = {
    Text = "심해의 숙녀"
  },
  CollectionHall_89378_Desc = {
    Text = "따뜻한 벽난로가 모든 손님을 환영한다. 하지만 조심하라, 밤에는 악성 개가 있으니 밖에 나가지 마라."
  },
  CollectionHall_89378_LockTip = {
    Text = "조사 작전 3-14 완료 시 해제"
  },
  CollectionHall_89378_Title = {
    Text = "눈 내리는 작은 마을"
  },
  CollectionHall_89379_Desc = {
    Text = "이 시간조차도 가둘 수 있는 문 뒤엔, 한 어머니가 그녀의 사랑하는 딸을 지키기 위해 내린 마지막 선택이 있다.\n“나는 당신을 사랑해, 릴리.”"
  },
  CollectionHall_89379_LockTip = {
    Text = "조사 작전·어려움 4-12 완료 시 해제"
  },
  CollectionHall_89379_Title = {
    Text = "영원한 감옥"
  },
  CollectionHall_89380_Desc = {
    Text = "사냥, 도망, 응고된 모성애가 생사를 초월한 포옹입니다."
  },
  CollectionHall_89380_LockTip = {
    Text = "조사 작전 4-16 완료 시 해제"
  },
  CollectionHall_89380_Title = {
    Text = "왜곡된 미치광이 정신병원"
  },
  CollectionHall_89381_Desc = {
    Text = "전능하신 주여, 저에게 마땅한 형벌을 주십시오."
  },
  CollectionHall_89381_LockTip = {
    Text = "특파대 기록 “혈액의 색깔” 완료"
  },
  CollectionHall_89381_Title = {
    Text = "맹목적인 성도"
  },
  CollectionHall_89382_Desc = {
    Text = "그때, 어머니는 책 페이지를 넘기며 아이에게 동화를 이야기해주었다.\n오후의 온도는 시간을 넘어, 이 좁은 시간에 흐른다."
  },
  CollectionHall_89382_LockTip = {
    Text = "조사 작전 4-16 완료 시 해제"
  },
  CollectionHall_89382_Title = {
    Text = "오후의 동화"
  },
  CollectionHall_89383_Desc = {
    Text = "자신을 어떻게 속여야 꺼진 불씨에서 생명이 계속되고 있다고 상상할 수 있을까요.\n그녀는 칠흑의 번데기와 끈적한 붉은 속에서 꿈속에서 먼 별을 응시하고 있습니다.\n“너무 추워, 하지만 이전의 따뜻함은 어디에 있을까요?”"
  },
  CollectionHall_89383_LockTip = {
    Text = "조사 작전 성신편 2-18 완료 시 해제"
  },
  CollectionHall_89383_Title = {
    Text = "재의 환상"
  },
  CollectionHall_89384_Desc = {
    Text = "높이 노래하라, 높이 노래하라!\n녹아내린 기계의 선율이 천지를 울리게 하고, 영원한 어둠이라 불리는 종말을 찬양하라!"
  },
  CollectionHall_89384_LockTip = {
    Text = "조사 작전·어려움 성신편 1-10 완료 시 해제"
  },
  CollectionHall_89384_Title = {
    Text = "융화를 통한 종말의 찬가"
  },
  CollectionHall_89385_Desc = {
    Text = "혈육이 흩날리고, 날카로운 칼날이 난무하며, 괴물은 이해할 수 없는 언어로 크게 노래합니다。광포한 뇌리에는 단 하나의 생각만 남습니다 — 그녀를 붙잡아라, 어떤 대가를 치르더라도 그녀를 붙잡아라。"
  },
  CollectionHall_89385_LockTip = {
    Text = "조사 작전·어려움 3-10 완료 시 해제"
  },
  CollectionHall_89385_Title = {
    Text = "광란 집착"
  },
  CollectionHall_89386_Desc = {
    Text = "봐라, 스칼렛 달이 이미 떠올랐다, 모든 죄인들은 정화될 것이다."
  },
  CollectionHall_89386_LockTip = {
    Text = "특파대 기록 “혈액의 색깔” 완료"
  },
  CollectionHall_89386_Title = {Text = "혈월"},
  CollectionHall_89387_Desc = {
    Text = "자비로운 아버지여, 나는 내 뼈와 피를 태우고, 내 영혼을 소각하여 「백염」을 점화할 장작으로 삼겠습니다.\n 모든 고통을 내게 부과해 주세요, 그러면 길을 잃은 아이들이 계속해서 길을 나아갈 수 있을 것입니다."
  },
  CollectionHall_89387_LockTip = {
    Text = "특파대 기록 “혈액의 색깔” 어려움 완료"
  },
  CollectionHall_89387_Title = {Text = "신은"},
  CollectionHall_89388_Desc = {
    Text = "램프는 모든 악을 추방할 것입니다.\n당신은 경건히 회개하고, 피를 흘려야만 죄악을 제거하고 천국으로 올라갈 수 있습니다."
  },
  CollectionHall_89388_LockTip = {
    Text = "특파대 기록 “혈액의 색깔” 완료"
  },
  CollectionHall_89388_Title = {
    Text = "등불의 빛이 오래도록 밝게"
  },
  CollectionHall_89389_Desc = {
    Text = "너는 나에게 약속했지, 너희는 나에게 약속했지.\n만약 내가 리모리아를 구할 수 없다면, 함께 묻히자고!"
  },
  CollectionHall_89389_LockTip = {
    Text = "조사 작전·어려움 5-10 완료 시 해제"
  },
  CollectionHall_89389_Title = {
    Text = "제멋대로 판단하기"
  },
  CollectionHall_89390_Desc = {
    Text = "진정한 기사라면 승리를 가져올 수 없다면, 수호자의 앞에서 전사해야 합니다."
  },
  CollectionHall_89390_LockTip = {
    Text = "의식 잠수 “기사의 소원” 어려움 완료"
  },
  CollectionHall_89390_Title = {
    Text = "후회 없는 뒷모습"
  },
  CollectionHall_89391_Desc = {
    Text = "붕괴의 음표가 춤추고, 무너지는 현실타래이 떠들썩하게 펼쳐진다.\n꿈의 촉수조차 이곳에 닿지 않는다."
  },
  CollectionHall_89391_LockTip = {
    Text = "조사 작전 성신편 1-14 완료 시 해제"
  },
  CollectionHall_89391_Title = {
    Text = "붕괴 변주"
  },
  CollectionHall_89392_Desc = {
    Text = "심해의 숙녀는 자신의 의지를 관철하기로 결심하고, 닿을 수 없는 자유를 향해 나아간다."
  },
  CollectionHall_89392_LockTip = {
    Text = "조사 작전·어려움 5-10 완료 시 해제"
  },
  CollectionHall_89392_Title = {
    Text = "바다를 덮는 결의"
  },
  CollectionHall_89393_Desc = {
    Text = "나는 너를 데려가려 한다. '주인'에게 데려가려 하며, 그렇게 해야……"
  },
  CollectionHall_89393_LockTip = {
    Text = "조사 작전 3-14 완료 시 해제"
  },
  CollectionHall_89393_Title = {
    Text = "혈육 같은 뿌리"
  },
  CollectionHall_89394_Desc = {
    Text = "당신이 싸우는 대상은 수많은 마음이 하나로 합쳐진 영혼입니다. 그들은 당신을 저항하고, 당신을 초대합니다. 무의미한 자아를 내려놓고, 당신의 무지한 두뇌를 카페 앞에 함께 놓아 영원히 외롭지 않은 집단에 참여하세요."
  },
  CollectionHall_89394_LockTip = {
    Text = "조사 작전·어려움 성신편 2-12 완료 시 해제"
  },
  CollectionHall_89394_Title = {
    Text = "군집 의지"
  },
  CollectionHall_89395_Desc = {
    Text = "아이야, 나를 도와줄 수 있니?"
  },
  CollectionHall_89395_LockTip = {
    Text = "특파대 기록 “혈액의 색깔” 완료"
  },
  CollectionHall_89395_Title = {
    Text = "이타적인 선"
  },
  CollectionHall_89396_Desc = {
    Text = "내 손을 잡아라, 기억 속 그 사라지지 않는 꽃을 가져가라.\n결코 뒤돌아보지 말고 앞으로 나아가라, 우리는 반드시 도달할 것이다. 그 빛나는 은빛의 문에."
  },
  CollectionHall_89396_LockTip = {
    Text = "조사 작전 성신편 2-18 완료 시 해제"
  },
  CollectionHall_89396_Title = {
    Text = "내 마음이 향하는 곳"
  },
  CollectionHall_89397_Desc = {
    Text = "여기 생산되는 것은 일반 산업품이 아니다."
  },
  CollectionHall_89397_LockTip = {
    Text = "조사 작전 성신편 1-14 완료 시 해제"
  },
  CollectionHall_89397_Title = {
    Text = "뇌수 제조"
  },
  CollectionHall_89398_Desc = {
    Text = "먼 하늘의 검은 종말은 하늘의 구멍처럼 보입니다.\n그곳은 밝혀지지 않은 땅에서 온 토템입니다."
  },
  CollectionHall_89398_LockTip = {
    Text = "조사 작전 성신편 1-14 완료 시 해제"
  },
  CollectionHall_89398_Title = {
    Text = "검은 태양 토템"
  },
  CollectionHall_89399_Desc = {
    Text = "회색 안개가 검은 태양을 덮고, 먼지가 입과 코를 가득 채운다.\n입을 벌리지 마라——희망은 이전에 묻혔다."
  },
  CollectionHall_89399_LockTip = {
    Text = "조사 작전 성신편 1-14 완료 시 해제"
  },
  CollectionHall_89399_Title = {
    Text = "질식의 연기와 먼지"
  },
  CollectionHall_89400_Desc = {
    Text = "너의 두개골을 열고 수많은 뇌와 공명하라.\n답은 아마 그 중에 숨겨져 있을지도 모른다."
  },
  CollectionHall_89400_LockTip = {
    Text = "조사 작전·어려움 성신편 1-10 완료 시 해제"
  },
  CollectionHall_89400_Title = {
    Text = "두개골 공명"
  },
  CollectionHall_89401_Desc = {
    Text = "겨울, 마녀, 아이들, 끝없이 내리는 눈."
  },
  CollectionHall_89401_LockTip = {
    Text = "조사 작전 3-14 완료 시 해제"
  },
  CollectionHall_89401_Title = {
    Text = "눈 내리는 소비자 그림자 마을"
  },
  CollectionHall_89402_Desc = {
    Text = "괴이한 속삭임이 공기 중에 메아리치고, 검은 점성이 희생을 포식하며, 옛날의 존재는 신의 귀환을 기대하고 있다."
  },
  CollectionHall_89402_LockTip = {
    Text = "조사 작전 4-16 완료 시 해제"
  },
  CollectionHall_89402_Title = {
    Text = "극지 제단"
  },
  CollectionHall_89403_Desc = {
    Text = "빛은 어둠을 몰아내고 모든 아이를 평등하게 비춥니다.\n그것은 창백하고 허약하지만, 무한히 따뜻하고 힘이 가득합니다.\n이 미약한 빛이 당신의 고통을 없애고 당신의 마음을 치유해 줄 수 있기를, 나의 아이여."
  },
  CollectionHall_89403_LockTip = {
    Text = "특파대 기록 “혈액의 색깔” 어려움 완료"
  },
  CollectionHall_89403_Title = {
    Text = "구세의 백염"
  },
  CollectionHall_89404_Desc = {
    Text = "열차가 갑자기 멈췄고, 쌍둥이는 혈통의 기운을 쫓아 다가왔습니다."
  },
  CollectionHall_89404_LockTip = {
    Text = "조사 작전 3-14 완료 시 해제"
  },
  CollectionHall_89404_Title = {Text = "급 정지"},
  CollectionHall_89405_Desc = {
    Text = "왕이여, 저는 예언을 따라 만 년을 기다려왔습니다. 그러나 미래는 왜 여전히 손이 닿지 않을까요? \n저는 계속 기도해야 했겠지만, 죄송합니다, 저는 기다릴 수 없었습니다."
  },
  CollectionHall_89405_LockTip = {
    Text = "조사 작전 5-15 완료 시 해제"
  },
  CollectionHall_89405_Title = {
    Text = "수많은 기도"
  },
  CollectionHall_89406_Desc = {
    Text = "비천한 도둑이 왕의 힘을 훔쳐, 위대한 의식을 방해하려 했습니다.\n불경한 위조품은 죽음으로 보답해야 합니다!"
  },
  CollectionHall_89406_LockTip = {
    Text = "조사 작전·어려움 5-10 완료 시 해제"
  },
  CollectionHall_89406_Title = {
    Text = "신을 모독하는 맹세"
  },
  CollectionHall_89407_Desc = {
    Text = "그 짙고 보이지 않는 태양의 안개 속에서, 나는 혼자서 미지의 길을 향해 나아갈 것이다.\n나는 그 안개 속에서 먼지와 피와 불꽃을 움켜잡아, 외롭고 막연한 슬픔의 눈물들을 잠재울 것이다.\n나는 더 이상 두려워하지 않을 것이다. 영원한 태양이 내 마음속에 이미 높이 걸려 있기 때문이다."
  },
  CollectionHall_89407_LockTip = {
    Text = "조사 작전 성신편 2-18 완료 시 해제"
  },
  CollectionHall_89407_Title = {
    Text = "나는 가겠다"
  },
  CollectionHall_89408_Desc = {
    Text = "아이들은 모두 들었다: 태양을 육안으로 바라보지 마라.\n지금 이 순간에도, 그분은 이미 타락해있다."
  },
  CollectionHall_89408_LockTip = {
    Text = "조사 작전 성신편 1-14 완료 시 해제"
  },
  CollectionHall_89408_Title = {
    Text = "검은 태양의 시대를 부활시키다"
  },
  CollectionHall_89409_Desc = {
    Text = "클레멘틴 의사의 개인 신경 요양원에 오신 것을 환영합니다. 의사의 안내에 따라 마음속의 모든 고통을 풀어내고 궁극적인 치유로 나아가세요."
  },
  CollectionHall_89409_LockTip = {
    Text = "조사 작전 성신편 2-18 완료 시 해제"
  },
  CollectionHall_89409_Title = {
    Text = "환상적인 벌레 둥지의 꿈"
  },
  CollectionHall_89410_Desc = {
    Text = "한때의 영광은 지나갔고, 이제 기억 속의 단편적인 벽과 잔해만 남아 있습니다."
  },
  CollectionHall_89410_LockTip = {
    Text = "의식 잠수 완료 “백색 후예”"
  },
  CollectionHall_89410_Title = {
    Text = "과거의 여명"
  },
  CollectionHall_89411_Desc = {
    Text = "너는 심연에 잠겨, 주머니에서 그녀의 마지막 메시지가 날아갔다. 그리고 끊임없는 어둠 속에서, 잠깐의 빛을 보았다."
  },
  CollectionHall_89411_LockTip = {
    Text = "조사 작전·어려움 성신편 2-12 완료 시 해제"
  },
  CollectionHall_89411_Title = {Text = "탈피"},
  CollectionHall_89412_Desc = {
    Text = "한때 너의 앞에 있었던, 이제 너의 뒤에 있습니다.\n 너는 항상 전력을 다해 달린 후, 그 시공의 끝에서 기다리는 반드시 그 익숙한 따뜻한 손일 것이라고 믿어왔습니다."
  },
  CollectionHall_89412_LockTip = {
    Text = "조사 작전·어려움 성신편 2-12 완료 시 해제"
  },
  CollectionHall_89412_Title = {
    Text = "변하지 않는 선택"
  },
  CollectionHall_89413_Desc = {
    Text = "지하철에서 공격을 당하는 것은 불행하지만, 소녀의 호기심을 만족시키기 위한 여흥 프로그램으로서는 적절했다."
  },
  CollectionHall_89413_LockTip = {
    Text = "조사 작전 3-14 완료 시 해제"
  },
  CollectionHall_89413_Title = {
    Text = "터널 모험기"
  },
  CollectionHall_89414_Desc = {
    Text = "영웅과 공주가 밤하늘 아래 달려갑니다. 발 아래의 자갈들이 삶의 기쁨을 이야기하고, 천 년 동안 갇혀 있었던 그 마음도 별똥별의 지나감과 함께 천천히 뛰기 시작합니다."
  },
  CollectionHall_89414_LockTip = {
    Text = "의식 잠수 “백색 후예” 어려움 완료"
  },
  CollectionHall_89414_Title = {
    Text = "두 사람의 유성"
  },
  CollectionHall_89415_Desc = {
    Text = "말이 필요 없어요. 여기 오면 가장 진실타래한 도움을 받을 수 있습니다.\n그 미소를 띤 길잡이가 당신에게 손을 내밀었고, 그녀는 당신이 스스로도 깨닫지 못한 마음의 밀림 깊숙이 데려갈 것입니다."
  },
  CollectionHall_89415_LockTip = {
    Text = "조사 작전 성신편 2-18 완료 시 해제"
  },
  CollectionHall_89415_Title = {
    Text = "정신의 밀림"
  },
  CollectionHall_89416_Desc = {
    Text = "강계의 첫 번째 아침빛이 미로로 비추어질 때, 천 다리의 공주가 천 년 동안 잠들었던 신도를 맞이하게 되었다."
  },
  CollectionHall_89416_LockTip = {
    Text = "의식 잠수 완료 “백색 후예”"
  },
  CollectionHall_89416_Title = {
    Text = "캄브리안의 아침 해"
  },
  CollectionHall_89417_Desc = {
    Text = "천재의 사고회로는 항상 구불구불하고, 비틀리고, 남들과 다르지만, 그게 바로 그녀의 사랑스러운 부분이 아닌가요?"
  },
  CollectionHall_89417_LockTip = {
    Text = "의식 잠수 완료 “왜곡된 핵심”"
  },
  CollectionHall_89417_Title = {
    Text = "천재의 고민"
  },
  CollectionHall_89418_Desc = {
    Text = "나와 함께 게임을 해보아요. 걱정 마세요, 그리 위험하지 않아요. 단지 지루한 시간을 보내기 위해서에요."
  },
  CollectionHall_89418_LockTip = {
    Text = "의식 잠수 완료 “백색 후예”"
  },
  CollectionHall_89418_Title = {
    Text = "수수께끼 게임"
  },
  CollectionHall_89419_Desc = {
    Text = "환광의 해조가 천체의 인력에 의해 휘날려져 장막을 짠다. 바다를 밟는 괴물이 물결을 타고 온다."
  },
  CollectionHall_89419_LockTip = {
    Text = "조사 작전 5-15 완료 시 해제"
  },
  CollectionHall_89419_Title = {
    Text = "환해 조수"
  },
  CollectionHall_89420_Desc = {
    Text = "왕은 최고이시며, 왕의 권위는 무한합니다. 왕은 찬란함의 정점에 앉아, 외롭게 그의 나라를 내려다보고 있습니다."
  },
  CollectionHall_89420_LockTip = {
    Text = "조사 작전 5-15 완료 시 해제"
  },
  CollectionHall_89420_Title = {
    Text = "심연의 왕에게 잠든"
  },
  CollectionHall_89706_Desc = {
    Text = "<Title:소개>\n고아, 출신 불명의 배를 타고 자란 아이. 기억이 시작될 때부터 선원들에게 양육받으면서 배 위에서 생활한다.\n이러한 경험 덕분에 클퍼산트는 어렸을 때부터 바다에 대한 갈망과 호기심이 넘쳤다.\n그녀가 성장하면서, 당연히 바다와 배와 관련된 직업인 항해사를 선택했다.\n그 이후, 바다를 사랑하는 소녀는 영원히 바다 위를 떠돌며, 별들과 함께 배의 방향을 인도할 것이다.\n그녀는 바다에서, 배 위에서 「태어난다」.\n그녀는 바다에서, 배 위에서 「죽는 것」을 두려워하지 않는다.\n이것이 그녀의 삶이다."
  },
  CollectionHall_89706_LockTip = {
    Text = "「클레포산트」를 깨어남한 후 해제"
  },
  CollectionHall_89706_Title = {
    Text = "코퍼산트"
  },
  CollectionHall_89968_Desc = {
    Text = "살육, 증오, 광기와 고통, 전장은 이러한 것들이 부족하지 않습니다. 당신이 괴물의 카드 게임에 목숨을 걸 때, 그 끔찍한 스칼렛 소용돌이를 일으킬 것임을 잘 생각해야 합니다."
  },
  CollectionHall_89968_LockTip = {
    Text = "완료 의식 잠수 “피와 모래”"
  },
  CollectionHall_89968_Title = {
    Text = "선홍의 소용돌이"
  },
  CollectionHall_89969_Desc = {
    Text = "전설에 따르면, 항해사가 죽은 후에는 마스트 위에서 푸른 흰색의 빛으로 변해 배의 항해를 계속 인도한다고 한다.\n그럼 그녀가 마스트 꼭대기에서 자신의 생명을 점화할 때, 그 희망의 귀환 길을 보았을까?"
  },
  CollectionHall_89969_LockTip = {
    Text = "의식 잠수 「마지막의 인도」를 완료했다"
  },
  CollectionHall_89969_Title = {
    Text = "성 에를모의 불"
  },
  CollectionHall_89970_Desc = {
    Text = "그녀는 태생부터 증오와 살육, 끝없는 전투로 가득 차 있는 운명을 지니고 있다.\n그녀가 모든 부드럽고 따뜻한 환영을 버리고 칼과 총을 들 때, 운명의 카르멘은 이미 그녀를 위해 연주되었다.\n그녀는 적의 피로 증오를 씻어내며, 아마도 영광스럽지 않을지라도 두려움 없이 후회 없는 삶을 살게 될 전사로 운명 지어졌다."
  },
  CollectionHall_89970_LockTip = {
    Text = "특파대 기록 “엘워스의 귀인”을 완료했습니다"
  },
  CollectionHall_89970_Title = {
    Text = "피로 원한을 씻는다"
  },
  CollectionHall_89971_Desc = {
    Text = "핏빛 저녁 노을 아래, 피로 물든 황사를 비추고 있습니다.\n가장 강력한 전사가 밤으로 가라앉을 전장에서 금색 불꽃과 영광을 회상합니다.\n수많은 비명 지르는 독수리가 날아오르며 마지막 햇빛을 가립니다. 위대한 동정 아래, 사막 가득이 보이던 영혼들이 그와 함께 매장됩니다."
  },
  CollectionHall_89971_LockTip = {
    Text = "의식 잠수 “피와 모래” 어려움 완료"
  },
  CollectionHall_89971_Title = {
    Text = "피의 햇살을 받다"
  },
  CollectionHall_89972_Desc = {
    Text = "만약 이 세상이 어둠에 휘말린다면, 내가 마지막의 횃불이 되리라.\n만약 인파 속에 정의가 더 이상 없다면, 내가 가장 약한 자를 위해 소리치리라."
  },
  CollectionHall_89972_LockTip = {
    Text = "의식 잠수 「마지막의 인도」를 완료했다"
  },
  CollectionHall_89972_Title = {
    Text = "길고 긴 밤의 불빛"
  },
  CollectionHall_89973_Desc = {
    Text = "그것은 그녀의 숙명 있는 전투이며, 그녀가 나아가야 할 전장입니다.\n그녀는 모든 나약함, 주저함, 두려움을 과거와 함께 버립니다.\n후회하지 않음은, 그녀가 이 생의 전투의 진리를 깨달았기 때문입니다.\n그녀는 혼자가 아니며, 손에 쥔 검의 날이 반사한 것은 또 다른 자기 자신이 미친 얼굴이었습니다."
  },
  CollectionHall_89973_LockTip = {
    Text = "특파대 기록 “엘워스의 귀인” 어려움 완료"
  },
  CollectionHall_89973_Title = {
    Text = "산들에 질문하다"
  },
  CollectionHall_89974_Desc = {
    Text = "헤이요, 헤이요, 배의 닻을 올리고, 돛을 올리며, 마지막 로프를 풀어.\n우리의 항해자가 이미 마스트에 올라가고, 화려한 깃발이 높이 걸려 있습니다.\n출항하자, 출항하자, 그녀가 가리키는 방향으로 우리는 출항할 것입니다!"
  },
  CollectionHall_89974_LockTip = {
    Text = "의식 잠수 「마지막의 인도」를 완료했다"
  },
  CollectionHall_89974_Title = {
    Text = "항해일지"
  },
  CollectionHall_89975_Desc = {
    Text = "그녀는 매 항해할 때마다 최신의 유서 준비를 해둡니다.\n 그 세대에서 전해져 내려온 노래는 꿈속의 자장가처럼 그녀의 영혼을 부드럽게 감싸줍니다.\n 화려한 깃발이 바람에 흔들리고, 그녀의 육체는 와해되거나 부패하거나 깊은 바다에 잠길 수 있지만, 그녀의 영혼은 반드시 그녀의 배 위에 서서 별과 바다에 영원한 빛을 발산할 것입니다."
  },
  CollectionHall_89975_LockTip = {
    Text = "의식 잠수 「마지막의 인도」를 완료했다"
  },
  CollectionHall_89975_Title = {
    Text = "항해사 만가"
  },
  CollectionHall_89976_Desc = {
    Text = "쿠시사막에서는 바람과 모래가 끊임없이 불며, 하늘을 나는 모래가 살아 있는 자의 입과 코 안으로 쏟아지고, 죽은 이름조차 모르는 시체를 묻습니다.\n오직 살육을 갈망하는 야수만이 바람 속에서 그 달콤한 향연의 기미를 찾아냅니다."
  },
  CollectionHall_89976_LockTip = {
    Text = "완료 의식 잠수 “피와 모래”"
  },
  CollectionHall_89976_Title = {
    Text = "황사와 야수"
  },
  CollectionHall_89977_Desc = {
    Text = "사막의 태양은 다른 곳과 다르며, 그것은 창백하고 눈부시며 혹독하여, 결코 온화한 면이 없었습니다. 짐승들은 너가 입에 담는 봄을 상상할 수 없으니, 그러니 그들을 대신하여 그 실타래제 태양을 보아줄 수 있는가."
  },
  CollectionHall_89977_LockTip = {
    Text = "완료 의식 잠수 “피와 모래”"
  },
  CollectionHall_89977_Title = {
    Text = "없던 피와 모래"
  },
  CollectionHall_89978_Desc = {
    Text = "눈보라가 끝없이 내리고, 전투원의 머리카락을 서리로 덮습니다.\n 그녀의 평생의 기억이 이 순간에 흐르고, 그녀는 사람의 마음 깊은 곳을 지나가며, 거대한 산속으로 향하고 있습니다.\n 배신, 버림과 보호, 모든 고통과 분노는 단지 한 번 또 한 번의 전투에 지나지 않습니다. 사람과, 산과, 자신과.\n 그녀는 자신의 인도자를 바라보고, 낯선 듯 익숙한 새로운 동료를 바라보며, 서툰 미소를 짓습니다.\n 그녀는 언젠가 승리할 수 있거나, 영원히 전장에서 쓰러질 수 있지만, 천국에 오르거나 지옥에 떨어지는 그 순간에도 손에 쥔 칼날을 놓지 않을 것입니다.\n 다시는 모든 것을 잃지 않기 위해, 이번에는 복수 전에 수호의 검을 들어홀로 자신의 전장으로 나아갑니다."
  },
  CollectionHall_89978_LockTip = {
    Text = "특파대 기록 “엘워스의 귀인”을 완료했습니다"
  },
  CollectionHall_89978_Title = {
    Text = "잃어버리지 않을 내일을 위해"
  },
  CollectionHall_89998_LockTip = {
    Text = "제한 시간 이벤트「신국의 그림자를 엿보는：비상 해조」의 임의의 스테이지를 클리어해야 합니다"
  },
  CollectionHall_89998_Title = {
    Text = "신국의 그림자를 엿보라 : 이변 해조"
  },
  CollectionHall_89999_LockTip = {
    Text = "제한된 시간 동안의 활동「거울 던전 포로：푸른 하늘로의 도약」어느 스테이지나 클리어 필요"
  },
  CollectionHall_89999_Title = {
    Text = "거울 던전 포로：푸른 하늘로의 도약"
  },
  CollectionHall_90245_LockTip = {
    Text = "이몽 시야「천변 저편·상」의 첫 번째 카드를 클리어하여 잠금 해제됩니다"
  },
  CollectionHall_90245_Title = {
    Text = "새가 히치코크의 결말에 이르지 못했을 때"
  },
  CollectionHall_90415_Title = {
    Text = "하늘의 저편·상"
  },
  CollectionHall_90416_Desc = {
    Text = "<Title:개요>\n등불 교회가 신 강림 의식을 위해 양성한 일련의 실타래험체 중 하나로서, 쌍둥이로 태어나 다행히 쓰레기 더미에 버려지는 운명에서 벗어났다.\n어릴 때부터 동생 폴뤼크스와 함께 성자로 존경받으며 엄격한 훈련을 받았고, 온종일 등불을 든 자에 관한 신학을 주입받았으며, 외부 세계에 관한 유일한 정보는 신자들이 바친 정교한 두꺼운 필사본 한 권이었다.\n소년 시절 동생이 교회의 잔혹한 개조 의식 이후, 두 사람은 함께 탈출하여 자유를 찾기로 결정했지만 곧 다시 붙잡혔다.\n그는 '죄의 웅덩이'라는 부식된 물탱크에 잠겨 '죄악 치료법'으로 상처를 치유받고 오랜 고통을 겪었다.\n결국 유리에트를 제외한 사람들에게 잊혔으며, 폴뤼크스와의 관계도 경직되었다.\n그 후로 그는 교회에 순종하는 척하면서 속으로는 다시 동생을 탈출시키려는 집념을 버리지 않고 자유를 얻을 기회를 계속 기다리고 있다."
  },
  CollectionHall_90416_LockTip = {
    Text = "「카스토르」를 깨어남한 후 해제"
  },
  CollectionHall_90416_Title = {
    Text = "카스토르"
  },
  CollectionHall_94552_LockTip = {
    Text = "시간제 활동 「위대한 정복: 신성한 사냥」의 임의의 레벨을 통과해야 합니다"
  },
  CollectionHall_94552_Title = {
    Text = "위대한 정복: 신성한 사냥"
  },
  CollectionHall_94553_Desc = {
    Text = "<Title:소개>\n등불 교회는 신을 강림시키기 위한 인공 쌍둥이 실타래험품을 양성했지만, 실타래험이 실타래패로 판별되어 잔인하게 버려질 위기에 처했을 때, 형의 혈육 속에서 분리되어 태어났습니다.\n그렇게 생존을 갈망하는 애착은 행운이 아니라 두 사람의 운명을 짧은 비극에서 더 긴 비극으로 바꾸어 놓았습니다.\n어쩌면 쌍둥이의 신비에서 비롯된 것인지, 그는 형과의 피부색과 성격이 전혀 다릅니다. 쌍둥이 중 더 활발하고 영리한 쪽으로, 항상 규율에 반하는 장난스러운 행동을 하며, 평범한 가정의 장난꾸러기 소년처럼 지냈습니다—신격의 용기로 양성되기 위해 선택되기 전까지, 정기적으로 고통스럽고 피비린내 나는 “신성 개조” 의식을 받기 시작했습니다.\n고통을 견딜 수 없는 절망적인 운명 속에서 그의 애원과 계획 아래, 형제 두 사람은 암호로 수년간 계획을 세워 여러 장애물을 뚫고 결국 탈출에 성공했습니다.\n그러나 그들은 기쁜 시간을 오래 가지 못하고 교회의 추격자에게 붙잡혀, 리에트의 명령에 따라 그 자유로운 날개를 뽑히고 극단적인 세뇌를 당해 결국 형을 잊고, 성자로서 사람들에게 추앙받는 기분을 즐기게 되었습니다.\n두 번째 탈출 후, 형의 죽음과 신을 강림시키는 의식의 영향으로 기억을 되찾고, 증오와 분노로 “성심”을 점화하여 등불 교회에 맞서는 것을 인생의 새로운 방향으로 삼게 되었습니다."
  },
  CollectionHall_94553_LockTip = {
    Text = "통과 이몽 시야「하늘끝·하」 해제"
  },
  CollectionHall_94553_Title = {Text = "폴룩스"},
  CollectionHall_95436_Desc = {
    Text = "날아라, 날아라, 새가 그 두 날개로 무거운 중력을 맞서 싸우며, 계속 오르고 또 오르며, 여러 차례의 난류와 소용돌이를 뚫고 점점 더 높은 곳으로 날아간다.\n그러나 그는 자신의 발목에 항상 보이지 않는 실타래이 묶여 있다는 것을 모르고, 그는 아마도 결코 진정한 새가 되지 못했을지도 모른다. 비록 날고 있더라도, 그것은 단지 불쌍한 연일 뿐이다.\n지금, 연이 감기는 중이다."
  },
  CollectionHall_95436_LockTip = {
    Text = "「이몽 시야」의 「하늘 끝 너머」 상급 완료"
  },
  CollectionHall_95436_Title = {Text = "연"},
  CollectionHall_95437_Desc = {
    Text = "너는 그 얼굴을 보았다. 그 부드럽고, 평화롭고, 아름다운 얼굴.\n그것은 너의 기억 속에서 금세 녹아버렸지만, 너는 여전히 긴 밤비가 끝난 후, 아침의 부드러운 빛의 색깔을 기억하게 될 것이다."
  },
  CollectionHall_95437_LockTip = {
    Text = "특파대 기록“비 마을의 그림자” 완료"
  },
  CollectionHall_95437_Title = {
    Text = "비막 깊은 곳"
  },
  CollectionHall_95438_Desc = {
    Text = "고양이가 되어, 걱정 없는 고양이가 되어, 사랑하는 사람과 함께만 지내고, 매일 그녀 옆에서 햇볕을 쬐는 것.\n그녀의 마음속에 아름답고 작은 꿈이지만, 아름다운 꿈이라면 항상 그렇게 약하고 부서지기 쉬운 것."
  },
  CollectionHall_95438_LockTip = {
    Text = "특파대 기록 “평온한 분열” 완료"
  },
  CollectionHall_95438_Title = {
    Text = "고양이의 소원"
  },
  CollectionHall_95439_Desc = {
    Text = "세상이 재로 날려버려도, 모든 것이 부식액에 물들어도, 순수한 해파리는 자신만의 환상 속에 영원히 잠길 수 있습니다.\n거기, 모든 것이 처음처럼. 오직 웃음만. 오직 행복만."
  },
  CollectionHall_95439_LockTip = {
    Text = "완료: 의식 잠수 “일상적으로 모든 일이 진행 중입니다” 어려움 난이도"
  },
  CollectionHall_95439_Title = {
    Text = "혼돈 속에 잠겨 흐트러지다"
  },
  CollectionHall_95440_Desc = {
    Text = "룬티니언의 겨울에는 눈이 자주 내리지 않는다. 매번 내리는 눈은 아이들을 흥분의 축제로 이끈다.\n너는 부드러운 긴 꿈에서 깨어나 창밖으로 손을 내밀었다. 한 송이 눈송이가 손바닥에 떨어져, 따듯한 곳에서 기꺼이 녹았다.\n눈송이가 휘날리며 하늘에서 짧은 여행을 거쳐, 다시 땅으로 돌아가고, 어두운 강으로, 모든 물방울의 집과 순환으로 돌아간다.\n올해 첫 눈 속에서 또 한 그녀가 그녀들의 집으로 돌아왔다.\n잘 자, 눈아; 잘 자, 「24」."
  },
  CollectionHall_95440_LockTip = {
    Text = "특파대 기록 “평온한 분열” 완료"
  },
  CollectionHall_95440_Title = {
    Text = "안녕히 주무세요, 눈"
  },
  CollectionHall_95441_Desc = {
    Text = "흰 산호가 가지를 뻗으며 순백의 궁전을 자라나게 합니다.\n기형의 기둥 사이로 다채로운 물고기들이 자유롭게 헤엄칩니다.\n신체는 가라앉고, 혼은 떠다닙니다.\n당신은 숨을 잃어도 좋다고 하고, 그녀와 함께 빠지고, 빠지고, 빠져들고 있습니다. 흰색 환상 속으로.\n그것은 바다의 기적이며, 따뜻한 파란색 고향입니다."
  },
  CollectionHall_95441_LockTip = {
    Text = "의식 잠수 완료 “노래 같은 조각”"
  },
  CollectionHall_95441_Title = {
    Text = "순백의 궁전"
  },
  CollectionHall_95442_Desc = {
    Text = "딱딱—— 작은 기차가 출발합니다! \n친구들과 함께 아픔이 없는 즐거운 동화 왕국으로 가봅시다."
  },
  CollectionHall_95442_LockTip = {
    Text = "의식 잠수 완료“일상적”"
  },
  CollectionHall_95442_Title = {
    Text = "순진한 꿈"
  },
  CollectionHall_95443_Desc = {
    Text = "그녀는 범죄자인가? 그녀는 당신과 오랜만에 만난 연인처럼 보인다.\n비, 마른 잎, 그리고 환상적인 꽃 향기, 당신은 코를 벌름거리며, 그 축축한 냄새 속에서 피의 냄새를 찾으려 하였으나, 아무 것도 맡지 못했다.\n그녀는 또한 설명할 생각이 없었고, 흐릿한 안개 속에서 당신은 그녀의 회색 꿈속으로 떨어져 들어갔다."
  },
  CollectionHall_95443_LockTip = {
    Text = "특파대 기록“비 마을의 그림자” 완료"
  },
  CollectionHall_95443_Title = {Text = "용의자"},
  CollectionHall_95444_Desc = {
    Text = "그 같은 허기을 그녀 역시 겪었습니다.\n연약하고, 거칠며 외롭습니다.\n그녀는 운이 좋은 편이었죠, 긴 유랑을 끝내고 평생 동안 씹을 수 있는 따뜻한 기억을 얻게 되었으니.\n지금 그녀는 동족의 손을 잡아 이 방황하는 영혼을 평화로운 꿈의 나라로 인도합니다."
  },
  CollectionHall_95444_LockTip = {
    Text = "특파대 기록 “비 마을의 그림자” 어려움 완료"
  },
  CollectionHall_95444_Title = {
    Text = "야수의 꿈"
  },
  CollectionHall_95445_Desc = {
    Text = "내 날카로운 칼날로, 내 심장을 찌르다.\n무자비한 운명과 쓴 삶 앞에서, 나는 그렇게 보잘것없고 연약하며 무기력하다.\n나는 도대체 누구인가? 나는 나를 잘 할 수 있었나?\n내 질문에서, 나는 대답할 수 없다."
  },
  CollectionHall_95445_LockTip = {
    Text = "특파대 기록 “평온한 분열” 완료"
  },
  CollectionHall_95445_Title = {
    Text = "내게 물어봐"
  },
  CollectionHall_95446_Desc = {
    Text = "어? 방금 전과 달라진 것 같아요? \n눈빛이 더 밝아졌나요? 행동이 더 활발해졌나요? 아니면 이 평범한 육체 안에서 이미 혼의 주인이 바뀌었나요?"
  },
  CollectionHall_95446_LockTip = {
    Text = "의식 잠수 완료 “노래 같은 조각”"
  },
  CollectionHall_95446_Title = {
    Text = "혼의 이동"
  },
  CollectionHall_95447_Desc = {
    Text = "눈이 오든, 비가 오든, 맑은 날이든, 흐린 날이든, 오늘의 강물은 여전히 조용히 흐르고 있다."
  },
  CollectionHall_95447_LockTip = {
    Text = "특파대 기록 “평온한 분열” 완료"
  },
  CollectionHall_95447_Title = {
    Text = "고요한 강"
  },
  CollectionHall_95448_Desc = {
    Text = "조수의 물결이 밀려오고, 머리가 날카롭게 소리친다.\n한 쌍의 눈이 너를 응시하며, 쫓아오기 벙어리 같은 입들이 너를 비난한다.\n그들은 너를 잠식하려 하며, 너를 포식하려 한다.\n너는 두 눈을 두려워하며 감고, 다시 눈을 뜨면, 그들이 너의 곁에 있다는 것을 발견한다."
  },
  CollectionHall_95448_LockTip = {
    Text = "특파대 기록“비 마을의 그림자” 완료"
  },
  CollectionHall_95448_Title = {
    Text = "머리 바다"
  },
  CollectionHall_95449_Desc = {
    Text = "그녀는 당신에게 약속했다, 반드시 당신과 함께 집으로 돌아가겠다고.\n——영원한 모습으로, 고요하고 기적과 아름다움이 있는 고향으로."
  },
  CollectionHall_95449_LockTip = {
    Text = "의식 잠수 완료 “노래 같은 조각”"
  },
  CollectionHall_95449_Title = {
    Text = "석화 예술"
  },
  CollectionHall_95450_Desc = {
    Text = "그 고귀한 손님은 카스토르의 희망찬 뒷모습을 바라보며 월광 아래에서 운명의 예언을 속삭였습니다:「그는 나가고, 폭풍 속에서 힘겹게 싸울 것입니다. 그를 높이 날게 한 것도 그를 추락하게 할 것입니다.」"
  },
  CollectionHall_95450_LockTip = {
    Text = "「이몽 시야」의 「하늘 끝 너머」 상급 완료"
  },
  CollectionHall_95450_Title = {
    Text = "폭풍 속에서"
  },
  CollectionHall_95451_Desc = {
    Text = "미에서 태어나고, 미에서 죽는다.\n그녀는 천재이고, 미치고, 악마이다. 그녀는 냉정한 키리이고, 네가 사랑하는 가족이기도 하다.\n그녀는 뜨거운 사랑으로 너를 완벽한 작품으로 만들어준다.\n그녀는 너를 포옹하고, 네 차가운 손을 잡아준다. 그녀는 너를 데리고 가서, 그녀와 함께 예술의 고향으로 돌아갈 것이다."
  },
  CollectionHall_95451_LockTip = {
    Text = "의식 잠수 “노래 같은 조각” 어려움 완료"
  },
  CollectionHall_95451_Title = {
    Text = "아름다운 죽음"
  },
  CollectionHall_95452_Desc = {
    Text = "대양이 나의 부름을 들었기에, 당신을 내 곁으로 데려왔습니다.\n그리하여 우리는 마음껏 대화하고, 놀이하고, 즐거워하며, 세상에서 가장 좋은 친구가 되었습니다.\n이 부식으로 가득 찬 침묵의 도시에서."
  },
  CollectionHall_95452_LockTip = {
    Text = "의식 잠수 완료“일상적”"
  },
  CollectionHall_95452_Title = {
    Text = "제발 나의 친구가 되어 줘"
  },
  CollectionHall_95453_Desc = {
    Text = "귀환하라, 모든 용감한 자, 두려운 자, 똑똑한 자, 어리석은 자, 강한 자, 약한 나들아.\n모든 기쁜, 슬픈, 분노하는, 고통받는, 지친 마음이 녹아내리게 하라.\n우리는 함께한다.\n그들은 영원히 함께이다."
  },
  CollectionHall_95453_LockTip = {
    Text = "특파대 기록 “평온한 분열” 어려움 완료"
  },
  CollectionHall_95453_Title = {
    Text = "그녀에게 귀환하다"
  },
  CollectionHall_95454_Desc = {
    Text = "이것은 영혼의 공허와 균열로, 오직 가장 순수한 동화만이 이를 채울 수 있습니다.\n언젠가 그녀는 고통에서 벗어나 동화 속 즐거움이 가득한「고향」으로 돌아올 것입니다."
  },
  CollectionHall_95454_LockTip = {
    Text = "의식 잠수 완료“일상적”"
  },
  CollectionHall_95454_Title = {
    Text = "순진한 공포 동화"
  },
  CollectionHall_95455_Desc = {
    Text = "그러한 어두운, 깊고 좁은 골목은 언제나 많은 운명의 전환 순간을 담고 있습니다. 재회, 언쟁, 결별, 그리고 폭력, 괴롭힘, 살인.\n다행히도 오늘의 이야기는 후반부의 끔찍한 장면이 발생하지 않았습니다, 하지만 누가 과거의 초래가 진정한 비극이 아니라고 말할 수 있을까요?"
  },
  CollectionHall_95455_LockTip = {
