  },
  CollectionHall_97736_LockTip = {
    Text = "기간 한정 이벤트 「신의 탄생제: 7일간의 창조」의 스테이지를 하나 이상 클리어해야 합니다"
  },
  CollectionHall_97736_Title = {
    Text = "신의 탄생제"
  },
  CollectionHall_97896_LockTip = {
    Text = "한정 이벤트 「모든 것이 정상이라면: 일광 아래 새로운 일」의 어떤 스테이지를 통과해야 한다"
  },
  CollectionHall_97896_Title = {
    Text = "모든 것이 평소대로였다면"
  },
  CollectionHall_98502_LockTip = {
    Text = "의식 잠수 “불멸의 극주”의 임의의 단계 해금"
  },
  CollectionHall_98502_Title = {
    Text = "결코 꺼지지 않는 추적"
  },
  CollectionHall_98636_Desc = {
    Text = "모독자가 깊은 푸른 해일을 일으키고, 홀로 고독한 왕이 천 미터의 거대한 파도를 향해 나아간다.\n 그의 머리카락은 바람에 날리며, 그의 뼈와 피가 그의 엄숙한 선언인 듯, 경멸하는 미소 속에서, 그는 자신을 죽음과 달에 근헌한다.\n 그러자 바다는 이 순간 응결되고, 거꾸로 매달린 만년설이 보름달 아래에서 고요히 멈추고, 모든 것이 고요해지고, 모든 평화가 그의 왕국으로 돌아온다."
  },
  CollectionHall_98636_LockTip = {
    Text = "조사 작전·어려움 성신편 3-10 완료 시 해제"
  },
  CollectionHall_98636_Title = {
    Text = "보름달 제사"
  },
  CollectionHall_98637_Desc = {
    Text = "죽은 자를 요리하는 것은 엄숙한 예술이다.\n그는 칼과 주걱을 사용해 미완의 유언을 묻고, 물과 불로 마지막 소망을 이루어준다.\n고통스럽고, 괴로운, 신맛 나는 기억의 조각들은 모두 빛나고 향기로운 작품으로 변해 사람들에게 맛보기 위해 소중히 간직될 것이다."
  },
  CollectionHall_98637_LockTip = {
    Text = "조사 작전 성신편 3-11 완료 시 해제"
  },
  CollectionHall_98637_Title = {
    Text = "식탁의 주인"
  },
  CollectionHall_98638_Desc = {
    Text = "아이들은 울고, 고래고래 소리를 지르며, 몹시 불평한다.\n그는 우주의 중심이며, 그는 이곳 모든 법칙이다.\n그는 모든 시선의 범위 내에서, 모두가 그를 둘러싸고, 따르고, 헌신하도록 한다."
  },
  CollectionHall_98638_LockTip = {
    Text = "조사 작전·어려움 6-10 완료 시 해제"
  },
  CollectionHall_98638_Title = {
    Text = "신명이 강림하다"
  },
  CollectionHall_98639_Desc = {
    Text = "그는 죽음을 거두는 모든 순간에 무정하게 낫을 휘두르지 않는다. \n 그는 따뜻한 두 손을 가지기도 했고, 감정이 풍부한 마음을 가지기도 했다.\n 그가 그 영혼의 슬픔을 맛보면, 그는 함께 눈물을 흘리곤 했다.\n 그가 뼈아픈 증오를 맛보면, 그는 대신 심판을 내린다.\n 그는 장례의 주인의 이름으로 약속한다: 모든 죽음을 모독하는 자들은 서리처럼 차가운 짙은 안개 속에서 사라질 것이다."
  },
  CollectionHall_98639_LockTip = {
    Text = "조사 작전 성신편 3-11 완료 시 해제"
  },
  CollectionHall_98639_Title = {
    Text = "죽음의 신이 내려다보는 모습"
  },
  CollectionHall_98640_Desc = {
    Text = "혈육의 달콤한 맛과 힘줄 파열의 감각은 그가 가장 익숙하고 깊이 새겨진 기억입니다.\n그는 이미 이해하고 있었습니다. 이 매장석 도시는 오늘날까지 지속되지만, 이는 생자의 힘에서 비롯된 것이 아니라, 죽은 자의 희생에서 비롯된 것입니다.\n다시 한번 선홍빛이 목구멍에서 삼켜지며, 그는 두 눈을 감고 각기 다른 향기를 곱씹으며 각 영혼의 맛을 깊이 새기며, 그의 친지와 백성은 그의 몸 속에서 영원히 살아 있습니다.\n그들은 영원토록 함께 하기로 약속했습니다."
  },
  CollectionHall_98640_LockTip = {
    Text = "조사 작전·어려움 성신편 3-10 완료 시 해제"
  },
  CollectionHall_98640_Title = {
    Text = "붉은색 계약"
  },
  CollectionHall_98641_Desc = {
    Text = "달빛 아래 제사 칼이 매력적인 빛을 발산하고 있다.\n그녀는 필사적인 죽음을 통해 그녀가 간절히 바라는 자유 의지를 증명했다."
  },
  CollectionHall_98641_LockTip = {
    Text = "조사 작전 6-15 완료 시 해제"
  },
  CollectionHall_98641_Title = {
    Text = "차가운 달빛"
  },
  CollectionHall_98642_Desc = {
    Text = "그는 부족의 사람들에게 어떻게 싸우고, 어떻게 죽이고, 어떻게 살아야 하는지를 가르쳤지만, 자신보다 수배 더 강한 적을 만났을 때 어떻게 도망치는지는 결코 가르치지 않았다.\n 그래서 그는 도망치지 않는다.\n 그저 목이 베어질 뿐이야, 가져가!\n 그는 이미 투명하게 간파했다: 힘을 추구하는 야망가가 추구하는 도중 죽는 것은 정해진 결말과 운명일 뿐이다."
  },
  CollectionHall_98642_LockTip = {
    Text = "의식 잠수 완료 “거인의 몰락”"
  },
  CollectionHall_98642_Title = {
    Text = "나는 죽음을 두려워하지 않는다"
  },
  CollectionHall_98643_Desc = {
    Text = "찢어짐, 아작.\n신은 입을 크게 벌려 신자의 모든 경건함과 신자 본인을 기꺼이 받아주었다."
  },
  CollectionHall_98643_LockTip = {
    Text = "조사 작전 6-15 완료 시 해제"
  },
  CollectionHall_98643_Title = {Text = "첫 끼니"},
  CollectionHall_98644_Desc = {
    Text = "예전의 동족들이 두서너명 몰려들며 패배 후 유배된 이들을 처치하려 했습니다. 오히려 블레셋 역사에서 가장 용맹한 지도자는 꺾이지 않는 의지를 가진 거인으로써, 학살로 응징했습니다.\n끝없는 비명이 울려 퍼지는 가운데, 거대한 칼날은 피를 끌여 마시며, 하나하나 흉측한 시체로 그의 전투 스타일을 정의합니다——독단적이고, 오만하고, 잔인하고, 폭력적입니다.\n적에게는 동정이 필요 없습니다.\n그들은 그가 다시 권력의 정점으로 돌아가기 위한 필수 단계일 뿐입니다."
  },
  CollectionHall_98644_LockTip = {
    Text = "의식 잠수 완료 “거인의 몰락”"
  },
  CollectionHall_98644_Title = {
    Text = "필요한 살상이네요"
  },
  CollectionHall_98645_Desc = {
    Text = "몸을 돌리는 그 순간, 엘튼은 다시 막 바다에 나선 그 소년이 된 듯했습니다. 푸른 하늘과 끝없는 바다가 연결되어, 세상은 모든 야망과 꿈을 담을 수 있을 만큼 컸습니다.\n 다르게 말하자면, 이번엔 그는 꿈이 실타래현되는 모습을 분명히 보았고, 백조들이 가득한 꿈의 귀환길을 향할 수 있었습니다."
  },
  CollectionHall_98645_LockTip = {
    Text = "조사 작전·어려움 6-10 완료 시 해제"
  },
  CollectionHall_98645_Title = {
    Text = "백조의 고향"
  },
  CollectionHall_98646_Desc = {
    Text = "시간이 다 되었다, 은빛 달이 높이 걸려 있다.\n굳어버린 발끝을 살짝 올리고, 오늘 밤 이 잔치의 시간을 즐기세요.\n그녀는 마지막 여행에 이르렀고, 우리는 그녀를 위하여 위장에서 장례를 치른다.\n당신에게 한 입, 나에게 한 입, 이제부터는 누구도 잊지 않을 것이다."
  },
  CollectionHall_98646_LockTip = {
    Text = "조사 작전 성신편 3-11 완료 시 해제"
  },
  CollectionHall_98646_Title = {
    Text = "안식의 무곡"
  },
  CollectionHall_98647_Desc = {
    Text = "신적이 만약 형태가 있다면, 그것은 그녀의 합장한 두 손과 같을 것이다.\n신명이 만약 외모가 있다면, 그것은 그녀의 평온한 얼굴과 같을 것이다."
  },
  CollectionHall_98647_LockTip = {
    Text = "조사 작전 6-15 완료 시 해제"
  },
  CollectionHall_98647_Title = {
    Text = "순백의 여신"
  },
  CollectionHall_98648_Desc = {
    Text = "축하하라, 나의 친구♪\n달빛 아래의 해골이 조용히 피어오른다♪ 한 사랑이 접시 위에 놓인다♪\n모든 손님이 도착했습니다! 노래하고, 춤추세요♪\n우리는 결코 망자를 위해 기도하지 않습니다♪ 우리는 결코 시신을 애도하지 않아요♪\n그녀는 메모리를 나에게 넘겼다♪ 그녀는 눈물을 나에게 넘겼다♪\n우리 함께 그녀의 혼과 썩은 육체를 삼켜♪\n죽음의 향연 속에서, 우리는 다시 만났다♪"
  },
  CollectionHall_98648_LockTip = {
    Text = "조사 작전 성신편 3-11 완료 시 해제"
  },
  CollectionHall_98648_Title = {
    Text = "식사 좀비의 노래"
  },
  CollectionHall_98649_Desc = {
    Text = "사람들은 그의 강함에 두려워하고, 경외하며, 그의 잔인함에 증오하고, 경멸하며, 그의 실타래패에 조롱하고 추방한다.\n 그러나 약자의 아우성은 무의미하며, 거인의 시선은 오직 강자에게 머물 뿐이다.\n 황폐한 망명 바다에서 그는 자신의 생명을 걸고 절대적인 힘을 찾는 여정을 시작한다."
  },
  CollectionHall_98649_LockTip = {
    Text = "의식 잠수 완료 “거인의 몰락”"
  },
  CollectionHall_98649_Title = {
    Text = "새로운 여정에 나서다"
  },
  CollectionHall_98650_Desc = {
    Text = "그는 그녀를 기억한다.\n폭풍 속에서 자신이 꼭 안고 있던 아기, 결국 자신이 직접 심연으로 보내버렸다——자신의 양심과 교환하기 위해, 그 흰 새가 날아오르는 꿈을 위해。\n그는 평생 바라던 아름다운 꿈이 이루어졌다고 기도하며, 이제는 남은 생애로 모든 칠흑의 죄를 갚을 때가 되었다."
  },
  CollectionHall_98650_LockTip = {
    Text = "조사 작전 6-15 완료 시 해제"
  },
  CollectionHall_98650_Title = {Text = "상환"},
  CollectionHall_98651_Desc = {
    Text = "이별과 죽음은 세상에서 벗어날 수 없는 일상이다.\n무수한 희생과 죽음에서 벗어나 불확실타래한 앞길로 나아가며, 어렴풋한 슬픔이 너의 마음을 감싼다. 하지만 죽음 속에 사는 사람들을 보고, 죽음을 따뜻한 결말로 이끄는 왕을 목격한 후, 너는 더 이상 미지의 결말을 두려워하지 않게 된다.\n푸른 보라색의 물망초가 너의 어깨에 떨어져, 그를 멀리 보내준다.\n너는 안다, 어찌 되었든 너의 귀향은 외롭지 않다는 것을."
  },
  CollectionHall_98651_LockTip = {
    Text = "조사 작전·어려움 성신편 3-10 완료 시 해제"
  },
  CollectionHall_98651_Title = {
    Text = "잊지 말고 나를 보내줘"
  },
  CollectionHall_98652_Desc = {
    Text = "「너희 친구로서, 왕으로서, 이 평화로운 땅의 주인의 이름으로, 나는 너희를 초대한다——소생하라! 사랑하는 고향으로 돌아가라! 우리 가족의 평화를 방해하는 자들을 영원히 몰아내라！」"
  },
  CollectionHall_98652_LockTip = {
    Text = "조사 작전 성신편 3-11 완료 시 해제"
  },
  CollectionHall_98652_Title = {
    Text = "모든 영혼의 분노"
  },
  CollectionHall_98653_Desc = {
    Text = "그녀와 그가 함께 있을 수는 없어서, 한 단검이 두 개의 심장에 꽂히며, 그것은 신에게 바친 보상이다."
  },
  CollectionHall_98653_LockTip = {
    Text = "조사 작전 6-15 완료 시 해제"
  },
  CollectionHall_98653_Title = {
    Text = "신명이 태어나는 날"
  },
  CollectionHall_98654_Desc = {
    Text = "당신은 한 왕과의 대화가 한 무도회로 시작된다는 것을 결코 상상하지 못했을 것입니다.\n강력한 침입, 방황하는 시험, 공격과 방어, 대치와 양보, 당신들은 회전하는 옷자락 속에서 은밀히 맞붙습니다.\n거래는 우아하게 마지막 막을 내리고, 왕의 머리칼이 흩날리며, 당신은 그 안개에 둘러싸인 눈 속에서 즐거운 미소가 반짝이는 것을 봅니다.\n어? 방금 그가 당신을 이끌어갔던 걸까요?"
  },
  CollectionHall_98654_LockTip = {
    Text = "조사 작전 성신편 3-11 완료 시 해제"
  },
  CollectionHall_98654_Title = {
    Text = "탱고 외교"
  },
  CollectionHall_98655_Desc = {
    Text = "당신이 본 가장 무서운 욕망을 향한 식사는, 그들의 생애에서 가장 부드러운 재회입니다."
  },
  CollectionHall_98655_LockTip = {
    Text = "조사 작전 성신편 3-11 완료 시 해제"
  },
  CollectionHall_98655_Title = {
    Text = "해골의 영면지"
  },
  CollectionHall_98656_Desc = {
    Text = "별은 그 궤도에서 정상적으로 운행하고 있지만, 먼지 속의 생명은 그로 인해 여러 번 침몰했다."
  },
  CollectionHall_98656_LockTip = {
    Text = "조사 작전 6-15 완료 시 해제"
  },
  CollectionHall_98656_Title = {
    Text = "뒤틀린 별"
  },
  CollectionHall_98657_Desc = {
    Text = "순식간에 사람을 죽음으로 몰아넣는 마녀 앞에서, 약자들은 두려움, 숭배, 회심의 기도를 한다.\n하지만 그는 결코 그렇지 않았다.\n그는 이 힘을 보았고, 이 힘을 갈망하며, 어떤 대가를 치르더라도 이 힘을 얻어야 한다고 생각했다.\n그 후, 그는 다시 일어설 것이고, 비레셋인이 밟은 모든 땅에서 그의 이름이 다시 알려지게 될 것이다."
  },
  CollectionHall_98657_LockTip = {
    Text = "의식 잠수 “거인의 몰락” 어려움 완료"
  },
  CollectionHall_98657_Title = {
    Text = "거인의 포부"
  },
  CollectionHall_99651_Desc = {
    Text = "<Bold:은코다24>\n매번 그 튀김 생선 식당을 지날 때마다, 나는 소리 지르고 싶어 견딜 수가 없다.\n왜 다치는 것은 항상 은코다일까? 우리는 사실타래 진짜 대구가 아닌데!\n살이 탄탄하고 맛이 좋다는 것도 우리의 잘못인가?\n\n<Bold:고양이24>\n흡슬흡슬……야옹, 야옹야옹(찬성)!\n\n<Bold:은코다24>\n레오 왕국에서는 매 분마다 한 마리의 은코다가 비참한 죽음을 당해 인간의 식탁에 오른다.\n그래, 우리가 이야기하는 틈새에 이미 10마리의 은코다가 영웅적으로 희생되었다.\n총 10마리! 아버지 신이여, 그들의 비명소리를 들으셨나요?\n\n<Bold:고양이24>\n어……야옹? 야옹야옹, 야옹야옹(어디)?\n\n<Bold:은코다24>\n그저 비유일 뿐이야, 바보야. 너는 조금 멍청할지 모르지만, 고양이의 야수 본능과 단기적 시각을 이길 수 있는 금 같은 마음을 가지고 있어.\n들어봐, 다음에 내가 계획이 있어, 너와 함께 실타래행해야 해……\n\n——《대존 존 튀김 생선 식당 폭발 사건·사건 요약: 증언 B-03》에서 발췌. 해당 시기에 베들레헴 정신병원이 만원이라 피의자가 수용 거부당하고, 렌티니엔타에 23일간 구금된 후 석방되었다."
  },
  CollectionHall_99651_Title = {
    Text = "은빛 물고기의 결심"
  },
  CollectionHall_99653_Desc = {
    Text = "위해 “그 순간”을 기다리며 소녀는 빙하의 바닥에서 잠들어 있다. 엘워스의 천척한 빙하가 그녀의 육체를 봉인했지만, 그녀의 신지를 완전히 차단하지는 못했다. \n그 신지는 아이로부터, 또한 어머니로부터 왔다. 신성은 그녀의 딸이 다크에서 임신한 자궁에서 만고의 장꿈을 이어갔다. \n25년의 시간 동안, 그녀는 무엇을 생각했을까, 무엇을 그리워했을까, 무엇을 기대했을까? \n지금에 이르러 이러한 질문들은 이미 아무도 답할 수 없다. 그 소녀 본인…… 그녀가 곁에 있는 이에게 진심을 털어놓을까? 모든 것을 시간과 미래에 맡기자."
  },
  CollectionHall_99653_Title = {
    Text = "빙하 아래에 잠든"
  },
  CollectionHall_99654_Desc = {
    Text = "조용히 죽어간 혼만이 세세히 감상할 가치가 있다. 살아 있는 자의 몸부림은 맛을 혼동시킬 뿐이다。\n반찬이 차려졌을 때 여전히 약간의 온기가 있었고, 심장은 중앙에 안정적으로 놓여 있었으며, 표면이 약간 부풀어 올랐고 막 마지막 박동을 끝낸 것처럼 보였다。 두 개의 안구가 한쪽에 장식되었고, 동공에는 죽기 전 그 순간의 당혹감이 봉인되어 있었으며, 부드러운 유백색으로 끓여졌다。\n그는 칼을 들어 천천히 심장을 가르다가 갑자기 멈췄다。\n그의 혼은 여전히 쉰 목소리로 비명을 지르고 있었고, 한 조각의 집착이 혈관 속에 남아서 완전히 사라지지 않았다。 그는 칼을 내려놓고 두 손을 모아 죽은 자의 목소리를 조용히 들었다。\n이 심장은 한 때 고통에 시달린 시인에게서 온 것이며, 긴 실타래망 속에서 죽음으로 해방되었지만 여전히 삶에 대한 미련이 남아 있었다。 그는 이 심장을 진정한 '맛'으로 만들어 주기 위해서는 음식에 대한 충분한 존경이 필요하다는 것을 알고 있었다. 유일한 방법은 기다리는 것이다——\n육체에 얽힌 집착이 죽음을 통해 완전히 붕괴할 때까지 기다린다; 죽은 자의 기억의 마지막 메아리가 혈관 벽에서 은은히 진하게 스며들 때까지 기다린다。\n그는 우아하게 두 손을 무릎 위에 겹쳐놓고 눈을 감고 깊게 숨을 들이마셨다。\n향기가 공기 중에 천천히 퍼져나가며, 그것은 복잡하고 부드러운 향기로, 연인의 떨림과 이별의 쓴 맛을 모두 갖추고 있었다。먹물의 향기, 허브 향기와 함께 아침 이슬 같은 소심함이 섞여 있었다。\n그는 생명의 나무 아래에서 조용히 앉아, 성숙한 과실타래이 갓 떨어지기를 기다렸다。"
  },
  CollectionHall_99654_Title = {Text = "진미"},
  CollectionHall_99655_Desc = {
    Text = "오래 전에 놓여져 시들어버린 꽃 한 송이입니다. \n주인을 기다려도 영원히 오지 않습니다."
  },
  CollectionHall_99655_Title = {
    Text = "보내지 않은 꽃"
  },
  CollectionHall_99656_Desc = {
    Text = "탄생부터 쌍둥이는 마음대로 날개를 사용해 날아오르는 것이 허락되지 않았습니다. 그들의 등에 성장한 두 번째 쌍팔은 성자의 권위를 나타내는 예기처럼 두 쌍의 장식물이 되어 언제나 그들의 자세와 태도를 규정하고 있습니다。\n어릴 적, 폴룩스는 둘 중에서 가장 그 날개를 아끼던 사람으로, 매일 빗질하고, 에센셜 오일을 발라 그 깃털을 실타래크처럼 반짝이게 관리했습니다。\n그는 항시 짧은 틈을 노려, 그 새의 날개가 처음 돋아난 날개를 몰래 펼치며 까스톡의 놀라움 속에서 살랑살랑 공중에서 떨어져 장식된 천장을 살짝 터치했습니다。\n폴룩스가 날개로 유연한 춤동작 같은 것을 할 수 있었던 반면, 까스톡은 자신의 날개가 항상 두 개의 나무 판자처럼 느껴져 불편해했습니다。쌍둥이의 비밀스러운 밤 시간에, 까스토르는 폴룩스가 어둠 속에서 도약하고, 회전하고, 작은 욕조에서 날아다니는 모습을 조용히 지켜보았습니다。\n「동생의 날개는 정말 아름다워. 하지만 내 경우엔 한 평생 날아다닐 능력이 있을까……」까스토르는 생각했습니다。\n그래서 그들이 도망친 그날 밤, 까스토르는 처음으로 석양의 산뜻한 바람이 날개를 미끄러져 가는 것을 느꼈습니다。더 능숙한 폴룩스는 휘청거리는 오빠를 단단히 붙잡고 하늘에서 크게 웃으며 곡선을 그리며 내려가고, 회전하며, 하늘의 새처럼 날아다녔습니다。\n까스토르는 고개를 돌려 폴룩스의 섬세하고 강력한 날개가 달빛에 비추어 깃털 사이로 초록빛 아우라를 반사하는 것을 보았습니다。\n「그것은 세상에서 가장 아름다운 것임에 틀림없어, 어떠한 상황에서도 나는 폴룩스를 보호할 것이다, 그리고 그 날개를. 그러니 이 일이 다시는 일어나지 않도록 할 것이다」。\n그러나 어려운 야외 생활 속에서 폴룩스의 날개는 야생 동물에게 상처를 입었습니다. 까스토르는 폴룩스의 낙엽처럼 떨어진 날개를 소중히 간직하였고 결코 이런 일이 두 번 다시 일어나지 않도록 조용히 다짐했다。그러나 그는 이후 그 외로운 깃핀이 그의 가장 귀중한 소유가 되고, 그 날개에 대한 마지막 유산이 될 줄은 몰랐습니다。"
  },
  CollectionHall_99656_Title = {
    Text = "고독한 깃털"
  },
  CollectionHall_99657_Desc = {
    Text = "우웅——우웅——\n경적 소리 가운데, 호화 여객선은 커퍼센트의 인도로 안전하게 정박했다.\n승객들은 웃으며 트랩을 내려오고, 모자를 휘두르며 그녀에게 감사의 인사를 건넸다. 선원들은 몰려와 칭찬을 전했다.\n「잘했어, 커퍼센트, 네가 미리 경고하지 않았다면 우리는 폭풍에 휩쓸렸을 거야.」\n「그래, 너의 정확한 인도 덕분에 우리는 바다에서 길을 잃지 않았어!」\n선원들이 웃으며, 그녀의 어깨를 두드리며, 엄지를 들어올렸다.\n사실타래, 커퍼센트는 이렇게 가까운 거리의 소셜 활동에 결코 적응할 수 없었다. 그녀의 고지식하고 이성적인 두뇌는 '작업'과 '책임' 외의 다른 생각이 없었다.\n그래서 그녀는 이것도 '작업'과 '책임'의 일부분이라고 간주하였다.\n「나는 단지 내 일을 했을 뿐이야. 조타사로서의 내 책임은 당신들을 안전하게 귀환시키는 것이다.」\n사무적이고 무미건조한 대답, 하지만 그녀의 성격을 잘 아는 선원들은 웃으며 작별을 고했다. 달가닥 달가닥 노래하며 어깨를 걸고 항구를 떠났다.\n「노틸러스호가 드디어 항해할 수 있어. 출발하자, 노틸러스호.」\n노래 소리가 점점 멀어지고, 커퍼센트는 여전히 해안에 남아 있었다. 그녀는 미래의 출항을 준비하고 있었다.\n바다는 변덕스러워, 어떤 조타사도 매번 성공할 수 있다고 보장할 수 없다. 그녀도 마찬가지였다. 그러나 그녀는 단지 하나의 확률이라도 높이기 위해 무한한 시간을 들일 것이다.\n점검, 순찰, 학습, 대조, 그들의 생명에는 '작업'이라는 것만 남았다.\n그렇지만 그녀는 기꺼이 감내한다. 왜냐하면 모든 것이 그 순간, 그 성공적인 항해와, 모두를 안전하게 인도한 그 순간을 위해서다."
  },
  CollectionHall_99657_Title = {
    Text = "바다의 길잡이"
  },
  CollectionHall_99658_Desc = {
    Text = "무한한 심연 속에서 청색 왕좌가 우뚝 서 있다. \n하늘이 낮게 드리우고, 별들이 떨리며, 만물이 침묵한다. \n\n고대적이고 신비로운 존재는 이미 사라졌으며, \n세대를 거듭하며 모든 생명체가 꿈속에서 찬미한다. \n어두운 물속, 잊혀진 비밀, \n너의 속삭임이 파도처럼 밀려와, 마음의 골짜기를 잠식한다. \n\n그 무한한 꿈속에서 예언자와 미치광이가 함께 놀아난다. \n형체 없는 영혼을 추적하며, 두려움과 경외가 얽혀 있다. \n청색 조류가 감싼 궤적은 마치 운명의 편찬처럼, \n길을 잃은 자들의 마음을 천천히 그 청색 왕좌로 이끈다. \n아, 우주의 황당함과 진리, \n꿈과 현실타래이 교차하는 곳에서 영원한 휘광이 반짝인다."
  },
  CollectionHall_99658_Title = {
    Text = "청석 왕좌"
  },
  CollectionHall_99660_Desc = {
    Text = "모두가 운명을 이기고 싶어하지만, 모두가 운명을 두려워한다.\n용감한 자는 전투의 함성을 내고, 비겁한 자는 순종의 속삭임을 내지만, 오직 그만이 운명을 이기는 비밀을 발견했다.\n그 비밀은 바로 운명과 계속해서 도박을 하며, 다음 판을 시작하도록 운명을 재촉하는 것이다.\n그는 운명을 두려워한 적이 없으니, 자신이 지지 않을 것이라고 믿었기 때문이다.\n그는 무엇을 걸어야 하는지 묻지 않았다. 어떤 대가를 치르더라도 망설임 없이 받아들였으며, 자신의 생명까지도 포함되었다.\n룰렛 건 한 자루로, 그는 수많은 일반인들을 물러나게 하고, 렌티니언에서 악명 높은 도박광이 되었다.\n아쉽다, 동등한 상대가 없다는 것은 얼마나 외로운 일인지.\n그런 그가 그 남자를 만났을 때까지.\n그는 수많은 일반인들을 이기고, 마침내 운명의 도박장에 앉았다.\n곧 그는 자신이 가진 모든 것을 잃었지만, 원금과 이자를 포함해 다시 모든 것을 되찾았다.\n야수로 다시 태어났을 때, 그는 땅에 떨어진 마지막 총알을 발사한 권총을 보았다.\n그는 한 발의 총알을 다시 장전하고, 자신의 머리에 한 번 더 방아쇠를 당겨서.\n한편의 침묵 속에서, 그는 입을 벌렸다.\n그는 아직 지지 않았으므로, 언젠가는 결국 승리할 것이라고 믿었다.\n그는 모든 것을 걸더라도 그렇게 믿고 있었다."
  },
  CollectionHall_99660_Title = {
    Text = "운명의 룰렛"
  },
  CollectionHall_99663_Desc = {
    Text = "그 신비한 여성이 장례 후 그녀를 찾아왔습니다. \n “가련한 아이야,” 그녀는 말했다. “너는 이런 불의의 재앙을 겪지 않아도 됐어.” \n “모릅니다. 그가 밀리를 해치운 후에 톰슨이 그를 찾아갔습니다. 에드워드라는 쓰레기는 작년에 죽어야 했는데, 한 사람이 그에게 도움을 줬습니다.” \n “왜냐고? 오, 제가 어떻게 알겠습니까. 아마도 그들은 뱀과 생쥐처럼 한통속이었거나…… 그 죄인 자신도 자신이 저지른 것이 죄라는 것을 몰랐을지도 모릅니다. 그는 어떻게 말했었죠? 맞아, 용서. 죄인에 대한 용서, 그들이 저지른 죄에 대한 용서.” \n “그는 모든 사람이 두 번째 기회를 가져야 한다고 믿었습니다. 당신은 어떻게 생각합니까? 우리는 에드워드에게 다시 한 번 기회를 줘야 합니까, 그가 밀리를 해치우고, 당신의 언니와 어머니를 해쳤으니까요?” \n “맞아요, 그런 사람은 변하지 않습니다, 절대 변하지 않을 겁니다. 그래서, 당신은 어떻게 해야 할지 알고 있겠죠?” \n 맞아요, 그런 사람은 변하지 않습니다. 이런 사람들을 종료시키려면, 이런 죄악, 이런 비극을 끝내려면, 단지…… \n 그들의 욕망을 드러내고, 그들의 추한 모습을 보여주며, 서로 싸우게 하고, 서로 다투게 하여, 그들을 완전히 정화해야 합니다—— \n 무죄의 청정한 땅을 맞이하기 위해."
  },
  CollectionHall_99663_Title = {
    Text = "거울 속 사람"
  },
  CollectionHall_99666_Desc = {
    Text = "망망한 양떼가 망망한 초원을 배회하고 있다. \n이 세상에는 너무나 많은 양이 존재하며, 양은 본래 목자의 인도를 필요로 한다. \n그녀는 언제나 이 세계의 선지자였으며, 지식의 홀을 손에 쥐고 있었다. \n그녀는 훌륭한 목자로서 양떼를 올바른 길로 이끌겠다는 결심을 지키고 있었다. \n그녀는 그 홀로 새끼 양들을 가르치고 늑대를 몰아냈다. \n그녀는 목자의 홀을 높이 들었으니, 항상 앞길을 미리 내다볼 수 있었다. \n예전에는 그녀가 양떼를 풍부한 물가와 싱싱한 초원으로 이끌었다. \n이제 그녀는 세상의 진실타래을 목격했기에, 양떼를 최후의 품으로 인도한다. \n이쪽으로 오라, 뒤돌아보지 말라. \n그녀는 미소 지으며 지혜의 홀을 휘둘렀다. \n양들은 앞에 있는 절벽을 보지 못했다. \n한 마리, 두 마리. \n양들이 떨어지고, 목자는 노래를 불렀다. \n무사의 목자를 따르라, 그녀는 이미 당신에게 가장 분명한 길을 제시했다. \n두려워하지 말라, 죽음의 그늘진 계곡을 지날지라도 그녀의 홀은 여전히 당신과 함께할 것이다. \n모두가 소멸의 심연으로 한걸음씩 나아갈 때까지. \n"
  },
  CollectionHall_99666_Title = {
    Text = "목동의 지팡이"
  },
  CollectionHall_99667_Desc = {
    Text = "그는 무한한 카오스 속을 기어다니며, 가끔씩 세상에 기어가는 모든 생명체에게 한 점 시선을 던진다. \n\n그의 눈에 드는 것들, 예를 들어 소렐 같은 이들에게 그는 거절하기 어려운 “계약 조항”을 제공한다. \n그의 눈에 들지 않는 것들, 그는 그들의 육신을 벗겨내고, 다시는 눈물을 흘릴 수 없는 눈 하나만 남긴다. \n이런 눈들은 “은총받는 자”라고 불린다. \n\n그들은 동굴에서 깜빡이며, 희망에 차 있으면서도 절망에 차 있어, 그의 소환을 기다린다. \n그러나 천 년이 지나, 만 년이 지나도, 은총받는 자들은 여전히 다크한 구석에서 잊혀져 있다. \n\n“그렇다면… 당신들은 어떤 이유로 남겨진 것일 거야. 당신들의 사명은 무엇인가?” \n“우리는 계속해서 기다리고 있어요.” \n“무엇을 기다리는 거야?” \n“기다리는 것… 그것뿐이에요.” \n“고통스럽지 않나?” \n“정확히 반대예요. 어른님에 대한 사랑이 우리를 가득 메우고 있어요. 이것이 우리가 할 수 있는 유일한 일이니까요.” \n“이것을 이해하는 것이 진정한 신도가 되는 길이에요.”"
  },
  CollectionHall_99667_Title = {
    Text = "무수한 총애의 시선"
  },
  CollectionHall_99668_Desc = {
    Text = "그녀의 이름은 지혜의 화신이다. \n그녀는 세상의 모든 지식을 알고 있으며, 미사그의 모든 학자들이 추구하는 최종 목표이다. \n그저 한 마디라도 들을 수 있다면, 깨달음의 경지를 얻을 수 있다. \n하지만 그녀는 자신이 단지 문지기일 른다고 말한다. \n그런 문이 과연 어떤 문일까? \n누구도 그 문을 본 적이 없으므로, 학자들은 그것을 진리라고 부른다. \n그녀는 진리의 문지기이며, 미사그를 지키는 아테나이다. \n타비는 그런 추측을 부정하지 않았지만, 언제나 이곳을, 이 세계를 바라보며, 침묵하면서도 비통하면서도 자비로웠다. \n만약 언젠가 그 문을 보게 된다면, 문 위에 매우 익숙한 눈을 볼 것이다. \n그 눈빛은 고요하고 영원하다. \n시간을, 네 영혼을 관통한다."
  },
  CollectionHall_99668_Title = {
    Text = "진리의 문"
  },
  CollectionHall_99670_Desc = {
    Text = "검은 피에 몸을 담가 다시 태어난 소녀는, 사막의 천년 동안 휘날린 모래바람 속에서, 풍성한 모나무의 신성한 피의 씨앗을 들어올렸다. \n\n“이 씨앗이 세상에 존재하는 한, 나무의 혈통은 단절되지 않을 것이다.” \n\n그 후 또 천 년이 지나, 이 씨앗은 나무의 후예와 함께 영광과 굴욕, 흥망성쇠를 목격하며, 유랑과 실타래종, 소멸과 재생성의 과정을 겪었다. 강물이 진득한 검은 피로 변할 때, 마지막 전승을 완수했다. \n뜨겁고 끈질긴 키스로 새로운 계승자를 감쌌다. 아직 채워지지 못한 갈망과 말하지 못한 이별의 정서가 따뜻한 심장 박동과 함께 퍼져나갔다. \n마노 같은 색채와 백옥 같은 광택은 생명의 박동과 함께 검은 종말을 넘어섰다. \n새로운 세계의 첫 번째 나무 씨앗은 그녀의 축복 아래 땅에서 솟아나 하늘과 땅을 덮는 거대한 나무로 자라났다."
  },
  CollectionHall_99670_Title = {
    Text = "작별의 키스"
  },
  CollectionHall_99671_Desc = {
    Text = "부활한 클레멘틴은 마치 이해하지 못하는 유충처럼 인간 세계에서, 그녀의 종족에 속하지 않는 화려한 세계를 돌아다니며, 혼란과 당황을 느낀다.\n그때 깨우침 같은 목소리가 울려퍼진다——\n\"여기, 샤를럿 의사님이십니까? 저는 심리 상담을 받으러, 샤를럿 의사님을 찾았습니다……\"\n클레멘틴은 드디어 정신을 차린다. 그녀는 샤를럿이 누구인지에 관심이 없고, 단지 방문자가 말한 새로운 단어인 \"심리 상담\"에 호기심을 느낀다.\n그러나 그녀는 성숙한 사냥꾼이다. 결코 자신의 무지를 드러내지 않기 때문에, 그녀는 웃기 시작한다. 마치 그녀가 샤를럿이며, 방문자가 말한 구원인 것처럼.\n눈물, 고통, 무력감은 자극 받을 필요도 없이, 방문자는 이미 그녀의 영혼 깊은 곳에서 고통을 짜내버린다.\n떠나기 전에, 상대는 홀가분한 얼굴로 클레멘틴을 바라보며 감탄한다. \"이런 이야기를 들어주셔서 감사합니다. 저 훨씬 나아진 것 같아요.\"\n그 다음은 닫히는 문 소리와, 클레멘틴이 처음으로 달콤함을 맛보며 내는 웃음소리다.\n이 웃음소리는 처음에 약간 미세하여, 마치 유충의 윙윙거림 같고, 점점 커져 마치 성충의 비명같다.\n그리고 이 웃음 속에서, 클레멘틴이라는 이름의 벌레 종은 빠르게 성숙해 간다.\n이후 모든 것은 자연스러운 일이다. 그녀는 심리 의사가 되어, 웃음과 진맥을 가지고 각 환자의 마음속으로 깊이 들어간다.\n그녀는 여전히 인간 세계를 걷고 있고, 여전히 이 화려한 세계에 속하지 않지만, 더 이상 혼란과 당황은 없다.\n왜냐하면 인간 세계 전체는 그녀의 최면 사냥터이기 때문이다."
  },
  CollectionHall_99671_Title = {
    Text = "최면 진자"
  },
  CollectionHall_99672_Desc = {
    Text = "태양은 매초 300 지조울 이상 에너지를 방출합니다. 그 중 수십억 분의 일이 빛과 열의 형태로 지구로 향해 147억 미터를 넘습니다.\n이 에너지는 지구상의 모든 생물의 필요를 충족시키며, 이 복잡하고 방대한 세 차원에서 모든 종이 성공적으로 번식하고 진화하는 것이 가능합니다.\n\n「이것이 세계의 진리이며, 어떤 경우에도 변치 않습니다.」\n그는 계속해서 자신에게 이렇게 말하며 정신의 안정을 유지했습니다.\n「그런데 왜…… 이렇게 뜨겁고, 이렇게 밝죠.」\n147억 미터 밖의 물체가 그의 동공을 천천히 차지하고 있었습니다.\n빛과 열이 그의 동공에서 퍼져나가며, 고귀한 육체의 모든 면을 태우고 있었습니다.\n「나는 이해했습니다, 이해했습니다. 왜 빛이 8분 20초 후에야 지구에 도착하는지를 이해했습니다.」\n「우리는 빛나는 대가를 지불할 수 없기 때문입니다.」\n그가 모든 것을 받아들일 때, 그는 크게 웃기 시작했습니다.\n「원래 나는 이카로스보다 더 태양에 가까웠습니다.」"
  },
  CollectionHall_99672_Title = {
    Text = "임박한 태양"
  },
  CollectionHall_99673_Desc = {
    Text = "<Title:아직 완벽하지 않아요, 오늘 밤 또 열 번 연습해보세요. 당신은 평범한 재능을 가지고 있기에, 악단에 들어가려면 더 열심히 해야 해요, 알겠습니까?」「네, 아버지.」\n어떤 연주가 완벽하다고 할 수 있는가?\n그의 두 손은 끊임없이 날아다니며, 실타래수를 허용하지 않았다.\n그는 자신의 잡념을 꾸짖고, 평범함을 경멸했다.\n수없이 많은 음표들이 그의 눈앞을 맴돌았고, 매일매일 그의 삶에서 모든 것은 음악뿐이었다.\n다행히 그는 매일 완벽한 연주에 가까워지고 있었으며, 꿈속 끝에 놓인 빛을 바라보며, 영원히 이를 닿을 수 없는 것처럼 느꼈다.\n완벽함에 대한 갈망은 그의 혼에 새겨져 있었지만, 모든 사람들이 이를 원하고 있는 것은 아니었다.\n「폐하를 위해, 세상을 위해 가장 완벽한 음악을 선보이는 것이 악단의 의무가 아닙니까?」\n그는 불만이 가득한 얼굴들을 보며, 마치 과거의 자신을 경멸하는 듯했다.\n아버지, 궁정 악단도 이 정도일 뿐이다.\n그는 과거에 동경했던 목표를 저버리며, 완벽함을 추구하는 길을 고집되게 걸어간다.\n그는 더 이상 그들의 손을 잡기 위해 두 손을 멈출 수 없었고, 예전의 자신의 손을 멈출 수 없었던 것처럼.\n매일매일 그는 끊임없이 연주하고 있었다.\n음악은 그의 생명이다.\n음악 외에는 그는 아무것도 없다."
  },
  CollectionHall_99673_Title = {
    Text = "끝없는 연주"
  },
  CollectionHall_99674_Desc = {
    Text = "그녀는 산봉우리에 올라 손에 든 검은 가시를 들어올렸다. \n하늘을 뒤덮은 눈보라와 함께 그녀는 미쳐버린 산맥을 맞이했고, 버림받고 배신당하고 짓밟힌 운명을 맞이했다. \n그녀는 결국 승리할 것이며, 얼음과 눈은 결국 녹아내릴 것이다. 그때 그녀는 새로운 모습으로 세상에 다시 나타날 것이다. 그녀는 그렇게 말했다. \n엘워스는 극한의 추운 땅이다. 그곳의 바람과 눈은 해마다 사라지지 않는다는 것은 상식이다. 마치 가장 강력한 전사라도 강력한 존재와 맞서지 못하는 것처럼, 누구든 자신의 운명을 이길 수 없다. \n하지만 그 눈 덮인 산은 결국 녹아내렸지 않나?"
  },
  CollectionHall_99674_Title = {
    Text = "설산이 녹을 때까지"
  },
  CollectionHall_99676_Desc = {
    Text = "첫 번째 왕부는 이사라우에서 왔습니다. \n그는 이사라우 사람 특유의 눈를 가지고 있었는데, 연한 금색으로, 멀리 떨어진 어두운 밤하늘에서 약하게 빛났습니다. \n하지만 그 빛은 이사라우가 함락되면서 사라졌고, 완다는 검은 진흙 속에서 마지막 운반체를 건져내어 소중히 보관했습니다. \n그녀는 프란 고원에서 두 번째와 세 번째 왕부를 만났습니다. \n그들은 탐욕스러운 영주 쌍둥이였고, 완다는 그들의 힘을 빌려 잃어버린 호수 속의 도시를 재건하길 바랐습니다. \n그녀는 속았고, 그래서 등가시가 그들의 골수 깊이 묻혔습니다. 마비 상태에서, 완다는 그 두 개의 비천하고 무례한 눈을 뽑아냈고, 그것을 자신의 존재를 증명하는 흔적으로 남겨두었습니다. \n네 번째 왕부, 완다는 그의 이름이 “존”이라고 기억합니다. \n그는 무미건조한 벙어리였지만, 그녀에게 충분히 편안하게 모셨습니다. 더욱 기쁜 것은, “존”도 연한 금색 눈를 가지고 있었고, 그녀의 것과 거의 똑같았습니다. \n\n“왕부의 눈을 파내세요.” \n“당신의 소망대로 하겠습니다… 하지만, 왕부가 잘못한 것이 있습니까?” \n완다는 잔 속의 흐린 물을 흔들며, 독소가 혀끝에서 흐르는 것을 느꼈습니다. 정말 바보 같아, 독을 내리는 것도 이렇게 서투르다니. \n“존”의 녹아내린 몸을 보면서, 그녀는 먼 별에서 고향을 떠나는 모습을 지켜보던, 죽은 눈들을 떠올렸습니다. \n그것은 “존”의 지금 눈과 매우 비슷했습니다. \n“……그저, 유머 감각이 부족하다는 거죠.”"
  },
  CollectionHall_99676_Title = {
    Text = "이살라우의 주시"
  },
  CollectionHall_99678_Desc = {
    Text = "그녀의 시가 서대에서 유행을 일으킨 이후로, 친구는 더욱 정성을 다해 그녀에게 꽃을 보내주었다. \n“이렇게 많은 꽃은 필요 없어, 코레트. 이건 정말 낭비야.” \n오늘 가져온 장미는 어제, 그저께, 대전날 가져온 것들과 함께 쌓여 있었고, 오래된 꽃들은 너무 붐비다 보니 썩기 시작했다. \n“어떻게 낭비겠어요? 우리 예전에 약속했잖아요, 내 꽃으로 당신의 시를 바꾸자고.” \n코레트는 고개를 저으며 조금은 민망한 표정으로 그녀를 바라보았다. \n그래, 꽃으로 시를 바꾸는 건 그들의 약속이었다. 그녀는 어떤 일이 변하고 있다는 것을 느낄 수 있었지만, 더 이상 생각하고 싶지 않았다. \n그녀는 계속해서 시를 써나갔다. 밤낮으로 시를 써나갔다. 예전에는 그녀의 시가 자연스럽게 펜 끝에서 흘러나왔지만, 이제는 펜이 조금씩 굳어지는 듯했다. \n친구가 꽃을 가져올 때마다 보이는 눈빛이 점점 낯설어졌고, 그녀는 방 안 가득히 썩어가는 장미들을 보며, 그들로부터 풍기는 썩은 냄새를 맡으면서 진심으로 아쉬움과 우울함을 느꼈다. \n하지만 그녀는 손에서 펜을 놓은 적이 한 번도 없었다. \n“나는 이 땅에서 자라는 꽃으로 우리에게 옷을 사고, 먹을 것을 살 거야. 언젠가는 저 위에 있는 건물 안의 집까지도 사게 될 거야!” \n“모든 사람은 자신이 태어나면서 해야 할 일이 있어. 나는 이 정원, 그 집을 위해 노력해야 하는 사람이고, 너는 시를 써야 하는 사람이야.” \n“나는 널 믿어, 오를라! 오늘부터 네 모든 시를 잘 보관해줄게. 앞으로는 내 꽃으로 네 시를 바꾸려고!” \n꽃과 시는 그들이 서로에게 준 약속이었다. \n그녀는 결코 손에서 펜을 놓지 않을 것이다."
  },
  CollectionHall_99678_Title = {
    Text = "지난날의 꽃과 시"
  },
  CollectionHall_99679_Desc = {
    Text = "마녀와 넓은 챙 모자의 인과관계는 때로 달걀과 닭의 관계와 같아, 모자가 마녀를 만든 건지, 아니면 마녀가 모자를 만든 건지 분간할 수 없다.\n하지만 어쨌든, 다프델은 이렇게 우아한 넓은 챙 모자를 가지고 있다.\n이 모자는 처음에 과거의 점원이 소유했던 것으로, 그 당시 다프델의 이름은 아직 다프델이 아니었다. 그녀는 막 정복당한, 혼란스러운 영혼에 불과하고, 어리둥절한 야생동물이었다.\n항상 미소 짓고 있는 그 여자는 그녀를 데리고, 마치 아이를 교육하듯이, 인내롭게 조금씩 그녀에게 '사람'이 되는 방법과 사람들과 소통하는 비밀을 가르쳤다.\n항구 도시의 상업은 번창했고, 그 당시 인류 문화의 가장 풍부한 결정체가 모여들었다. 교환 상점이 있는 거리에는 갖가지 상점들이 거의 모두 망라되어 있었고, 점원들은 모든 가게 주인들과 친구처럼 신기하게 대화를 나눌 수 있었다.\n「그녀는 정말 대단해.」그 당시의 다프델은 생각했다.「하지만 그리 이상한 일도 아니야. 누구나 그녀를 싫어하지 않을 거야.」\n점원은 쇼핑을 좋아했고, 그래서 천 년 동안 그녀에게 목이 잘린 인간들의 역할을 맡아온 다프델은 처음으로 자신의 의견을 이야기하라는 요청을 받았다.\n「어떤 모자가 좋다고 생각해? 이 작은 모자, 아니면 이 넓은 챙 모자?」\n여자는 거울을 보며, 화려한 모자들을 번갈아 써보았다. 원래 다프델에게 이들은 단순히 신체를 감싸고, 자신을 더 인간답게 만들기 위한 도구였다.\n하지만 그 날, 그녀는 점원이 큰 꽃처럼 보이는 넓은 챙 모자를 쓰고 있는 모습을 보고, 갑자기 여자가 그런 모자를 쓰고 해변의 모래사장에서 산책하는 모습이 떠올랐다.\n「이 모자!」그녀가 갑자기 입을 열었다.「바로 이 모자야.」\n점원은 약간 놀라서 뒤돌아보며, 그녀가 이렇게 확실타래히 취향을 드러낼 것이라고는 생각하지 못했던 것 같다.\n「좋아, 정말 좋은 모자야. 네가 나를 위해 선택한 거니까, 나는 반드시 잘 소중히 할 거야.」\n다프델을 격려하기 위해서였는지, 이 모자는 점원의 약속처럼 그녀의 머리에 항상 자리 잡게 되었고, 결국 그녀의 손에서 떨어져 다프델에게 스스로 건네주었으며, 미소를 짓고 있는 그녀의 머리와 함께했다.\n「정말 좋은 모자야, 나는 반드시 잘 소중히 할 거야.」\n찬란하게 피어나는 보라색 검은 꽃이 결국 새로운 주인의 머리 위에 만개했다."
  },
  CollectionHall_99679_Title = {
    Text = "마녀의 모자"
  },
  CollectionHall_99683_Desc = {
    Text = "왕좌의 환몽 속에서, 왕은 신성의 계시를 듣는다:\n리모리아의 폭풍이 잦아들 것이다. 리모리아의 심연이 사라질 것이다. \n꿈을 정원으로, 별을 촛불로 삼아, 왕은 선한 백성을 보호하고 신의 나라를 가져올 것이다. \n\n우리 주님의 신도여, 네 마음을 열고 주님을 받아들여라. \n먼 곳의 어두운 심연에서, 고대의 위대한 영혼이 깊은 잠하며 신들의 저어를 듣는다. \n그분의 의지는 별들의 그물처럼 얽혀 있으며, 그분은 영원한 공허에서 너의 꿈에 들어오기를 기다린다. \n\n폭풍이 잠잠해지고, 물결이 일지 않는다. \n지진이 멎고, 대지가 평온하다. \n재앙은 그분의 평온한 꿈 속에서 공허로 변하고, \n백성은 그분의 보호 아래 안전하다. \n우리의 노래가 깊은 바다를 통과하여, 그분이 재앙에서 우리를 구원하는 계시를 내려주시길, \n우리를 무한한 평온과 극락으로 인도하소서. \n우리의 믿음은 그분과 함께하며, 별들이 사라질 때까지, 시간의 끝까지 함께할 것이다. \n"
  },
  CollectionHall_99683_Title = {
    Text = "심연의 부름"
  },
  CollectionHall_99684_Desc = {
    Text = "구울로의 변이가 시작된 지 7일째, 그는 사지가 날로 부패해가는 극심한 고통 속에서 신음했다. 미세한 움직임 하나하나가 예민한 신경을 자극하며, 찢어지는 듯한 고통을……그리고 전율하게 하는 영감의 불꽃을 터뜨렸다.\n그러나 당혹의 그림자가 이 예술가를 시종 뒤덮고 있었다——도대체 어떤 붓이어야 그 가장 극치의 진실타래을 그려낼 수 있단 말인가?\n픽맨의 쇠약한 눈이 사방을 탐색했다. 저택 옆의 벽돌에서 무덤 위의 나뭇가지까지, 마침내 시선이 그의 위축되고 궤양된 오른쪽 다리 속 드러난 백골에 잠금되었다.\n마치 어떤 신성한 부름을 들은 것처럼, 픽맨은 다리뼈를 꺼내어 손가락 끝으로 달라붙은 살점을 반복해서 문질러 제거하고, 그것을 단단한 붓으로 만들었다.\n그는 붓끝을 날카로운 송곳니처럼 갈았지만, 붓끝이 캔버스를 물기 전에 먼저 주인의 마른 손끝을 찔렀다. 픽맨은 아파서 손을 놓았고, 붓은 그의 통제에서 벗어났다.\n비상! 도약! 회전! 붓은 캔버스 위에서 광란의 춤을 추며, 혼란스럽고 광기 어린 선을 새겼다. 선은 증식하며 미친 듯이 자라나, 끊임없이 팽창하는 기괴한 형태의 어두운 얼룩을 끌어내며, 느리지만 단호하게 픽맨의 목을 물어뜯었다.\n순간의 광희가 날카로운 가시처럼 그의 남아있는 심장을 관통했다——그 부풀어 오른 기관, 혼돈스러운 형태는 그를 전율하게 했지만, 시들어가던 감각을 되살리기도 했다. 그것들은 전도되고 무질서한 방식으로, 직접적이고 날카롭게 고통, 기이함과 욕망을 드러내며, 가감 없는 충격적인 힘을 폭발시켰다.\n이 도착 속에서, 픽맨은 「미」의 성역에 더 가까워진 듯했다.\n모든 것이 가라앉자, 픽맨은 이미 부식된 날카로운 발톱을 내밀어, 그 창백한 붓을 반복해서 어루만졌다. 아직 인간의 형태를 유지하고 있는 이 껍데기 안에서, 더 뜨겁고 더 절박한 갈망이 분출되었다.\n그는 이 붓과 함께, 그 세기의 걸작의 마지막 한 획을 완성할 것이다."
  },
  CollectionHall_99684_Title = {
    Text = "갈망의 붓"
  },
  CollectionHall_99687_Desc = {
    Text = "「성자는 등불을 든 자가 주시하는 사람이며, 태어나면서부터 그분의 은총을 받는다.」\n「성자는 그분의 뜻을 전파하고, 경건한 의인에게 빛을 내려야 한다.」\n「성자는 영혼의 청결을 유지해야 한다.」\n「성자는 속된 욕망을 끊고 경건히 수행하며, 온 마음으로 빛을 섬겨야 한다.」\n「성자는 말을 많이 해서는 안 되며, 망언을 해서는 안 된다.」\n「성자는 죄악에서 멀리하고, 죄 있는 자에게서 멀리하며, 더러운 영혼에 오염되어서는 안 된다.」\n「성자는……」\n그에게 기억이 있는 때부터, 하나 또 하나의 계율이 쇠사슬처럼 그를 속박하며, 그를 존숭의 높은 단상 위에 올려놓으면서도, 예의를 잃어서는 안 되고, 고개를 숙여서는 안 되고, 희노를 방종해서는 안 되게 했다.\n그는 크고 화려한 의포를 걸치고, 수많은 시종들에 둘러싸여, 요구에 따라 그 신성한 대리인을 연기하며, 경건한 신도들이 엎드려 무릎 꿇고 조심스럽게 그의 옷자락에 입 맞추는 것을 내려다보았다.\n성자는 마땅히 그래야 했고, 아무도 그 고고하고 변하지 않는 얼굴 아래에 어떤 감정과 취향이 있는지 신경 쓰지 않았다.\n마치 그가 그 고고한 미소에 익숙해져, 아무도 없을 때조차 자신이 진정으로 어떤 표정을 짓고 싶은지 알지 못하는 것처럼.\n「폴리덱스 성자님, 축복 의식에 가셔야 합니다.」고개를 숙인 시녀가 공손하게 그의 변함없는 일상을 안배했다.\n그는 몸을 돌려, 고개를 들고, 그 똑같이 변함없는 미소를 지으며, 마치 직접 신성한 가면을 쓰는 것 같았다.\n그 방황, 공허와 외로움은 모두 가면 아래에 가려져, 마치 존재한 적이 없는 것처럼."
  },
  CollectionHall_99687_Title = {
    Text = "성자의 존안"
  },
  CollectionHall_99691_Desc = {
    Text = "이야기 속에는 마법이 존재한다고 프란시스는 리리에게 그렇게 말해주곤 했습니다. \n그때 그녀는 이야기책을 껴안고 창가에 앉아 있었죠. 초여름 햇빛이 하얀 가운을 따뜻하게 만들었고, 부드럽고 따뜻한 향기가 풍겼습니다. \n그녀의 목소리는 부드럽고 천천히 흘러나왔지만, 전날 밤 수술에 집중하면서 쌓인 피로가 너무 많아서, 이야기가 끝나기도 전에 프란시스는 깊이 잠들어버렸습니다. \n리리는 결코 어머니를 탓하지 않았습니다. 왜냐하면 어머니가 창틀에 기대어 잠든 모습은 너무도 안정감을 주었기 때문입니다. \n\n지금은 필름이 책 대신 이야기와 마법을 담고 있습니다. 마치 아이들의 실타래수로 노출되어 손상된 필름을 새로운 필름이 대체하듯, 새로운 친구들의 장난이 과거의 따뜻하고 아픈 휴식 시간을 대체했습니다. \n하지만 묻혀진 기억들은 여전히 노출된 필름처럼, 알려지지 않은 모퉁이에서 잠자고 있으며, 언제나 빛나고 있습니다."
